window.MV_DATA=window.MV_DATA||{};window.MV_DATA[2]={"id":2,"topics":[{"id":11,"words":[{"en":"technical drawing","pos":"noun phrase","ipa":"/ˌteknɪkl ˈdrɔːɪŋ/","ja":"図面","kana":"ずめん","romaji":"zumen","vi":"bản vẽ kỹ thuật","level":1,"def_vi":"Tài liệu hình vẽ biểu diễn hình dạng, kích thước và yêu cầu kỹ thuật của chi tiết theo quy ước tiêu chuẩn.","def_en":"A drawing that shows the shape, size and technical requirements of a part using standardised conventions.","def_ja":"規格に従い、部品の形状・寸法・技術的要求を表した図。","usage_en":"Danh từ đếm được (a technical drawing, technical drawings). Hay đi với: read / prepare / issue / revise a technical drawing; trong giao tiếp thường gọi tắt là 'drawing'.","usage_ja":"図面 là từ dùng hằng ngày cả ở văn phòng lẫn xưởng; động từ đi kèm: 図面を描く, 図面を読む, 図面を出図する. 製図 chỉ hoạt động vẽ, còn bản vẽ cụ thể luôn gọi là 図面.","context_vi":"Là 'ngôn ngữ chung' giữa phòng thiết kế, xưởng gia công, bộ phận kiểm tra và nhà cung cấp.","ex_en":"Please check the latest technical drawing before you start machining the flange.","ex_ja":"フランジの加工を始める前に、最新の図面を確認してください。","ex_vi":"Hãy kiểm tra bản vẽ kỹ thuật mới nhất trước khi bắt đầu gia công mặt bích.","syn_en":["engineering drawing","drawing (khẩu ngữ)"],"syn_ja":["技術図面","機械図面 (nghĩa hẹp hơn)"]},{"en":"drafting","pos":"noun","ipa":"/ˈdrɑːftɪŋ/","ja":"製図","kana":"せいず","romaji":"seizu","vi":"vẽ kỹ thuật (công việc lập bản vẽ)","level":1,"def_vi":"Công việc lập bản vẽ kỹ thuật bằng tay hoặc bằng phần mềm theo các quy tắc tiêu chuẩn.","def_en":"The work of preparing technical drawings by hand or with software according to standard rules.","def_ja":"規格の約束に従い、手描きまたはソフトで図面を作成すること。","usage_en":"Danh từ không đếm được, chỉ hoạt động/nghề; không nói 'a drafting'. Hay đi với: drafting standards, drafting room, CAD drafting; Anh-Anh viết 'draughting'.","usage_ja":"製図 chỉ hoạt động vẽ và cả môn học; động từ: 製図する. Ghép: 製図規格, 製図室, 手描き製図, CAD製図.","context_vi":"Gặp trong môn học vẽ kỹ thuật, phòng thiết kế và các tiêu chuẩn như JIS B 0001, ISO 128, TCVN.","ex_en":"All drafting in our design office follows JIS B 0001.","ex_ja":"当社設計部の製図は、すべてJIS B 0001に従っている。","ex_vi":"Toàn bộ công việc vẽ kỹ thuật ở phòng thiết kế của chúng tôi tuân theo JIS B 0001.","syn_en":["draughting (Anh-Anh)","drawing preparation"],"syn_ja":["図面作成","作図 (nghĩa rộng hơn)"]},{"en":"title block","pos":"noun phrase","ipa":"/ˈtaɪtl blɒk/","ja":"表題欄","kana":"ひょうだいらん","romaji":"hyoudairan","vi":"khung tên","level":1,"def_vi":"Ô ở góc dưới bên phải bản vẽ ghi tên bản vẽ, số bản vẽ, tỷ lệ, vật liệu, người vẽ và người duyệt.","def_en":"The box in the lower right corner of a drawing giving its title, number, scale, material and approvals.","def_ja":"図面の右下に設け、図名・図番・尺度・材料・作成者・承認者などを記入する欄。","usage_en":"Danh từ đếm được. Hay nói: fill in / complete the title block; thông tin nằm 'in the title block' (dùng giới từ in, không dùng on).","usage_ja":"Văn bản chuẩn JIS dùng 表題欄; ngoài xưởng nhiều người nói タイトル欄. Cụm: 表題欄に記入する, 表題欄を確認する.","context_vi":"Kỹ sư và thợ luôn nhìn khung tên đầu tiên để biết tên chi tiết, vật liệu, tỷ lệ và phiên bản bản vẽ.","ex_en":"The material is listed as S45C in the title block.","ex_ja":"表題欄には材料がS45Cと記入されている。","ex_vi":"Trong khung tên, vật liệu được ghi là S45C.","syn_en":["title box","title strip (ít dùng)"],"syn_ja":["タイトル欄 (khẩu ngữ)","図枠 (liên quan)"]},{"en":"scale","pos":"noun","ipa":"/skeɪl/","ja":"尺度","kana":"しゃくど","romaji":"shakudo","vi":"tỷ lệ (bản vẽ)","level":1,"def_vi":"Tỷ số giữa kích thước của hình vẽ trên bản vẽ và kích thước thật của vật thể.","def_en":"The ratio between the size of an object as drawn and its actual size.","def_ja":"図形の大きさと対象物の実際の大きさとの比。","usage_en":"Danh từ đếm được. Hay nói: drawn to scale, at a scale of 1:2, 'not to scale' (NTS). Tỷ lệ 1:2 đọc là 'one to two'.","usage_ja":"Ghi dạng 尺度 1:2 trong 表題欄. Ngoài xưởng hay nói スケール; 'đúng tỷ lệ' là 尺度どおり.","context_vi":"Ghi trong khung tên mọi bản vẽ; quan trọng khi chọn khổ giấy hoặc khi đo trực tiếp trên bản in.","ex_en":"The housing is drawn at a scale of 1:2 to fit on an A3 sheet.","ex_ja":"ハウジングはA3用紙に収まるよう尺度1:2で描かれている。","ex_vi":"Vỏ hộp được vẽ theo tỷ lệ 1:2 để vừa khổ giấy A3.","syn_en":["drawing scale","ratio (liên quan)"],"syn_ja":["スケール (khẩu ngữ)","縮尺 (nghĩa hẹp hơn)"]},{"en":"visible line","pos":"noun phrase","ipa":"/ˈvɪzəbl laɪn/","ja":"外形線","kana":"がいけいせん","romaji":"gaikeisen","vi":"đường bao thấy (nét liền đậm)","level":1,"def_vi":"Nét liền đậm biểu diễn các cạnh và đường bao nhìn thấy được của vật thể.","def_en":"A thick continuous line showing the visible edges and outlines of an object.","def_ja":"対象物の見える部分の形状を表す太い実線。","usage_en":"Danh từ đếm được. Mỹ hay gọi 'object line'; collocation: draw visible lines as thick continuous lines.","usage_ja":"外形線 là thuật ngữ JIS cho nét thấy, vẽ bằng 太い実線. Cụm: 外形線を描く, 外形線で示す.","context_vi":"Là loại nét đầu tiên học trong vẽ kỹ thuật; dùng trên mọi hình chiếu để thể hiện hình dạng chi tiết.","ex_en":"Draw every visible line as a 0.5 mm thick continuous line.","ex_ja":"外形線はすべて太さ0.5 mmの太い実線で描くこと。","ex_vi":"Vẽ tất cả đường bao thấy bằng nét liền đậm dày 0,5 mm.","syn_en":["object line (Mỹ)","outline"],"syn_ja":["太い実線 (liên quan)","実線 (nghĩa rộng hơn)"]},{"en":"hidden line","pos":"noun phrase","ipa":"/ˈhɪdn laɪn/","ja":"かくれ線","kana":"かくれせん","romaji":"kakuresen","vi":"đường khuất (nét đứt)","level":1,"def_vi":"Nét đứt biểu diễn các cạnh và đường bao bị che khuất, không nhìn thấy từ hướng chiếu.","def_en":"A dashed line showing edges and outlines that are hidden from the viewing direction.","def_ja":"対象物の見えない部分の形状を表す破線。","usage_en":"Danh từ đếm được; số nhiều 'hidden lines' rất hay dùng. Collocation: show a bore with hidden lines, omit hidden lines (để bản vẽ rõ hơn).","usage_ja":"JIS viết かくれ線, cũng gặp 隠れ線; vẽ bằng 破線. Cụm: かくれ線で示す, かくれ線を省略する.","context_vi":"Dùng để thể hiện lỗ, rãnh bên trong chi tiết khi không vẽ mặt cắt.","ex_en":"The internal bore is shown by a hidden line in the side view.","ex_ja":"内側の穴は側面図でかくれ線により示されている。","ex_vi":"Lỗ bên trong được thể hiện bằng đường khuất trên hình chiếu cạnh.","syn_en":["hidden outline","dashed line (liên quan)"],"syn_ja":["隠れ線","破線 (liên quan)"]},{"en":"centre line","pos":"noun phrase","ipa":"/ˈsentə laɪn/","ja":"中心線","kana":"ちゅうしんせん","romaji":"chuushinsen","vi":"đường tâm","level":1,"def_vi":"Nét chấm gạch mảnh biểu diễn trục đối xứng hoặc tâm của lỗ, trục và các chi tiết tròn.","def_en":"A thin chain line marking the axis or centre of holes, shafts and symmetrical features.","def_ja":"図形の中心や穴・軸の中心を表す細い一点鎖線。","usage_en":"Danh từ đếm được; Mỹ viết 'center line' hoặc 'centerline'. Collocation: draw a centre line through the hole; centre lines intersect at the hole centre.","usage_ja":"中心線 vẽ bằng 細い一点鎖線; cụm: 中心線を引く, 中心線を入れる. Khẩu ngữ đôi khi gọi センターライン.","context_vi":"Có mặt trên hầu hết bản vẽ chi tiết trụ, lỗ, mặt bích và chi tiết đối xứng.","ex_en":"Add a centre line through each bolt hole on the flange.","ex_ja":"フランジの各ボルト穴に中心線を入れてください。","ex_vi":"Hãy vẽ đường tâm qua từng lỗ bu lông trên mặt bích.","syn_en":["center line (Mỹ)","axis line"],"syn_ja":["センターライン (khẩu ngữ)","一点鎖線 (liên quan)"]},{"en":"freehand sketch","pos":"noun phrase","ipa":"/ˌfriːhænd ˈsketʃ/","ja":"フリーハンドスケッチ","kana":"フリーハンドスケッチ","romaji":"furiihandosuketchi","vi":"bản vẽ phác (vẽ tay)","level":1,"def_vi":"Bản vẽ nhanh bằng tay không dùng dụng cụ, ghi lại hình dạng và kích thước sơ bộ của chi tiết.","def_en":"A quick drawing made by hand without instruments to record a part's shape and approximate dimensions.","def_ja":"定規などを使わず手で描き、形状と寸法を素早く記録した図。","usage_en":"Danh từ đếm được. Hay nói: make / do a freehand sketch; 'sketch' cũng là động từ: sketch the bracket.","usage_ja":"Viết đầy đủ フリーハンドスケッチ hoặc gọn スケッチ. Động từ: スケッチする, スケッチを取る (vẽ phác chi tiết thật để đo).","context_vi":"Dùng khi đo vẽ lại chi tiết hỏng ngoài hiện trường hoặc trao đổi ý tưởng nhanh trước khi dựng CAD.","ex_en":"The maintenance technician made a freehand sketch of the broken bracket with all key dimensions.","ex_ja":"保全担当者が、壊れたブラケットの主要寸法を入れたフリーハンドスケッチを描いた。","ex_vi":"Kỹ thuật viên bảo trì đã vẽ phác bằng tay giá đỡ bị gãy kèm đầy đủ các kích thước chính.","syn_en":["sketch","hand sketch"],"syn_ja":["スケッチ","手描きスケッチ"]},{"en":"T-square","pos":"noun","ipa":"/ˈtiː skweə/","ja":"T定規","kana":"ティーじょうぎ","romaji":"tiijougi","vi":"thước chữ T","level":1,"def_vi":"Thước hình chữ T trượt dọc mép bàn vẽ để kẻ các đường nằm ngang song song.","def_en":"A T-shaped ruler that slides along the edge of a drawing board to draw parallel horizontal lines.","def_ja":"製図板の縁に沿って動かし、平行な水平線を引くT字形の定規。","usage_en":"Danh từ đếm được, viết có gạch nối và chữ T in hoa. Collocation: slide the T-square, use a T-square with a set square.","usage_ja":"Viết T定規, đọc ティーじょうぎ. Cụm: T定規を当てる, T定規で水平線を引く.","context_vi":"Dùng trong vẽ tay trên bàn vẽ, chủ yếu ở trường học và bài thi vẽ kỹ thuật.","ex_en":"Hold the T-square firmly against the left edge of the board.","ex_ja":"T定規を製図板の左端にしっかり当ててください。","ex_vi":"Giữ chặt thước chữ T áp vào mép trái của bàn vẽ.","syn_en":["tee square","parallel rule (liên quan)"],"syn_ja":["ティー定規","平行定規 (liên quan)"]},{"en":"set square","pos":"noun phrase","ipa":"/ˈset skweə/","ja":"三角定規","kana":"さんかくじょうぎ","romaji":"sankakujougi","vi":"ê ke","level":1,"def_vi":"Thước hình tam giác vuông (loại 45° hoặc 30°/60°) dùng để kẻ đường thẳng đứng và đường xiên.","def_en":"A right-angled triangular ruler, 45° or 30°/60°, used to draw vertical and angled lines.","def_ja":"45°または30°・60°の直角三角形の定規で、垂直線や斜線を引くもの。","usage_en":"Danh từ đếm được (Anh-Anh); Mỹ gọi 'triangle'. Collocation: a 45° set square, a 30/60 set square; use it against the T-square.","usage_ja":"Thường dùng theo bộ hai cái 45° và 30°・60°: 三角定規を組み合わせる. Loại chỉnh được góc gọi 勾配定規.","context_vi":"Dụng cụ vẽ tay cơ bản trong lớp vẽ kỹ thuật, dùng kết hợp với thước chữ T.","ex_en":"Use the 30/60 set square to draw the 60° chamfer line.","ex_ja":"60°の面取り線は30°・60°の三角定規で引いてください。","ex_vi":"Dùng ê ke 30/60 để kẻ đường vát mép 60°.","syn_en":["triangle (Mỹ)","drafting triangle"],"syn_ja":["勾配定規 (ê ke chỉnh góc, liên quan)"]},{"en":"compass","pos":"noun","ipa":"/ˈkʌmpəs/","ja":"コンパス","kana":"コンパス","romaji":"konpasu","vi":"compa","level":1,"def_vi":"Dụng cụ có hai chân, một chân kim và một chân chì, dùng để vẽ đường tròn và cung tròn.","def_en":"A two-legged instrument, one leg with a point and one with a lead, for drawing circles and arcs.","def_ja":"針と鉛筆の二本の脚をもち、円や円弧を描く製図器具。","usage_en":"Danh từ đếm được; Anh-Anh hay nói 'a pair of compasses'. Đừng nhầm với la bàn (cũng là compass). Collocation: set the compass to a radius of 25 mm.","usage_ja":"Viết katakana コンパス; cụm: コンパスで円を描く, 半径を合わせる. Dụng cụ chia khoảng gọi ディバイダ.","context_vi":"Dùng khi vẽ tay đường tròn, cung nối tiếp trên bàn vẽ.","ex_en":"Set the compass to a radius of 25 mm and draw the bolt circle.","ex_ja":"コンパスを半径25 mmに合わせて、ボルト穴の円を描きなさい。","ex_vi":"Chỉnh compa bán kính 25 mm rồi vẽ đường tròn lỗ bu lông.","syn_en":["pair of compasses (Anh-Anh)","dividers (liên quan)"],"syn_ja":["製図用コンパス","ディバイダ (liên quan)"]},{"en":"drafter","pos":"noun","ipa":"/ˈdrɑːftə/","ja":"製図者","kana":"せいずしゃ","romaji":"seizusha","vi":"người vẽ (họa viên)","level":2,"def_vi":"Người lập bản vẽ kỹ thuật từ thông tin thiết kế; tên được ghi ở ô 'người vẽ' trong khung tên.","def_en":"A person who prepares technical drawings from design information; their name appears in the title block.","def_ja":"設計情報をもとに図面を作成する人。表題欄に氏名を記入する。","usage_en":"Danh từ đếm được; Anh-Anh dùng 'draughtsman' / 'draughtsperson'. Collocation: CAD drafter, senior drafter; ô 'drawn by' trong khung tên ghi người vẽ.","usage_ja":"Trong khung tên ô người vẽ ghi 製図 hoặc 作成; nghề nghiệp hay gọi CADオペレーター. Văn viết: 製図者, 作図者.","context_vi":"Gặp trong phòng thiết kế, tin tuyển dụng (họa viên CAD) và quy trình ký duyệt bản vẽ.","ex_en":"The drafter updated the bracket drawing after the design review.","ex_ja":"製図者は設計審査の後でブラケットの図面を修正した。","ex_vi":"Họa viên đã cập nhật bản vẽ giá đỡ sau buổi xem xét thiết kế.","syn_en":["draughtsman (Anh-Anh)","CAD operator"],"syn_ja":["作図者","CADオペレーター"]},{"en":"drawing sheet","pos":"noun phrase","ipa":"/ˈdrɔːɪŋ ʃiːt/","ja":"製図用紙","kana":"せいずようし","romaji":"seizuyoushi","vi":"khổ giấy vẽ","level":2,"def_vi":"Tờ giấy vẽ có kích thước theo khổ chuẩn A0–A4, có khung bản vẽ và khung tên.","def_en":"A sheet of standard size, A0 to A4, with a border and title block, on which a drawing is made.","def_ja":"A0〜A4の規定サイズをもち、輪郭と表題欄を設けた図面用の紙。","usage_en":"Danh từ đếm được. Collocation: an A3 drawing sheet, sheet size; 'sheet 2 of 3' dùng cho bản vẽ nhiều tờ.","usage_ja":"製図用紙のサイズ là thuật ngữ JIS Z 8311; khi làm CAD người ta nói 図枠 hoặc 用紙サイズ. Cụm: A3の製図用紙に描く.","context_vi":"Chọn khi bắt đầu lập bản vẽ; khổ A3, A4 phổ biến cho chi tiết, A1, A0 cho bản vẽ lắp lớn.","ex_en":"The assembly does not fit on an A3 drawing sheet, so we use A1.","ex_ja":"この組立品はA3の製図用紙に収まらないので、A1を使う。","ex_vi":"Cụm lắp này không vừa khổ giấy A3 nên chúng tôi dùng A1.","syn_en":["sheet","drawing format (liên quan)"],"syn_ja":["図面用紙","図枠 (liên quan)"]},{"en":"border","pos":"noun","ipa":"/ˈbɔːdə/","ja":"輪郭線","kana":"りんかくせん","romaji":"rinkakusen","vi":"đường khung bản vẽ","level":2,"def_vi":"Đường liền đậm vẽ cách mép giấy một khoảng quy định, giới hạn vùng vẽ của bản vẽ.","def_en":"A thick continuous line drawn inside the sheet edge that bounds the drawing area.","def_ja":"用紙の縁から一定の間隔をとり、図を描く領域を区切る太い実線。","usage_en":"Danh từ đếm được. Collocation: border line, drawing border, inside the border; 'frame' cũng được dùng.","usage_ja":"JIS gọi 輪郭 và 輪郭線; trong CAD khung có sẵn gọi 図枠. Cụm: 輪郭線を引く, 輪郭の内側に描く.","context_vi":"Thuộc mẫu bản vẽ chuẩn; giúp không mất nét khi in, photo hoặc đóng tập bản vẽ.","ex_en":"Keep all views at least 10 mm inside the border.","ex_ja":"すべての投影図は輪郭線から10 mm以上内側に配置すること。","ex_vi":"Đặt mọi hình chiếu cách đường khung bản vẽ ít nhất 10 mm vào trong.","syn_en":["border line","frame"],"syn_ja":["輪郭","図枠 (liên quan)"]},{"en":"line thickness","pos":"noun phrase","ipa":"/ˈlaɪn ˌθɪknəs/","ja":"線の太さ","kana":"せんのふとさ","romaji":"sennofutosa","vi":"bề rộng nét vẽ","level":2,"def_vi":"Bề rộng của nét vẽ, chọn theo dãy chuẩn (0,25; 0,35; 0,5; 0,7 mm...) với tỷ lệ nét mảnh và nét đậm khoảng 1:2.","def_en":"The width of a drawn line, chosen from a standard series, usually with a thin-to-thick ratio of 1:2.","def_ja":"線の幅。0.25、0.35、0.5、0.7 mmなどから選び、細線と太線の比を1:2とする。","usage_en":"Danh từ không đếm được khi nói chung. Trong CAD thường dùng 'line width' hoặc 'line weight' (Mỹ); collocation: set the line thickness to 0.5 mm.","usage_ja":"線の太さ dùng trong JIS; trong CAD gọi 線幅. Phân loại: 細線, 太線, 極太線; cụm: 線の太さを使い分ける.","context_vi":"Thiết lập trong mẫu CAD và khi in bản vẽ; sai bề rộng nét làm bản vẽ khó đọc.","ex_en":"Check the line thickness settings in the CAD template before printing.","ex_ja":"印刷前にCADテンプレートの線の太さの設定を確認してください。","ex_vi":"Kiểm tra cài đặt bề rộng nét trong mẫu CAD trước khi in.","syn_en":["line width","line weight (Mỹ)"],"syn_ja":["線幅"]},{"en":"chain line","pos":"noun phrase","ipa":"/ˈtʃeɪn laɪn/","ja":"一点鎖線","kana":"いってんさせん","romaji":"ittensasen","vi":"nét chấm gạch","level":2,"def_vi":"Nét gồm các gạch dài xen kẽ một gạch ngắn (chấm), dùng cho đường tâm, đường tròn chia và một số mục đích khác.","def_en":"A line of long dashes alternating with single short dashes, used for centre lines and pitch lines.","def_ja":"長い線と短い線（点）を交互に並べた線。中心線やピッチ線に用いる。","usage_en":"Danh từ đếm được; tên đầy đủ theo ISO 128 là 'long-dashed dotted line'. Hay nói: thin chain line, thick chain line.","usage_ja":"一点鎖線 đọc いってんさせん; có 細い一点鎖線 (đường tâm) và 太い一点鎖線 (chỉ vùng yêu cầu đặc biệt). Cụm: 一点鎖線で描く.","context_vi":"Gặp trên mọi bản vẽ có đường tâm, vòng tròn lỗ bu lông và đường tròn chia bánh răng.","ex_en":"The pitch circle of the gear is drawn as a thin chain line.","ex_ja":"歯車のピッチ円は細い一点鎖線で描く。","ex_vi":"Đường tròn chia của bánh răng được vẽ bằng nét chấm gạch mảnh.","syn_en":["long-dashed dotted line","dash-dot line"],"syn_ja":["一点長鎖線","鎖線 (nghĩa rộng hơn)"]},{"en":"phantom line","pos":"noun phrase","ipa":"/ˈfæntəm laɪn/","ja":"想像線","kana":"そうぞうせん","romaji":"souzousen","vi":"đường tưởng tượng (nét hai chấm gạch)","level":2,"def_vi":"Nét hai chấm gạch mảnh biểu diễn chi tiết lân cận, vị trí giới hạn của chi tiết chuyển động hoặc hình dạng trước gia công.","def_en":"A thin double-dotted chain line showing adjacent parts, extreme positions of moving parts, or shape before machining.","def_ja":"隣接部分、可動部の移動位置、加工前の形状などを表す細い二点鎖線。","usage_en":"Danh từ đếm được. Collocation: show the open position in phantom lines; tên theo ISO là 'long-dashed double-dotted line'.","usage_ja":"想像線 là tên theo mục đích, vẽ bằng 細い二点鎖線; ngoài xưởng hay nói luôn 二点鎖線. Cụm: 想像線で示す.","context_vi":"Dùng trên bản vẽ lắp để chỉ hành trình của tay quay, nắp, xi lanh hoặc chi tiết lắp liền kề.","ex_en":"The open position of the cover is shown with a phantom line.","ex_ja":"カバーの開いた位置は想像線で示している。","ex_vi":"Vị trí mở của nắp được thể hiện bằng đường tưởng tượng.","syn_en":["long-dashed double-dotted line","alternate position line (liên quan)"],"syn_ja":["二点鎖線"]},{"en":"break line","pos":"noun phrase","ipa":"/ˈbreɪk laɪn/","ja":"破断線","kana":"はだんせん","romaji":"hadansen","vi":"nét lượn sóng (đường cắt lìa)","level":2,"def_vi":"Nét mảnh vẽ tay hoặc nét dích dắc dùng để giới hạn phần hình vẽ bị cắt lìa hoặc phần hình cắt cục bộ.","def_en":"A thin freehand or zigzag line marking where part of a view is broken off or limited.","def_ja":"対象物の一部を破った境界、または一部を取り去った境界を表す細い線。","usage_en":"Danh từ đếm được. Collocation: shorten a long shaft with break lines; freehand break line, zigzag break line.","usage_ja":"破断線 vẽ bằng nét mảnh フリーハンド hoặc ジグザグ線. Cụm: 破断線で省略する, 破断線で区切る.","context_vi":"Dùng để rút ngắn hình vẽ trục dài, thanh dài hoặc giới hạn phần hình cắt cục bộ.","ex_en":"The 2 m long shaft is shortened with a pair of break lines.","ex_ja":"長さ2 mの軸は、2本の破断線で中間部を省略して描く。","ex_vi":"Trục dài 2 m được vẽ rút ngắn bằng hai nét lượn sóng.","syn_en":["short break line","zigzag line (liên quan)"],"syn_ja":["ジグザグ線 (liên quan)"]},{"en":"full scale","pos":"noun phrase","ipa":"/ˌfʊl ˈskeɪl/","ja":"現尺","kana":"げんしゃく","romaji":"genshaku","vi":"tỷ lệ nguyên hình (1:1)","level":2,"def_vi":"Tỷ lệ 1:1, hình vẽ có kích thước bằng kích thước thật của vật thể.","def_en":"A scale of 1:1, where the drawing is the same size as the actual object.","def_ja":"尺度1:1で、図形を実物と同じ大きさで描くこと。","usage_en":"Thường dùng làm trạng ngữ: drawn at full scale; đứng trước danh từ thì có gạch nối: a full-scale drawing.","usage_ja":"現尺 là thuật ngữ JIS; trên bản vẽ ghi 1:1. Khẩu ngữ: 原寸 (げんすん), 原寸大.","context_vi":"Dùng cho chi tiết vừa khổ giấy, tiện so sánh trực tiếp với chi tiết thật hoặc làm dưỡng.","ex_en":"Small fittings are usually drawn at full scale.","ex_ja":"小さな継手は通常、現尺で描く。","ex_vi":"Các chi tiết nối nhỏ thường được vẽ theo tỷ lệ nguyên hình.","syn_en":["1:1 scale","actual size"],"syn_ja":["原寸","原寸大 (khẩu ngữ)"]},{"en":"reduced scale","pos":"noun phrase","ipa":"/rɪˌdjuːst ˈskeɪl/","ja":"縮尺","kana":"しゅくしゃく","romaji":"shukushaku","vi":"tỷ lệ thu nhỏ","level":2,"def_vi":"Tỷ lệ nhỏ hơn 1:1 (như 1:2, 1:5, 1:10), dùng khi vật thể quá lớn so với khổ giấy.","def_en":"A scale smaller than 1:1, such as 1:2 or 1:10, used when the object is too large for the sheet.","def_ja":"1:2、1:10など、実物より小さく描く尺度。","usage_en":"Danh từ đếm được. Collocation: drawn at a reduced scale of 1:5; khẩu ngữ thường chỉ nói 'scale 1:5'.","usage_ja":"縮尺 là thuật ngữ chuẩn, cũng dùng rộng rãi trong bản đồ và kiến trúc. Cụm: 縮尺1:5で描く.","context_vi":"Dùng cho bản vẽ lắp máy lớn, khung máy, kết cấu thép và mặt bằng bố trí.","ex_en":"The frame is drawn at a reduced scale of 1:10.","ex_ja":"フレームは縮尺1:10で描かれている。","ex_vi":"Khung máy được vẽ theo tỷ lệ thu nhỏ 1:10.","syn_en":["reduction scale","scale-down (khẩu ngữ)"],"syn_ja":["縮小尺度"]},{"en":"enlarged scale","pos":"noun phrase","ipa":"/ɪnˌlɑːdʒd ˈskeɪl/","ja":"倍尺","kana":"ばいしゃく","romaji":"baishaku","vi":"tỷ lệ phóng to","level":2,"def_vi":"Tỷ lệ lớn hơn 1:1 (như 2:1, 5:1), dùng để vẽ chi tiết nhỏ hoặc phần chi tiết cần nhìn rõ.","def_en":"A scale larger than 1:1, such as 2:1 or 5:1, used for small parts or fine details.","def_ja":"2:1、5:1など、実物より大きく描く尺度。","usage_en":"Danh từ đếm được. Collocation: drawn at an enlarged scale of 5:1; thường đi cùng 'detail view'.","usage_ja":"倍尺 là thuật ngữ JIS; ngoài xưởng hay nói 拡大 hoặc '2倍'. Cụm: 倍尺5:1で描く.","context_vi":"Dùng cho linh kiện nhỏ, rãnh nhỏ, chi tiết đồng hồ hoặc hình trích phóng to.","ex_en":"The tiny spring clip is drawn at an enlarged scale of 5:1.","ex_ja":"小さなばねクリップは倍尺5:1で描いてある。","ex_vi":"Kẹp lò xo nhỏ được vẽ theo tỷ lệ phóng to 5:1.","syn_en":["enlargement scale","magnified scale"],"syn_ja":["拡大尺度"]},{"en":"drawing number","pos":"noun phrase","ipa":"/ˈdrɔːɪŋ ˌnʌmbə/","ja":"図面番号","kana":"ずめんばんごう","romaji":"zumenbangou","vi":"số bản vẽ","level":2,"def_vi":"Mã định danh duy nhất của bản vẽ, ghi trong khung tên, dùng để tra cứu, quản lý và đặt hàng.","def_en":"The unique identifier of a drawing, shown in the title block and used for filing and ordering.","def_ja":"図面を識別する固有の番号で、表題欄に記入し、管理や発注に用いる。","usage_en":"Danh từ đếm được; viết tắt 'DWG No.' hoặc 'drawing no.'. Collocation: assign / quote a drawing number.","usage_ja":"Khẩu ngữ rất hay nói tắt 図番 (ずばん). Cụm: 図番を採番する, 図番で検索する.","context_vi":"Dùng khi đặt hàng gia công, tra cứu lưu trữ, ghi trong danh mục vật tư và phiếu yêu cầu thay đổi.","ex_en":"Please quote the drawing number on every purchase order.","ex_ja":"すべての注文書に図面番号を記載してください。","ex_vi":"Vui lòng ghi số bản vẽ trên mọi đơn đặt hàng.","syn_en":["DWG No.","part number (liên quan)"],"syn_ja":["図番 (khẩu ngữ)"]},{"en":"assembly drawing","pos":"noun phrase","ipa":"/əˈsembli ˌdrɔːɪŋ/","ja":"組立図","kana":"くみたてず","romaji":"kumitatezu","vi":"bản vẽ lắp","level":2,"def_vi":"Bản vẽ thể hiện cách các chi tiết lắp với nhau thành bộ phận hoặc máy, kèm số vị trí và bảng kê chi tiết.","def_en":"A drawing that shows how parts fit together into a unit, with item numbers and a parts list.","def_ja":"部品の組み合わせ方と相互関係を示し、照合番号と部品欄をもつ図面。","usage_en":"Danh từ đếm được. Collocation: general assembly drawing (GA), sub-assembly drawing; refer to the assembly drawing.","usage_ja":"組立図 đối lập với 部品図; bản lắp tổng gọi 総組立図, bản lắp cụm gọi 部分組立図. Cụm: 組立図を見て組み付ける.","context_vi":"Dùng ở xưởng lắp ráp, bảo trì và khi lập danh mục vật tư cho sản phẩm.","ex_en":"Item 7 on the assembly drawing is the oil seal.","ex_ja":"組立図の照合番号7はオイルシールです。","ex_vi":"Chi tiết số 7 trên bản vẽ lắp là phớt chắn dầu.","syn_en":["GA drawing (general assembly)","assembly (khẩu ngữ)"],"syn_ja":["総組立図 (nghĩa hẹp hơn)","アッセンブリ図 (khẩu ngữ)"]},{"en":"part drawing","pos":"noun phrase","ipa":"/ˈpɑːt ˌdrɔːɪŋ/","ja":"部品図","kana":"ぶひんず","romaji":"buhinzu","vi":"bản vẽ chi tiết","level":2,"def_vi":"Bản vẽ của một chi tiết riêng lẻ, có đủ hình chiếu, kích thước, dung sai và yêu cầu kỹ thuật để chế tạo.","def_en":"A drawing of a single part containing all views, dimensions and requirements needed to make it.","def_ja":"一つの部品について、製作に必要な形状・寸法・公差などをすべて示した図面。","usage_en":"Danh từ đếm được; cũng hay gọi 'detail drawing'. Collocation: issue a part drawing to the machine shop.","usage_ja":"部品図 dùng cho từng chi tiết; trong xưởng còn nói 単品図. Cụm: 部品図を出図する.","context_vi":"Được gửi xuống xưởng gia công hoặc nhà cung cấp để chế tạo và kiểm tra từng chi tiết.","ex_en":"Each machined component needs its own part drawing.","ex_ja":"機械加工部品には、それぞれ部品図が必要である。","ex_vi":"Mỗi chi tiết gia công cơ cần có bản vẽ chi tiết riêng.","syn_en":["detail drawing","component drawing"],"syn_ja":["単品図 (khẩu ngữ)","詳細図 (liên quan)"]},{"en":"drafting machine","pos":"noun phrase","ipa":"/ˈdrɑːftɪŋ məˌʃiːn/","ja":"製図機械","kana":"せいずきかい","romaji":"seizukikai","vi":"máy vẽ (thước vẽ tay đòn)","level":2,"def_vi":"Thiết bị gắn trên bàn vẽ, có hai thước vuông góc trên đầu xoay, dùng để kẻ đường song song và đường xiên góc bất kỳ.","def_en":"A board-mounted device with two perpendicular scales on a rotating head for drawing parallel and angled lines.","def_ja":"製図板に取り付け、回転する頭部の直交する定規で平行線や任意角度の線を引く装置。","usage_en":"Danh từ đếm được; ít dùng từ khi có CAD. Collocation: set the angle on the drafting machine head.","usage_ja":"Thuật ngữ chuẩn là 製図機械, nhưng hầu như ai cũng gọi theo tên thương mại ドラフター. Cụm: ドラフターで線を引く.","context_vi":"Còn gặp ở trường kỹ thuật, kỳ thi tay nghề và các phòng thiết kế cũ.","ex_en":"Students still learn on a drafting machine before moving to CAD.","ex_ja":"学生はCADに移る前に、製図機械で手描きを学ぶ。","ex_vi":"Sinh viên vẫn học vẽ trên máy vẽ trước khi chuyển sang CAD.","syn_en":["drafting arm","track drafter"],"syn_ja":["ドラフター (tên thương mại)","平行定規 (liên quan)"]},{"en":"blueprint","pos":"noun","ipa":"/ˈbluːprɪnt/","ja":"青図","kana":"あおず","romaji":"aozu","vi":"bản in lam (bản vẽ in)","level":2,"def_vi":"Bản sao bản vẽ in bằng phương pháp hóa học cũ có màu xanh; nay dùng chỉ chung bản vẽ in phát xuống xưởng.","def_en":"A copy of a drawing made by an old blue chemical process; now loosely any printed drawing.","def_ja":"感光紙による青色の複写図。現在は印刷した図面全般を指すこともある。","usage_en":"Danh từ đếm được; nghĩa bóng là 'kế hoạch chi tiết'. Collocation: read blueprints; 'blueprint reading' là kỹ năng đọc bản vẽ.","usage_ja":"青図 (hay 青焼き) là bản sao kiểu cũ; ngày nay xưởng chỉ gọi 図面. Cụm: 青焼きを取る.","context_vi":"Gặp trong tài liệu cũ, xưởng lâu năm và các khóa 'đọc bản vẽ' (blueprint reading) ở Mỹ.","ex_en":"The old pump drawings exist only as faded blueprints.","ex_ja":"古いポンプの図面は、色あせた青図しか残っていない。","ex_vi":"Các bản vẽ bơm cũ chỉ còn lại dưới dạng bản in lam đã phai màu.","syn_en":["print","copy drawing"],"syn_ja":["青焼き","複写図"]},{"en":"drawing check","pos":"noun phrase","ipa":"/ˈdrɔːɪŋ tʃek/","ja":"検図","kana":"けんず","romaji":"kenzu","vi":"kiểm tra bản vẽ (soát bản vẽ)","level":3,"def_vi":"Việc người thứ hai soát lại hình chiếu, kích thước, dung sai, vật liệu của bản vẽ trước khi duyệt và phát hành.","def_en":"A review of a drawing by a second person for errors in views, dimensions and tolerances before release.","def_ja":"出図前に、投影・寸法・公差などの誤りを作成者以外が確認すること。","usage_en":"Danh từ đếm được hoặc không. Collocation: carry out a drawing check, pass the drawing check; ô 'checked by' trong khung tên ghi người kiểm.","usage_ja":"検図 rất hay dùng ở công ty Nhật; động từ 検図する, người kiểm gọi 検図者. Các ô ký trong khung tên: 設計・製図・検図・承認.","context_vi":"Là bước bắt buộc trong quy trình phát hành bản vẽ của công ty Nhật và nhà máy áp dụng ISO 9001.","ex_en":"The drawing check found two missing tolerances on the bore.","ex_ja":"検図で、穴の公差の記入漏れが2か所見つかった。","ex_vi":"Đợt kiểm tra bản vẽ phát hiện hai chỗ thiếu dung sai trên lỗ.","syn_en":["drawing review","checking (liên quan)"],"syn_ja":["図面チェック (khẩu ngữ)","図面審査"]},{"en":"manufacturing drawing","pos":"noun phrase","ipa":"/ˌmænjuˈfæktʃərɪŋ ˌdrɔːɪŋ/","ja":"製作図","kana":"せいさくず","romaji":"seisakuzu","vi":"bản vẽ chế tạo","level":3,"def_vi":"Bản vẽ chứa đầy đủ thông tin cần để chế tạo sản phẩm, phân biệt với bản vẽ phương án hay bản vẽ bố trí sơ bộ.","def_en":"A drawing giving all information needed to manufacture a product, as opposed to a concept or layout drawing.","def_ja":"製品の製作に必要なすべての情報を示した図面。計画図などと区別する。","usage_en":"Danh từ đếm được. Collocation: release manufacturing drawings, convert a layout into manufacturing drawings.","usage_ja":"Phân loại theo mục đích trong JIS: 計画図 → 製作図; ngành kết cấu thép gọi 工作図. Cụm: 製作図を作成する.","context_vi":"Dùng khi chuyển từ giai đoạn thiết kế sang sản xuất, gửi cho xưởng hoặc nhà thầu chế tạo.","ex_en":"Manufacturing drawings will be released after the prototype is approved.","ex_ja":"試作品の承認後に製作図を出図する。","ex_vi":"Bản vẽ chế tạo sẽ được phát hành sau khi mẫu thử được phê duyệt.","syn_en":["production drawing","working drawing"],"syn_ja":["工作図 (kết cấu thép, liên quan)","詳細図 (liên quan)"]},{"en":"thick chain line","pos":"noun phrase","ipa":"/ˌθɪk ˈtʃeɪn laɪn/","ja":"特殊指定線","kana":"とくしゅしていせん","romaji":"tokushushiteisen","vi":"nét chấm gạch đậm (chỉ vùng yêu cầu đặc biệt)","level":3,"def_vi":"Nét chấm gạch đậm vẽ song song bề mặt, chỉ phạm vi cần xử lý hoặc yêu cầu đặc biệt như tôi cao tần, mạ.","def_en":"A thick chain line drawn beside a surface to show the area requiring special treatment, such as hardening.","def_ja":"表面に沿って描き、熱処理など特殊な加工を必要とする範囲を示す太い一点鎖線。","usage_en":"Danh từ đếm được. Collocation: indicate the hardened zone with a thick chain line; luôn kèm chú thích yêu cầu và kích thước phạm vi.","usage_ja":"特殊指定線 là tên theo mục đích, vẽ bằng 太い一点鎖線. Cụm: 特殊指定線で範囲を示す.","context_vi":"Gặp trên bản vẽ trục có đoạn tôi cứng, vùng mạ, vùng không sơn hoặc vùng gia công đặc biệt.","ex_en":"The induction-hardened zone is marked with a thick chain line.","ex_ja":"高周波焼入れの範囲は特殊指定線で示す。","ex_vi":"Vùng tôi cao tần được đánh dấu bằng nét chấm gạch đậm.","syn_en":["special-requirement line","thick long-dashed dotted line"],"syn_ja":["太い一点鎖線"]},{"en":"centring mark","pos":"noun phrase","ipa":"/ˈsentərɪŋ mɑːk/","ja":"中心マーク","kana":"ちゅうしんマーク","romaji":"chuushinmaaku","vi":"dấu định tâm (khung bản vẽ)","level":3,"def_vi":"Các vạch ngắn ở giữa bốn cạnh khung bản vẽ, giúp định vị khi sao chụp, chụp vi phim hoặc quét bản vẽ.","def_en":"Short lines at the midpoint of each border side used to position the drawing when copying or scanning.","def_ja":"輪郭の各辺の中央に設け、複写やマイクロ撮影の際の位置決めに用いる線。","usage_en":"Danh từ đếm được, thường dùng số nhiều. Mỹ viết 'centering mark'. Collocation: centring marks on all four sides.","usage_ja":"Thuật ngữ JIS Z 8311 中心マーク, vẽ bằng nét liền đậm. Ít nói trong xưởng, chủ yếu gặp trong mẫu khung bản vẽ CAD.","context_vi":"Gặp trong tiêu chuẩn trình bày bản vẽ và khi thiết lập khung bản vẽ trong phần mềm CAD.","ex_en":"Our CAD template already includes a centring mark on each of the four sides.","ex_ja":"当社のCADテンプレートには、四辺それぞれに中心マークが入っている。","ex_vi":"Mẫu CAD của chúng tôi đã có sẵn dấu định tâm ở cả bốn cạnh.","syn_en":["centering mark (Mỹ)","centre mark"],"syn_ja":["センターマーク"]}]},{"id":12,"words":[{"en":"projection","pos":"noun","ipa":"/prəˈdʒekʃn/","ja":"投影","kana":"とうえい","romaji":"touei","vi":"phép chiếu","level":1,"def_vi":"Cách biểu diễn vật thể ba chiều lên mặt phẳng bằng các tia chiếu đi qua các điểm của vật thể.","def_en":"A method of representing a three-dimensional object on a plane using projecting lines through its points.","def_ja":"投影線を用いて、立体の形を平面上に表す方法。","usage_en":"Danh từ, vừa đếm được (a projection = một hình chiếu) vừa không đếm được (phương pháp). Collocation: method of projection, orthographic / oblique / perspective projection.","usage_ja":"投影 chỉ phép chiếu; hình chiếu cụ thể gọi 投影図. Ghép: 投影法, 投影線, 投影面; động từ: 投影する.","context_vi":"Là nền tảng của môn vẽ kỹ thuật; mọi hình chiếu, hình cắt đều xây dựng từ phép chiếu.","ex_en":"Choose the method of projection before laying out the views.","ex_ja":"投影図を配置する前に、投影の方法を決めておくこと。","ex_vi":"Hãy chọn phương pháp chiếu trước khi bố trí các hình chiếu.","syn_en":["projection method (liên quan)","view (liên quan)"],"syn_ja":["投影法","投象 (cách viết cũ)"]},{"en":"orthographic projection","pos":"noun phrase","ipa":"/ˌɔːθəˈɡræfɪk prəˈdʒekʃn/","ja":"正投影","kana":"せいとうえい","romaji":"seitouei","vi":"phép chiếu vuông góc","level":1,"def_vi":"Phép chiếu có các tia chiếu song song và vuông góc với mặt phẳng hình chiếu, cho hình đúng kích thước.","def_en":"Projection with parallel projecting lines perpendicular to the projection plane, giving true shapes and sizes.","def_ja":"投影線が投影面に垂直で互いに平行な投影。形と大きさを正しく表せる。","usage_en":"Danh từ không đếm được khi nói về phương pháp. Collocation: in orthographic projection, an orthographic view; khẩu ngữ: 'orthographic drawing', 'multiview drawing'.","usage_ja":"正投影 dùng trong văn bản; bản vẽ dùng phép chiếu này gọi 正投影図. Ghép: 正投影法, 正投影図で描く.","context_vi":"Là phương pháp chuẩn của bản vẽ chi tiết và bản vẽ lắp trong cơ khí.","ex_en":"Mechanical part drawings are normally prepared in orthographic projection.","ex_ja":"機械部品の図面は、通常、正投影で作成する。","ex_vi":"Bản vẽ chi tiết máy thường được lập theo phép chiếu vuông góc.","syn_en":["orthogonal projection","multiview projection"],"syn_ja":["正投影法","直投影 (ít dùng)"]},{"en":"front view","pos":"noun phrase","ipa":"/ˌfrʌnt ˈvjuː/","ja":"正面図","kana":"しょうめんず","romaji":"shoumenzu","vi":"hình chiếu đứng","level":1,"def_vi":"Hình chiếu nhìn từ phía trước, thể hiện rõ nhất hình dạng đặc trưng của vật thể và là hình chiếu chính.","def_en":"The view looking at the object from the front, normally chosen to show its most characteristic shape.","def_ja":"対象物を正面から見た図で、形状の特徴を最もよく表すように選ぶ。","usage_en":"Danh từ đếm được. Collocation: in the front view, project the top view from the front view; Mỹ còn gọi 'front elevation'.","usage_ja":"正面図 thường là 主投影図; vị trí các hình khác đặt theo 正面図. Cụm: 正面図に寸法を集める.","context_vi":"Là hình chiếu đầu tiên được chọn khi lập bản vẽ; phần lớn kích thước được ghi trên hình này.","ex_en":"Most of the dimensions are given in the front view.","ex_ja":"寸法の大部分は正面図に記入されている。","ex_vi":"Phần lớn kích thước được ghi trên hình chiếu đứng.","syn_en":["front elevation","main view (liên quan)"],"syn_ja":["主投影図 (liên quan)"]},{"en":"top view","pos":"noun phrase","ipa":"/ˌtɒp ˈvjuː/","ja":"平面図","kana":"へいめんず","romaji":"heimenzu","vi":"hình chiếu bằng","level":1,"def_vi":"Hình chiếu nhìn từ trên xuống, thể hiện chiều dài và chiều rộng của vật thể.","def_en":"The view looking down on the object from above, showing its length and width.","def_ja":"対象物を上から見た図で、長さと幅を表す。","usage_en":"Danh từ đếm được; Anh-Anh hay gọi 'plan' hoặc 'plan view'. Collocation: shown in the top view.","usage_ja":"平面図 dùng cả trong cơ khí và kiến trúc (nghĩa mặt bằng). Trong phép chiếu góc thứ ba, 平面図 đặt phía trên 正面図.","context_vi":"Dùng để thể hiện bố trí lỗ, rãnh trên mặt trên của chi tiết và mặt bằng bố trí thiết bị.","ex_en":"The four mounting holes are clearly visible in the top view.","ex_ja":"4つの取付け穴は平面図ではっきり見える。","ex_vi":"Bốn lỗ bắt chân thể hiện rõ trên hình chiếu bằng.","syn_en":["plan view","plan (Anh-Anh)"],"syn_ja":["上面図"]},{"en":"side view","pos":"noun phrase","ipa":"/ˌsaɪd ˈvjuː/","ja":"側面図","kana":"そくめんず","romaji":"sokumenzu","vi":"hình chiếu cạnh","level":1,"def_vi":"Hình chiếu nhìn từ bên trái hoặc bên phải vật thể, thể hiện chiều cao và chiều rộng.","def_en":"The view looking at the object from the left or right side, showing its height and depth.","def_ja":"対象物を左または右から見た図。","usage_en":"Danh từ đếm được; nói rõ: right side view, left side view. Mỹ còn gọi 'side elevation'.","usage_ja":"JIS phân biệt 右側面図 và 左側面図; nói chung gọi 側面図. Cụm: 側面図を追加する.","context_vi":"Bổ sung cho hình chiếu đứng và hình chiếu bằng để xác định đầy đủ hình dạng chi tiết.","ex_en":"A right side view is needed to show the slot depth.","ex_ja":"溝の深さを示すため、右側面図が必要である。","ex_vi":"Cần thêm hình chiếu cạnh phải để thể hiện chiều sâu rãnh.","syn_en":["side elevation","end view"],"syn_ja":["右側面図 (nghĩa hẹp hơn)","左側面図 (nghĩa hẹp hơn)"]},{"en":"third-angle projection","pos":"noun phrase","ipa":"/ˌθɜːd ˌæŋɡl prəˈdʒekʃn/","ja":"第三角法","kana":"だいさんかくほう","romaji":"daisankakuhou","vi":"phương pháp chiếu góc thứ ba","level":1,"def_vi":"Cách bố trí hình chiếu trong đó hình nhìn từ phía nào được đặt về chính phía đó so với hình chiếu đứng.","def_en":"A layout in which each view is placed on the same side of the front view as the direction it is viewed from.","def_ja":"見る側と同じ側に投影図を配置する投影法。日本や米国で標準。","usage_en":"Danh từ không đếm được. Collocation: drawn in third-angle projection; ký hiệu phép chiếu (projection symbol) ghi trong khung tên.","usage_ja":"JIS B 0001 lấy 第三角法 làm chuẩn; khẩu ngữ gọi 三角法. Cụm: 第三角法で描く, 第三角法の記号.","context_vi":"Chuẩn ở Nhật Bản, Mỹ; khi làm với khách Nhật cần chú ý vì sách giáo khoa Việt Nam dùng góc thứ nhất.","ex_en":"Japanese customers' drawings are always in third-angle projection.","ex_ja":"日本の顧客の図面は必ず第三角法で描かれている。","ex_vi":"Bản vẽ của khách hàng Nhật luôn dùng phương pháp chiếu góc thứ ba.","syn_en":["third-angle method","American projection (khẩu ngữ)"],"syn_ja":["三角法 (khẩu ngữ)","第三角投影法"]},{"en":"first-angle projection","pos":"noun phrase","ipa":"/ˌfɜːst ˌæŋɡl prəˈdʒekʃn/","ja":"第一角法","kana":"だいいっかくほう","romaji":"daiikkakuhou","vi":"phương pháp chiếu góc thứ nhất","level":1,"def_vi":"Cách bố trí hình chiếu trong đó hình nhìn từ phía nào được đặt ở phía đối diện so với hình chiếu đứng.","def_en":"A layout in which each view is placed on the side of the front view opposite to the viewing direction.","def_ja":"見る側と反対側に投影図を配置する投影法。欧州などで用いる。","usage_en":"Danh từ không đếm được. Collocation: drawn in first-angle projection; còn gọi 'European projection'.","usage_ja":"第一角法 được JIS cho phép nhưng ít dùng ở Nhật; khẩu ngữ gọi 一角法. Cụm: 第一角法の記号を表題欄に示す.","context_vi":"Chuẩn ở châu Âu và trong TCVN (sách vẽ kỹ thuật Việt Nam); cần đọc ký hiệu phép chiếu để tránh đọc nhầm.","ex_en":"The German supplier's drawing uses first-angle projection, so the views are swapped.","ex_ja":"ドイツの仕入先の図面は第一角法なので、投影図の配置が逆になっている。","ex_vi":"Bản vẽ của nhà cung cấp Đức dùng phương pháp chiếu góc thứ nhất nên vị trí các hình chiếu bị đảo.","syn_en":["first-angle method","European projection (khẩu ngữ)"],"syn_ja":["一角法 (khẩu ngữ)","第一角投影法"]},{"en":"sectional view","pos":"noun phrase","ipa":"/ˈsekʃənl vjuː/","ja":"断面図","kana":"だんめんず","romaji":"danmenzu","vi":"hình cắt","level":1,"def_vi":"Hình biểu diễn phần vật thể sau khi tưởng tượng cắt bỏ một phần bằng mặt phẳng cắt, để thấy rõ cấu tạo bên trong.","def_en":"A view drawn as if part of the object were cut away by a cutting plane, revealing internal features.","def_ja":"対象物を仮想的に切断し、内部の形状を表した図。","usage_en":"Danh từ đếm được; khẩu ngữ hay nói 'section' hoặc 'section view': section A-A. Collocation: draw a sectional view, shown in section.","usage_ja":"断面図 dùng cả trong JIS và xưởng; cụ thể gọi A-A断面. Cụm: 断面図で示す, 断面にする.","context_vi":"Dùng thay cho nhiều đường khuất khi chi tiết có lỗ, rãnh, hốc bên trong như vỏ bơm, mặt bích, ống lót.","ex_en":"A sectional view makes the internal oil passages much easier to read.","ex_ja":"断面図にすると、内部の油路がずっと読みやすくなる。","ex_vi":"Vẽ hình cắt giúp đọc các đường dầu bên trong dễ hơn nhiều.","syn_en":["section view","section"],"syn_ja":["断面 (khẩu ngữ)","切断図 (ít dùng)"]},{"en":"hatching","pos":"noun","ipa":"/ˈhætʃɪŋ/","ja":"ハッチング","kana":"ハッチング","romaji":"hatchingu","vi":"đường gạch gạch mặt cắt","level":1,"def_vi":"Các nét mảnh song song, thường nghiêng 45°, vẽ trên phần mặt cắt để phân biệt phần vật liệu bị cắt.","def_en":"Thin parallel lines, usually at 45°, drawn on cut surfaces in a sectional view.","def_ja":"断面であることを示すため、切り口に施す細い平行線。通常45°に引く。","usage_en":"Danh từ không đếm được. Collocation: apply hatching, hatching at 45°, reverse the hatching on adjacent parts; Mỹ cũng gọi 'section lining'.","usage_ja":"Viết katakana ハッチング; động từ ハッチングを施す, ハッチングを入れる. Phần tô màu đặc gọi スマッジング.","context_vi":"Có trên mọi hình cắt; trên bản vẽ lắp, các chi tiết kề nhau được gạch khác hướng hoặc khác khoảng cách.","ex_en":"Use opposite hatching directions for the shaft and the housing.","ex_ja":"軸とハウジングのハッチングは向きを逆にすること。","ex_vi":"Gạch mặt cắt của trục và vỏ theo hai hướng ngược nhau.","syn_en":["section lining (Mỹ)","cross-hatching"],"syn_ja":["スマッジング (liên quan)"]},{"en":"isometric drawing","pos":"noun phrase","ipa":"/ˌaɪsəˈmetrɪk ˈdrɔːɪŋ/","ja":"等角図","kana":"とうかくず","romaji":"toukakuzu","vi":"hình chiếu trục đo vuông góc đều (hình đẳng cự)","level":1,"def_vi":"Hình vẽ ba chiều có ba trục nghiêng đều 120° với nhau, các cạnh theo trục vẽ đúng chiều dài thật.","def_en":"A pictorial drawing whose three axes are 120° apart, with lengths along the axes drawn at true size.","def_ja":"三つの軸が互いに120°をなし、軸方向の長さを実長で描く立体図。","usage_en":"Danh từ đếm được; khẩu ngữ gọi 'isometric' hoặc 'iso view'. Collocation: an isometric drawing of the bracket, isometric view in CAD.","usage_ja":"等角図 (vẽ đúng chiều dài) khác 等角投影図 (thu nhỏ khoảng 0,82). Khẩu ngữ: アイソメ, アイソメ図.","context_vi":"Dùng trong hướng dẫn lắp ráp, catalog, sơ đồ đường ống (isometric) và để minh họa chi tiết cho người không chuyên.","ex_en":"Add an isometric drawing in the corner so the operators understand the part quickly.","ex_ja":"作業者がすぐ形状を理解できるよう、隅に等角図を追加する。","ex_vi":"Thêm một hình đẳng cự ở góc bản vẽ để công nhân hiểu nhanh hình dạng chi tiết.","syn_en":["isometric view","iso (khẩu ngữ)"],"syn_ja":["アイソメ図 (khẩu ngữ)","等角投影図 (gần nghĩa)"]},{"en":"pictorial drawing","pos":"noun phrase","ipa":"/pɪkˈtɔːriəl ˈdrɔːɪŋ/","ja":"立体図","kana":"りったいず","romaji":"rittaizu","vi":"hình biểu diễn không gian (hình nổi)","level":2,"def_vi":"Hình vẽ thể hiện vật thể dưới dạng ba chiều trên một hình duy nhất, như hình trục đo hoặc hình phối cảnh.","def_en":"A drawing showing an object in three dimensions in a single view, such as isometric or perspective.","def_ja":"等角図や透視図のように、一つの図で対象物を立体的に表した図。","usage_en":"Danh từ đếm được, là tên chung (nghĩa rộng) cho isometric, oblique, perspective drawings. Collocation: include a pictorial drawing for reference.","usage_ja":"立体図 là cách gọi chung; trong xưởng hay gọi 斜視図 hoặc 3D図. Bản phác tay dạng nổi gọi 見取図.","context_vi":"Dùng trong hướng dẫn lắp ráp, tài liệu đào tạo và phần minh họa của bản vẽ.","ex_en":"A small pictorial drawing helps new staff understand the assembly.","ex_ja":"小さな立体図を入れると、新人でも組立品を理解しやすい。","ex_vi":"Một hình nổi nhỏ giúp nhân viên mới hiểu cụm lắp dễ hơn.","syn_en":["pictorial view","3D view (khẩu ngữ)"],"syn_ja":["斜視図","見取図"]},{"en":"bottom view","pos":"noun phrase","ipa":"/ˌbɒtəm ˈvjuː/","ja":"下面図","kana":"かめんず","romaji":"kamenzu","vi":"hình chiếu từ dưới","level":2,"def_vi":"Hình chiếu nhìn từ dưới lên, dùng khi mặt đáy có hình dạng hoặc lỗ cần thể hiện.","def_en":"The view looking up at the object from below, used when the underside has features to show.","def_ja":"対象物を下から見た図。","usage_en":"Danh từ đếm được. Collocation: add a bottom view, shown in the bottom view.","usage_ja":"下面図 đọc かめんず, ít dùng hơn 平面図; trong phép chiếu góc thứ ba, nó đặt phía dưới 正面図.","context_vi":"Dùng cho chi tiết có lỗ bắt chân, rãnh hoặc gân ở mặt đáy như đế máy, vỏ hộp.","ex_en":"The ribs on the base are only visible in the bottom view.","ex_ja":"ベースのリブは下面図でしか見えない。","ex_vi":"Các gân của đế máy chỉ thấy trên hình chiếu từ dưới.","syn_en":["underside view","bottom plan"],"syn_ja":["底面図"]},{"en":"rear view","pos":"noun phrase","ipa":"/ˌrɪə ˈvjuː/","ja":"背面図","kana":"はいめんず","romaji":"haimenzu","vi":"hình chiếu từ sau","level":2,"def_vi":"Hình chiếu nhìn từ phía sau vật thể, ngược hướng với hình chiếu đứng.","def_en":"The view looking at the object from behind, opposite to the front view.","def_ja":"対象物を後ろから見た図。","usage_en":"Danh từ đếm được; còn gọi 'back view'. Collocation: shown in the rear view.","usage_ja":"背面図 dùng cho tủ điện, máy móc có cổng nối, đầu nối ở mặt sau. Cụm: 背面図を追加する.","context_vi":"Dùng cho tủ điều khiển, vỏ máy, thiết bị có cổng nối hoặc tấm che ở mặt sau.","ex_en":"The cable entries are shown in the rear view of the control box.","ex_ja":"制御ボックスのケーブル引込口は背面図に示している。","ex_vi":"Các lỗ luồn cáp được thể hiện trên hình chiếu từ sau của hộp điều khiển.","syn_en":["back view","rear elevation"],"syn_ja":["裏面図 (ít dùng)"]},{"en":"auxiliary view","pos":"noun phrase","ipa":"/ɔːɡˈzɪliəri vjuː/","ja":"補助投影図","kana":"ほじょとうえいず","romaji":"hojotoueizu","vi":"hình chiếu phụ","level":2,"def_vi":"Hình chiếu lên mặt phẳng song song với một bề mặt nghiêng, để thể hiện đúng hình dạng thật của bề mặt đó.","def_en":"A view projected onto a plane parallel to an inclined surface to show its true shape.","def_ja":"斜面に平行な投影面に投影し、斜面の実形を表した図。","usage_en":"Danh từ đếm được. Collocation: project an auxiliary view from the inclined face; primary / secondary auxiliary view.","usage_ja":"補助投影図 đọc ほじょとうえいず; thường chỉ vẽ phần bề mặt nghiêng, kèm mũi tên và chữ chỉ hướng nhìn. Cụm: 補助投影図で実形を示す.","context_vi":"Dùng cho chi tiết có mặt vát, tai nghiêng, mặt bích nghiêng như thân van, giá đỡ nghiêng.","ex_en":"An auxiliary view shows the true shape of the angled mounting face.","ex_ja":"傾いた取付け面の実形を補助投影図で示している。","ex_vi":"Hình chiếu phụ thể hiện hình dạng thật của mặt lắp nghiêng.","syn_en":["auxiliary projection","inclined view (liên quan)"],"syn_ja":["補助図 (khẩu ngữ)"]},{"en":"partial view","pos":"noun phrase","ipa":"/ˌpɑːʃl ˈvjuː/","ja":"部分投影図","kana":"ぶぶんとうえいず","romaji":"bubuntoueizu","vi":"hình chiếu riêng phần","level":2,"def_vi":"Hình chiếu chỉ vẽ một phần của vật thể, đủ để thể hiện đặc điểm cần thiết, phần còn lại giới hạn bằng nét lượn sóng.","def_en":"A view showing only the necessary portion of an object, limited by a break line.","def_ja":"図の一部だけを示せば足りる場合に、必要な部分だけを描いた投影図。","usage_en":"Danh từ đếm được. Collocation: a partial view is sufficient; draw a partial view of the keyway.","usage_ja":"部分投影図 giới hạn bằng 破断線; khác với 局部投影図 (chỉ vẽ một chi tiết cục bộ như rãnh then). Cụm: 部分投影図で示す.","context_vi":"Dùng để tiết kiệm diện tích bản vẽ khi chỉ một phần của hình chiếu là có thông tin mới.","ex_en":"A partial view of the flange is enough to show the bolt pattern.","ex_ja":"ボルト穴の配置は、フランジの部分投影図で十分に示せる。","ex_vi":"Chỉ cần hình chiếu riêng phần của mặt bích là đủ thể hiện bố trí lỗ bu lông.","syn_en":["broken view (gần nghĩa)","local view (liên quan)"],"syn_ja":["部分図 (khẩu ngữ)"]},{"en":"detail view","pos":"noun phrase","ipa":"/ˈdiːteɪl vjuː/","ja":"部分拡大図","kana":"ぶぶんかくだいず","romaji":"bubunkakudaizu","vi":"hình trích (hình phóng to)","level":2,"def_vi":"Hình vẽ phóng to một vùng nhỏ của vật thể, được khoanh tròn và ký hiệu bằng chữ trên hình chiếu gốc.","def_en":"An enlarged view of a small area, circled and labelled with a letter on the main view.","def_ja":"細部を見やすくするため、該当部分を円で囲み、文字を付けて拡大して描いた図。","usage_en":"Danh từ đếm được. Collocation: see detail A, detail view at scale 5:1; khẩu ngữ chỉ nói 'detail A'.","usage_ja":"部分拡大図 ghi kèm chữ và 尺度, ví dụ 'A部拡大図 (5:1)'. Khẩu ngữ: 拡大図, A部詳細.","context_vi":"Dùng cho rãnh phanh, bán kính góc lượn nhỏ, rãnh phớt, ren nhỏ khó ghi kích thước trên hình chính.","ex_en":"The O-ring groove dimensions are given in detail view A at 5:1.","ex_ja":"Oリング溝の寸法は、5:1のA部の部分拡大図に記入している。","ex_vi":"Kích thước rãnh lắp vòng O được ghi trên hình trích A tỷ lệ 5:1.","syn_en":["enlarged view","detail (khẩu ngữ)"],"syn_ja":["拡大図","詳細図 (liên quan)"]},{"en":"principal view","pos":"noun phrase","ipa":"/ˈprɪnsəpl vjuː/","ja":"主投影図","kana":"しゅとうえいず","romaji":"shutoueizu","vi":"hình chiếu chính","level":2,"def_vi":"Hình chiếu thể hiện nhiều thông tin nhất về hình dạng và chức năng của vật thể, được chọn làm hình chiếu gốc.","def_en":"The most informative view of an object, chosen as the reference from which other views are arranged.","def_ja":"対象物の形状や機能を最も明瞭に表す投影図で、他の図の基準となる。","usage_en":"Danh từ đếm được; thường trùng với front view. Collocation: choose the principal view, the principal view should show the part in its machining position.","usage_ja":"主投影図 là thuật ngữ JIS; quy tắc: chọn hướng thể hiện rõ đặc trưng và tư thế gia công. Khẩu ngữ: メインビュー.","context_vi":"Là quyết định đầu tiên khi bố trí bản vẽ; trục thường vẽ nằm ngang như tư thế tiện.","ex_en":"For a turned shaft, the principal view shows the axis horizontally.","ex_ja":"旋削する軸では、軸線を水平にした図を主投影図とする。","ex_vi":"Với trục tiện, hình chiếu chính thể hiện trục nằm ngang.","syn_en":["main view","front view (thường trùng)"],"syn_ja":["正面図 (thường trùng)","メインビュー (khẩu ngữ)"]},{"en":"projection plane","pos":"noun phrase","ipa":"/prəˈdʒekʃn pleɪn/","ja":"投影面","kana":"とうえいめん","romaji":"toueimen","vi":"mặt phẳng hình chiếu","level":2,"def_vi":"Mặt phẳng tưởng tượng mà hình dạng vật thể được chiếu lên để tạo ra hình chiếu.","def_en":"The imaginary plane onto which the shape of an object is projected to form a view.","def_ja":"対象物の形を投影して図を得るための仮想の平面。","usage_en":"Danh từ đếm được. Collocation: horizontal / vertical / profile projection plane; parallel to the projection plane.","usage_ja":"Ghép: 立画面 (mặt phẳng đứng), 平画面 (mặt phẳng bằng), 側画面 (mặt phẳng cạnh). Cụm: 投影面に平行な面.","context_vi":"Gặp trong môn hình họa và khi giải thích phép chiếu góc thứ nhất, góc thứ ba.","ex_en":"A face parallel to the projection plane appears in its true shape.","ex_ja":"投影面に平行な面は実形で表れる。","ex_vi":"Mặt song song với mặt phẳng hình chiếu được thể hiện đúng hình dạng thật.","syn_en":["plane of projection","picture plane (phối cảnh)"],"syn_ja":["画面 (liên quan)"]},{"en":"cutting plane line","pos":"noun phrase","ipa":"/ˈkʌtɪŋ pleɪn laɪn/","ja":"切断線","kana":"せつだんせん","romaji":"setsudansen","vi":"nét cắt (vết mặt phẳng cắt)","level":2,"def_vi":"Nét chỉ vị trí mặt phẳng cắt trên hình chiếu, có nét đậm ở hai đầu, mũi tên chỉ hướng nhìn và chữ ký hiệu.","def_en":"A line on a view showing where the cutting plane passes, with arrows for viewing direction and letters.","def_ja":"断面の切断位置を示す線。両端を太くし、矢印と文字で投影方向と名称を示す。","usage_en":"Danh từ đếm được. Collocation: label the cutting plane line A-A; arrows on the cutting plane line show the viewing direction.","usage_ja":"切断線 vẽ bằng 細い一点鎖線 với hai đầu và chỗ gấp vẽ đậm. Cụm: 切断線を記入する, 切断線A-A.","context_vi":"Luôn đi kèm hình cắt để người đọc biết hình cắt được lấy ở đâu và nhìn theo hướng nào.","ex_en":"The cutting plane line A-A passes through the centre of the oil hole.","ex_ja":"切断線A-Aは油穴の中心を通っている。","ex_vi":"Nét cắt A-A đi qua tâm lỗ dầu.","syn_en":["section line (dễ nhầm với hatching)","viewing plane line (liên quan)"],"syn_ja":["切断位置 (liên quan)"]},{"en":"full section","pos":"noun phrase","ipa":"/ˌfʊl ˈsekʃn/","ja":"全断面図","kana":"ぜんだんめんず","romaji":"zendanmenzu","vi":"hình cắt toàn bộ","level":2,"def_vi":"Hình cắt khi mặt phẳng cắt đi xuyên suốt toàn bộ vật thể, thường đi qua trục đối xứng.","def_en":"A sectional view in which the cutting plane passes completely through the object, usually along its axis.","def_ja":"対象物を一つの平面で完全に切断して表した断面図。","usage_en":"Danh từ đếm được. Collocation: show the housing in full section; a full section through the centre line.","usage_ja":"全断面図 thường cắt qua 中心線; nếu cắt qua trục đối xứng thì có thể bỏ ghi 切断線. Cụm: 全断面で示す.","context_vi":"Dùng cho chi tiết tròn xoay rỗng như ống lót, puly, vỏ bơm để thấy toàn bộ cấu tạo bên trong.","ex_en":"The pulley is shown in full section through its axis.","ex_ja":"プーリは軸線を通る全断面図で示している。","ex_vi":"Puly được thể hiện bằng hình cắt toàn bộ đi qua trục.","syn_en":["full sectional view","full cut (khẩu ngữ)"],"syn_ja":["全断面"]},{"en":"half section","pos":"noun phrase","ipa":"/ˌhɑːf ˈsekʃn/","ja":"片側断面図","kana":"かたがわだんめんず","romaji":"katagawadanmenzu","vi":"hình cắt một nửa (nửa hình chiếu, nửa hình cắt)","level":2,"def_vi":"Hình biểu diễn vật thể đối xứng, một nửa vẽ hình chiếu bên ngoài, nửa kia vẽ hình cắt, phân cách bằng đường tâm.","def_en":"A view of a symmetrical object with one half shown in section and the other half as an outside view.","def_ja":"対称形の対象物で、中心線を境に半分を断面、半分を外形で表した図。","usage_en":"Danh từ đếm được. Collocation: draw the cover as a half section; chỉ dùng cho chi tiết đối xứng.","usage_ja":"片側断面図 chỉ áp dụng cho vật đối xứng; ranh giới là 中心線. Cụm: 片側断面で示す.","context_vi":"Dùng cho nắp, mặt bích, khớp nối đối xứng để vừa thấy hình ngoài vừa thấy cấu tạo bên trong.","ex_en":"A half section shows both the outer ribs and the inner bore of the cover.","ex_ja":"片側断面図にすると、カバーの外側のリブと内側の穴を同時に示せる。","ex_vi":"Hình cắt một nửa thể hiện được cả gân bên ngoài lẫn lỗ bên trong của nắp.","syn_en":["half-sectional view","quarter section (khẩu ngữ, Mỹ)"],"syn_ja":["片側断面","半断面図 (ít dùng)"]},{"en":"partial section","pos":"noun phrase","ipa":"/ˌpɑːʃl ˈsekʃn/","ja":"部分断面図","kana":"ぶぶんだんめんず","romaji":"bubundanmenzu","vi":"hình cắt cục bộ","level":2,"def_vi":"Hình cắt chỉ một vùng nhỏ của vật thể, giới hạn bằng nét lượn sóng, để thể hiện một chi tiết bên trong.","def_en":"A section of only a small region of an object, bounded by a break line, to reveal a local internal feature.","def_ja":"対象物の必要な一部だけを切り取って断面とし、破断線で境界を示した図。","usage_en":"Danh từ đếm được; Mỹ gọi 'broken-out section'. Collocation: use a partial section to show the keyway.","usage_ja":"部分断面図 giới hạn bằng 破断線; xưởng hay gọi 部分断面. Cụm: 部分断面で示す.","context_vi":"Dùng cho trục có rãnh then, lỗ tâm, lỗ ren nằm trong chi tiết đặc mà không cần cắt toàn bộ.","ex_en":"A partial section shows the depth of the tapped hole in the shaft end.","ex_ja":"軸端のねじ穴の深さは部分断面図で示している。","ex_vi":"Hình cắt cục bộ thể hiện chiều sâu lỗ ren ở đầu trục.","syn_en":["broken-out section (Mỹ)","local section"],"syn_ja":["部分断面"]},{"en":"cross-section","pos":"noun","ipa":"/ˈkrɒs ˌsekʃn/","ja":"横断面","kana":"おうだんめん","romaji":"oudanmen","vi":"mặt cắt ngang","level":2,"def_vi":"Mặt cắt vuông góc với trục dài của vật thể như trục, thanh, dầm, ống.","def_en":"A section taken perpendicular to the long axis of an object such as a shaft, bar or beam.","def_ja":"軸や棒などの長手方向に垂直な平面で切った断面。","usage_en":"Danh từ đếm được; cũng có nghĩa chung 'tiết diện'. Collocation: circular cross-section, cross-section of the beam, cross-sectional area.","usage_ja":"横断面 đối lập với 縦断面; trong sức bền vật liệu thường nói 断面 (tiết diện). Cụm: 横断面の形状.","context_vi":"Dùng khi thể hiện tiết diện trục có rãnh then, thép hình, gân, dầm và trong tính toán sức bền.","ex_en":"The cross-section of the arm is an I shape to save weight.","ex_ja":"アームの横断面は軽量化のためI形にしている。","ex_vi":"Mặt cắt ngang của tay đòn có dạng chữ I để giảm khối lượng.","syn_en":["transverse section","section (nghĩa rộng hơn)"],"syn_ja":["横断面図","断面 (nghĩa rộng hơn)"]},{"en":"longitudinal section","pos":"noun phrase","ipa":"/ˌlɒndʒɪˈtjuːdɪnl ˈsekʃn/","ja":"縦断面","kana":"じゅうだんめん","romaji":"juudanmen","vi":"mặt cắt dọc","level":2,"def_vi":"Mặt cắt theo mặt phẳng chứa hoặc song song với trục dài của vật thể.","def_en":"A section taken along a plane containing or parallel to the long axis of an object.","def_ja":"対象物の長手方向の軸を含む、または平行な平面で切った断面。","usage_en":"Danh từ đếm được. Collocation: a longitudinal section through the pipe, show the shaft in longitudinal section.","usage_ja":"縦断面 đọc じゅうだんめん; đối lập với 横断面. Cụm: 縦断面図, 縦断面で見る.","context_vi":"Dùng cho ống, trục rỗng, xi lanh, nòng và các chi tiết dài cần thấy cấu tạo theo chiều dọc.","ex_en":"The longitudinal section of the cylinder shows the piston and both end caps.","ex_ja":"シリンダの縦断面にピストンと両端のカバーが示されている。","ex_vi":"Mặt cắt dọc của xi lanh thể hiện piston và hai nắp đầu.","syn_en":["lengthwise section","axial section"],"syn_ja":["縦断面図"]},{"en":"oblique projection","pos":"noun phrase","ipa":"/əˈbliːk prəˈdʒekʃn/","ja":"斜投影","kana":"しゃとうえい","romaji":"shatouei","vi":"phép chiếu xiên","level":2,"def_vi":"Phép chiếu song song có tia chiếu xiên với mặt phẳng hình chiếu; mặt trước giữ đúng hình dạng, chiều sâu vẽ xiên.","def_en":"Parallel projection with lines oblique to the plane, keeping the front face true and drawing depth at an angle.","def_ja":"投影線を投影面に斜めに当てる投影。正面は実形、奥行きは斜めに表す。","usage_en":"Danh từ không đếm được (phương pháp). Collocation: in oblique projection; hai dạng phổ biến: cavalier và cabinet oblique.","usage_ja":"Hình vẽ theo phép chiếu này gọi 斜投影図; dạng chiều sâu thu nửa gọi キャビネット図, giữ nguyên gọi カバリエ図.","context_vi":"Dùng để vẽ nhanh hình nổi của chi tiết có mặt trước phức tạp như bánh răng, mặt bích, tấm có lỗ tròn.","ex_en":"Oblique projection is handy because circles on the front face stay round.","ex_ja":"斜投影では正面の円がそのまま円で描けるので便利である。","ex_vi":"Phép chiếu xiên tiện lợi vì các đường tròn ở mặt trước vẫn giữ là đường tròn.","syn_en":["oblique drawing","cabinet projection (nghĩa hẹp hơn)"],"syn_ja":["斜投影図","キャビネット図 (nghĩa hẹp hơn)"]},{"en":"revolved section","pos":"noun phrase","ipa":"/rɪˈvɒlvd ˈsekʃn/","ja":"回転図示断面図","kana":"かいてんずしだんめんず","romaji":"kaitenzushidanmenzu","vi":"mặt cắt xoay (mặt cắt chập / mặt cắt rời)","level":3,"def_vi":"Mặt cắt ngang của tay đòn, gân, nan hoa được xoay 90° và vẽ chập lên hình chiếu hoặc vẽ rời bên cạnh.","def_en":"A cross-section of an arm, rib or spoke rotated 90° and drawn on the view or removed beside it.","def_ja":"アームやリブなどの切り口を90°回転させ、図中または図外に描いた断面図。","usage_en":"Danh từ đếm được; khi vẽ tách ra ngoài gọi 'removed section'. Collocation: show the spoke profile with a revolved section.","usage_ja":"回転図示断面図 là thuật ngữ JIS gồm cả kiểu vẽ tại chỗ (細い実線) và vẽ ra ngoài. Khẩu ngữ: 回転断面.","context_vi":"Dùng cho tay quay, nan hoa bánh đà, móc cẩu, gân tăng cứng, thép hình có tiết diện thay đổi.","ex_en":"A revolved section shows the elliptical shape of the handwheel spoke.","ex_ja":"ハンドルのスポークの楕円形状は回転図示断面図で示している。","ex_vi":"Mặt cắt chập thể hiện hình elip của nan tay quay.","syn_en":["removed section (dạng vẽ rời)","rotated section"],"syn_ja":["回転断面 (khẩu ngữ)"]},{"en":"local view","pos":"noun phrase","ipa":"/ˈləʊkl vjuː/","ja":"局部投影図","kana":"きょくぶとうえいず","romaji":"kyokubutoueizu","vi":"hình chiếu cục bộ","level":3,"def_vi":"Hình chiếu chỉ vẽ riêng một đặc điểm nhỏ như rãnh then hay lỗ, nối với hình chính bằng đường tâm.","def_en":"A view showing only a small feature such as a keyway or hole, linked to the main view by a centre line.","def_ja":"穴やキー溝など一部の形だけを図示すれば足りる場合に、その部分だけを描いた投影図。","usage_en":"Danh từ đếm được; là quy ước của ISO 128-34. Collocation: a local view of the keyway.","usage_ja":"局部投影図 nối với hình chính bằng 中心線, không cần mũi tên hướng nhìn; khác 部分投影図 (giới hạn bằng nét lượn sóng).","context_vi":"Dùng để thể hiện hình dạng rãnh then, lỗ ovan trên trục mà không cần vẽ cả hình chiếu cạnh.","ex_en":"A local view above the shaft shows the shape of the keyway.","ex_ja":"軸の上に局部投影図を描いて、キー溝の形を示す。","ex_vi":"Một hình chiếu cục bộ phía trên trục thể hiện hình dạng rãnh then.","syn_en":["local feature view","partial view (liên quan)"],"syn_ja":["局部図 (khẩu ngữ)"]},{"en":"symmetry symbol","pos":"noun phrase","ipa":"/ˈsɪmətri ˌsɪmbl/","ja":"対称図示記号","kana":"たいしょうずしきごう","romaji":"taishouzushikigou","vi":"ký hiệu đối xứng","level":3,"def_vi":"Hai vạch ngắn song song vẽ ở hai đầu đường tâm, cho biết chỉ vẽ một nửa hình vì vật thể đối xứng.","def_en":"Two short parallel lines at each end of a centre line indicating that only half of a symmetrical object is drawn.","def_ja":"対称な図形の片側だけを描くとき、中心線の両端に付ける2本の短い平行線。","usage_en":"Danh từ đếm được. Collocation: draw half the part with symmetry symbols on the centre line.","usage_ja":"対称図示記号 là thuật ngữ JIS; cụm: 対称図示記号を付けて片側を省略する.","context_vi":"Dùng để rút gọn bản vẽ chi tiết đối xứng lớn như tấm, nắp, mặt bích.","ex_en":"Only half of the gasket is drawn, with a symmetry symbol at each end of the centre line.","ex_ja":"ガスケットは片側だけを描き、中心線の両端に対称図示記号を付けている。","ex_vi":"Chỉ vẽ một nửa gioăng, có ký hiệu đối xứng ở hai đầu đường tâm.","syn_en":["symmetry mark","half-view convention (liên quan)"],"syn_ja":["対称記号"]},{"en":"perspective projection","pos":"noun phrase","ipa":"/pəˈspektɪv prəˈdʒekʃn/","ja":"透視投影","kana":"とうしとうえい","romaji":"toushitouei","vi":"phép chiếu phối cảnh","level":3,"def_vi":"Phép chiếu xuyên tâm, các tia chiếu hội tụ tại mắt người nhìn nên vật ở xa trông nhỏ hơn.","def_en":"Central projection in which lines converge at the viewer's eye, so distant parts appear smaller.","def_ja":"視点に集まる投影線による中心投影。遠くのものほど小さく見える。","usage_en":"Danh từ không đếm được. Collocation: one-point / two-point perspective, perspective view in CAD rendering.","usage_ja":"Hình vẽ gọi 透視図 hoặc パース (khẩu ngữ). Ghép: 一点透視, 二点透視; điểm tụ gọi 消点.","context_vi":"Dùng trong kiến trúc, thiết kế công nghiệp và render; ít dùng trong bản vẽ chế tạo vì không đo được kích thước.","ex_en":"Perspective projection looks realistic but cannot be used for measuring.","ex_ja":"透視投影は写実的に見えるが、寸法の読み取りには使えない。","ex_vi":"Phép chiếu phối cảnh trông thật nhưng không dùng để đo kích thước được.","syn_en":["central projection","perspective drawing"],"syn_ja":["透視図","パース (khẩu ngữ)"]},{"en":"axonometric projection","pos":"noun phrase","ipa":"/ˌæksənəˈmetrɪk prəˈdʒekʃn/","ja":"軸測投影","kana":"じくそくとうえい","romaji":"jikusokutouei","vi":"phép chiếu trục đo","level":3,"def_vi":"Phép chiếu vuông góc với vật thể đặt nghiêng để thấy cả ba mặt; gồm các dạng đẳng cự, hai trục bằng, ba trục khác nhau.","def_en":"Orthographic projection of an object tilted to show three faces; includes isometric, dimetric and trimetric types.","def_ja":"対象物を傾けて三面が見えるように正投影する方法。等角・二等角・不等角投影がある。","usage_en":"Danh từ không đếm được, là nhóm phương pháp. Collocation: isometric, dimetric and trimetric axonometric projection.","usage_ja":"軸測投影 là thuật ngữ học thuật; các dạng: 等角投影, 二等角投影, 不等角投影. Trong xưởng ít dùng, hay nói アイソメ.","context_vi":"Gặp trong giáo trình hình họa, vẽ kỹ thuật và cài đặt hướng nhìn trong phần mềm CAD.","ex_en":"Isometric drawing is the most common form of axonometric projection.","ex_ja":"等角図は軸測投影の中で最もよく使われる形式である。","ex_vi":"Hình đẳng cự là dạng phổ biến nhất của phép chiếu trục đo.","syn_en":["axonometric drawing","isometric projection (nghĩa hẹp hơn)"],"syn_ja":["軸測投影法","等角投影 (nghĩa hẹp hơn)"]}]},{"id":13,"words":[{"en":"dimension","pos":"noun","ipa":"/daɪˈmenʃn/","ja":"寸法","kana":"すんぽう","romaji":"sunpou","vi":"kích thước","level":1,"def_vi":"Giá trị độ dài hoặc góc ghi trên bản vẽ để xác định độ lớn và vị trí của một yếu tố trên chi tiết.","def_en":"A length or angle value shown on a drawing that defines the size or position of a feature.","def_ja":"図面に示し、形体の大きさや位置を定める長さまたは角度の値。","usage_en":"Danh từ đếm được. Hay đi với: add / check / measure a dimension; 'dimension' cũng là động từ: dimension the hole from the left edge.","usage_ja":"寸法 đọc すんぽう (không phải すんほう). Cụm: 寸法を入れる, 寸法を測る, 寸法が出ていない (kích thước không đạt).","context_vi":"Dùng hằng ngày ở phòng thiết kế, xưởng gia công và bộ phận kiểm tra khi lập, đọc và đo theo bản vẽ.","ex_en":"This dimension is missing on the side view, so the operator cannot machine the slot.","ex_ja":"側面図にこの寸法が抜けているので、作業者は溝を加工できない。","ex_vi":"Hình chiếu cạnh thiếu kích thước này nên công nhân không thể gia công rãnh.","syn_en":["size (nghĩa rộng hơn)","measurement (khẩu ngữ)"],"syn_ja":["サイズ (khẩu ngữ)","寸法値 (liên quan)"]},{"en":"dimension line","pos":"noun phrase","ipa":"/daɪˈmenʃn laɪn/","ja":"寸法線","kana":"すんぽうせん","romaji":"sunpousen","vi":"đường kích thước","level":1,"def_vi":"Nét liền mảnh có mũi tên ở hai đầu, vẽ song song với đoạn cần ghi, phía trên đặt con số kích thước.","def_en":"A thin line with arrowheads at its ends, drawn parallel to the measured length, carrying the dimension value.","def_ja":"測る長さに平行に引き、両端に矢印を付けて寸法数値を記入する細い実線。","usage_en":"Danh từ đếm được. Collocation: draw a dimension line, place the value above the dimension line; tránh để dimension lines cắt nhau.","usage_ja":"寸法線 vẽ bằng 細い実線, nối giữa hai 寸法補助線. Cụm: 寸法線を引く, 寸法線の上に数値を書く.","context_vi":"Có mặt trên mọi bản vẽ chi tiết; là phần đầu tiên học khi tập ghi kích thước.","ex_en":"Keep each dimension line at least 10 mm away from the outline.","ex_ja":"寸法線は外形線から10 mm以上離して引くこと。","ex_vi":"Đặt mỗi đường kích thước cách đường bao ít nhất 10 mm.","syn_en":["dim line (khẩu ngữ CAD)"],"syn_ja":["寸法補助線 (liên quan)"]},{"en":"extension line","pos":"noun phrase","ipa":"/ɪkˈstenʃn laɪn/","ja":"寸法補助線","kana":"すんぽうほじょせん","romaji":"sunpouhojosen","vi":"đường gióng","level":1,"def_vi":"Nét liền mảnh kéo ra từ cạnh của vật thể, vuông góc với đường kích thước, để giới hạn đoạn được ghi kích thước.","def_en":"A thin line extended from a feature, perpendicular to the dimension line, marking the limits of the dimension.","def_ja":"形体から引き出し、寸法線に垂直に引いて寸法の範囲を示す細い実線。","usage_en":"Danh từ đếm được; Anh-Anh còn gọi 'projection line'. Collocation: extension lines extend about 2 mm beyond the dimension line; leave a small gap from the outline.","usage_ja":"寸法補助線 vượt quá 寸法線 khoảng 2–3 mm. Cụm: 寸法補助線を引き出す.","context_vi":"Dùng cùng đường kích thước khi ghi kích thước bên ngoài hình vẽ để hình không bị rối.","ex_en":"The extension line should not touch the outline of the part.","ex_ja":"寸法補助線は部品の外形線に接しないようにする。","ex_vi":"Đường gióng không được chạm vào đường bao của chi tiết.","syn_en":["projection line (Anh-Anh)","witness line (Anh-Anh)"],"syn_ja":["補助線 (khẩu ngữ)"]},{"en":"arrowhead","pos":"noun","ipa":"/ˈærəʊhed/","ja":"矢印","kana":"やじるし","romaji":"yajirushi","vi":"mũi tên (đầu đường kích thước)","level":1,"def_vi":"Ký hiệu hình mũi tên ở đầu đường kích thước, chạm vào đường gióng hoặc đường bao để chỉ giới hạn kích thước.","def_en":"An arrow-shaped mark at the end of a dimension line touching the extension line or outline.","def_ja":"寸法線の端に付け、寸法補助線や外形線に当てて寸法の限界を示す記号。","usage_en":"Danh từ đếm được, viết liền một từ. Collocation: filled / open arrowheads; khi chỗ hẹp có thể thay bằng dot hoặc oblique stroke.","usage_ja":"Khẩu ngữ là 矢印; JIS gọi chung các loại đầu mút là 端末記号 (mũi tên, gạch xiên, chấm). Cụm: 矢印を付ける.","context_vi":"Có trên mọi đường kích thước và đường dẫn chú thích; kích thước mũi tên được quy định trong mẫu CAD.","ex_en":"Where the space is too narrow, draw the arrowhead outside the extension lines.","ex_ja":"間隔が狭い場合は、矢印を寸法補助線の外側に描く。","ex_vi":"Chỗ nào quá hẹp thì vẽ mũi tên ra phía ngoài đường gióng.","syn_en":["arrow","terminator (nghĩa rộng hơn)"],"syn_ja":["端末記号 (thuật ngữ JIS, nghĩa rộng hơn)"]},{"en":"leader line","pos":"noun phrase","ipa":"/ˈliːdə laɪn/","ja":"引出線","kana":"ひきだしせん","romaji":"hikidashisen","vi":"đường dẫn (đường chú dẫn)","level":1,"def_vi":"Nét liền mảnh, thường nghiêng, kéo từ một yếu tố trên hình vẽ ra ngoài để ghi kích thước, ký hiệu hoặc ghi chú.","def_en":"A thin, usually inclined line drawn from a feature to a note, dimension or symbol placed outside the view.","def_ja":"形体から斜めに引き出し、寸法・記号・注記などを記入するための細い実線。","usage_en":"Danh từ đếm được; khẩu ngữ gọi 'leader'. Collocation: a leader line ending in an arrowhead / a dot; draw a leader to the hole.","usage_ja":"引出線 cũng viết 引き出し線; đầu chỉ vào cạnh dùng mũi tên, chỉ vào bên trong bề mặt dùng chấm đen. Cụm: 引出線で指示する.","context_vi":"Dùng để ghi kích thước lỗ, vát mép, ghi chú vật liệu, số vị trí trên bản vẽ lắp.","ex_en":"Use a leader line to call out the hole size and depth.","ex_ja":"穴の径と深さは引出線を使って指示する。","ex_vi":"Dùng đường dẫn để ghi đường kính và chiều sâu lỗ.","syn_en":["leader"],"syn_ja":["引き出し線"]},{"en":"diameter symbol","pos":"noun phrase","ipa":"/daɪˈæmɪtə ˌsɪmbl/","ja":"直径記号","kana":"ちょっけいきごう","romaji":"chokkeikigou","vi":"ký hiệu đường kính (Ø)","level":1,"def_vi":"Ký hiệu Ø đặt trước con số để chỉ kích thước đó là đường kính của yếu tố tròn.","def_en":"The symbol Ø placed before a value to show that it is the diameter of a circular feature.","def_ja":"寸法数値の前に付け、円形の直径であることを示す記号φ。","usage_en":"Danh từ đếm được. Khi đọc, Ø20 nói 'twenty diameter' hoặc 'diameter twenty'; viết tắt khác: 'dia.', 'DIA'.","usage_ja":"Ký hiệu φ; ngoài xưởng đọc 'まる' (φ20 = まる20) hoặc 'ファイ'. Cụm: 直径記号を付ける.","context_vi":"Dùng cho mọi kích thước trục, lỗ, đường tròn trên bản vẽ; thường ghi được ngay trên hình chiếu không tròn.","ex_en":"Do not forget the diameter symbol before the shaft size.","ex_ja":"軸の寸法の前に直径記号を忘れずに付けること。","ex_vi":"Đừng quên ký hiệu đường kính trước kích thước trục.","syn_en":["dia. (viết tắt)","Ø"],"syn_ja":["φ (まる, khẩu ngữ)","ファイ (khẩu ngữ)"]},{"en":"radius","pos":"noun","ipa":"/ˈreɪdiəs/","ja":"半径","kana":"はんけい","romaji":"hankei","vi":"bán kính","level":1,"def_vi":"Khoảng cách từ tâm đến cung tròn; trên bản vẽ ghi bằng ký hiệu R đặt trước con số.","def_en":"The distance from the centre of an arc to its edge, shown with the symbol R before the value.","def_ja":"円弧の中心から弧までの距離。寸法数値の前に記号Rを付けて示す。","usage_en":"Danh từ đếm được, số nhiều 'radii'. Collocation: corner radius, inside radius, R5; 'all unspecified radii R1' là ghi chú hay gặp.","usage_ja":"Ký hiệu R, đọc アール; xưởng thường nói 'R5' thay vì 半径5. Cụm: Rを付ける (bo góc), 半径を指示する.","context_vi":"Dùng cho góc lượn, mép bo, cung tròn trên chi tiết phay, đúc, gia công tấm.","ex_en":"All internal corners have a radius of 3 mm to suit the end mill.","ex_ja":"内側の角はすべて、エンドミルに合わせて半径3 mmとする。","ex_vi":"Tất cả góc trong có bán kính 3 mm cho phù hợp với dao phay ngón.","syn_en":["R (ký hiệu)","fillet radius (nghĩa hẹp hơn)"],"syn_ja":["R (アール, khẩu ngữ)","アール"]},{"en":"outside diameter","pos":"noun phrase","ipa":"/ˌaʊtsaɪd daɪˈæmɪtə/","ja":"外径","kana":"がいけい","romaji":"gaikei","vi":"đường kính ngoài","level":1,"def_vi":"Đường kính đo ở mặt ngoài của chi tiết tròn như trục, ống, vòng bi.","def_en":"The diameter measured across the outer surface of a round part such as a shaft, pipe or ring.","def_ja":"軸・管・リングなど円形部品の外側の直径。","usage_en":"Danh từ đếm được; viết tắt 'OD' rất phổ biến. Collocation: the outside diameter of the pipe, turn the OD.","usage_ja":"外径 dùng cả văn bản lẫn xưởng; động từ: 外径を測る, 外径を削る. Đối lập: 内径.","context_vi":"Dùng khi gia công tiện, kiểm tra trục, chọn ống và vòng bi.","ex_en":"The outside diameter of the bushing is 40 mm.","ex_ja":"ブシュの外径は40 mmである。","ex_vi":"Đường kính ngoài của bạc lót là 40 mm.","syn_en":["OD (viết tắt)","outer diameter"],"syn_ja":["外直径 (ít dùng)"]},{"en":"inside diameter","pos":"noun phrase","ipa":"/ˌɪnsaɪd daɪˈæmɪtə/","ja":"内径","kana":"ないけい","romaji":"naikei","vi":"đường kính trong","level":1,"def_vi":"Đường kính đo ở mặt trong của lỗ hoặc chi tiết rỗng như ống, bạc lót.","def_en":"The diameter measured across the inner surface of a hole or hollow part.","def_ja":"穴や中空部品の内側の直径。","usage_en":"Danh từ đếm được; viết tắt 'ID'. Collocation: the inside diameter of the bore, bore the ID to size.","usage_ja":"内径 dùng cả văn bản lẫn xưởng; cụm: 内径を測る, 内径を仕上げる. Dụng cụ đo: 内径マイクロメータ.","context_vi":"Dùng khi gia công lỗ, chọn ống, bạc, vòng bi và khi kiểm tra bằng đồng hồ so đo lỗ.","ex_en":"Measure the inside diameter of the sleeve at three positions.","ex_ja":"スリーブの内径を3か所で測定すること。","ex_vi":"Đo đường kính trong của ống lót ở ba vị trí.","syn_en":["ID (viết tắt)","bore (khẩu ngữ)"],"syn_ja":["穴径 (liên quan)"]},{"en":"chamfer","pos":"noun","ipa":"/ˈtʃæmfə/","ja":"面取り","kana":"めんとり","romaji":"mentori","vi":"vát mép","level":1,"def_vi":"Phần cạnh được vát nghiêng; trên bản vẽ vát 45° ghi bằng ký hiệu C và chiều dài cạnh vát, ví dụ C1.","def_en":"A bevelled edge; a 45° chamfer is dimensioned with the symbol C and its leg length, e.g. C1.","def_ja":"角を斜めに削ったもの。45°の面取りは記号Cと寸法で示す（例：C1）。","usage_en":"Danh từ đếm được và động từ (chamfer the edge). Theo ISO thường ghi '1 × 45°'; ký hiệu C là của JIS.","usage_ja":"面取り đọc めんとり; ghi C1, C0.5. Cụm: 面取りをする, 糸面取り (vát rất nhỏ), 'C面' (khẩu ngữ).","context_vi":"Dùng ở mọi bản vẽ chi tiết để bỏ cạnh sắc, dễ lắp ráp và tránh ba via.","ex_en":"Add a C1 chamfer to both ends of the shaft.","ex_ja":"軸の両端にC1の面取りを入れてください。","ex_vi":"Vát mép C1 ở cả hai đầu trục.","syn_en":["bevel (gần nghĩa)","edge break (nghĩa rộng hơn)"],"syn_ja":["C面取り","C面 (khẩu ngữ)"]},{"en":"dimensioning","pos":"noun","ipa":"/daɪˈmenʃənɪŋ/","ja":"寸法記入","kana":"すんぽうきにゅう","romaji":"sunpoukinyuu","vi":"ghi kích thước","level":2,"def_vi":"Việc ghi các kích thước, ký hiệu và ghi chú lên bản vẽ theo quy tắc tiêu chuẩn để xác định đầy đủ chi tiết.","def_en":"The practice of adding dimensions, symbols and notes to a drawing according to standard rules.","def_ja":"規格の規則に従い、図面に寸法・記号・注記を記入すること。","usage_en":"Danh từ không đếm được. Collocation: dimensioning rules, dimensioning scheme, poor dimensioning causes scrap.","usage_ja":"寸法記入 đọc すんぽうきにゅう; ghép: 寸法記入法, 寸法記入の原則. Động từ thường nói 寸法を入れる.","context_vi":"Là phần học quan trọng nhất của vẽ kỹ thuật; quyết định chi tiết có gia công và kiểm tra đúng hay không.","ex_en":"Good dimensioning should reflect how the part will be machined and inspected.","ex_ja":"良い寸法記入は、部品の加工方法と検査方法を反映している。","ex_vi":"Cách ghi kích thước tốt phải phản ánh cách gia công và kiểm tra chi tiết.","syn_en":["dimensioning practice","annotation (nghĩa rộng hơn)"],"syn_ja":["寸法の記入","寸法入れ (khẩu ngữ)"]},{"en":"dimension value","pos":"noun phrase","ipa":"/daɪˈmenʃn ˌvæljuː/","ja":"寸法数値","kana":"すんぽうすうち","romaji":"sunpousuuchi","vi":"con số kích thước","level":2,"def_vi":"Con số ghi trên đường kích thước, đơn vị mặc định là milimét và không ghi đơn vị.","def_en":"The number written on a dimension line, normally in millimetres without a unit symbol.","def_ja":"寸法線に沿って記入する数値。単位は通常mmで、単位記号は付けない。","usage_en":"Danh từ đếm được; khẩu ngữ hay nói 'dimension figure' hoặc chỉ 'the number'. Collocation: the dimension value reads from the bottom or right side of the sheet.","usage_ja":"寸法数値 ghi phía trên 寸法線, đọc được từ phía dưới hoặc bên phải bản vẽ. Cụm: 寸法数値を記入する.","context_vi":"Gặp khi lập và kiểm tra bản vẽ; con số sai hoặc khó đọc là lỗi thường gặp gây phế phẩm.","ex_en":"The dimension value is hidden behind the hatching, please move it.","ex_ja":"寸法数値がハッチングに隠れているので、移動してください。","ex_vi":"Con số kích thước bị đường gạch mặt cắt che mất, hãy dời nó đi.","syn_en":["dimension figure","dimension text (CAD)"],"syn_ja":["寸法値","寸法文字 (CAD)"]},{"en":"note","pos":"noun","ipa":"/nəʊt/","ja":"注記","kana":"ちゅうき","romaji":"chuuki","vi":"ghi chú (yêu cầu kỹ thuật)","level":2,"def_vi":"Dòng chữ trên bản vẽ nêu yêu cầu không thể hiện bằng hình hay ký hiệu, như vát mép chung, xử lý nhiệt, dung sai chung.","def_en":"Text on a drawing stating requirements not shown by views or symbols, such as general chamfers or treatment.","def_ja":"図や記号で表せない要求事項を文章で図面に記入したもの。","usage_en":"Danh từ đếm được. Collocation: general note, local note, 'see note 3'; ghi chú chung thường đặt gần khung tên.","usage_ja":"注記 dùng trong văn bản; ghi chú chung gọi 一般注記, xưởng hay nói 注意書き. Cụm: 注記を追加する.","context_vi":"Dùng để ghi vát mép không chỉ định, mạ, nhiệt luyện, làm sạch ba via, tiêu chuẩn dung sai chung.","ex_en":"Note 2 says: remove all burrs and sharp edges.","ex_ja":"注記2には「バリ及び鋭いエッジを除去すること」と書かれている。","ex_vi":"Ghi chú 2 viết: làm sạch toàn bộ ba via và cạnh sắc.","syn_en":["general note (nghĩa hẹp hơn)","callout (liên quan)"],"syn_ja":["注意書き (khẩu ngữ)","一般注記 (nghĩa hẹp hơn)"]},{"en":"overall length","pos":"noun phrase","ipa":"/ˌəʊvərɔːl ˈleŋθ/","ja":"全長","kana":"ぜんちょう","romaji":"zenchou","vi":"chiều dài toàn bộ (kích thước bao)","level":2,"def_vi":"Kích thước lớn nhất theo chiều dài của chi tiết, đo từ đầu này đến đầu kia.","def_en":"The largest length of a part, measured from one end to the other.","def_ja":"部品の一端から他端までの最大の長さ。","usage_en":"Danh từ đếm được; viết tắt 'OAL'. Collocation: overall length, overall width, overall height (kích thước bao).","usage_ja":"全長 dùng rộng rãi; cùng nhóm: 全幅, 全高. Cụm: 全長を測る, 全長を記入する.","context_vi":"Dùng để cắt phôi, chọn kích thước vật liệu, đóng gói và kiểm tra không gian lắp.","ex_en":"The overall length of the shaft is 350 mm, so cut the blank to 355 mm.","ex_ja":"軸の全長は350 mmなので、素材は355 mmに切断する。","ex_vi":"Chiều dài toàn bộ của trục là 350 mm nên cắt phôi dài 355 mm.","syn_en":["OAL (viết tắt)","overall dimension (nghĩa rộng hơn)"],"syn_ja":["全体寸法 (nghĩa rộng hơn)"]},{"en":"angular dimension","pos":"noun phrase","ipa":"/ˈæŋɡjələ daɪˈmenʃn/","ja":"角度寸法","kana":"かくどすんぽう","romaji":"kakudosunpou","vi":"kích thước góc","level":2,"def_vi":"Kích thước biểu thị góc giữa hai cạnh hoặc hai bề mặt, ghi bằng độ trên đường kích thước dạng cung tròn.","def_en":"A dimension giving the angle between two lines or surfaces, written in degrees on an arc-shaped dimension line.","def_ja":"二つの線や面のなす角度を表す寸法。円弧状の寸法線に度で記入する。","usage_en":"Danh từ đếm được. Collocation: an angular dimension of 30°, angular tolerance; đơn vị độ, phút (30°15′).","usage_ja":"角度寸法 ghi trên 寸法線 hình cung có tâm ở đỉnh góc. Cụm: 角度寸法を入れる.","context_vi":"Dùng cho mặt vát, rãnh chữ V, côn, lỗ chia đều trên vòng tròn.","ex_en":"The angular dimension between the two arms is 120°.","ex_ja":"2本のアーム間の角度寸法は120°である。","ex_vi":"Kích thước góc giữa hai tay đòn là 120°.","syn_en":["angle dimension","angle (khẩu ngữ)"],"syn_ja":["角度"]},{"en":"centre distance","pos":"noun phrase","ipa":"/ˈsentə ˌdɪstəns/","ja":"中心距離","kana":"ちゅうしんきょり","romaji":"chuushinkyori","vi":"khoảng cách tâm","level":2,"def_vi":"Khoảng cách giữa tâm của hai lỗ, hai trục hoặc hai yếu tố tròn.","def_en":"The distance between the centres of two holes, shafts or other circular features.","def_ja":"二つの穴や軸などの中心間の距離。","usage_en":"Danh từ đếm được; Mỹ viết 'center distance'. Collocation: hole centre distance, shaft centre distance; khẩu ngữ 'centres': 50 mm centres.","usage_ja":"中心距離 dùng trong văn bản; xưởng hay nói ピッチ hoặc 芯間 (しんかん). Cụm: 中心距離を指示する.","context_vi":"Dùng khi bố trí lỗ bu lông, khoảng cách trục bánh răng, puly và kiểm tra lắp ghép.","ex_en":"The centre distance between the two dowel holes is critical for assembly.","ex_ja":"2つのピン穴の中心距離は組立上重要である。","ex_vi":"Khoảng cách tâm giữa hai lỗ chốt định vị rất quan trọng cho lắp ráp.","syn_en":["center distance (Mỹ)","centres (khẩu ngữ)"],"syn_ja":["芯間 (khẩu ngữ)","ピッチ (khẩu ngữ)"]},{"en":"arc length","pos":"noun phrase","ipa":"/ˈɑːk leŋθ/","ja":"円弧の長さ","kana":"えんこのながさ","romaji":"enkononagasa","vi":"chiều dài cung","level":2,"def_vi":"Kích thước đo dọc theo cung tròn, ghi với ký hiệu cung (⌒) đặt trước hoặc trên con số.","def_en":"A dimension measured along a curved arc, marked with the arc symbol before or above the value.","def_ja":"円弧に沿った長さ。寸法数値の前に円弧の長さ記号を付けて示す。","usage_en":"Danh từ đếm được. Collocation: dimension the arc length, arc length symbol; đường kích thước là cung đồng tâm.","usage_ja":"円弧の長さ ghi bằng ký hiệu ⌒ (JIS B 0001). Cụm: 円弧の長さ記号, 円弧の長さを指示する.","context_vi":"Dùng cho chi tiết uốn cong, rãnh cung, chiều dài khai triển của tôn uốn.","ex_en":"The slot is defined by its arc length of 45 mm.","ex_ja":"その溝は円弧の長さ45 mmで指示されている。","ex_vi":"Rãnh được xác định bằng chiều dài cung 45 mm.","syn_en":["length of arc","chord length (liên quan)"],"syn_ja":["弧長","弦の長さ (liên quan)"]},{"en":"square symbol","pos":"noun phrase","ipa":"/ˈskweə ˌsɪmbl/","ja":"正方形の辺の記号","kana":"せいほうけいのへんのきごう","romaji":"seihoukeinohennokigou","vi":"ký hiệu tiết diện vuông (□)","level":2,"def_vi":"Ký hiệu □ đặt trước con số để chỉ tiết diện vuông có cạnh bằng giá trị đó, chỉ cần ghi một kích thước.","def_en":"The symbol □ placed before a value to show a square section whose side equals that value.","def_ja":"寸法数値の前に□を付け、その値を一辺とする正方形であることを示す記号。","usage_en":"Danh từ đếm được. □20 đọc là 'twenty square'; collocation: a 20 mm square bar, dimensioned with the square symbol.","usage_ja":"Ký hiệu □; xưởng đọc 'かく' (□20 = かく20). Thuật ngữ JIS đầy đủ: 正方形の辺の記号.","context_vi":"Dùng cho đầu trục vuông, thép vuông, lỗ vuông, đầu vặn của van.","ex_en":"The shaft end is marked □14 with the square symbol, so only one dimension is needed.","ex_ja":"軸端は正方形の辺の記号を用いて□14と指示しているので、寸法は一つで足りる。","ex_vi":"Đầu trục được ghi □14 bằng ký hiệu tiết diện vuông nên chỉ cần một kích thước.","syn_en":["□ (ký hiệu)","square (khẩu ngữ)"],"syn_ja":["角 (かく, khẩu ngữ)","□"]},{"en":"spherical radius","pos":"noun phrase","ipa":"/ˌsferɪkl ˈreɪdiəs/","ja":"球の半径","kana":"きゅうのはんけい","romaji":"kyuunohankei","vi":"bán kính cầu (SR)","level":2,"def_vi":"Bán kính của mặt cầu, ghi bằng ký hiệu SR đặt trước con số; đường kính cầu ghi SØ.","def_en":"The radius of a spherical surface, shown with the symbol SR before the value; sphere diameter uses SØ.","def_ja":"球面の半径。寸法数値の前にSRを付ける。球の直径はSφで示す。","usage_en":"Danh từ đếm được. Collocation: a spherical radius of SR10, spherical diameter SØ20.","usage_ja":"Ký hiệu SR đọc エスアール; đường kính cầu Sφ. Cụm: SRで指示する, 球の半径を指示する.","context_vi":"Dùng cho đầu bi, đầu chốt tròn, đầu tay nắm, mặt tỳ dạng cầu.","ex_en":"The tip of the pin has a spherical radius of SR5.","ex_ja":"ピンの先端は球の半径SR5とする。","ex_vi":"Đầu chốt có bán kính cầu SR5.","syn_en":["SR (ký hiệu)","spherical diameter (liên quan)"],"syn_ja":["SR (khẩu ngữ)","球の直径 (liên quan)"]},{"en":"thickness symbol","pos":"noun phrase","ipa":"/ˈθɪknəs ˌsɪmbl/","ja":"厚さ記号","kana":"あつさきごう","romaji":"atsusakigou","vi":"ký hiệu chiều dày (t)","level":2,"def_vi":"Chữ t đặt trước con số để chỉ chiều dày tấm, giúp không cần vẽ thêm hình chiếu cạnh.","def_en":"The letter t placed before a value to give plate thickness without drawing an extra view.","def_ja":"板の厚さを、別の投影図を描かずに示すため、数値の前に付ける記号t。","usage_en":"Danh từ đếm được. Thường viết 't = 3' hoặc 't3' trong hình hoặc ghi chú; tiếng Anh nói 'three millimetre plate' / '3 mm thick'.","usage_ja":"Ký hiệu t đọc ティー; xưởng nói 't3' (ティーさん) để chỉ tấm dày 3 mm. Cụm: 厚さ記号tで示す.","context_vi":"Dùng phổ biến trên bản vẽ gia công tấm, gioăng, tấm đệm, chi tiết cắt laser.","ex_en":"The bracket is shown in one view with the thickness symbol t2.","ex_ja":"ブラケットは厚さ記号t2を付けて一つの図だけで示している。","ex_vi":"Giá đỡ chỉ được vẽ một hình chiếu kèm ký hiệu chiều dày t2.","syn_en":["t (ký hiệu)","plate thickness (liên quan)"],"syn_ja":["板厚 (liên quan)","t (ティー, khẩu ngữ)"]},{"en":"hole depth","pos":"noun phrase","ipa":"/ˈhəʊl depθ/","ja":"穴深さ","kana":"あなふかさ","romaji":"anafukasa","vi":"chiều sâu lỗ","level":2,"def_vi":"Chiều sâu phần hình trụ đầy đủ của lỗ không thông, không tính phần mũi nhọn ở đáy; ghi bằng ký hiệu ↧.","def_en":"The depth of the full-diameter part of a blind hole, excluding the drill point, shown with the ↧ symbol.","def_ja":"止まり穴の直径部分の深さ。先端の円すい部は含まない。記号↧で示す。","usage_en":"Danh từ đếm được. Collocation: drill Ø8 × 20 deep, hole depth symbol; lỗ thông ghi 'THRU'.","usage_ja":"JIS có ký hiệu 穴深さ ↧; trước đây hay ghi chữ 深さ hoặc 深. Lỗ thông ghi 貫通 hoặc キリ.","context_vi":"Dùng cho lỗ khoan không thông, lỗ ren, lỗ chốt trên bản vẽ chi tiết.","ex_en":"The hole depth does not include the 118° drill point.","ex_ja":"穴深さには118°のドリル先端部は含まない。","ex_vi":"Chiều sâu lỗ không tính phần mũi khoan 118° ở đáy.","syn_en":["depth (khẩu ngữ)","drill depth"],"syn_ja":["深さ","穴の深さ"]},{"en":"equal spacing","pos":"noun phrase","ipa":"/ˌiːkwəl ˈspeɪsɪŋ/","ja":"等間隔","kana":"とうかんかく","romaji":"toukankaku","vi":"chia đều (khoảng cách đều)","level":2,"def_vi":"Cách ghi gọn cho nhóm yếu tố giống nhau cách đều, chỉ ghi số lượng và một khoảng cách, viết tắt EQS.","def_en":"A simplified way of dimensioning repeated features at equal pitch, often abbreviated EQS.","def_ja":"同じ形体が等しいピッチで並ぶとき、数と間隔だけで簡略に示す方法。","usage_en":"Danh từ không đếm được; viết tắt 'EQS' hoặc 'EQ SP'. Collocation: 6 holes at equal spacing on a Ø100 PCD.","usage_ja":"等間隔 dùng trong ghi chú, ví dụ '6×φ10 等間隔'; với lỗ trên vòng tròn hay ghi 等配 (とうはい).","context_vi":"Dùng cho dãy lỗ trên mặt bích, tấm đục lỗ, rãnh chia đều trên chi tiết tròn.","ex_en":"Eight bolt holes are arranged at equal spacing on the flange.","ex_ja":"フランジには8個のボルト穴が等間隔に配置されている。","ex_vi":"Tám lỗ bu lông được bố trí chia đều trên mặt bích.","syn_en":["EQS (viết tắt)","equally spaced"],"syn_ja":["等配 (lỗ trên vòng tròn)","等ピッチ"]},{"en":"chain dimensioning","pos":"noun phrase","ipa":"/ˌtʃeɪn daɪˈmenʃənɪŋ/","ja":"直列寸法記入法","kana":"ちょくれつすんぽうきにゅうほう","romaji":"chokuretsusunpoukinyuuhou","vi":"ghi kích thước nối tiếp","level":2,"def_vi":"Cách ghi các kích thước nối tiếp nhau từ yếu tố này sang yếu tố kế tiếp; sai số sẽ cộng dồn.","def_en":"Dimensioning features one after another in a chain, so that tolerances accumulate.","def_ja":"個々の寸法を直列につないで記入する方法。公差が累積する。","usage_en":"Danh từ không đếm được. Collocation: avoid chain dimensioning on critical features because of tolerance build-up.","usage_ja":"直列寸法記入法 là tên JIS; xưởng nói 直列寸法. Chỉ dùng khi sai số cộng dồn không ảnh hưởng chức năng.","context_vi":"Gặp khi lập và kiểm tra bản vẽ; dùng cho kích thước không quan trọng như khoảng cách rãnh trang trí.","ex_en":"Chain dimensioning of the five holes caused a 0.3 mm error at the last hole.","ex_ja":"5つの穴を直列寸法記入法で指示したため、最後の穴で0.3 mmの誤差が出た。","ex_vi":"Việc ghi kích thước nối tiếp năm lỗ khiến lỗ cuối cùng bị sai 0,3 mm.","syn_en":["continuous dimensioning","point-to-point dimensioning"],"syn_ja":["直列寸法 (khẩu ngữ)"]},{"en":"baseline dimensioning","pos":"noun phrase","ipa":"/ˈbeɪslaɪn daɪˈmenʃənɪŋ/","ja":"並列寸法記入法","kana":"へいれつすんぽうきにゅうほう","romaji":"heiretsusunpoukinyuuhou","vi":"ghi kích thước song song (từ chuẩn chung)","level":2,"def_vi":"Cách ghi mọi kích thước từ cùng một đường chuẩn hoặc mặt chuẩn, nên sai số không cộng dồn.","def_en":"Dimensioning all features from one common reference line or surface, so tolerances do not accumulate.","def_ja":"共通の基準から各寸法を並列に記入する方法。公差は累積しない。","usage_en":"Danh từ không đếm được; còn gọi 'parallel dimensioning'. Collocation: use baseline dimensioning from the left face.","usage_ja":"並列寸法記入法 là tên JIS; xưởng nói 並列寸法 hoặc 基準からの寸法. Cụm: 基準面から並列に寸法を入れる.","context_vi":"Dùng cho chi tiết gia công CNC có mặt chuẩn rõ ràng, giúp lập trình và đo kiểm thuận tiện.","ex_en":"Baseline dimensioning from the left face matches the CNC program origin.","ex_ja":"左端面からの並列寸法記入法は、NCプログラムの原点と一致する。","ex_vi":"Ghi kích thước song song từ mặt đầu bên trái trùng với gốc tọa độ chương trình CNC.","syn_en":["parallel dimensioning","datum dimensioning"],"syn_ja":["並列寸法 (khẩu ngữ)"]},{"en":"reference dimension","pos":"noun phrase","ipa":"/ˈrefrəns daɪˌmenʃn/","ja":"参考寸法","kana":"さんこうすんぽう","romaji":"sankousunpou","vi":"kích thước tham khảo","level":2,"def_vi":"Kích thước ghi trong ngoặc đơn chỉ để tham khảo, không dùng để gia công hay kiểm tra nghiệm thu.","def_en":"A dimension in brackets given for information only, not used for manufacturing or inspection.","def_ja":"括弧を付けて記入し、参考として示す寸法。加工や検査の対象としない。","usage_en":"Danh từ đếm được. Ghi trong ngoặc (25) hoặc ghi 'REF' (Mỹ); collocation: shown as a reference dimension.","usage_ja":"参考寸法 ghi trong (  ); không có dung sai, không kiểm tra. Cụm: 参考寸法として記入する.","context_vi":"Dùng để báo chiều dài tổng hoặc kích thước phụ thuộc giúp người đọc dễ hình dung mà không gây trùng kích thước.","ex_en":"The overall length is given as a reference dimension in brackets.","ex_ja":"全長は括弧付きの参考寸法として記入している。","ex_vi":"Chiều dài toàn bộ được ghi trong ngoặc như một kích thước tham khảo.","syn_en":["REF dimension (Mỹ)","auxiliary dimension (Anh-Anh)"],"syn_ja":["括弧寸法 (khẩu ngữ)"]},{"en":"ordinate dimensioning","pos":"noun phrase","ipa":"/ˈɔːdɪnət daɪˈmenʃənɪŋ/","ja":"累進寸法記入法","kana":"るいしんすんぽうきにゅうほう","romaji":"ruishinsunpoukinyuuhou","vi":"ghi kích thước lũy tiến (theo tọa độ từ gốc)","level":3,"def_vi":"Cách ghi kích thước từ một gốc chung trên một đường kích thước duy nhất, con số ghi ở đầu đường gióng.","def_en":"Dimensioning from a common origin along a single dimension line, with values at the ends of extension lines.","def_ja":"共通の起点から一本の寸法線で累進的に寸法を示す方法。数値は寸法補助線の端に記入する。","usage_en":"Danh từ không đếm được; còn gọi 'running dimensioning' (Anh). Collocation: ordinate dimensions from the origin 0.","usage_ja":"累進寸法記入法 dùng 起点記号 (vòng tròn nhỏ) ở gốc 0; ưu điểm như 並列寸法 nhưng gọn hơn.","context_vi":"Dùng cho tấm nhiều lỗ, chi tiết cắt laser, đột dập, gia công CNC để bản vẽ gọn và không cộng dồn sai số.","ex_en":"Ordinate dimensioning keeps the drawing of the perforated plate clean.","ex_ja":"累進寸法記入法を使うと、多数の穴がある板の図面がすっきりする。","ex_vi":"Ghi kích thước lũy tiến giúp bản vẽ tấm đục lỗ gọn gàng.","syn_en":["running dimensioning (Anh-Anh)","ordinate dimensions"],"syn_ja":["累進寸法 (khẩu ngữ)"]},{"en":"coordinate dimensioning","pos":"noun phrase","ipa":"/kəʊˈɔːdɪnət daɪˈmenʃənɪŋ/","ja":"座標寸法記入法","kana":"ざひょうすんぽうきにゅうほう","romaji":"zahyousunpoukinyuuhou","vi":"ghi kích thước theo tọa độ (bảng tọa độ)","level":3,"def_vi":"Cách ghi vị trí các lỗ bằng tọa độ X, Y trong một bảng tham chiếu từ gốc tọa độ, thay vì vẽ từng đường kích thước.","def_en":"Giving feature positions as X and Y coordinates from an origin, usually in a table instead of dimension lines.","def_ja":"穴などの位置を原点からのX・Y座標で表に示す寸法記入法。","usage_en":"Danh từ không đếm được. Collocation: a hole table with X/Y coordinates; phù hợp khi dữ liệu xuất trực tiếp từ CAD.","usage_ja":"座標寸法記入法 đi kèm 座標表 hoặc 穴表; cụm: 座標で穴位置を示す.","context_vi":"Dùng cho tấm mạch, tấm đế nhiều lỗ, khuôn dập và chi tiết lập trình CNC.","ex_en":"Coordinate dimensioning with a hole table replaced over forty dimension lines.","ex_ja":"穴表を使った座標寸法記入法により、40本以上の寸法線が不要になった。","ex_vi":"Ghi kích thước theo tọa độ với bảng lỗ đã thay thế hơn bốn mươi đường kích thước.","syn_en":["tabular dimensioning","hole table (liên quan)"],"syn_ja":["座標寸法","穴表 (liên quan)"]},{"en":"functional dimension","pos":"noun phrase","ipa":"/ˈfʌŋkʃənl daɪˈmenʃn/","ja":"機能寸法","kana":"きのうすんぽう","romaji":"kinousunpou","vi":"kích thước chức năng","level":3,"def_vi":"Kích thước ảnh hưởng trực tiếp đến chức năng hoặc lắp ghép của chi tiết, phải được ghi trực tiếp và kiểm soát chặt.","def_en":"A dimension that directly affects the function or fit of a part and must be specified directly.","def_ja":"部品の機能や組立に直接影響し、直接記入して管理すべき寸法。","usage_en":"Danh từ đếm được. Collocation: dimension functional features directly; đối lập với 'non-functional dimension'.","usage_ja":"機能寸法 đối lập với 非機能寸法 và 参考寸法. Trong xưởng gọi 重要寸法 và thường đánh dấu để kiểm tra 100%.","context_vi":"Dùng khi xem xét thiết kế, lập kế hoạch kiểm tra và phân loại kích thước quan trọng (critical dimension).","ex_en":"The bearing seat diameter is a functional dimension and must be checked on every part.","ex_ja":"軸受はめあい部の直径は機能寸法なので、全数検査が必要である。","ex_vi":"Đường kính chỗ lắp ổ lăn là kích thước chức năng nên phải kiểm tra trên mọi chi tiết.","syn_en":["critical dimension (gần nghĩa)","key dimension"],"syn_ja":["重要寸法 (gần nghĩa)","非機能寸法 (trái nghĩa)"]},{"en":"redundant dimension","pos":"noun phrase","ipa":"/rɪˈdʌndənt daɪˈmenʃn/","ja":"重複寸法","kana":"ちょうふくすんぽう","romaji":"choufukusunpou","vi":"kích thước thừa (trùng lặp)","level":3,"def_vi":"Kích thước được ghi nhiều lần hoặc có thể suy ra từ các kích thước khác, gây mâu thuẫn dung sai; phải tránh.","def_en":"A dimension given more than once or derivable from others, which can create conflicting tolerances.","def_ja":"同じ寸法を重ねて記入したり、他の寸法から求まる寸法を記入したもの。避けるべきである。","usage_en":"Danh từ đếm được. Collocation: remove redundant dimensions; còn gọi 'double dimensioning' hoặc 'over-dimensioning'.","usage_ja":"重複寸法 đọc ちょうふくすんぽう; nguyên tắc JIS: 寸法は重複記入を避ける. Nếu cần thì đổi thành 参考寸法.","context_vi":"Là lỗi hay bị phát hiện khi kiểm tra bản vẽ, đặc biệt khi kích thước tổng và các đoạn đều có dung sai.","ex_en":"The checker marked the 120 mm length as a redundant dimension.","ex_ja":"検図者は120 mmの長さを重複寸法として指摘した。","ex_vi":"Người kiểm bản vẽ đánh dấu kích thước dài 120 mm là kích thước thừa.","syn_en":["double dimensioning","over-dimensioning"],"syn_ja":["二重寸法 (khẩu ngữ)"]},{"en":"not-to-scale dimension","pos":"noun phrase","ipa":"/ˌnɒt tə ˈskeɪl daɪˌmenʃn/","ja":"非比例寸法","kana":"ひひれいすんぽう","romaji":"hihireisunpou","vi":"kích thước không theo tỷ lệ","level":3,"def_vi":"Kích thước có con số không khớp với độ dài vẽ trên hình (do sửa đổi), được gạch dưới con số để báo hiệu.","def_en":"A dimension whose value does not match the drawn length, shown by underlining the value.","def_ja":"図形の大きさと比例しない寸法。寸法数値の下に太い線を引いて示す。","usage_en":"Danh từ đếm được. Mỹ thường ghi 'NTS' hoặc gạch dưới; collocation: underline the not-to-scale dimension.","usage_ja":"非比例寸法 được đánh dấu bằng nét đậm gạch dưới con số. Hay xuất hiện khi sửa bản vẽ tay mà không vẽ lại hình.","context_vi":"Gặp trên bản vẽ cũ được sửa đổi nhiều lần hoặc khi rút ngắn hình vẽ; người đọc không được đo trên giấy.","ex_en":"The 85 mm length is underlined because it is a not-to-scale dimension.","ex_ja":"長さ85 mmは非比例寸法なので、数値に下線が引かれている。","ex_vi":"Chiều dài 85 mm được gạch dưới vì là kích thước không theo tỷ lệ.","syn_en":["NTS dimension","out-of-scale dimension"],"syn_ja":["尺度どおりでない寸法"]}]},{"id":14,"words":[{"en":"tolerance","pos":"noun","ipa":"/ˈtɒlərəns/","ja":"公差","kana":"こうさ","romaji":"kousa","vi":"dung sai","level":1,"def_vi":"Hiệu giữa kích thước giới hạn lớn nhất và nhỏ nhất cho phép; là phạm vi sai lệch được chấp nhận khi chế tạo.","def_en":"The difference between the maximum and minimum permitted sizes; the allowed variation in manufacture.","def_ja":"許容される最大寸法と最小寸法との差。製作上許されるばらつきの幅。","usage_en":"Danh từ đếm được và không đếm được. Collocation: tight / close / loose tolerance, within tolerance, out of tolerance, a tolerance of ±0.05 mm.","usage_ja":"公差 dùng trong văn bản và xưởng; cụm: 公差内 (trong dung sai), 公差外 (ngoài dung sai), 公差が厳しい. Khẩu ngữ đôi khi nói トレランス.","context_vi":"Có mặt trên mọi bản vẽ chế tạo, phiếu kiểm tra và trong trao đổi giữa thiết kế và gia công về chi phí và khả năng làm được.","ex_en":"This bore has a tolerance of only 0.02 mm, so it must be reamed.","ex_ja":"この穴の公差は0.02 mmしかないので、リーマ仕上げが必要である。","ex_vi":"Lỗ này có dung sai chỉ 0,02 mm nên phải doa.","syn_en":["permissible variation","size tolerance (nghĩa hẹp hơn)"],"syn_ja":["トレランス (khẩu ngữ)","寸法公差 (nghĩa hẹp hơn)"]},{"en":"fit","pos":"noun","ipa":"/fɪt/","ja":"はめあい","kana":"はめあい","romaji":"hameai","vi":"lắp ghép","level":1,"def_vi":"Mối quan hệ về kích thước giữa lỗ và trục trước khi lắp, quyết định mối ghép lỏng hay chặt.","def_en":"The size relationship between a hole and a shaft before assembly, determining how loose or tight the joint is.","def_ja":"組み立てる前の穴と軸の寸法の関係。すきまやしめしろの状態を表す。","usage_en":"Danh từ đếm được. Collocation: H7/g6 fit, a loose / tight / sliding fit; động từ 'fit' nghĩa 'lắp vừa'.","usage_ja":"Viết hiragana はめあい (JIS), cũng gặp 嵌め合い. Cụm: はめあいを選ぶ, はめあい記号 H7/g6.","context_vi":"Dùng khi thiết kế mối ghép ổ lăn, bánh răng với trục, chốt định vị, bạc lót.","ex_en":"We chose an H7/g6 fit for the sliding pin.","ex_ja":"スライドピンにはH7/g6のはめあいを選んだ。","ex_vi":"Chúng tôi chọn lắp ghép H7/g6 cho chốt trượt.","syn_en":["fitting (ít dùng)","fit class (liên quan)"],"syn_ja":["嵌め合い","フィット (ít dùng)"]},{"en":"clearance","pos":"noun","ipa":"/ˈklɪərəns/","ja":"すきま","kana":"すきま","romaji":"sukima","vi":"độ hở","level":1,"def_vi":"Hiệu dương giữa kích thước lỗ và kích thước trục khi lỗ lớn hơn trục.","def_en":"The positive difference between hole size and shaft size when the hole is larger than the shaft.","def_ja":"穴の寸法が軸の寸法より大きいときの、両者の差。","usage_en":"Danh từ không đếm được hoặc đếm được (a clearance of 0.03 mm). Collocation: radial clearance, too much clearance, check the clearance with a feeler gauge.","usage_ja":"JIS viết hiragana すきま (cũng gặp 隙間). Cụm: すきまがある, すきまを測る, すきまゲージ.","context_vi":"Dùng khi lắp ráp, bảo trì (khe hở ổ trượt, khe hở piston) và khi tính toán lắp ghép.","ex_en":"The clearance between the shaft and the bush is 0.04 mm.","ex_ja":"軸とブシュの間のすきまは0.04 mmである。","ex_vi":"Độ hở giữa trục và bạc là 0,04 mm.","syn_en":["play (khẩu ngữ)","gap (nghĩa rộng hơn)"],"syn_ja":["隙間","クリアランス (khẩu ngữ)"]},{"en":"interference","pos":"noun","ipa":"/ˌɪntəˈfɪərəns/","ja":"しめしろ","kana":"しめしろ","romaji":"shimeshiro","vi":"độ dôi","level":1,"def_vi":"Hiệu giữa kích thước trục và kích thước lỗ khi trục lớn hơn lỗ, làm mối ghép chặt sau khi lắp.","def_en":"The difference between shaft size and hole size when the shaft is larger than the hole.","def_ja":"軸の寸法が穴の寸法より大きいときの、両者の差。","usage_en":"Danh từ không đếm được hoặc đếm được (an interference of 0.02 mm). Trong CAD, 'interference' còn nghĩa là 'va chạm' giữa chi tiết.","usage_ja":"Viết hiragana しめしろ (JIS), cũng gặp 締め代. Cụm: しめしろが大きい, しめしろを付ける. Va chạm trong CAD gọi 干渉.","context_vi":"Dùng khi thiết kế mối ghép ép bánh răng, vòng bi, bạc với trục để truyền mô-men không cần then.","ex_en":"An interference of 0.03 mm is enough to hold the bearing in place.","ex_ja":"軸受を固定するには0.03 mmのしめしろで十分である。","ex_vi":"Độ dôi 0,03 mm là đủ để giữ ổ lăn cố định.","syn_en":["negative clearance","press allowance (ít dùng)"],"syn_ja":["締め代","締めしろ"]},{"en":"clearance fit","pos":"noun phrase","ipa":"/ˈklɪərəns fɪt/","ja":"すきまばめ","kana":"すきまばめ","romaji":"sukimabame","vi":"lắp ghép có độ hở (lắp lỏng)","level":1,"def_vi":"Lắp ghép luôn có độ hở, lỗ luôn lớn hơn trục trong mọi tổ hợp kích thước cho phép.","def_en":"A fit that always gives clearance, the hole always being larger than the shaft.","def_ja":"穴と軸の間に常にすきまができるはめあい。","usage_en":"Danh từ đếm được. Collocation: a running / sliding clearance fit, H7/g6 is a clearance fit.","usage_ja":"すきまばめ viết hiragana (cũng gặp 隙間嵌め). Cụm: すきまばめにする, すきまばめで組み付ける.","context_vi":"Dùng cho trục quay trong bạc, chốt trượt, piston trong xi lanh, các mối ghép cần tháo lắp dễ.","ex_en":"The guide pin uses a clearance fit so it can slide freely.","ex_ja":"ガイドピンは自由にしゅう動できるよう、すきまばめにしている。","ex_vi":"Chốt dẫn hướng dùng lắp ghép có độ hở để trượt tự do.","syn_en":["loose fit","running fit (nghĩa hẹp hơn)"],"syn_ja":["隙間嵌め","ルーズフィット (khẩu ngữ)"]},{"en":"interference fit","pos":"noun phrase","ipa":"/ˌɪntəˈfɪərəns fɪt/","ja":"しまりばめ","kana":"しまりばめ","romaji":"shimaribame","vi":"lắp ghép có độ dôi (lắp chặt)","level":1,"def_vi":"Lắp ghép luôn có độ dôi, trục luôn lớn hơn lỗ, phải ép, nung nóng hoặc làm lạnh để lắp.","def_en":"A fit that always gives interference, the shaft always being larger than the hole.","def_ja":"穴と軸の間に常にしめしろができるはめあい。","usage_en":"Danh từ đếm được; khẩu ngữ hay gọi 'press fit'. Collocation: H7/p6 interference fit, assemble with an interference fit.","usage_ja":"しまりばめ viết hiragana (cũng gặp 締まり嵌め). Cụm: しまりばめで固定する. Lắp bằng máy ép gọi 圧入.","context_vi":"Dùng để cố định bạc, bánh răng, vòng bi trên trục hoặc trong vỏ mà không cần then hay vít.","ex_en":"The bronze bush is held in the housing by an interference fit.","ex_ja":"青銅ブシュはしまりばめでハウジングに固定されている。","ex_vi":"Bạc đồng được giữ trong vỏ bằng lắp ghép có độ dôi.","syn_en":["press fit (khẩu ngữ)","force fit"],"syn_ja":["締まり嵌め","圧入はめあい (khẩu ngữ)"]},{"en":"transition fit","pos":"noun phrase","ipa":"/trænˈzɪʃn fɪt/","ja":"中間ばめ","kana":"ちゅうかんばめ","romaji":"chuukanbame","vi":"lắp ghép trung gian","level":1,"def_vi":"Lắp ghép có thể có độ hở hoặc độ dôi nhỏ tùy kích thước thực của lỗ và trục.","def_en":"A fit that may give either a small clearance or a small interference, depending on actual sizes.","def_ja":"実際の寸法によって、すきまにもしめしろにもなるはめあい。","usage_en":"Danh từ đếm được. Collocation: H7/k6 transition fit, a transition fit for locating parts.","usage_ja":"中間ばめ đọc ちゅうかんばめ. Cụm: 中間ばめを選定する; dùng nhiều cho vòng trong ổ lăn với trục.","context_vi":"Dùng cho chi tiết cần định vị chính xác nhưng vẫn tháo lắp được như chốt định vị, khớp nối, puly.","ex_en":"A transition fit locates the coupling accurately but still allows removal.","ex_ja":"中間ばめにより、軸継手を正確に位置決めしつつ取り外しもできる。","ex_vi":"Lắp ghép trung gian giúp định vị khớp nối chính xác mà vẫn tháo ra được.","syn_en":["location fit (liên quan)","push fit (khẩu ngữ)"],"syn_ja":["中間嵌め"]},{"en":"nominal size","pos":"noun phrase","ipa":"/ˌnɒmɪnl ˈsaɪz/","ja":"基準寸法","kana":"きじゅんすんぽう","romaji":"kijunsunpou","vi":"kích thước danh nghĩa","level":1,"def_vi":"Kích thước lý thuyết ghi trên bản vẽ, làm gốc để tính các kích thước giới hạn bằng cách cộng sai lệch.","def_en":"The theoretical size shown on the drawing, from which the limits of size are calculated.","def_ja":"図面に示す基準となる寸法で、許容差を加えて許容限界寸法を求める。","usage_en":"Danh từ đếm được. Collocation: a nominal size of 25 mm, nominal diameter; 'basic size' là tên cũ.","usage_ja":"Xưởng và tài liệu cũ dùng 基準寸法; JIS B 0401:2016 đổi thành 図示サイズ. Cả hai đều cần biết.","context_vi":"Dùng khi tra bảng dung sai lắp ghép, ghi kích thước và chọn vật liệu, dụng cụ cắt.","ex_en":"For a nominal size of 30 mm, H7 gives a tolerance of 0 to +0.021 mm.","ex_ja":"基準寸法30 mmの場合、H7の許容差は0〜+0.021 mmである。","ex_vi":"Với kích thước danh nghĩa 30 mm, H7 cho dung sai từ 0 đến +0,021 mm.","syn_en":["basic size (tên cũ)","nominal dimension"],"syn_ja":["図示サイズ (JIS 2016)","呼び寸法 (gần nghĩa)"]},{"en":"general tolerance","pos":"noun phrase","ipa":"/ˌdʒenrəl ˈtɒlərəns/","ja":"普通公差","kana":"ふつうこうさ","romaji":"futsuukousa","vi":"dung sai chung (dung sai không chỉ dẫn)","level":1,"def_vi":"Dung sai áp dụng cho mọi kích thước không ghi dung sai riêng, chỉ định bằng một ghi chú theo tiêu chuẩn như ISO 2768.","def_en":"The tolerance applied to all dimensions without an individual tolerance, specified by a note such as ISO 2768-m.","def_ja":"個々に公差の指示がない寸法に適用する公差。JIS B 0405などを注記で指示する。","usage_en":"Danh từ đếm được. Collocation: general tolerances to ISO 2768-m; khẩu ngữ 'title block tolerance'.","usage_ja":"普通公差 thường ghi trong 表題欄 hoặc 注記: '普通公差 JIS B 0405-m'. Cấp: 精級 f, 中級 m, 粗級 c, 極粗級 v.","context_vi":"Có trên hầu hết bản vẽ chi tiết; giúp không phải ghi dung sai cho từng kích thước không quan trọng.","ex_en":"Unless otherwise stated, the general tolerance is ISO 2768-m.","ex_ja":"特に指示のない寸法の普通公差はJIS B 0405の中級とする。","ex_vi":"Trừ khi có ghi khác, dung sai chung là ISO 2768-m.","syn_en":["untoleranced dimension tolerance","title block tolerance (khẩu ngữ)"],"syn_ja":["一般公差","寸法の普通公差"]},{"en":"press fit","pos":"noun phrase","ipa":"/ˈpres fɪt/","ja":"圧入","kana":"あつにゅう","romaji":"atsunyuu","vi":"lắp ép","level":1,"def_vi":"Cách lắp chi tiết có độ dôi bằng lực ép của máy ép hoặc búa ở nhiệt độ thường.","def_en":"Assembly of an interference joint by pushing the parts together with a press at room temperature.","def_ja":"しめしろのある部品を常温でプレスなどにより押し込んで組み立てること。","usage_en":"Danh từ đếm được; động từ viết có gạch nối 'press-fit': press-fit the bearing. Collocation: press-fit force, press fit into the housing.","usage_ja":"圧入 đọc あつにゅう; động từ 圧入する. Cụm: 圧入荷重, ベアリングを圧入する, 圧入治具.","context_vi":"Dùng ở dây chuyền lắp ráp ổ lăn, bạc, chốt; thường kiểm soát lực ép để phát hiện lỗi.","ex_en":"The bearing is mounted on the shaft by press fit using a hydraulic press.","ex_ja":"軸受は油圧プレスで軸に圧入する。","ex_vi":"Ổ lăn được lắp ép lên trục bằng máy ép thủy lực.","syn_en":["force fit","interference fit (gần nghĩa)"],"syn_ja":["プレスフィット","しまりばめ (gần nghĩa)"]},{"en":"upper limit of size","pos":"noun phrase","ipa":"/ˌʌpə ˌlɪmɪt əv ˈsaɪz/","ja":"最大許容寸法","kana":"さいだいきょようすんぽう","romaji":"saidaikyoyousunpou","vi":"kích thước giới hạn lớn nhất","level":2,"def_vi":"Kích thước lớn nhất cho phép của một yếu tố, bằng kích thước danh nghĩa cộng sai lệch trên.","def_en":"The largest permitted size of a feature, equal to the nominal size plus the upper deviation.","def_ja":"形体に許される最大の寸法。基準寸法に上の許容差を加えた値。","usage_en":"Danh từ đếm được; viết tắt ULS; khẩu ngữ 'max size', 'high limit'. Collocation: exceed the upper limit of size.","usage_ja":"Tài liệu cũ dùng 最大許容寸法; JIS 2016 dùng 上の許容サイズ. Xưởng thường nói 上限 (じょうげん).","context_vi":"Dùng khi thiết lập calip, giới hạn trên của phiếu đo và tính độ hở, độ dôi.","ex_en":"The upper limit of size for Ø20 H7 is 20.021 mm.","ex_ja":"φ20 H7の最大許容寸法は20.021 mmである。","ex_vi":"Kích thước giới hạn lớn nhất của lỗ Ø20 H7 là 20,021 mm.","syn_en":["maximum limit of size","high limit (khẩu ngữ)"],"syn_ja":["上の許容サイズ (JIS 2016)","上限 (khẩu ngữ)"]},{"en":"lower limit of size","pos":"noun phrase","ipa":"/ˌləʊə ˌlɪmɪt əv ˈsaɪz/","ja":"最小許容寸法","kana":"さいしょうきょようすんぽう","romaji":"saishoukyoyousunpou","vi":"kích thước giới hạn nhỏ nhất","level":2,"def_vi":"Kích thước nhỏ nhất cho phép của một yếu tố, bằng kích thước danh nghĩa cộng sai lệch dưới.","def_en":"The smallest permitted size of a feature, equal to the nominal size plus the lower deviation.","def_ja":"形体に許される最小の寸法。基準寸法に下の許容差を加えた値。","usage_en":"Danh từ đếm được; viết tắt LLS; khẩu ngữ 'min size', 'low limit'. Collocation: below the lower limit of size.","usage_ja":"Tài liệu cũ dùng 最小許容寸法; JIS 2016 dùng 下の許容サイズ. Xưởng thường nói 下限 (かげん).","context_vi":"Dùng khi đo kiểm, đánh giá chi tiết đạt hay không và khi đặt giới hạn dưới cho máy đo tự động.","ex_en":"The shaft measured 19.978 mm, below the lower limit of size.","ex_ja":"軸の測定値は19.978 mmで、最小許容寸法を下回っていた。","ex_vi":"Trục đo được 19,978 mm, nhỏ hơn kích thước giới hạn nhỏ nhất.","syn_en":["minimum limit of size","low limit (khẩu ngữ)"],"syn_ja":["下の許容サイズ (JIS 2016)","下限 (khẩu ngữ)"]},{"en":"upper deviation","pos":"noun phrase","ipa":"/ˌʌpə ˌdiːviˈeɪʃn/","ja":"上の許容差","kana":"うえのきょようさ","romaji":"uenokyoyousa","vi":"sai lệch trên","level":2,"def_vi":"Hiệu giữa kích thước giới hạn lớn nhất và kích thước danh nghĩa; ký hiệu ES cho lỗ, es cho trục.","def_en":"Upper limit of size minus nominal size; symbol ES for holes and es for shafts.","def_ja":"最大許容寸法から基準寸法を引いた値。穴はES、軸はesで表す。","usage_en":"Danh từ đếm được. Collocation: an upper deviation of +0.021 mm; ghi trên bản vẽ dạng 20 +0.021/0.","usage_ja":"上の許容差 đọc うえのきょようさ; ghi phía trên trong cặp sai lệch. Cụm: 上の許容差を記入する.","context_vi":"Dùng khi tra bảng dung sai ISO/JIS và khi ghi dung sai dạng số trên bản vẽ.","ex_en":"For Ø20 H7 the upper deviation is +0.021 mm.","ex_ja":"φ20 H7の上の許容差は+0.021 mmである。","ex_vi":"Với lỗ Ø20 H7, sai lệch trên là +0,021 mm.","syn_en":["ES / es (ký hiệu)","upper limit deviation"],"syn_ja":["上の寸法許容差","ES・es (ký hiệu)"]},{"en":"lower deviation","pos":"noun phrase","ipa":"/ˌləʊə ˌdiːviˈeɪʃn/","ja":"下の許容差","kana":"したのきょようさ","romaji":"shitanokyoyousa","vi":"sai lệch dưới","level":2,"def_vi":"Hiệu giữa kích thước giới hạn nhỏ nhất và kích thước danh nghĩa; ký hiệu EI cho lỗ, ei cho trục.","def_en":"Lower limit of size minus nominal size; symbol EI for holes and ei for shafts.","def_ja":"最小許容寸法から基準寸法を引いた値。穴はEI、軸はeiで表す。","usage_en":"Danh từ đếm được. Collocation: a lower deviation of −0.013 mm; với lỗ H thì lower deviation bằng 0.","usage_ja":"下の許容差 đọc したのきょようさ; ghi phía dưới trong cặp sai lệch. Cụm: 下の許容差はゼロ.","context_vi":"Dùng khi tra bảng dung sai, tính độ hở và độ dôi của lắp ghép.","ex_en":"For a g6 shaft of Ø20, the lower deviation is −0.020 mm.","ex_ja":"φ20 g6の軸では、下の許容差は−0.020 mmである。","ex_vi":"Với trục Ø20 g6, sai lệch dưới là −0,020 mm.","syn_en":["EI / ei (ký hiệu)","lower limit deviation"],"syn_ja":["下の寸法許容差","EI・ei (ký hiệu)"]},{"en":"tolerance zone","pos":"noun phrase","ipa":"/ˈtɒlərəns zəʊn/","ja":"公差域","kana":"こうさいき","romaji":"kousaiki","vi":"miền dung sai","level":2,"def_vi":"Vùng giới hạn bởi kích thước lớn nhất và nhỏ nhất, biểu diễn trên sơ đồ lắp ghép so với đường không.","def_en":"The region between the upper and lower limits of size, shown relative to the zero line in fit diagrams.","def_ja":"最大許容寸法と最小許容寸法の間の領域。基準線に対して図示する。","usage_en":"Danh từ đếm được. Collocation: within the tolerance zone, position of the tolerance zone; trong GD&T cũng dùng cho vùng dung sai hình học.","usage_ja":"公差域 đọc こうさいき; vị trí của nó được ký hiệu bằng chữ (H, g, k...). Cụm: 公差域の位置, 公差域内.","context_vi":"Dùng khi giải thích hệ thống lắp ghép ISO và vẽ sơ đồ phân bố dung sai lỗ – trục.","ex_en":"The tolerance zone of the g6 shaft lies entirely below the zero line.","ex_ja":"g6の軸の公差域は、すべて基準線より下にある。","ex_vi":"Miền dung sai của trục g6 nằm hoàn toàn dưới đường không.","syn_en":["tolerance interval (ISO 2016)","tolerance band"],"syn_ja":["公差範囲 (khẩu ngữ)","公差幅 (liên quan)"]},{"en":"bilateral tolerance","pos":"noun phrase","ipa":"/baɪˈlætərəl ˈtɒlərəns/","ja":"両側公差","kana":"りょうがわこうさ","romaji":"ryougawakousa","vi":"dung sai hai phía","level":2,"def_vi":"Dung sai có sai lệch về cả hai phía của kích thước danh nghĩa, ví dụ 50 ±0,1 hoặc 50 +0,2/−0,1.","def_en":"A tolerance that varies on both sides of the nominal size, e.g. 50 ±0.1.","def_ja":"基準寸法の上下両側に許容差をもつ公差。例：50±0.1。","usage_en":"Danh từ đếm được. Dạng đối xứng gọi 'equal bilateral' (±), không đối xứng gọi 'unequal bilateral'.","usage_ja":"両側公差 đọc りょうがわこうさ; xưởng thường chỉ nói 'プラマイ0.1' (±0,1). Cụm: 両側公差で指示する.","context_vi":"Dùng phổ biến cho kích thước vị trí lỗ, chiều dài, khoảng cách tâm không đòi hỏi lắp ghép.","ex_en":"The hole position has a bilateral tolerance of ±0.05 mm.","ex_ja":"穴位置には±0.05 mmの両側公差が指示されている。","ex_vi":"Vị trí lỗ có dung sai hai phía ±0,05 mm.","syn_en":["plus-minus tolerance","symmetrical tolerance (nghĩa hẹp hơn)"],"syn_ja":["プラスマイナス公差 (khẩu ngữ)"]},{"en":"unilateral tolerance","pos":"noun phrase","ipa":"/ˌjuːnɪˈlætərəl ˈtɒlərəns/","ja":"片側公差","kana":"かたがわこうさ","romaji":"katagawakousa","vi":"dung sai một phía","level":2,"def_vi":"Dung sai chỉ sai lệch về một phía của kích thước danh nghĩa, ví dụ 20 +0,1/0 hoặc 20 0/−0,05.","def_en":"A tolerance that varies on one side of the nominal size only, e.g. 20 +0.1/0.","def_ja":"基準寸法の片側だけに許容差をもつ公差。例：20 +0.1/0。","usage_en":"Danh từ đếm được. Collocation: specify a unilateral tolerance on the bore; hay dùng cho lỗ (dương) và trục (âm).","usage_ja":"片側公差 đọc かたがわこうさ. Cụm: 片側公差にする; ví dụ '+0.1 / 0' đọc プラス0.1ゼロ.","context_vi":"Dùng cho lỗ, trục, chiều sâu rãnh khi chỉ cho phép lệch về phía an toàn cho lắp ráp.","ex_en":"The groove depth has a unilateral tolerance of +0.1/0 mm.","ex_ja":"溝の深さは+0.1/0 mmの片側公差である。","ex_vi":"Chiều sâu rãnh có dung sai một phía +0,1/0 mm.","syn_en":["one-sided tolerance","single-limit tolerance (liên quan)"],"syn_ja":["片側許容差"]},{"en":"hole-basis system","pos":"noun phrase","ipa":"/ˈhəʊl ˌbeɪsɪs ˌsɪstəm/","ja":"穴基準はめあい","kana":"あなきじゅんはめあい","romaji":"anakijunhameai","vi":"hệ thống lỗ cơ sở","level":2,"def_vi":"Hệ lắp ghép giữ lỗ là H (sai lệch dưới bằng 0) và thay đổi miền dung sai trục để có lắp lỏng, trung gian, chặt.","def_en":"A fit system keeping the hole at H (zero lower deviation) and varying the shaft to get different fits.","def_ja":"穴の公差域をH（下の許容差0）に固定し、軸の公差域を変えて各種はめあいを得る方式。","usage_en":"Danh từ đếm được; còn gọi 'basic hole system'. Collocation: use the hole-basis system, H7 hole-basis fits.","usage_ja":"Thuật ngữ JIS: 穴基準はめあい方式; xưởng nói 穴基準. Phổ biến hơn 軸基準 vì lỗ khó gia công nhiều cỡ.","context_vi":"Là hệ được ưu tiên trong chế tạo máy vì giảm số loại mũi doa và calip lỗ.","ex_en":"Our company uses the hole-basis system, so most bores are H7.","ex_ja":"当社は穴基準はめあいを採用しているので、ほとんどの穴はH7である。","ex_vi":"Công ty chúng tôi dùng hệ thống lỗ cơ sở nên phần lớn các lỗ là H7.","syn_en":["basic hole system","hole-based fit system"],"syn_ja":["穴基準はめあい方式","穴基準 (khẩu ngữ)"]},{"en":"shaft-basis system","pos":"noun phrase","ipa":"/ˈʃɑːft ˌbeɪsɪs ˌsɪstəm/","ja":"軸基準はめあい","kana":"じくきじゅんはめあい","romaji":"jikukijunhameai","vi":"hệ thống trục cơ sở","level":2,"def_vi":"Hệ lắp ghép giữ trục là h (sai lệch trên bằng 0) và thay đổi miền dung sai lỗ để có các kiểu lắp khác nhau.","def_en":"A fit system keeping the shaft at h (zero upper deviation) and varying the hole to get different fits.","def_ja":"軸の公差域をh（上の許容差0）に固定し、穴の公差域を変えて各種はめあいを得る方式。","usage_en":"Danh từ đếm được; còn gọi 'basic shaft system'. Collocation: shaft-basis fits for drawn bar stock.","usage_ja":"Thuật ngữ JIS: 軸基準はめあい方式; xưởng nói 軸基準. Cụm: 軸基準で設計する.","context_vi":"Dùng khi một trục dài kéo nguội lắp nhiều chi tiết khác nhau, hoặc với vòng ngoài ổ lăn, chốt tiêu chuẩn.","ex_en":"The textile machine uses a shaft-basis system because one long shaft carries many parts.","ex_ja":"その繊維機械は1本の長い軸に多くの部品を付けるため、軸基準はめあいを採用している。","ex_vi":"Máy dệt dùng hệ thống trục cơ sở vì một trục dài lắp nhiều chi tiết.","syn_en":["basic shaft system","shaft-based fit system"],"syn_ja":["軸基準はめあい方式","軸基準 (khẩu ngữ)"]},{"en":"tolerance grade","pos":"noun phrase","ipa":"/ˈtɒlərəns ɡreɪd/","ja":"公差等級","kana":"こうさとうきゅう","romaji":"kousatoukyuu","vi":"cấp chính xác (cấp dung sai IT)","level":2,"def_vi":"Cấp độ chính xác của dung sai theo hệ ISO, từ IT01 đến IT18; số càng nhỏ dung sai càng hẹp.","def_en":"A level of accuracy in the ISO system, IT01 to IT18; the smaller the number, the tighter the tolerance.","def_ja":"ISOの公差の精度の段階。IT01〜IT18があり、数字が小さいほど公差が小さい。","usage_en":"Danh từ đếm được; hay gọi 'IT grade'. Collocation: IT7 tolerance grade, a finer / coarser grade.","usage_ja":"公差等級 dùng trong văn bản; JIS 2016 gọi 基本サイズ公差等級. Xưởng nói 'IT7級', '7級'.","context_vi":"Dùng khi chọn phương pháp gia công: tiện tinh khoảng IT7–IT8, mài khoảng IT5–IT6.","ex_en":"Grinding is needed to reach tolerance grade IT6 on this shaft.","ex_ja":"この軸で公差等級IT6を得るには研削が必要である。","ex_vi":"Cần mài để trục này đạt cấp chính xác IT6.","syn_en":["IT grade","standard tolerance grade"],"syn_ja":["IT等級","基本サイズ公差等級 (JIS 2016)"]},{"en":"maximum clearance","pos":"noun phrase","ipa":"/ˌmæksɪməm ˈklɪərəns/","ja":"最大すきま","kana":"さいだいすきま","romaji":"saidaisukima","vi":"độ hở lớn nhất","level":2,"def_vi":"Độ hở khi lỗ ở kích thước lớn nhất và trục ở kích thước nhỏ nhất.","def_en":"The clearance when the hole is at its largest size and the shaft at its smallest.","def_ja":"穴が最大許容寸法、軸が最小許容寸法のときのすきま。","usage_en":"Danh từ đếm được. Collocation: calculate the maximum clearance; đi cặp với 'minimum clearance'.","usage_ja":"最大すきま = 穴の最大 − 軸の最小; đi cặp với 最小すきま. Cụm: 最大すきまを計算する.","context_vi":"Dùng khi kiểm tra lắp ghép có quá lỏng, gây rơ, ồn hay rò rỉ hay không.","ex_en":"The maximum clearance of the H7/g6 fit at Ø20 is 0.041 mm.","ex_ja":"φ20のH7/g6における最大すきまは0.041 mmである。","ex_vi":"Độ hở lớn nhất của lắp ghép H7/g6 tại Ø20 là 0,041 mm.","syn_en":["max clearance (khẩu ngữ)","minimum clearance (liên quan)"],"syn_ja":["最小すきま (liên quan)"]},{"en":"maximum interference","pos":"noun phrase","ipa":"/ˌmæksɪməm ˌɪntəˈfɪərəns/","ja":"最大しめしろ","kana":"さいだいしめしろ","romaji":"saidaishimeshiro","vi":"độ dôi lớn nhất","level":2,"def_vi":"Độ dôi khi trục ở kích thước lớn nhất và lỗ ở kích thước nhỏ nhất.","def_en":"The interference when the shaft is at its largest size and the hole at its smallest.","def_ja":"軸が最大許容寸法、穴が最小許容寸法のときのしめしろ。","usage_en":"Danh từ đếm được. Collocation: maximum interference determines the press-fit force and hoop stress.","usage_ja":"最大しめしろ = 軸の最大 − 穴の最小; đi cặp với 最小しめしろ. Cụm: 最大しめしろで圧入荷重を求める.","context_vi":"Dùng khi tính lực ép, ứng suất vòng của bạc và nhiệt độ nung nóng khi lắp nóng.","ex_en":"The press capacity was chosen for the maximum interference of 0.06 mm.","ex_ja":"プレスの能力は最大しめしろ0.06 mmを基準に選定した。","ex_vi":"Công suất máy ép được chọn theo độ dôi lớn nhất 0,06 mm.","syn_en":["max interference (khẩu ngữ)","minimum interference (liên quan)"],"syn_ja":["最小しめしろ (liên quan)"]},{"en":"shrink fit","pos":"noun phrase","ipa":"/ˈʃrɪŋk fɪt/","ja":"焼ばめ","kana":"やきばめ","romaji":"yakibame","vi":"lắp nóng (lắp co nhiệt)","level":2,"def_vi":"Cách lắp ghép có độ dôi bằng cách nung nóng chi tiết bao cho nở ra, lồng vào rồi để nguội co lại ôm chặt.","def_en":"An interference fit made by heating the outer part so it expands, assembling it, then letting it cool.","def_ja":"外側の部品を加熱して膨張させてはめ込み、冷えて収縮する力で固定するしまりばめ。","usage_en":"Danh từ đếm được; động từ 'shrink-fit' hoặc 'shrink on'. Collocation: shrink-fit the gear onto the shaft.","usage_ja":"焼ばめ cũng viết 焼き嵌め; ngược lại, làm lạnh trục gọi 冷やしばめ. Cụm: 焼ばめする, 焼ばめ温度.","context_vi":"Dùng để lắp bánh răng lớn, vành bánh xe lửa, khớp nối, bầu kẹp dao (shrink-fit chuck).","ex_en":"The gear rim is heated to 200 °C for the shrink fit onto the hub.","ex_ja":"歯車のリムを200 °Cに加熱し、ハブに焼ばめする。","ex_vi":"Vành bánh răng được nung đến 200 °C để lắp nóng lên moay-ơ.","syn_en":["shrinkage fit","expansion fit (lắp lạnh, liên quan)"],"syn_ja":["焼き嵌め","冷やしばめ (lắp lạnh, liên quan)"]},{"en":"actual size","pos":"noun phrase","ipa":"/ˌæktʃuəl ˈsaɪz/","ja":"実寸法","kana":"じっすんぽう","romaji":"jissunpou","vi":"kích thước thực","level":2,"def_vi":"Kích thước đo được trên chi tiết đã chế tạo, dùng để so với kích thước giới hạn khi kiểm tra.","def_en":"The size of a manufactured feature obtained by measurement, compared with the limits of size.","def_ja":"製作された形体を測定して得た寸法。許容限界寸法と比べて合否を判定する。","usage_en":"Danh từ đếm được. Collocation: the actual size is within limits; đừng nhầm với 'actual size' nghĩa 'tỷ lệ 1:1'.","usage_ja":"実寸法 đọc じっすんぽう; xưởng nói 実寸 hoặc 実測値. JIS 2016 dùng các khái niệm mới như 当てはめサイズ.","context_vi":"Dùng trong phiếu đo, báo cáo kiểm tra và khi phân loại chi tiết để lắp chọn.","ex_en":"The actual size of the bore was 25.012 mm, inside the H7 limits.","ex_ja":"穴の実寸法は25.012 mmで、H7の範囲内だった。","ex_vi":"Kích thước thực của lỗ là 25,012 mm, nằm trong giới hạn H7.","syn_en":["measured size","actual local size (thuật ngữ ISO)"],"syn_ja":["実寸 (khẩu ngữ)","実測値"]},{"en":"fundamental deviation","pos":"noun phrase","ipa":"/ˌfʌndəˈmentl ˌdiːviˈeɪʃn/","ja":"基礎となる許容差","kana":"きそとなるきょようさ","romaji":"kisotonarukyoyousa","vi":"sai lệch cơ bản","level":3,"def_vi":"Sai lệch gần đường không nhất, xác định vị trí miền dung sai và được ký hiệu bằng chữ cái (H, g, k, p...).","def_en":"The deviation nearest the zero line, fixing the tolerance zone position; shown by a letter such as H, g or p.","def_ja":"基準線に最も近い許容差で、公差域の位置を決め、H、g、pなどの文字で表す。","usage_en":"Danh từ đếm được. Chữ in hoa cho lỗ, chữ thường cho trục; collocation: fundamental deviation 'g' is −0.007 mm at Ø20.","usage_ja":"Thuật ngữ JIS: 基礎となる許容差; chữ cái gọi 公差域の位置の記号. Cụm: 基礎となる許容差を表から求める.","context_vi":"Dùng khi tra bảng ISO 286 để tính sai lệch cho ký hiệu dung sai như g6, k6, P7.","ex_en":"The fundamental deviation of a g shaft is always negative.","ex_ja":"gの軸の基礎となる許容差は常に負である。","ex_vi":"Sai lệch cơ bản của trục g luôn mang giá trị âm.","syn_en":["fundamental deviation letter (liên quan)","position of tolerance zone (liên quan)"],"syn_ja":["基礎許容差 (khẩu ngữ)"]},{"en":"standard tolerance","pos":"noun phrase","ipa":"/ˌstændəd ˈtɒlərəns/","ja":"基本公差","kana":"きほんこうさ","romaji":"kihonkousa","vi":"dung sai tiêu chuẩn (trị số IT)","level":3,"def_vi":"Trị số dung sai lấy từ bảng ISO 286 theo khoảng kích thước danh nghĩa và cấp chính xác IT.","def_en":"A tolerance value from the ISO 286 table, determined by the nominal size range and the IT grade.","def_ja":"ISO 286の表で、寸法区分と公差等級により定まる公差の値。","usage_en":"Danh từ đếm được. Collocation: the standard tolerance for IT7 at 30 mm is 21 µm; ký hiệu IT7, IT8.","usage_ja":"Tài liệu cũ dùng 基本公差; JIS B 0401:2016 dùng 基本サイズ公差. Cụm: 基本公差の数値表.","context_vi":"Dùng khi tính toán dung sai lắp ghép và khi lập bảng tra dung sai trong phòng thiết kế.","ex_en":"The standard tolerance IT7 for sizes from 18 to 30 mm is 0.021 mm.","ex_ja":"寸法区分18〜30 mmにおけるIT7の基本公差は0.021 mmである。","ex_vi":"Dung sai tiêu chuẩn IT7 cho khoảng kích thước 18–30 mm là 0,021 mm.","syn_en":["IT tolerance","international tolerance"],"syn_ja":["基本サイズ公差 (JIS 2016)","IT公差"]},{"en":"tolerance class","pos":"noun phrase","ipa":"/ˈtɒlərəns klɑːs/","ja":"公差クラス","kana":"こうさクラス","romaji":"kousakurasu","vi":"ký hiệu miền dung sai (như H7, g6)","level":3,"def_vi":"Tổ hợp chữ chỉ sai lệch cơ bản và số chỉ cấp chính xác, ví dụ H7, g6, xác định hoàn toàn miền dung sai.","def_en":"The combination of a fundamental deviation letter and an IT grade number, such as H7 or g6.","def_ja":"基礎となる許容差の記号と公差等級の数字の組合せ。例：H7、g6。","usage_en":"Danh từ đếm được. Collocation: tolerance class H7, specify the tolerance class after the size: Ø25 H7.","usage_ja":"JIS 2016 dùng 公差クラス; tài liệu cũ gọi 公差域クラス. Xưởng chỉ nói 'H7', 'エイチなな'.","context_vi":"Ghi trực tiếp sau kích thước trên bản vẽ (Ø25 H7) và dùng để chọn mũi doa, calip.","ex_en":"Write the tolerance class directly after the nominal size, for example Ø25 H7.","ex_ja":"公差クラスは基準寸法の後に、例えばφ25 H7のように記入する。","ex_vi":"Ghi ký hiệu miền dung sai ngay sau kích thước danh nghĩa, ví dụ Ø25 H7.","syn_en":["tolerance designation","fit symbol (liên quan)"],"syn_ja":["公差域クラス (tên cũ)","はめあい記号 (liên quan)"]},{"en":"zero line","pos":"noun phrase","ipa":"/ˈzɪərəʊ laɪn/","ja":"基準線","kana":"きじゅんせん","romaji":"kijunsen","vi":"đường không (đường kích thước danh nghĩa)","level":3,"def_vi":"Đường thẳng biểu diễn kích thước danh nghĩa trên sơ đồ lắp ghép, từ đó đo các sai lệch dương và âm.","def_en":"The straight line representing the nominal size in a fit diagram, from which deviations are measured.","def_ja":"はめあいの図示で基準寸法を表す直線。許容差はこれを基準に正負で表す。","usage_en":"Danh từ đếm được. Collocation: above / below the zero line; dùng khi vẽ sơ đồ miền dung sai.","usage_ja":"基準線 trong ngữ cảnh はめあい; JIS 2016 gọi ゼロ線. Cụm: 基準線より上.","context_vi":"Gặp trong giáo trình dung sai lắp ghép và sơ đồ phân bố miền dung sai lỗ – trục.","ex_en":"Hole tolerance zones marked H start exactly at the zero line.","ex_ja":"Hの穴の公差域は基準線からちょうど始まる。","ex_vi":"Miền dung sai lỗ H bắt đầu đúng tại đường không.","syn_en":["nominal line","line of zero deviation"],"syn_ja":["ゼロ線 (JIS 2016)"]},{"en":"tolerance stack-up","pos":"noun phrase","ipa":"/ˈtɒlərəns ˌstæk ʌp/","ja":"公差積み上げ","kana":"こうさつみあげ","romaji":"kousatsumiage","vi":"chuỗi kích thước (cộng dồn dung sai)","level":3,"def_vi":"Việc cộng dồn dung sai của các kích thước trong một chuỗi để tính sai lệch của khâu khép kín như khe hở lắp ráp.","def_en":"The accumulation of tolerances along a chain of dimensions to find the variation of a resulting gap.","def_ja":"寸法の連鎖に沿って公差を積み上げ、組立後のすきまなどのばらつきを求めること。","usage_en":"Danh từ đếm được hoặc không; khẩu ngữ 'stack-up'. Collocation: do / run a tolerance stack-up, stack-up analysis.","usage_ja":"公差積み上げ còn gọi 公差計算, 寸法連鎖計算; xưởng gọi 積み上げ計算. Cụm: 公差積み上げを行う.","context_vi":"Dùng khi thiết kế cụm lắp nhiều chi tiết để đảm bảo khe hở dọc trục, khe hở lắp ráp luôn trong giới hạn.","ex_en":"The tolerance stack-up shows the axial gap could reach 0.8 mm.","ex_ja":"公差積み上げの結果、軸方向のすきまは最大0.8 mmになり得る。","ex_vi":"Tính chuỗi kích thước cho thấy khe hở dọc trục có thể lên tới 0,8 mm.","syn_en":["stack-up (khẩu ngữ)","tolerance chain"],"syn_ja":["公差計算","寸法連鎖 (liên quan)"]},{"en":"worst-case analysis","pos":"noun phrase","ipa":"/ˌwɜːst keɪs əˈnæləsɪs/","ja":"ワーストケース解析","kana":"ワーストケースかいせき","romaji":"waasutokeesukaiseki","vi":"phân tích trường hợp xấu nhất (phương pháp max–min)","level":3,"def_vi":"Phương pháp tính chuỗi kích thước bằng cách cộng toàn bộ dung sai ở giới hạn bất lợi nhất, đảm bảo lắp được 100%.","def_en":"A stack-up method adding all tolerances at their extreme limits, guaranteeing 100% assembly.","def_ja":"すべての公差を最悪の限界値で足し合わせ、全数の組立を保証する計算方法。","usage_en":"Danh từ đếm được. Collocation: worst-case stack-up, worst-case analysis is conservative and costly.","usage_ja":"Khẩu ngữ ワーストケース計算; tên học thuật: 完全互換性法 hoặc 最大最小法. Cụm: ワーストケースで計算する.","context_vi":"Dùng cho cụm lắp ít chi tiết hoặc chi tiết an toàn, khi không chấp nhận bất kỳ sản phẩm lắp hỏng nào.","ex_en":"Worst-case analysis requires a 0.02 mm tolerance on every spacer, which is too expensive.","ex_ja":"ワーストケース解析では各スペーサに0.02 mmの公差が必要になり、コストが高すぎる。","ex_vi":"Phân tích trường hợp xấu nhất đòi hỏi dung sai 0,02 mm cho mỗi vòng đệm, quá tốn kém.","syn_en":["arithmetic stack-up","max-min method"],"syn_ja":["完全互換性法","最大最小法"]}]},{"id":15,"words":[{"en":"geometric tolerance","pos":"noun phrase","ipa":"/ˌdʒiːəˈmetrɪk ˈtɒlərəns/","ja":"幾何公差","kana":"きかこうさ","romaji":"kikakousa","vi":"dung sai hình học","level":1,"def_vi":"Dung sai giới hạn sai lệch về hình dạng, hướng, vị trí và độ đảo của một yếu tố, độc lập với dung sai kích thước.","def_en":"A tolerance limiting the form, orientation, location or runout of a feature, separate from size tolerance.","def_ja":"形体の形状・姿勢・位置・振れの狂いの許容値。寸法公差とは別に指示する。","usage_en":"Danh từ đếm được. Hệ thống ghi gọi là GD&T (geometric dimensioning and tolerancing). Collocation: apply / specify a geometric tolerance.","usage_ja":"幾何公差 đọc きかこうさ; cụm: 幾何公差を指示する, 幾何公差記号. Tiêu chuẩn: JIS B 0021 (ISO 1101).","context_vi":"Dùng trên bản vẽ chi tiết chính xác như trục, vỏ hộp số, khuôn, linh kiện ô tô và hàng không.","ex_en":"A size tolerance alone cannot control flatness, so add a geometric tolerance.","ex_ja":"寸法公差だけでは平面度を規制できないので、幾何公差を追加する。","ex_vi":"Chỉ dung sai kích thước thì không kiểm soát được độ phẳng, nên hãy thêm dung sai hình học.","syn_en":["GD&T (hệ thống, nghĩa rộng hơn)","geometrical tolerance (ISO)"],"syn_ja":["GD&T (hệ ASME)","幾何偏差 (sai lệch thực, liên quan)"]},{"en":"datum","pos":"noun","ipa":"/ˈdeɪtəm/","ja":"データム","kana":"データム","romaji":"deetamu","vi":"chuẩn (mặt chuẩn, chuẩn đo)","level":1,"def_vi":"Điểm, đường thẳng hoặc mặt phẳng lý tưởng làm gốc để xác định hướng và vị trí của dung sai hình học.","def_en":"A theoretically exact point, axis or plane used as the reference for orientation and location tolerances.","def_ja":"姿勢公差や位置公差を規制するための基準となる、理論的に正確な点・直線・平面。","usage_en":"Danh từ đếm được, số nhiều 'datums' (kỹ thuật) hơn là 'data'. Collocation: datum A, primary / secondary / tertiary datum, measure from the datum.","usage_ja":"Viết katakana データム; trong xưởng cũng nói 基準, 基準面. Cụm: データムAに対して, データムを設定する.","context_vi":"Dùng trên bản vẽ có dung sai hình học, khi lập trình đo CMM và khi thiết kế đồ gá định vị.","ex_en":"All hole positions are measured from datum A, the bottom face.","ex_ja":"すべての穴位置は、底面であるデータムAから測定する。","ex_vi":"Mọi vị trí lỗ được đo từ chuẩn A, tức mặt đáy.","syn_en":["reference (khẩu ngữ)","datum plane (nghĩa hẹp hơn)"],"syn_ja":["基準 (khẩu ngữ)","基準面 (nghĩa hẹp hơn)"]},{"en":"flatness","pos":"noun","ipa":"/ˈflætnəs/","ja":"平面度","kana":"へいめんど","romaji":"heimendo","vi":"độ phẳng","level":1,"def_vi":"Dung sai hình dạng yêu cầu bề mặt nằm giữa hai mặt phẳng song song cách nhau bằng trị số dung sai.","def_en":"A form tolerance requiring a surface to lie between two parallel planes separated by the tolerance value.","def_ja":"対象の平面が、公差値だけ離れた二つの平行な平面の間にあることを求める形状公差。","usage_en":"Danh từ không đếm được. Collocation: flatness of 0.05 mm, check flatness on a surface plate; không cần datum.","usage_ja":"平面度 đọc へいめんど; ký hiệu ▱. Cụm: 平面度0.05, 平面度を測る, 平面度が出ない.","context_vi":"Dùng cho mặt lắp gioăng, mặt bích, mặt đế máy, mặt trượt và mặt tiếp xúc của khuôn.","ex_en":"The sealing face needs a flatness of 0.02 mm to prevent leaks.","ex_ja":"漏れを防ぐため、シール面には平面度0.02 mmが必要である。","ex_vi":"Mặt làm kín cần độ phẳng 0,02 mm để chống rò rỉ.","syn_en":["planarity (ít dùng)","flatness tolerance"],"syn_ja":["平面度公差","フラットネス (ít dùng)"]},{"en":"straightness","pos":"noun","ipa":"/ˈstreɪtnəs/","ja":"真直度","kana":"しんちょくど","romaji":"shinchokudo","vi":"độ thẳng","level":1,"def_vi":"Dung sai hình dạng giới hạn độ cong của một đường thẳng trên bề mặt hoặc của đường trục.","def_en":"A form tolerance limiting how much a line on a surface or an axis may deviate from a straight line.","def_ja":"表面上の線や軸線が、幾何学的な直線からどれだけ狂ってよいかを規制する形状公差。","usage_en":"Danh từ không đếm được. Collocation: straightness of the axis, straightness of 0.01 mm per 100 mm.","usage_ja":"真直度 đọc しんちょくど (không phải まっすぐど); ký hiệu một đoạn thẳng ―. Cụm: 軸線の真直度.","context_vi":"Dùng cho trục dài, thanh dẫn hướng, ray trượt, cần piston và đường sinh của chi tiết trụ.","ex_en":"The guide rail has a straightness tolerance of 0.01 mm per 100 mm.","ex_ja":"ガイドレールの真直度は100 mmあたり0.01 mmである。","ex_vi":"Thanh ray dẫn hướng có dung sai độ thẳng 0,01 mm trên 100 mm.","syn_en":["straightness tolerance","bow (độ cong, khẩu ngữ)"],"syn_ja":["真直度公差","曲がり (khẩu ngữ)"]},{"en":"roundness","pos":"noun","ipa":"/ˈraʊndnəs/","ja":"真円度","kana":"しんえんど","romaji":"shinendo","vi":"độ tròn","level":1,"def_vi":"Dung sai hình dạng yêu cầu mỗi tiết diện ngang nằm giữa hai đường tròn đồng tâm cách nhau bằng trị số dung sai.","def_en":"A form tolerance requiring each cross-section to lie between two concentric circles separated by the tolerance.","def_ja":"各横断面の外形が、公差値だけ離れた二つの同心円の間にあることを求める形状公差。","usage_en":"Danh từ không đếm được; Mỹ (ASME) gọi 'circularity'. Collocation: roundness of 0.005 mm, measure roundness on a roundness tester.","usage_ja":"真円度 đọc しんえんど; ký hiệu ○. Máy đo gọi 真円度測定機. Cụm: 真円度が悪い (méo).","context_vi":"Dùng cho ngõng trục, lỗ lắp ổ lăn, piston, xi lanh, con lăn ổ lăn.","ex_en":"Poor roundness of the bore caused the bearing to run hot.","ex_ja":"穴の真円度が悪かったため、軸受が発熱した。","ex_vi":"Độ tròn của lỗ kém khiến ổ lăn bị nóng khi chạy.","syn_en":["circularity (ASME)","out-of-roundness (sai lệch, liên quan)"],"syn_ja":["真円度公差","楕円 (khẩu ngữ, liên quan)"]},{"en":"cylindricity","pos":"noun","ipa":"/ˌsɪlɪnˈdrɪsəti/","ja":"円筒度","kana":"えんとうど","romaji":"entoudo","vi":"độ trụ","level":1,"def_vi":"Dung sai hình dạng yêu cầu toàn bộ mặt trụ nằm giữa hai mặt trụ đồng trục cách nhau bằng trị số dung sai.","def_en":"A form tolerance requiring a whole cylindrical surface to lie between two coaxial cylinders.","def_ja":"円筒面全体が、公差値だけ離れた二つの同軸円筒の間にあることを求める形状公差。","usage_en":"Danh từ không đếm được. Collocation: cylindricity of 0.01 mm; tổng hợp cả độ tròn, độ thẳng và độ côn.","usage_ja":"円筒度 đọc えんとうど; ký hiệu ⌭ (vòng tròn giữa hai nét xiên). Cụm: 円筒度を指示する.","context_vi":"Dùng cho xi lanh thủy lực, ống lót, trục lắp ổ lăn, nòng van trượt.","ex_en":"The hydraulic cylinder bore has a cylindricity tolerance of 0.01 mm.","ex_ja":"油圧シリンダの内径には円筒度0.01 mmが指示されている。","ex_vi":"Lỗ xi lanh thủy lực có dung sai độ trụ 0,01 mm.","syn_en":["cylindricity tolerance","roundness (liên quan)"],"syn_ja":["円筒度公差","真円度 (liên quan)"]},{"en":"parallelism","pos":"noun","ipa":"/ˈpærəlelɪzəm/","ja":"平行度","kana":"へいこうど","romaji":"heikoudo","vi":"độ song song","level":1,"def_vi":"Dung sai hướng yêu cầu mặt hoặc trục song song với chuẩn, nằm giữa hai mặt song song với chuẩn cách nhau bằng dung sai.","def_en":"An orientation tolerance requiring a surface or axis to lie within a zone parallel to a datum.","def_ja":"データムに平行で、公差値だけ離れた二平面などの間に対象があることを求める姿勢公差。","usage_en":"Danh từ không đếm được. Collocation: parallelism to datum A, parallelism of 0.02 mm; luôn cần datum.","usage_ja":"平行度 đọc へいこうど; ký hiệu //. Cụm: データムAに対する平行度, 平行度を出す.","context_vi":"Dùng cho hai mặt đối diện của tấm, mặt trượt, trục song song trong hộp số.","ex_en":"The top face must have a parallelism of 0.03 mm to datum A.","ex_ja":"上面はデータムAに対して平行度0.03 mm以内とする。","ex_vi":"Mặt trên phải có độ song song 0,03 mm so với chuẩn A.","syn_en":["parallelism tolerance","parallel (khẩu ngữ)"],"syn_ja":["平行度公差"]},{"en":"perpendicularity","pos":"noun","ipa":"/ˌpɜːpənˌdɪkjuˈlærəti/","ja":"直角度","kana":"ちょっかくど","romaji":"chokkakudo","vi":"độ vuông góc","level":1,"def_vi":"Dung sai hướng yêu cầu mặt hoặc trục vuông góc với chuẩn trong phạm vi trị số dung sai.","def_en":"An orientation tolerance requiring a surface or axis to be at 90° to a datum within the tolerance.","def_ja":"対象の面や軸線がデータムに対して直角であるべき姿勢の狂いを規制する公差。","usage_en":"Danh từ không đếm được; ASME còn gọi 'squareness' (khẩu ngữ). Collocation: perpendicularity to datum A, perpendicularity of the bore axis.","usage_ja":"直角度 đọc ちょっかくど; ký hiệu ⊥. Cụm: データムAに対する直角度, 直角度を測る.","context_vi":"Dùng cho lỗ chốt so với mặt lắp, mặt đầu trục so với đường trục, các mặt của khối gá.","ex_en":"The pin hole has a perpendicularity of 0.02 mm to the mounting face.","ex_ja":"ピン穴は取付け面に対して直角度0.02 mmである。","ex_vi":"Lỗ chốt có độ vuông góc 0,02 mm so với mặt lắp.","syn_en":["squareness (khẩu ngữ)","perpendicularity tolerance"],"syn_ja":["直角度公差","直角 (khẩu ngữ)"]},{"en":"position","pos":"noun","ipa":"/pəˈzɪʃn/","ja":"位置度","kana":"いちど","romaji":"ichido","vi":"dung sai vị trí (độ vị trí)","level":1,"def_vi":"Dung sai vị trí giới hạn sai lệch của tâm hoặc trục lỗ so với vị trí lý thuyết xác định từ các chuẩn.","def_en":"A location tolerance limiting how far a feature's centre or axis may be from its exact location relative to datums.","def_ja":"データムと理論的に正確な寸法で決まる位置から、形体の中心や軸線がずれてよい範囲を規制する公差。","usage_en":"Danh từ không đếm được trong GD&T; còn gọi 'true position'. Collocation: position tolerance of Ø0.1, position relative to A, B, C.","usage_ja":"位置度 đọc いちど; ký hiệu ⌖ (vòng tròn có chữ thập). Cụm: 位置度φ0.1, 位置度公差.","context_vi":"Là dung sai hình học dùng nhiều nhất, cho vị trí lỗ bu lông, lỗ chốt, rãnh trên vỏ và tấm lắp.","ex_en":"The four holes have a position tolerance of Ø0.1 mm relative to datums A, B and C.","ex_ja":"4つの穴には、データムA、B、Cに対して位置度φ0.1 mmが指示されている。","ex_vi":"Bốn lỗ có dung sai vị trí Ø0,1 mm so với các chuẩn A, B và C.","syn_en":["true position (ASME)","positional tolerance"],"syn_ja":["位置度公差","トゥルーポジション (khẩu ngữ)"]},{"en":"coaxiality","pos":"noun","ipa":"/ˌkəʊæksiˈæləti/","ja":"同軸度","kana":"どうじくど","romaji":"doujikudo","vi":"độ đồng trục","level":1,"def_vi":"Dung sai vị trí yêu cầu đường trục của yếu tố nằm trong hình trụ nhỏ đồng trục với trục chuẩn.","def_en":"A location tolerance requiring a feature's axis to lie within a small cylinder coaxial with the datum axis.","def_ja":"対象の軸線が、データム軸直線と同軸の円筒の中にあることを求める位置公差。","usage_en":"Danh từ không đếm được; khẩu ngữ hay nói 'concentricity' nhưng ISO phân biệt (concentricity dùng cho điểm). Collocation: coaxiality of Ø0.02 to datum A.","usage_ja":"同軸度 đọc どうじくど; ký hiệu ◎. Với tâm của một tiết diện gọi 同心度. Xưởng hay nói 芯ずれ (lệch tâm).","context_vi":"Dùng cho trục bậc, hai lỗ ổ lăn ở hai đầu vỏ hộp, bạc, ống lót cần đồng tâm.","ex_en":"The two bearing bores require a coaxiality of Ø0.02 mm.","ex_ja":"2つの軸受穴にはφ0.02 mmの同軸度が必要である。","ex_vi":"Hai lỗ lắp ổ lăn đòi hỏi độ đồng trục Ø0,02 mm.","syn_en":["concentricity (khẩu ngữ, gần nghĩa)","coaxiality tolerance"],"syn_ja":["同心度 (gần nghĩa)","芯ずれ (sai lệch, khẩu ngữ)"]},{"en":"feature control frame","pos":"noun phrase","ipa":"/ˈfiːtʃə kənˈtrəʊl freɪm/","ja":"公差記入枠","kana":"こうさきにゅうわく","romaji":"kousakinyuuwaku","vi":"khung ghi dung sai hình học","level":2,"def_vi":"Khung chữ nhật chia ô chứa ký hiệu đặc tính, trị số dung sai và chữ chuẩn, nối với yếu tố bằng đường dẫn.","def_en":"A rectangular box divided into cells holding the characteristic symbol, tolerance value and datum letters.","def_ja":"幾何特性の記号、公差値、データム文字を区切って記入する長方形の枠。","usage_en":"Danh từ đếm được; viết tắt FCF. Collocation: read the feature control frame from left to right.","usage_ja":"公差記入枠 đọc こうさきにゅうわく; xưởng gọi 公差枠. Cụm: 公差記入枠を引出線で形体に結ぶ.","context_vi":"Có trên mọi bản vẽ dùng GD&T; người đo CMM đọc khung này để lập chương trình đo.","ex_en":"The feature control frame reads: position, Ø0.1, datums A, B, C.","ex_ja":"公差記入枠には「位置度、φ0.1、データムA、B、C」と記入されている。","ex_vi":"Khung ghi dung sai đọc là: vị trí, Ø0,1, chuẩn A, B, C.","syn_en":["FCF (viết tắt)","tolerance frame (ISO)"],"syn_ja":["公差枠 (khẩu ngữ)"]},{"en":"datum feature","pos":"noun phrase","ipa":"/ˈdeɪtəm ˌfiːtʃə/","ja":"データム形体","kana":"データムけいたい","romaji":"deetamukeitai","vi":"bề mặt chuẩn (yếu tố chuẩn thực)","level":2,"def_vi":"Bề mặt hoặc lỗ thực trên chi tiết được chỉ định để thiết lập chuẩn; khác với chuẩn là đối tượng lý tưởng.","def_en":"The actual surface or hole on a part designated to establish a datum, as opposed to the ideal datum itself.","def_ja":"データムを設定するために指定した、部品上の実際の面や穴。","usage_en":"Danh từ đếm được. Collocation: select datum features, the datum feature contacts the fixture; phân biệt datum (lý tưởng) và datum feature (thực).","usage_ja":"データム形体 đọc データムけいたい; cụm: データム形体を指定する, データム形体に当てる.","context_vi":"Dùng khi chọn mặt định vị trên bản vẽ, thiết kế đồ gá kiểm và gá đặt chi tiết trên máy CMM.","ex_en":"Choose a large, stable machined face as the primary datum feature.","ex_ja":"第一次データム形体には、大きく安定した加工面を選ぶ。","ex_vi":"Hãy chọn một mặt gia công lớn và ổn định làm bề mặt chuẩn thứ nhất.","syn_en":["datum surface","datum feature simulator (liên quan)"],"syn_ja":["データム面 (nghĩa hẹp hơn)","基準面 (khẩu ngữ)"]},{"en":"datum triangle","pos":"noun phrase","ipa":"/ˈdeɪtəm ˌtraɪæŋɡl/","ja":"データム三角記号","kana":"データムさんかくきごう","romaji":"deetamusankakukigou","vi":"ký hiệu tam giác chuẩn","level":2,"def_vi":"Hình tam giác tô đen hoặc rỗng gắn vào bề mặt chuẩn, nối với ô vuông ghi chữ cái tên chuẩn.","def_en":"A filled or open triangle attached to the datum feature and connected to a box containing the datum letter.","def_ja":"データム形体に付け、データムを示す文字の枠と結ぶ黒塗りまたは白抜きの三角形。","usage_en":"Danh từ đếm được; ký hiệu đầy đủ gọi 'datum feature symbol'. Collocation: attach the datum triangle to the extension line.","usage_ja":"データム三角記号 đọc データムさんかくきごう; cụm: データム三角記号を付ける. Nếu đặt trên đường kích thước thì chuẩn là trục/mặt giữa.","context_vi":"Gặp khi đọc bản vẽ GD&T; vị trí đặt tam giác quyết định chuẩn là bề mặt hay đường trục.","ex_en":"The datum triangle on the dimension line means datum B is the axis of the bore.","ex_ja":"データム三角記号が寸法線上にあるので、データムBは穴の軸直線である。","ex_vi":"Ký hiệu tam giác chuẩn đặt trên đường kích thước nghĩa là chuẩn B là đường trục của lỗ.","syn_en":["datum feature symbol","datum identifier"],"syn_ja":["データム記号"]},{"en":"angularity","pos":"noun","ipa":"/ˌæŋɡjuˈlærəti/","ja":"傾斜度","kana":"けいしゃど","romaji":"keishado","vi":"độ nghiêng","level":2,"def_vi":"Dung sai hướng yêu cầu mặt hoặc trục nghiêng một góc lý thuyết xác định so với chuẩn, trong phạm vi dung sai.","def_en":"An orientation tolerance controlling a surface or axis at a specified exact angle to a datum.","def_ja":"データムに対して理論的に正確な角度をもつべき面や軸線の狂いを規制する姿勢公差。","usage_en":"Danh từ không đếm được. Collocation: angularity of 0.05 mm to datum A; góc được ghi bằng kích thước lý thuyết trong khung chữ nhật.","usage_ja":"傾斜度 đọc けいしゃど; ký hiệu ∠. Góc ghi bằng 理論的に正確な寸法 (đóng khung).","context_vi":"Dùng cho mặt vát lắp ghép, lỗ khoan nghiêng, mặt nghiêng của thân van và khuôn.","ex_en":"The inclined face has an angularity of 0.05 mm relative to datum A.","ex_ja":"傾斜面には、データムAに対して傾斜度0.05 mmが指示されている。","ex_vi":"Mặt nghiêng có độ nghiêng 0,05 mm so với chuẩn A.","syn_en":["angularity tolerance","inclination (ít dùng)"],"syn_ja":["傾斜度公差"]},{"en":"symmetry","pos":"noun","ipa":"/ˈsɪmətri/","ja":"対称度","kana":"たいしょうど","romaji":"taishoudo","vi":"độ đối xứng","level":2,"def_vi":"Dung sai vị trí yêu cầu mặt phẳng giữa của yếu tố nằm giữa hai mặt song song đối xứng qua mặt phẳng chuẩn.","def_en":"A location tolerance requiring a feature's median plane to lie in a zone symmetrical about a datum plane.","def_ja":"対象の中心平面が、データム中心平面に対称な二平面の間にあることを求める位置公差。","usage_en":"Danh từ không đếm được. Collocation: symmetry of the keyway to the shaft axis; ASME 2018 đã bỏ ký hiệu này, khuyên dùng position.","usage_ja":"対称度 đọc たいしょうど; ký hiệu ⌯ (ba vạch ngang). Cụm: キー溝の対称度.","context_vi":"Dùng cho rãnh then, rãnh trượt, mỏ kẹp cần nằm đối xứng qua trục hoặc mặt giữa.","ex_en":"The keyway requires a symmetry of 0.03 mm to the shaft axis.","ex_ja":"キー溝には軸の中心に対して対称度0.03 mmが必要である。","ex_vi":"Rãnh then cần độ đối xứng 0,03 mm so với tâm trục.","syn_en":["symmetry tolerance","position (thay thế theo ASME 2018)"],"syn_ja":["対称度公差"]},{"en":"circular runout","pos":"noun phrase","ipa":"/ˌsɜːkjələ ˈrʌnaʊt/","ja":"円周振れ","kana":"えんしゅうふれ","romaji":"enshuufure","vi":"độ đảo hướng kính (đảo tròn)","level":2,"def_vi":"Dung sai giới hạn sai lệch số chỉ đồng hồ so tại từng vị trí đo khi quay chi tiết một vòng quanh trục chuẩn.","def_en":"A tolerance limiting the indicator reading at each measuring position as the part rotates once about a datum axis.","def_ja":"データム軸直線のまわりに一回転させたとき、各測定位置での振れの大きさを規制する公差。","usage_en":"Danh từ không đếm được; khẩu ngữ 'runout', 'TIR'. Collocation: radial / axial circular runout of 0.02 mm.","usage_ja":"円周振れ đọc えんしゅうふれ; ký hiệu ↗ (một mũi tên). Gồm 半径方向の円周振れ và 軸方向の円周振れ. Xưởng nói 振れ, フレ.","context_vi":"Dùng cho trục, puly, bánh răng, đĩa phanh; đo bằng đồng hồ so khi chi tiết quay trên mũi tâm hoặc khối V.","ex_en":"The circular runout of the pulley must not exceed 0.05 mm.","ex_ja":"プーリの円周振れは0.05 mm以下でなければならない。","ex_vi":"Độ đảo hướng kính của puly không được vượt quá 0,05 mm.","syn_en":["runout (khẩu ngữ)","TIR (total indicator reading, liên quan)"],"syn_ja":["振れ (khẩu ngữ)","フレ (khẩu ngữ)"]},{"en":"total runout","pos":"noun phrase","ipa":"/ˌtəʊtl ˈrʌnaʊt/","ja":"全振れ","kana":"ぜんふれ","romaji":"zenfure","vi":"độ đảo toàn phần","level":2,"def_vi":"Dung sai giới hạn sai lệch số chỉ đồng hồ so trên toàn bộ bề mặt khi vừa quay chi tiết vừa dịch chuyển đồng hồ dọc bề mặt.","def_en":"A tolerance limiting indicator variation over the whole surface while the part rotates and the indicator moves along it.","def_ja":"データム軸のまわりに回転させながら測定器を移動させ、表面全体の振れを規制する公差。","usage_en":"Danh từ không đếm được. Collocation: total runout of 0.03 mm to datum A-B; chặt hơn circular runout vì kiểm soát cả độ côn và độ thẳng.","usage_ja":"全振れ đọc ぜんふれ; ký hiệu ⌰ (hai mũi tên). Cụm: 全振れを測定する.","context_vi":"Dùng cho trục chính máy công cụ, trục quay tốc độ cao, mặt lắp ổ lăn quan trọng.","ex_en":"Total runout of the spindle journal is specified as 0.005 mm.","ex_ja":"主軸ジャーナルの全振れは0.005 mmと指示されている。","ex_vi":"Độ đảo toàn phần của cổ trục chính được quy định là 0,005 mm.","syn_en":["total runout tolerance","full indicator movement (liên quan)"],"syn_ja":["全振れ公差"]},{"en":"profile of a line","pos":"noun phrase","ipa":"/ˌprəʊfaɪl əv ə ˈlaɪn/","ja":"線の輪郭度","kana":"せんのりんかくど","romaji":"sennorinkakudo","vi":"độ biên dạng đường","level":2,"def_vi":"Dung sai giới hạn sai lệch của một đường biên dạng cong trong từng tiết diện so với biên dạng lý thuyết.","def_en":"A tolerance limiting deviation of a curved line in each section from its theoretically exact profile.","def_ja":"各断面における曲線の、理論的に正確な輪郭からの狂いを規制する公差。","usage_en":"Danh từ không đếm được; ASME gọi 'line profile'. Collocation: profile of a line tolerance of 0.1 mm.","usage_ja":"線の輪郭度 đọc せんのりんかくど; ký hiệu ⌒ (cung). Biên dạng lý thuyết cho bằng 理論的に正確な寸法.","context_vi":"Dùng cho biên dạng cam, cánh quạt, chi tiết đùn nhôm, tiết diện gioăng.","ex_en":"The cam contour is controlled by a profile of a line tolerance of 0.05 mm.","ex_ja":"カムの外形は線の輪郭度0.05 mmで規制している。","ex_vi":"Biên dạng cam được kiểm soát bằng dung sai độ biên dạng đường 0,05 mm.","syn_en":["line profile (ASME)","profile tolerance (nghĩa rộng hơn)"],"syn_ja":["線の輪郭度公差"]},{"en":"profile of a surface","pos":"noun phrase","ipa":"/ˌprəʊfaɪl əv ə ˈsɜːfɪs/","ja":"面の輪郭度","kana":"めんのりんかくど","romaji":"mennorinkakudo","vi":"độ biên dạng mặt","level":2,"def_vi":"Dung sai giới hạn sai lệch của toàn bộ một bề mặt cong so với bề mặt lý thuyết, có thể kèm hoặc không kèm chuẩn.","def_en":"A tolerance limiting deviation of a whole curved surface from its theoretically exact shape.","def_ja":"曲面全体の、理論的に正確な形状からの狂いを規制する公差。","usage_en":"Danh từ không đếm được; ASME gọi 'surface profile'. Collocation: profile of a surface 0.2 to A, B, C.","usage_ja":"面の輪郭度 đọc めんのりんかくど; ký hiệu ⌓ (cung khép kín). Xưởng gọi tắt 面輪郭.","context_vi":"Dùng nhiều cho chi tiết dập thân xe, khuôn, chi tiết nhựa, cánh tuabin; đo bằng CMM hoặc quét 3D.","ex_en":"The door panel is controlled by a profile of a surface tolerance of 0.5 mm.","ex_ja":"ドアパネルは面の輪郭度0.5 mmで管理されている。","ex_vi":"Tấm cửa xe được kiểm soát bằng dung sai độ biên dạng mặt 0,5 mm.","syn_en":["surface profile (ASME)","profile tolerance (nghĩa rộng hơn)"],"syn_ja":["面輪郭度 (khẩu ngữ)"]},{"en":"theoretically exact dimension","pos":"noun phrase","ipa":"/ˌθɪəˈretɪkli ɪɡˌzækt daɪˈmenʃn/","ja":"理論的に正確な寸法","kana":"りろんてきにせいかくなすんぽう","romaji":"rirontekiniseikakunasunpou","vi":"kích thước lý thuyết chính xác (kích thước đóng khung)","level":2,"def_vi":"Kích thước ghi trong khung chữ nhật, không có dung sai, xác định vị trí hoặc hình dạng lý thuyết cho dung sai hình học.","def_en":"A boxed dimension with no tolerance that defines the exact location or shape for a geometric tolerance.","def_ja":"枠で囲んで示し、公差をもたず、幾何公差の基準となる理論的な位置や形状を定める寸法。","usage_en":"Danh từ đếm được; viết tắt TED (ISO), ASME gọi 'basic dimension'. Collocation: locate the holes with theoretically exact dimensions.","usage_ja":"Thuật ngữ JIS 理論的に正確な寸法, viết tắt TED; xưởng gọi 枠付き寸法 hoặc 箱寸法.","context_vi":"Luôn đi kèm dung sai vị trí, độ nghiêng và độ biên dạng trên bản vẽ GD&T.","ex_en":"The hole spacing of 50 mm is a theoretically exact dimension shown in a box.","ex_ja":"穴間隔50 mmは枠で囲んだ理論的に正確な寸法である。","ex_vi":"Khoảng cách lỗ 50 mm là kích thước lý thuyết chính xác được ghi trong khung.","syn_en":["basic dimension (ASME)","TED (viết tắt)"],"syn_ja":["TED","枠付き寸法 (khẩu ngữ)"]},{"en":"form tolerance","pos":"noun phrase","ipa":"/ˈfɔːm ˌtɒlərəns/","ja":"形状公差","kana":"けいじょうこうさ","romaji":"keijoukousa","vi":"dung sai hình dạng","level":2,"def_vi":"Nhóm dung sai hình học kiểm soát hình dạng riêng của yếu tố, không cần chuẩn: độ thẳng, độ phẳng, độ tròn, độ trụ.","def_en":"The group of geometric tolerances controlling a feature's own shape without a datum, such as flatness and roundness.","def_ja":"データムを必要とせず、形体自身の形を規制する幾何公差。真直度・平面度・真円度・円筒度など。","usage_en":"Danh từ đếm được. Collocation: form tolerances do not need a datum; form tolerance must be smaller than the size tolerance.","usage_ja":"形状公差 đọc けいじょうこうさ; là một trong bốn nhóm: 形状, 姿勢, 位置, 振れ. Cụm: 形状公差を指示する.","context_vi":"Gặp khi phân loại dung sai hình học trong giáo trình và khi chọn phương pháp đo.","ex_en":"Flatness is a form tolerance, so no datum letter is written in the frame.","ex_ja":"平面度は形状公差なので、公差記入枠にデータム文字は書かない。","ex_vi":"Độ phẳng là dung sai hình dạng nên không ghi chữ chuẩn trong khung.","syn_en":["form control (ASME)","shape tolerance (ít dùng)"],"syn_ja":["形状偏差 (sai lệch thực, liên quan)"]},{"en":"orientation tolerance","pos":"noun phrase","ipa":"/ˌɔːriənˈteɪʃn ˌtɒlərəns/","ja":"姿勢公差","kana":"しせいこうさ","romaji":"shiseikousa","vi":"dung sai hướng","level":2,"def_vi":"Nhóm dung sai hình học kiểm soát hướng của yếu tố so với chuẩn: độ song song, độ vuông góc, độ nghiêng.","def_en":"The group of geometric tolerances controlling a feature's orientation to a datum: parallelism, perpendicularity, angularity.","def_ja":"データムに対する形体の向きを規制する幾何公差。平行度・直角度・傾斜度。","usage_en":"Danh từ đếm được. Collocation: orientation tolerances always need a datum; ASME gọi 'orientation controls'.","usage_ja":"姿勢公差 đọc しせいこうさ; tài liệu cũ gọi 姿勢偏差 cho sai lệch thực tế. Cụm: 姿勢公差はデータムが必要.","context_vi":"Gặp khi phân loại dung sai hình học và khi xây dựng kế hoạch đo kiểm chi tiết.","ex_en":"Perpendicularity is an orientation tolerance and needs at least one datum.","ex_ja":"直角度は姿勢公差なので、少なくとも一つのデータムが必要である。","ex_vi":"Độ vuông góc là dung sai hướng nên cần ít nhất một chuẩn.","syn_en":["orientation control (ASME)","attitude tolerance (ít dùng)"],"syn_ja":["姿勢偏差 (sai lệch thực, liên quan)"]},{"en":"location tolerance","pos":"noun phrase","ipa":"/ləʊˈkeɪʃn ˌtɒlərəns/","ja":"位置公差","kana":"いちこうさ","romaji":"ichikousa","vi":"dung sai vị trí (nhóm)","level":2,"def_vi":"Nhóm dung sai hình học kiểm soát vị trí của yếu tố so với chuẩn: vị trí, đồng trục, đối xứng.","def_en":"The group of geometric tolerances controlling a feature's location relative to datums: position, coaxiality, symmetry.","def_ja":"データムに対する形体の位置を規制する幾何公差。位置度・同軸度・対称度など。","usage_en":"Danh từ đếm được. Collocation: location tolerances are given with theoretically exact dimensions.","usage_ja":"位置公差 đọc いちこうさ, khác 位置度 (một loại cụ thể trong nhóm). Cụm: 位置公差で規制する.","context_vi":"Gặp khi phân loại dung sai hình học; nhóm quan trọng nhất cho khả năng lắp lẫn.","ex_en":"Coaxiality and symmetry both belong to the location tolerance group.","ex_ja":"同軸度と対称度は、どちらも位置公差に属する。","ex_vi":"Độ đồng trục và độ đối xứng đều thuộc nhóm dung sai vị trí.","syn_en":["location control (ASME)","positional tolerance (nghĩa hẹp hơn)"],"syn_ja":["位置偏差 (sai lệch thực, liên quan)"]},{"en":"runout tolerance","pos":"noun phrase","ipa":"/ˈrʌnaʊt ˌtɒlərəns/","ja":"振れ公差","kana":"ふれこうさ","romaji":"furekousa","vi":"dung sai độ đảo","level":2,"def_vi":"Nhóm dung sai hình học kiểm soát độ đảo của bề mặt khi quay quanh trục chuẩn: độ đảo tròn và độ đảo toàn phần.","def_en":"The group of geometric tolerances controlling surface variation during rotation about a datum axis.","def_ja":"データム軸直線のまわりに回転させたときの表面の振れを規制する幾何公差。","usage_en":"Danh từ đếm được. Collocation: runout tolerances apply to rotating parts and need a datum axis.","usage_ja":"振れ公差 đọc ふれこうさ; gồm 円周振れ và 全振れ. Cụm: 振れ公差を指示する.","context_vi":"Dùng cho chi tiết quay như trục, bánh đà, puly, đĩa phanh, rô-to.","ex_en":"A runout tolerance is easy to check with a dial indicator between centres.","ex_ja":"振れ公差は、センタ間で支えてダイヤルゲージを当てれば簡単に確認できる。","ex_vi":"Dung sai độ đảo dễ kiểm tra bằng đồng hồ so khi chống tâm hai đầu.","syn_en":["runout control (ASME)","runout (khẩu ngữ)"],"syn_ja":["振れ偏差 (sai lệch thực, liên quan)"]},{"en":"datum reference frame","pos":"noun phrase","ipa":"/ˈdeɪtəm ˈrefrəns freɪm/","ja":"三平面データム系","kana":"さんへいめんデータムけい","romaji":"sanheimendeetamukei","vi":"hệ chuẩn ba mặt phẳng","level":3,"def_vi":"Hệ ba mặt phẳng vuông góc với nhau tạo bởi chuẩn thứ nhất, thứ hai, thứ ba, khống chế đủ sáu bậc tự do của chi tiết.","def_en":"Three mutually perpendicular planes set by primary, secondary and tertiary datums, constraining all six degrees of freedom.","def_ja":"第一次・第二次・第三次データムによる互いに直交する三平面。部品の6自由度を拘束する。","usage_en":"Danh từ đếm được; viết tắt DRF. Collocation: establish the datum reference frame A|B|C; thứ tự chữ trong khung quyết định thứ tự tiếp xúc.","usage_ja":"三平面データム系 là thuật ngữ JIS; cụm: 三平面データム系を設定する. Thứ tự gọi 第一次, 第二次, 第三次データム.","context_vi":"Dùng khi thiết kế đồ gá kiểm, lập trình CMM theo quy tắc định vị 3-2-1.","ex_en":"The CMM program aligns the part to the datum reference frame A-B-C.","ex_ja":"三次元測定機のプログラムで、部品をA-B-Cの三平面データム系に合わせる。","ex_vi":"Chương trình CMM căn chỉnh chi tiết theo hệ chuẩn ba mặt phẳng A-B-C.","syn_en":["DRF (viết tắt)","datum system (ISO)"],"syn_ja":["データム系","3-2-1基準 (liên quan)"]},{"en":"datum target","pos":"noun phrase","ipa":"/ˈdeɪtəm ˌtɑːɡɪt/","ja":"データムターゲット","kana":"データムターゲット","romaji":"deetamutaagetto","vi":"điểm chuẩn (điểm, đường, vùng chuẩn)","level":3,"def_vi":"Điểm, đường hoặc vùng nhỏ cụ thể trên bề mặt dùng để thiết lập chuẩn khi cả bề mặt không đủ phẳng hoặc không đều.","def_en":"A specified point, line or small area on a part used to establish a datum when the whole surface is irregular.","def_ja":"面全体が不規則な場合に、データムを設定するために指定する点・線・限定した領域。","usage_en":"Danh từ đếm được. Ký hiệu A1, A2, A3 trong vòng tròn chia đôi; collocation: datum target points, datum target area.","usage_ja":"Viết katakana データムターゲット; ký hiệu ×(điểm), đường, vùng gạch chéo. Cụm: データムターゲットを指示する.","context_vi":"Dùng cho chi tiết đúc, rèn, dập tấm lớn, nhựa cong vênh khi bề mặt thô không làm chuẩn toàn phần được.","ex_en":"Three datum target points A1, A2 and A3 define datum A on the casting.","ex_ja":"鋳物では、3点のデータムターゲットA1、A2、A3でデータムAを設定する。","ex_vi":"Ba điểm chuẩn A1, A2, A3 xác định chuẩn A trên chi tiết đúc.","syn_en":["target point (nghĩa hẹp hơn)","datum target area (nghĩa hẹp hơn)"],"syn_ja":["ターゲット点 (khẩu ngữ)"]},{"en":"maximum material condition","pos":"noun phrase","ipa":"/ˌmæksɪməm məˈtɪəriəl kənˌdɪʃn/","ja":"最大実体状態","kana":"さいだいじったいじょうたい","romaji":"saidaijittaijoutai","vi":"trạng thái vật liệu lớn nhất (MMC)","level":3,"def_vi":"Trạng thái yếu tố chứa nhiều vật liệu nhất trong giới hạn kích thước: trục lớn nhất, lỗ nhỏ nhất; ký hiệu Ⓜ.","def_en":"The state in which a feature contains the most material within its size limits: largest shaft, smallest hole.","def_ja":"形体がサイズ許容範囲内で実体が最大となる状態。軸は最大、穴は最小。記号Ⓜ。","usage_en":"Danh từ đếm được; viết tắt MMC (ASME), ISO gọi 'maximum material requirement' (MMR). Collocation: position Ø0.1 at MMC, bonus tolerance.","usage_ja":"最大実体状態 viết tắt MMC; khi dùng ký hiệu Ⓜ gọi 最大実体公差方式. Khi lệch khỏi MMC được thêm dung sai gọi ボーナス公差.","context_vi":"Dùng cho lỗ bu lông và chốt để tăng dung sai khi kích thước thực rời khỏi MMC, giảm phế phẩm và cho phép dùng calip chức năng.","ex_en":"The position tolerance applies at maximum material condition, so a larger hole gets bonus tolerance.","ex_ja":"位置度は最大実体状態で適用されるので、穴が大きくなればボーナス公差が得られる。","ex_vi":"Dung sai vị trí áp dụng ở trạng thái vật liệu lớn nhất nên lỗ to hơn sẽ được cộng thêm dung sai.","syn_en":["MMC (viết tắt)","maximum material requirement (ISO)"],"syn_ja":["MMC","最大実体公差方式 (liên quan)"]},{"en":"least material condition","pos":"noun phrase","ipa":"/ˌliːst məˈtɪəriəl kənˌdɪʃn/","ja":"最小実体状態","kana":"さいしょうじったいじょうたい","romaji":"saishoujittaijoutai","vi":"trạng thái vật liệu nhỏ nhất (LMC)","level":3,"def_vi":"Trạng thái yếu tố chứa ít vật liệu nhất trong giới hạn kích thước: trục nhỏ nhất, lỗ lớn nhất; ký hiệu Ⓛ.","def_en":"The state in which a feature contains the least material within its size limits: smallest shaft, largest hole.","def_ja":"形体がサイズ許容範囲内で実体が最小となる状態。軸は最小、穴は最大。記号Ⓛ。","usage_en":"Danh từ đếm được; viết tắt LMC (ASME), ISO gọi 'least material requirement' (LMR). Collocation: specified at LMC to protect minimum wall thickness.","usage_ja":"最小実体状態 viết tắt LMC; ký hiệu Ⓛ gọi 最小実体公差方式. Ít dùng hơn MMC.","context_vi":"Dùng để đảm bảo chiều dày thành tối thiểu, ví dụ lỗ gần mép chi tiết hoặc ống có thành mỏng.","ex_en":"Using least material condition on the bore protects the minimum wall thickness.","ex_ja":"穴に最小実体状態を適用することで、最小肉厚を確保できる。","ex_vi":"Áp dụng trạng thái vật liệu nhỏ nhất cho lỗ giúp đảm bảo chiều dày thành tối thiểu.","syn_en":["LMC (viết tắt)","least material requirement (ISO)"],"syn_ja":["LMC","最小実体公差方式 (liên quan)"]},{"en":"virtual condition","pos":"noun phrase","ipa":"/ˌvɜːtʃuəl kənˈdɪʃn/","ja":"実効状態","kana":"じっこうじょうたい","romaji":"jikkoujoutai","vi":"trạng thái biên ảo (trạng thái hiệu dụng)","level":3,"def_vi":"Biên giới hạn sinh ra do kích thước ở trạng thái vật liệu lớn nhất kết hợp với dung sai hình học, dùng để kiểm tra khả năng lắp.","def_en":"The boundary produced by the combined effect of size at MMC and the geometric tolerance, used to check assemblability.","def_ja":"最大実体寸法と幾何公差の総合効果で生じる境界。組立可能性の確認に用いる。","usage_en":"Danh từ đếm được; viết tắt VC (ASME), ISO gọi 'maximum material virtual condition' (MMVC). Collocation: virtual condition of the pin = MMC size + position tolerance.","usage_ja":"Thuật ngữ JIS: 最大実体実効状態 (MMVC) và 最大実体実効寸法; nói chung gọi 実効状態. Cụm: 実効寸法で機能ゲージを設計する.","context_vi":"Dùng khi tính toán lắp bu lông – lỗ và khi thiết kế calip chức năng (functional gauge).","ex_en":"The functional gauge pin is made to the virtual condition of the hole.","ex_ja":"機能ゲージのピンは、穴の実効状態の寸法で製作する。","ex_vi":"Chốt của calip chức năng được chế tạo theo kích thước trạng thái biên ảo của lỗ.","syn_en":["VC (viết tắt)","maximum material virtual condition (ISO)"],"syn_ja":["最大実体実効状態","実効寸法 (liên quan)"]},{"en":"envelope requirement","pos":"noun phrase","ipa":"/ˈenvələʊp rɪˌkwaɪəmənt/","ja":"包絡の条件","kana":"ほうらくのじょうけん","romaji":"hourakunojouken","vi":"yêu cầu bao hình (nguyên tắc bao)","level":3,"def_vi":"Yêu cầu bề mặt yếu tố không vượt qua bao hình hoàn hảo ở trạng thái vật liệu lớn nhất; ký hiệu Ⓔ sau kích thước.","def_en":"A requirement that a feature must not violate a perfect-form envelope at maximum material size; symbol Ⓔ.","def_ja":"形体が最大実体寸法の完全形状の包絡面を超えてはならないという要求。記号Ⓔ。","usage_en":"Danh từ đếm được. Theo ISO phải ghi Ⓔ; theo ASME thì mặc định áp dụng (Rule #1, Taylor principle).","usage_ja":"包絡の条件 đọc ほうらくのじょうけん; ghi Ⓔ sau kích thước, ví dụ φ20 h7 Ⓔ. Liên quan テーラーの原理.","context_vi":"Dùng cho mối lắp ghép lỗ – trục quan trọng để đảm bảo lắp được dù chi tiết bị cong hoặc méo.","ex_en":"Add the envelope requirement Ⓔ to the shaft size to guarantee the fit.","ex_ja":"はめあいを保証するため、軸の寸法に包絡の条件Ⓔを付ける。","ex_vi":"Thêm yêu cầu bao hình Ⓔ vào kích thước trục để đảm bảo lắp ghép.","syn_en":["Rule #1 (ASME)","Taylor principle (liên quan)"],"syn_ja":["テーラーの原理 (liên quan)","包絡の原理 (liên quan)"]}]},{"id":16,"words":[{"en":"surface roughness","pos":"noun phrase","ipa":"/ˈsɝːfəs ˈrʌfnəs/","ja":"表面粗さ","kana":"ひょうめんあらさ","romaji":"hyoumen'arasa","vi":"độ nhám bề mặt","level":1,"def_vi":"Mức độ nhấp nhô rất nhỏ, khoảng cách ngắn trên bề mặt chi tiết sau gia công, thường đo bằng micromet.","def_en":"The fine, closely spaced irregularities on a machined surface, usually expressed in micrometres.","def_ja":"加工面に現れる細かく短い間隔の凹凸の程度。通常はμmで表す。","usage_en":"Danh từ không đếm được. Hay đi với: specify / measure / reduce / improve surface roughness; 'a surface roughness of Ra 0.8 µm'.","usage_ja":"Ngoài xưởng hay nói tắt 面粗さ hoặc 面粗度. Động từ đi kèm: 表面粗さを測定する, 表面粗さが悪い/良い, 表面粗さを指示する.","context_vi":"Dùng trên bản vẽ chi tiết, phiếu kiểm tra và khi thảo luận về chất lượng gia công các mặt lắp ghép, mặt làm kín, mặt trượt.","ex_en":"The seal groove requires a surface roughness of Ra 0.8 µm or better.","ex_ja":"シール溝の表面粗さはRa0.8μm以下が要求されている。","ex_vi":"Rãnh lắp phớt yêu cầu độ nhám bề mặt Ra 0,8 µm hoặc tốt hơn.","syn_en":["roughness","surface finish (khẩu ngữ, nghĩa gần)"],"syn_ja":["面粗さ","面粗度 (khẩu ngữ)"]},{"en":"surface finish","pos":"noun phrase","ipa":"/ˈsɝːfəs ˈfɪnɪʃ/","ja":"仕上げ面","kana":"しあげめん","romaji":"shiagemen","vi":"chất lượng bề mặt gia công (độ bóng)","level":1,"def_vi":"Tình trạng chung của bề mặt sau gia công cuối cùng, gồm độ nhám, vết dao và vẻ ngoài.","def_en":"The overall condition of a surface after the final machining step, including roughness, tool marks and appearance.","def_ja":"最終加工後の面の状態。粗さ、刃物目、外観などを含む。","usage_en":"Thường không đếm được. Hay đi với: good / poor / fine surface finish, achieve a surface finish; dân xưởng Mỹ hay dùng thay cho 'surface roughness'.","usage_ja":"Hay nói 仕上げ面が良い/悪い, 仕上げ面粗さ. Từ tương ứng trang trọng là 表面性状; trong xưởng nói ngắn gọn 面.","context_vi":"Dùng khi đánh giá kết quả tiện, phay, mài và khi chọn chế độ cắt cho lần gia công tinh.","ex_en":"Reducing the feed rate gave a much better surface finish on the shaft.","ex_ja":"送りを下げたところ、軸の仕上げ面がかなり良くなった。","ex_vi":"Giảm lượng chạy dao đã giúp bề mặt trục bóng hơn nhiều.","syn_en":["finish","surface quality"],"syn_ja":["表面仕上げ","仕上げ面粗さ (nghĩa hẹp hơn)"]},{"en":"smooth","pos":"adjective","ipa":"/smuːð/","ja":"滑らか","kana":"なめらか","romaji":"nameraka","vi":"nhẵn, trơn láng","level":1,"def_vi":"Có bề mặt rất ít nhấp nhô, sờ vào không thấy gợn và độ nhám thấp.","def_en":"Having very few surface irregularities, so it feels even and has low roughness.","def_ja":"凹凸が非常に少なく、手触りが均一で粗さが小さい様子。","usage_en":"Tính từ; so sánh: smoother, smoothest. Hay đi với: a smooth surface, smooth finish; động từ: make smooth, smooth out (làm phẳng).","usage_ja":"Là tính từ đuôi な: 滑らかな面, 滑らかに仕上げる. Trong xưởng cũng hay nói ツルツル (khẩu ngữ).","context_vi":"Dùng khi mô tả bề mặt sau mài, đánh bóng hoặc khi yêu cầu mặt trượt, mặt làm kín không có gợn.","ex_en":"The sliding surface must be smooth enough to avoid damaging the wiper seal.","ex_ja":"ワイパーシールを傷めないよう、摺動面は十分に滑らかでなければならない。","ex_vi":"Mặt trượt phải đủ nhẵn để không làm hỏng phớt gạt bụi.","syn_en":["fine (về độ nhám)","even (nghĩa gần)"],"syn_ja":["平滑","ツルツル (khẩu ngữ)"]},{"en":"rough","pos":"adjective","ipa":"/rʌf/","ja":"粗い","kana":"あらい","romaji":"arai","vi":"nhám, thô","level":1,"def_vi":"Có nhiều nhấp nhô rõ rệt trên bề mặt, độ nhám lớn.","def_en":"Having pronounced surface irregularities and a high roughness value.","def_ja":"表面の凹凸が大きく、粗さの値が大きい様子。","usage_en":"Tính từ; so sánh: rougher, roughest. Hay đi với: rough surface, rough machining (gia công thô); danh từ là 'roughness'.","usage_ja":"Tính từ đuôi い: 粗い面, 面が粗い. Phân biệt với 荒い (thô bạo); trong gia công 'gia công thô' viết 荒加工 (あらかこう).","context_vi":"Dùng khi mô tả bề mặt sau gia công thô, bề mặt đúc, hoặc khi phàn nàn chất lượng bề mặt không đạt.","ex_en":"The cast face is too rough to seal against the gasket without machining.","ex_ja":"鋳肌の面は粗いので、加工しないとガスケットでシールできない。","ex_vi":"Mặt đúc quá nhám nên không thể làm kín với gioăng nếu không gia công.","syn_en":["coarse","uneven (nghĩa gần)"],"syn_ja":["ザラザラ (khẩu ngữ)","粗面 (danh từ, liên quan)"]},{"en":"scratch","pos":"noun","ipa":"/skrætʃ/","ja":"引っかき傷","kana":"ひっかききず","romaji":"hikkakikizu","vi":"vết xước","level":1,"def_vi":"Vết rạch mảnh, dài và nông trên bề mặt do vật cứng hoặc sắc cọ vào.","def_en":"A thin, long, shallow mark on a surface caused by a hard or sharp object sliding across it.","def_ja":"硬いものや鋭いものが擦れてできた、細く長く浅い傷。","usage_en":"Danh từ đếm được, cũng là động từ (to scratch). Hay đi với: deep / fine scratch, scratch on the surface; 'scratch-free'.","usage_ja":"Ngoài xưởng hầu như chỉ nói キズ hoặc 傷; 引っかき傷 dùng khi cần nói rõ dạng vết. Động từ: 傷が付く, 傷を付ける.","context_vi":"Dùng trong kiểm tra ngoại quan, đóng gói, vận chuyển chi tiết đã gia công tinh hoặc mạ.","ex_en":"A deep scratch on the piston rod will quickly wear out the rod seal.","ex_ja":"ピストンロッドに深い引っかき傷があると、ロッドシールがすぐ摩耗する。","ex_vi":"Một vết xước sâu trên cần piston sẽ làm phớt cần mòn rất nhanh.","syn_en":["score mark","scuff (nghĩa gần)"],"syn_ja":["キズ (khẩu ngữ)","擦り傷"]},{"en":"dent","pos":"noun","ipa":"/dɛnt/","ja":"打痕","kana":"だこん","romaji":"dakon","vi":"vết lõm (vết va đập)","level":1,"def_vi":"Chỗ lõm nhỏ trên bề mặt do bị va đập hoặc rơi vào vật cứng.","def_en":"A small hollow in a surface caused by an impact or by being dropped against something hard.","def_ja":"ぶつけたり落としたりしてできた、表面の小さなくぼみ。","usage_en":"Danh từ đếm được, cũng là động từ (to dent). Hay đi với: a dent in/on the surface, handling dent; 'dented part'.","usage_ja":"Từ rất phổ biến trong kiểm tra ngoại quan Nhật: 打痕がある, 打痕を付ける, 打痕不良. Hay đi cặp với 傷: 傷・打痕なきこと.","context_vi":"Dùng trong tiêu chuẩn ngoại quan, ghi chú bản vẽ và báo cáo lỗi do vận chuyển, xếp dỡ chi tiết.","ex_en":"The inspector rejected the flange because of a dent on the sealing face.","ex_ja":"シール面に打痕があったため、検査員はフランジを不合格にした。","ex_vi":"Nhân viên kiểm tra loại bỏ mặt bích vì có vết lõm trên mặt làm kín.","syn_en":["ding (khẩu ngữ Mỹ)","nick (vết mẻ, nghĩa gần)"],"syn_ja":["当たり傷","へこみ"]},{"en":"tool mark","pos":"noun phrase","ipa":"/ˈtuːl ˌmɑːrk/","ja":"ツールマーク","kana":"ツールマーク","romaji":"tsuurumaaku","vi":"vết dao","level":1,"def_vi":"Vết đường rãnh đều đặn mà dụng cụ cắt để lại trên bề mặt sau tiện, phay hoặc mài.","def_en":"The regular pattern of grooves left on a surface by a cutting tool after turning, milling or grinding.","def_ja":"旋削・フライス削り・研削などで工具が面に残す規則的な筋。","usage_en":"Danh từ đếm được, thường dùng số nhiều: visible tool marks, remove tool marks; 'feed marks' là vết theo bước tiến dao.","usage_ja":"Trong xưởng hay nói 刃物目, バイト目 (khi tiện) hoặc カッターマーク (khi phay). Động từ: ツールマークが残る, ツールマークを消す.","context_vi":"Dùng khi đánh giá ngoại quan mặt gia công, nhất là mặt nhìn thấy được hoặc mặt cần đánh bóng sau đó.","ex_en":"Visible tool marks on the cover are not acceptable for this customer.","ex_ja":"このお客様では、カバーに見えるツールマークは許容されない。","ex_vi":"Khách hàng này không chấp nhận vết dao nhìn thấy được trên nắp.","syn_en":["machining mark","feed mark (nghĩa hẹp hơn)"],"syn_ja":["刃物目","カッターマーク"]},{"en":"mirror finish","pos":"noun phrase","ipa":"/ˈmɪrər ˈfɪnɪʃ/","ja":"鏡面仕上げ","kana":"きょうめんしあげ","romaji":"kyoumenshiage","vi":"bề mặt bóng gương","level":1,"def_vi":"Bề mặt được gia công cực nhẵn đến mức phản chiếu hình ảnh như gương, độ nhám rất thấp.","def_en":"An extremely smooth surface that reflects images like a mirror, with very low roughness.","def_ja":"鏡のように像を映すほど、粗さが非常に小さい滑らかな仕上げ。","usage_en":"Danh từ không đếm được. Hay đi với: polish to a mirror finish, mirror-finished surface; không nói 'mirror finishing surface'.","usage_ja":"Hay dùng 鏡面仕上げにする, 鏡面加工, 鏡面研磨. Ngoài xưởng chỉ cần nói 鏡面.","context_vi":"Dùng cho khuôn ép nhựa trong suốt, trục cán, chi tiết thực phẩm - y tế, mặt làm kín đặc biệt.","ex_en":"The mold cavity for the lens cover is polished to a mirror finish.","ex_ja":"レンズカバー用の金型キャビティは鏡面仕上げにしている。","ex_vi":"Lòng khuôn của nắp thấu kính được đánh bóng đến bề mặt bóng gương.","syn_en":["mirror polish","high-gloss finish (nghĩa gần)"],"syn_ja":["鏡面加工","鏡面研磨"]},{"en":"roughness tester","pos":"noun phrase","ipa":"/ˈrʌfnəs ˌtɛstər/","ja":"表面粗さ測定機","kana":"ひょうめんあらさそくていき","romaji":"hyoumen'arasasokuteiki","vi":"máy đo độ nhám","level":1,"def_vi":"Thiết bị đo độ nhám bề mặt, thường kéo một mũi dò qua bề mặt và tính ra các thông số như Ra, Rz.","def_en":"An instrument that measures surface roughness, usually by dragging a stylus across the surface and computing Ra, Rz, etc.","def_ja":"触針などで面をなぞり、Ra・Rzなどの粗さパラメータを求める測定機。","usage_en":"Danh từ đếm được. Hay đi với: portable roughness tester, check with a roughness tester; còn gọi 'profilometer' trong tài liệu kỹ thuật.","usage_ja":"Ngoài xưởng nói gọn 粗さ計; nhiều nơi gọi theo tên sản phẩm サーフテスト. Động từ: 粗さ計で測る, 測定機を当てる.","context_vi":"Dùng tại phòng QC và ngay bên máy để kiểm tra mặt trục, lỗ, mặt làm kín sau gia công.","ex_en":"Check the bore with the portable roughness tester before releasing the batch.","ex_ja":"ロットを流す前に、携帯型の表面粗さ測定機で穴を確認してください。","ex_vi":"Hãy kiểm tra lỗ bằng máy đo độ nhám cầm tay trước khi cho lô hàng đi.","syn_en":["profilometer","surface roughness gauge"],"syn_ja":["粗さ計 (khẩu ngữ)","粗さ測定機"]},{"en":"surface defect","pos":"noun phrase","ipa":"/ˈsɝːfəs ˈdiːfɛkt/","ja":"表面欠陥","kana":"ひょうめんけっかん","romaji":"hyoumenkekkan","vi":"khuyết tật bề mặt","level":1,"def_vi":"Chỗ bất thường riêng lẻ trên bề mặt như vết xước, lõm, rỗ, nứt, không thuộc độ nhám thông thường.","def_en":"An isolated irregularity on a surface, such as a scratch, dent, pit or crack, not part of normal roughness.","def_ja":"傷・打痕・ピット・割れなど、通常の粗さに含まれない局部的な異常。","usage_en":"Danh từ đếm được. Hay đi với: detect / inspect for / be free of surface defects. Khi đo độ nhám phải tránh vùng có khuyết tật.","usage_ja":"Văn bản dùng 表面欠陥; xưởng thường nói cụ thể 傷, 打痕, ピンホール hoặc gọi chung 外観不良.","context_vi":"Dùng trong tiêu chuẩn kiểm tra ngoại quan, báo cáo không phù hợp và tiêu chuẩn ISO 8785.","ex_en":"Each shaft is inspected under a lamp for surface defects before plating.","ex_ja":"めっき前に、各シャフトをライトの下で表面欠陥がないか検査する。","ex_vi":"Mỗi trục đều được kiểm tra khuyết tật bề mặt dưới đèn trước khi mạ.","syn_en":["surface imperfection (ISO 8785)","cosmetic defect (nghĩa gần)"],"syn_ja":["外観不良 (nghĩa rộng hơn)","表面きず"]},{"en":"surface texture","pos":"noun phrase","ipa":"/ˈsɝːfəs ˈtɛkstʃər/","ja":"表面性状","kana":"ひょうめんせいじょう","romaji":"hyoumenseijou","vi":"cấu trúc nhám bề mặt (đặc tính bề mặt)","level":2,"def_vi":"Khái niệm tổng quát mô tả hình dạng hình học nhỏ của bề mặt, gồm độ nhám, độ sóng, hướng vết và khuyết tật.","def_en":"The overall geometric character of a surface, including roughness, waviness, lay and flaws.","def_ja":"粗さ・うねり・筋目方向・きずなどを含む、面の微細な幾何学的特性の総称。","usage_en":"Danh từ không đếm được. Là thuật ngữ chuẩn trong ISO 1302 / ASME B46.1; hay đi với: surface texture requirements, surface texture parameters.","usage_ja":"Thuật ngữ JIS (B 0601, B 0031) thay cho cách nói cũ 面の肌, 仕上げ記号. Hay gặp: 表面性状の図示方法, 表面性状パラメータ.","context_vi":"Dùng trong tiêu chuẩn, bản vẽ thiết kế và tài liệu đo lường khi cần nói chính xác hơn 'độ nhám'.","ex_en":"The surface texture requirements are shown in the title block note.","ex_ja":"表面性状の要求事項は表題欄の注記に示されている。","ex_vi":"Các yêu cầu về đặc tính bề mặt được ghi trong phần ghi chú của khung tên.","syn_en":["surface finish (khẩu ngữ)","surface topography (nghĩa gần)"],"syn_ja":["表面の肌 (cách nói cũ)","サーフェステクスチャ"]},{"en":"arithmetic mean roughness","pos":"noun phrase","ipa":"/ˌærɪθˈmɛtɪk ˈmiːn ˈrʌfnəs/","ja":"算術平均粗さ","kana":"さんじゅつへいきんあらさ","romaji":"sanjutsuheikin'arasa","vi":"sai lệch trung bình số học của profin (Ra)","level":2,"def_vi":"Giá trị trung bình của trị tuyệt đối độ lệch profin so với đường trung bình trong chiều dài chuẩn, ký hiệu Ra.","def_en":"The average of the absolute deviations of the profile from the mean line over the sampling length; symbol Ra.","def_ja":"基準長さにおける平均線からの偏差の絶対値の平均。記号Ra。","usage_en":"Trong thực tế hầu như chỉ nói 'Ra' (đọc /ɑːr eɪ/): 'Ra 1.6', 'an Ra value of 0.4 µm'. Thuật ngữ ISO đầy đủ là 'arithmetical mean deviation of the profile'.","usage_ja":"Hay nói Ra (アールエー); ví dụ Ra1.6, Ra0.8. Động từ: Raで指示する, Raを測る.","context_vi":"Là thông số độ nhám phổ biến nhất trên bản vẽ chi tiết máy ở Việt Nam, Nhật, châu Âu và Mỹ.","ex_en":"The arithmetic mean roughness of the journal must not exceed 0.4 µm.","ex_ja":"ジャーナル部の算術平均粗さは0.4μm以下とすること。","ex_vi":"Sai lệch trung bình số học Ra của cổ trục không được vượt quá 0,4 µm.","syn_en":["Ra","arithmetical mean deviation (ISO 4287)","AA / CLA (cách gọi cũ)"],"syn_ja":["Ra","中心線平均粗さ (cách gọi cũ)"]},{"en":"maximum height of profile","pos":"noun phrase","ipa":"/ˈmæksɪməm ˈhaɪt əv ˈproʊfaɪl/","ja":"最大高さ粗さ","kana":"さいだいたかさあらさ","romaji":"saidaitakasaarasa","vi":"chiều cao lớn nhất của profin (Rz)","level":2,"def_vi":"Tổng chiều cao đỉnh cao nhất và độ sâu đáy thấp nhất của profin nhám trong chiều dài chuẩn, ký hiệu Rz.","def_en":"The sum of the highest peak height and the deepest valley depth of the roughness profile within the sampling length; symbol Rz.","def_ja":"基準長さにおける最も高い山の高さと最も深い谷の深さの和。記号Rz。","usage_en":"Trong giao tiếp thường gọi 'Rz'. Chú ý: Rz theo ISO hiện hành khác Rz 'mười điểm' cũ, nên ghi rõ tiêu chuẩn khi trao đổi với khách hàng.","usage_ja":"Hay gọi Rz (アールゼット). Từ JIS 2001, Rz mang nghĩa 最大高さ; Rz cũ (mười điểm) đổi thành RzJIS. Cách gọi cũ: Ry, Rmax.","context_vi":"Dùng cho mặt làm kín, mặt chịu mỏi, nơi một đỉnh hoặc rãnh sâu đơn lẻ cũng gây ảnh hưởng.","ex_en":"For the O-ring face we specify the maximum height of profile, Rz 6.3, instead of Ra.","ex_ja":"Oリング面にはRaではなく最大高さ粗さRz6.3を指示している。","ex_vi":"Đối với mặt lắp vòng O, chúng tôi chỉ định chiều cao lớn nhất của profin Rz 6,3 thay vì Ra.","syn_en":["Rz","Rmax / Ry (cách gọi cũ)"],"syn_ja":["Rz","最大高さ (Rmax, cách gọi cũ)"]},{"en":"waviness","pos":"noun","ipa":"/ˈweɪvinəs/","ja":"うねり","kana":"うねり","romaji":"uneri","vi":"độ sóng bề mặt","level":2,"def_vi":"Thành phần nhấp nhô có bước lớn hơn độ nhám, thường do rung, biến dạng nhiệt hoặc độ đảo của máy gây ra.","def_en":"Surface irregularities with longer spacing than roughness, often caused by vibration, heat or machine run-out.","def_ja":"粗さより長い間隔の凹凸。振動・熱変形・機械の振れなどで生じる。","usage_en":"Danh từ không đếm được. Hay đi với: waviness profile, waviness height (Wt), excessive waviness; đừng nhầm với 'flatness' (độ phẳng).","usage_ja":"Viết bằng hiragana うねり; thông số: うねり曲線, Wa, Wt. Động từ: うねりが出る, うねりを抑える.","context_vi":"Dùng khi phân tích bề mặt mài, mặt trượt dẫn hướng, mặt bích lớn và khi lọc tín hiệu trong máy đo nhám.","ex_en":"Grinding wheel imbalance produced visible waviness on the roll surface.","ex_ja":"砥石のアンバランスにより、ロール表面に目に見えるうねりが発生した。","ex_vi":"Đá mài mất cân bằng đã tạo ra độ sóng nhìn thấy được trên bề mặt trục cán.","syn_en":["waviness profile (W-profile)","undulation (nghĩa gần)"],"syn_ja":["うねり曲線 (liên quan)","ウェービネス"]},{"en":"lay","pos":"noun","ipa":"/leɪ/","ja":"筋目方向","kana":"すじめほうこう","romaji":"sujimehoukou","vi":"hướng vết gia công (hướng nhấp nhô)","level":2,"def_vi":"Hướng chủ đạo của các vết gia công trên bề mặt, như song song, vuông góc, chéo hay tròn đồng tâm.","def_en":"The predominant direction of the surface pattern left by machining, such as parallel, perpendicular, crossed or circular.","def_ja":"加工によって生じた筋目の主な方向。平行・直角・交差・同心円など。","usage_en":"Danh từ không đếm được trong nghĩa này. Hay đi với: lay direction, lay symbol, 'circular lay', 'perpendicular lay'. Đừng nhầm với động từ 'lay' (đặt).","usage_ja":"Ký hiệu trên bản vẽ: =, ⊥, X, M, C, R, P. Hay nói 筋目方向の記号, 筋目方向を指示する; ngoài xưởng nói 目の向き.","context_vi":"Dùng trên bản vẽ cho mặt làm kín, mặt trượt, nơi hướng vết gia công ảnh hưởng đến rò rỉ hoặc ma sát.","ex_en":"A circular lay is required on the face that contacts the mechanical seal.","ex_ja":"メカニカルシールと接する面には同心円状の筋目方向が要求される。","ex_vi":"Mặt tiếp xúc với phớt cơ khí yêu cầu hướng vết gia công dạng tròn đồng tâm.","syn_en":["direction of lay","lay direction"],"syn_ja":["筋目","加工目の方向 (khẩu ngữ)"]},{"en":"sampling length","pos":"noun phrase","ipa":"/ˈsæmplɪŋ ˌlɛŋθ/","ja":"基準長さ","kana":"きじゅんながさ","romaji":"kijunnagasa","vi":"chiều dài chuẩn","level":2,"def_vi":"Đoạn chiều dài theo trục X dùng để xác định một giá trị thông số nhám, thường bằng bước sóng cắt λc.","def_en":"The length along the X axis used to determine one value of a roughness parameter, usually equal to the cutoff λc.","def_ja":"粗さパラメータを1回求めるためのX軸方向の長さ。通常カットオフ値λcに等しい。","usage_en":"Danh từ đếm được, ký hiệu lr (độ nhám) hoặc lw (độ sóng). Hay đi với: over one sampling length, a sampling length of 0.8 mm.","usage_ja":"Ký hiệu lr; hay nói 基準長さ0.8mm, 基準長さを選ぶ. Thường đi cùng 評価長さ = 基準長さ×5.","context_vi":"Dùng khi cài đặt máy đo nhám và khi đọc tiêu chuẩn ISO 4288 / JIS B 0633.","ex_en":"For Ra 0.8 µm, a sampling length of 0.8 mm is normally selected.","ex_ja":"Ra0.8μmの場合、通常は基準長さ0.8mmを選ぶ。","ex_vi":"Với Ra 0,8 µm, thường chọn chiều dài chuẩn 0,8 mm.","syn_en":["lr (ký hiệu)","cutoff length (nghĩa gần)"],"syn_ja":["lr","カットオフ長さ (nghĩa gần)"]},{"en":"stylus","pos":"noun","ipa":"/ˈstaɪləs/","ja":"触針","kana":"しょくしん","romaji":"shokushin","vi":"mũi dò (kim dò)","level":2,"def_vi":"Đầu kim nhọn, thường bằng kim cương, tiếp xúc và trượt trên bề mặt để ghi lại profin trong máy đo nhám.","def_en":"A fine-tipped probe, usually diamond, that traces the surface to record its profile in a roughness instrument.","def_ja":"粗さ測定機で面をなぞり断面形状を記録する、先端の細い針。通常はダイヤモンド製。","usage_en":"Danh từ đếm được, số nhiều 'styli' hoặc 'styluses'. Hay đi với: stylus tip radius (2 µm, 5 µm), stylus force, replace the stylus.","usage_ja":"Hay gặp: 触針式 (kiểu tiếp xúc), 触針先端半径, 触針を交換する. Ngoài xưởng có khi gọi スタイラス hoặc 針.","context_vi":"Dùng khi vận hành, bảo dưỡng máy đo nhám và khi chọn đầu dò cho rãnh hẹp, lỗ nhỏ.","ex_en":"A worn stylus tip will give lower Ra readings than the real surface.","ex_ja":"触針の先端が摩耗すると、実際の面よりRaが小さく測定される。","ex_vi":"Mũi dò bị mòn sẽ cho giá trị Ra thấp hơn bề mặt thực tế.","syn_en":["probe","diamond tip"],"syn_ja":["スタイラス","検出器の針 (khẩu ngữ)"]},{"en":"surface texture symbol","pos":"noun phrase","ipa":"/ˈsɝːfəs ˈtɛkstʃər ˈsɪmbəl/","ja":"表面性状の図示記号","kana":"ひょうめんせいじょうのずしきごう","romaji":"hyoumenseijounozushikigou","vi":"ký hiệu nhám bề mặt","level":2,"def_vi":"Ký hiệu hình chữ V có đuôi trên bản vẽ, kèm thông số nhám, phương pháp gia công và hướng vết.","def_en":"The tick-shaped drawing symbol, with added parameters, process and lay, used to specify surface texture.","def_ja":"図面上で表面性状を指示するレ形の記号。パラメータ・加工方法・筋目方向を添える。","usage_en":"Danh từ đếm được. Hay đi với: add / apply a surface texture symbol; biến thể: basic symbol, 'material removal required' symbol, 'no material removal' symbol.","usage_ja":"Ngoài xưởng gọi 面の指示記号 hoặc 粗さ記号. Có ba dạng: 基本図示記号, 除去加工の有無を問わない/要する/許さない.","context_vi":"Dùng khi lập và đọc bản vẽ chi tiết theo ISO 1302 / JIS B 0031 / TCVN.","ex_en":"The surface texture symbol on the bore shows Ra 1.6 with material removal required.","ex_ja":"穴の表面性状の図示記号は、除去加工ありのRa1.6を示している。","ex_vi":"Ký hiệu nhám bề mặt ở lỗ cho biết Ra 1,6 và yêu cầu gia công cắt gọt.","syn_en":["surface finish symbol","roughness symbol (khẩu ngữ)"],"syn_ja":["面の指示記号","粗さ記号 (khẩu ngữ)"]},{"en":"finish mark","pos":"noun phrase","ipa":"/ˈfɪnɪʃ ˌmɑːrk/","ja":"仕上げ記号","kana":"しあげきごう","romaji":"shiagekigou","vi":"ký hiệu độ bóng (tam giác, kiểu cũ)","level":2,"def_vi":"Ký hiệu cũ trên bản vẽ (tam giác ▽, chữ f) cho biết bề mặt cần gia công và mức độ nhẵn yêu cầu.","def_en":"An older drawing symbol (triangles ▽ or an 'f') indicating that a surface must be machined and how smooth.","def_ja":"▽などの三角記号で、加工の要否と仕上げ程度を示した旧来の図面記号。","usage_en":"Danh từ đếm được; chủ yếu gặp trên bản vẽ cũ. Khi trao đổi nên quy đổi sang ký hiệu ISO hiện hành, ví dụ ▽▽▽ ≈ Ra 1.6.","usage_ja":"Còn gọi 三角記号; xưởng Nhật vẫn nói '▽▽ (さんかく2つ)', '▽▽▽'. JIS đã bỏ năm 2003 nhưng còn rất nhiều bản vẽ cũ.","context_vi":"Dùng khi đọc bản vẽ cũ của Nhật, Liên Xô hoặc Việt Nam và khi chuyển đổi sang ký hiệu Ra mới.","ex_en":"The old drawing uses a triple-triangle finish mark, which we convert to Ra 1.6.","ex_ja":"旧図面の▽▽▽の仕上げ記号は、Ra1.6に置き換える。","ex_vi":"Bản vẽ cũ dùng ký hiệu độ bóng ba tam giác, chúng tôi quy đổi thành Ra 1,6.","syn_en":["triangle symbol","finish symbol (cách gọi cũ)"],"syn_ja":["三角記号","仕上げ三角 (khẩu ngữ)"]},{"en":"roughness comparison specimen","pos":"noun phrase","ipa":"/ˈrʌfnəs kəmˈpærɪsən ˈspɛsɪmən/","ja":"粗さ標準片","kana":"あらさひょうじゅんへん","romaji":"arasahyoujunhen","vi":"mẫu so sánh độ nhám","level":2,"def_vi":"Bộ mẫu kim loại có các mức nhám đã biết, dùng để so sánh bằng mắt và tay với bề mặt gia công.","def_en":"A set of metal samples with known roughness values used to compare a machined surface by sight and touch.","def_ja":"粗さが既知の金属片の組。加工面と目視・触感で比較するのに使う。","usage_en":"Danh từ đếm được, hay dùng số nhiều 'specimens'. Hay đi với: compare against a roughness comparison specimen; khẩu ngữ: 'roughness comparator'.","usage_ja":"Tên JIS đầy đủ: 比較用表面粗さ標準片. Ngoài xưởng gọi tắt 標準片 hoặc 粗さサンプル; động từ: 標準片と比べる.","context_vi":"Dùng ngay tại máy tiện, phay khi không có máy đo nhám, để thợ tự đánh giá nhanh bề mặt.","ex_en":"The operator checked the milled face against a roughness comparison specimen.","ex_ja":"作業者はフライス加工面を粗さ標準片と比べて確認した。","ex_vi":"Người thợ đã so mặt phay với mẫu so sánh độ nhám.","syn_en":["roughness comparator","surface finish comparator"],"syn_ja":["比較用表面粗さ標準片","粗さサンプル (khẩu ngữ)"]},{"en":"profile peak","pos":"noun phrase","ipa":"/ˈproʊfaɪl ˌpiːk/","ja":"山","kana":"やま","romaji":"yama","vi":"đỉnh profin","level":2,"def_vi":"Phần profin nằm phía trên đường trung bình giữa hai giao điểm liên tiếp với đường này.","def_en":"The part of the profile lying above the mean line between two successive intersections with it.","def_ja":"平均線と交わる隣り合う2点の間で、平均線より上にある輪郭曲線の部分。","usage_en":"Danh từ đếm được. Hay đi với: profile valley (đáy), peak height (Rp), sharp peaks; 'peaks and valleys'.","usage_ja":"Thuật ngữ JIS đầy đủ: 輪郭曲線の山; đối lập là 谷. Hay gặp: 山の高さ (Rp), 山と谷.","context_vi":"Dùng khi giải thích các thông số Rp, Rz, Rsk và khi phân tích bề mặt chạy rà, mài mòn ban đầu.","ex_en":"Each sharp profile peak is quickly worn off during the running-in period.","ex_ja":"鋭い山はなじみ運転の間にすぐ削り取られる。","ex_vi":"Các đỉnh profin nhọn bị mòn đi nhanh chóng trong giai đoạn chạy rà.","syn_en":["peak","asperity (nghĩa gần)"],"syn_ja":["輪郭曲線の山 (JIS)","ピーク"]},{"en":"mean line","pos":"noun phrase","ipa":"/ˈmiːn ˌlaɪn/","ja":"平均線","kana":"へいきんせん","romaji":"heikinsen","vi":"đường trung bình (của profin)","level":2,"def_vi":"Đường chuẩn đi qua profin sao cho phần nhô lên và phần lõm xuống cân bằng, dùng làm gốc tính thông số nhám.","def_en":"The reference line through the profile that balances peaks and valleys, used as the datum for roughness parameters.","def_ja":"山と谷が釣り合うように輪郭曲線に引いた基準線。粗さパラメータの基準となる。","usage_en":"Danh từ đếm được, thường dùng với 'the': deviation from the mean line; trong ISO còn gọi 'reference line'.","usage_ja":"Hay gặp: 平均線からの偏差, 平均線を基準に. Cách gọi cũ: 中心線 (trong 中心線平均粗さ).","context_vi":"Dùng khi học định nghĩa các thông số nhám và khi đọc biểu đồ profin từ máy đo.","ex_en":"All amplitude parameters are calculated relative to the mean line.","ex_ja":"振幅パラメータはすべて平均線を基準に計算される。","ex_vi":"Tất cả các thông số biên độ đều được tính so với đường trung bình.","syn_en":["reference line","centre line (cách gọi cũ)"],"syn_ja":["中心線 (cách gọi cũ)","基準線 (nghĩa gần)"]},{"en":"chatter mark","pos":"noun phrase","ipa":"/ˈtʃætər ˌmɑːrk/","ja":"びびりマーク","kana":"びびりマーク","romaji":"bibirimaaku","vi":"vết rung dao","level":2,"def_vi":"Vết sóng lặp lại đều trên bề mặt gia công do dao hoặc phôi bị rung tự kích (rung động) khi cắt.","def_en":"Regularly repeated wave-like marks on a machined surface caused by self-excited vibration during cutting.","def_ja":"切削中の自励振動によって加工面に規則的に現れる波状の模様。","usage_en":"Danh từ đếm được, thường số nhiều 'chatter marks'. Động từ 'chatter' = rung; hay nói: leave chatter marks, eliminate chatter.","usage_ja":"Ngoài xưởng hay nói びびり, びびり目, びびりが出る. Động từ: びびりマークが出る, びびりを抑える.","context_vi":"Dùng khi tiện trục dài, doa lỗ sâu, phay thành mỏng hoặc khi đồ gá không đủ cứng.","ex_en":"Chatter marks appeared on the long shaft, so we added a steady rest.","ex_ja":"長い軸にびびりマークが出たので、振れ止めを追加した。","ex_vi":"Trên trục dài xuất hiện vết rung dao nên chúng tôi đã lắp thêm luynet.","syn_en":["chatter","vibration marks"],"syn_ja":["びびり目","びびり (khẩu ngữ)"]},{"en":"matte finish","pos":"noun phrase","ipa":"/ˈmæt ˈfɪnɪʃ/","ja":"梨地仕上げ","kana":"なしじしあげ","romaji":"nashijishiage","vi":"bề mặt mờ (nhám mờ)","level":2,"def_vi":"Bề mặt có vân nhám mịn, đồng đều, không bóng, thường tạo bằng phun cát, phun bi hoặc ăn mòn.","def_en":"A fine, uniform, non-glossy surface, typically produced by sand blasting, bead blasting or etching.","def_ja":"ショットやエッチングなどで作る、細かく均一でつやのない面。","usage_en":"Danh từ không đếm được; Anh-Anh viết 'matt finish'. Hay đi với: a matte finish on the housing, bead-blasted matte finish.","usage_ja":"梨地 lấy hình ảnh vỏ quả lê Nhật; hay nói 梨地にする, 梨地加工, シボ (vân khuôn nhựa). Đối lập với 鏡面.","context_vi":"Dùng cho vỏ thiết bị, khuôn nhựa, chi tiết nhôm anod và chi tiết cần chống lóa hoặc che vết tay.","ex_en":"The aluminium cover gets a bead-blasted matte finish before anodizing.","ex_ja":"アルミカバーはアルマイト前にビーズブラストで梨地仕上げにする。","ex_vi":"Nắp nhôm được phun bi tạo bề mặt mờ trước khi anod hóa.","syn_en":["satin finish (nghĩa gần)","matt finish (Anh)"],"syn_ja":["梨地","マット仕上げ"]},{"en":"ten-point mean roughness","pos":"noun phrase","ipa":"/ˈtɛn ˌpɔɪnt ˈmiːn ˈrʌfnəs/","ja":"十点平均粗さ","kana":"じってんへいきんあらさ","romaji":"jittenheikin'arasa","vi":"chiều cao nhấp nhô trung bình mười điểm (Rz cũ)","level":3,"def_vi":"Trung bình 5 đỉnh cao nhất cộng trung bình 5 đáy sâu nhất của profin trong chiều dài chuẩn; nay ký hiệu RzJIS.","def_en":"The mean of the five highest peaks plus the mean of the five deepest valleys within the sampling length; now RzJIS.","def_ja":"基準長さ内の高い山5つの平均と深い谷5つの平均の和。現在の記号はRzJIS。","usage_en":"Thuật ngữ cũ (ISO 4287:1984); dễ nhầm với Rz hiện hành. Khi gặp 'Rz' trên bản vẽ cũ của Nhật cần hỏi rõ là ten-point mean roughness hay maximum height.","usage_ja":"Hiện ghi là RzJIS (JIS B 0601 phụ lục). Bản vẽ Nhật trước 2001 ghi 'Rz' hoặc 'Z' đều mang nghĩa này.","context_vi":"Gặp khi đọc bản vẽ cũ của Nhật và khi chuyển đổi tiêu chuẩn nhám giữa các nhà cung cấp.","ex_en":"The drawing from 1995 gives ten-point mean roughness, so we must not compare it with the new Rz.","ex_ja":"1995年の図面は十点平均粗さなので、新しいRzと比べてはいけない。","ex_vi":"Bản vẽ năm 1995 ghi chiều cao nhấp nhô trung bình mười điểm nên không được so sánh với Rz mới.","syn_en":["RzJIS","Rz (DIN/ISO cũ)"],"syn_ja":["RzJIS","Rz (cách ghi cũ)"]},{"en":"root mean square roughness","pos":"noun phrase","ipa":"/ˈruːt ˈmiːn ˈskwɛr ˈrʌfnəs/","ja":"二乗平均平方根粗さ","kana":"にじょうへいきんへいほうこんあらさ","romaji":"nijouheikinheihoukon'arasa","vi":"sai lệch bình phương trung bình của profin (Rq)","level":3,"def_vi":"Căn bậc hai của trung bình bình phương độ lệch profin so với đường trung bình trong chiều dài chuẩn, ký hiệu Rq.","def_en":"The square root of the mean of the squared profile deviations from the mean line; symbol Rq.","def_ja":"平均線からの偏差の二乗平均の平方根。記号Rq。","usage_en":"Thường viết 'Rq' hoặc 'RMS roughness'. Rq nhạy với đỉnh và đáy hơn Ra; với profin hình sin Rq ≈ 1,11 Ra.","usage_ja":"Hay gọi Rq (アールキュー) hoặc RMS粗さ. Thường dùng trong quang học và nghiên cứu, ít gặp trên bản vẽ cơ khí thông thường.","context_vi":"Dùng trong quang học, bán dẫn, nghiên cứu ma sát và khi khách hàng Mỹ ghi 'RMS' trên bản vẽ cũ.","ex_en":"The optical supplier specifies root mean square roughness, Rq, below 5 nm.","ex_ja":"光学部品メーカーは二乗平均平方根粗さRqを5nm以下と規定している。","ex_vi":"Nhà cung cấp linh kiện quang học quy định sai lệch bình phương trung bình Rq dưới 5 nm.","syn_en":["Rq","RMS roughness"],"syn_ja":["Rq","RMS粗さ"]},{"en":"primary profile","pos":"noun phrase","ipa":"/ˈpraɪmɛri ˈproʊfaɪl/","ja":"断面曲線","kana":"だんめんきょくせん","romaji":"danmenkyokusen","vi":"profin sơ cấp (profin thô)","level":3,"def_vi":"Đường profin đo được sau khi chỉ lọc bỏ thành phần bước rất ngắn λs, chứa cả độ nhám lẫn độ sóng.","def_en":"The measured profile after only the short-wavelength filter λs, containing both roughness and waviness.","def_ja":"λsフィルタのみを通した測定断面曲線。粗さとうねりの両方を含む。","usage_en":"Danh từ đếm được, gọi tắt 'P-profile'; các thông số tương ứng bắt đầu bằng P: Pa, Pt, Pz.","usage_ja":"Còn gọi P曲線; thông số Pt, Pa. Phân biệt với 粗さ曲線 (R) và うねり曲線 (W).","context_vi":"Dùng trong phân tích đo nhám chuyên sâu và khi đọc tiêu chuẩn ISO 4287 / JIS B 0601.","ex_en":"The primary profile is split by the λc filter into roughness and waviness.","ex_ja":"断面曲線はλcフィルタで粗さ曲線とうねり曲線に分けられる。","ex_vi":"Profin sơ cấp được bộ lọc λc tách thành profin nhám và profin sóng.","syn_en":["P-profile","unfiltered profile (nghĩa gần)"],"syn_ja":["P曲線","測定断面曲線 (liên quan)"]},{"en":"roughness profile","pos":"noun phrase","ipa":"/ˈrʌfnəs ˈproʊfaɪl/","ja":"粗さ曲線","kana":"あらさきょくせん","romaji":"arasakyokusen","vi":"profin nhám","level":3,"def_vi":"Profin thu được khi lọc bỏ thành phần sóng dài khỏi profin sơ cấp bằng bộ lọc λc, chỉ còn độ nhám.","def_en":"The profile obtained by removing long-wavelength components from the primary profile with the λc filter.","def_ja":"断面曲線からλcフィルタで長波長成分を除いて得た曲線。","usage_en":"Danh từ đếm được, gọi tắt 'R-profile'; tất cả thông số Ra, Rz, Rq... được tính từ profin này.","usage_ja":"Còn gọi R曲線; hay gặp: 粗さ曲線を表示する, 粗さ曲線から算出する.","context_vi":"Dùng khi đọc kết quả in ra từ máy đo nhám và khi viết báo cáo đo lường.","ex_en":"The roughness profile shows a deep groove that explains the high Rz value.","ex_ja":"粗さ曲線に深い溝が見られ、これがRzが大きい原因である。","ex_vi":"Profin nhám cho thấy một rãnh sâu, giải thích vì sao giá trị Rz cao.","syn_en":["R-profile","filtered profile (nghĩa gần)"],"syn_ja":["R曲線","粗さプロファイル"]},{"en":"cutoff wavelength","pos":"noun phrase","ipa":"/ˈkʌtɔːf ˈweɪvlɛŋθ/","ja":"カットオフ値","kana":"カットオフち","romaji":"kattoofuchi","vi":"bước sóng cắt (giá trị cut-off λc)","level":3,"def_vi":"Bước sóng tại đó bộ lọc của máy đo phân tách độ nhám với độ sóng, ký hiệu λc, ví dụ 0,8 mm.","def_en":"The wavelength at which the instrument filter separates roughness from waviness; symbol λc, e.g. 0.8 mm.","def_ja":"粗さとうねりを分けるフィルタの境界波長。記号λc、例0.8mm。","usage_en":"Danh từ đếm được; hay nói ngắn 'cutoff' hoặc 'λc'. Hay đi với: set the cutoff wavelength to 0.8 mm, standard cutoffs 0.25 / 0.8 / 2.5 mm.","usage_ja":"Hay nói カットオフ, λc; động từ: カットオフ値を設定する, カットオフ値を変える. Chọn theo JIS B 0633.","context_vi":"Dùng khi cài đặt máy đo nhám; chọn sai λc là nguyên nhân phổ biến khiến kết quả đo giữa hai bên lệch nhau.","ex_en":"The supplier used a cutoff wavelength of 2.5 mm, so their Ra was higher than ours.","ex_ja":"サプライヤはカットオフ値2.5mmで測ったため、Raが当社より大きかった。","ex_vi":"Nhà cung cấp dùng bước sóng cắt 2,5 mm nên giá trị Ra của họ cao hơn của chúng tôi.","syn_en":["cutoff","λc"],"syn_ja":["λc","カットオフ"]},{"en":"evaluation length","pos":"noun phrase","ipa":"/ɪˌvæljuˈeɪʃən ˌlɛŋθ/","ja":"評価長さ","kana":"ひょうかながさ","romaji":"hyoukanagasa","vi":"chiều dài đánh giá","level":3,"def_vi":"Tổng chiều dài dùng để đánh giá profin, thường gồm năm chiều dài chuẩn liên tiếp, ký hiệu ln.","def_en":"The total length used to assess the profile, normally five consecutive sampling lengths; symbol ln.","def_ja":"輪郭曲線を評価する全長さ。通常は基準長さの5倍。記号ln。","usage_en":"Danh từ đếm được. Hay đi với: over the evaluation length, an evaluation length of 4 mm; khác với 'traverse length' (chiều dài hành trình đầu dò).","usage_ja":"Ký hiệu ln; hay gặp: 評価長さ4mm, 評価長さを短くする. Đừng nhầm với 測定長さ/走査長さ.","context_vi":"Dùng khi đo các chi tiết có mặt đo ngắn (rãnh, vai trục) phải rút ngắn chiều dài đánh giá.","ex_en":"The groove is only 3 mm wide, so the evaluation length was reduced to three cutoffs.","ex_ja":"溝幅が3mmしかないため、評価長さをカットオフ3つ分に短縮した。","ex_vi":"Rãnh chỉ rộng 3 mm nên chiều dài đánh giá được rút ngắn còn ba bước cắt.","syn_en":["ln (ký hiệu)","assessment length (nghĩa gần)"],"syn_ja":["ln","測定長さ (nghĩa gần)"]}]},{"id":17,"words":[{"en":"CAD","pos":"abbreviation","ipa":"/kæd/","ja":"CAD","kana":"キャド","romaji":"kyado","vi":"thiết kế có trợ giúp của máy tính (CAD)","level":1,"def_vi":"Việc dùng phần mềm máy tính để tạo, sửa và lưu bản vẽ 2D hoặc mô hình 3D của sản phẩm.","def_en":"Computer-aided design: using software to create, modify and store 2D drawings or 3D models of products.","def_ja":"コンピュータで製品の2D図面や3Dモデルを作成・修正・保存すること。","usage_en":"Viết tắt của computer-aided design, đọc như một từ /kæd/, không đánh vần. Hay đi với: CAD software, CAD model, CAD data, 'draw it in CAD'.","usage_ja":"Đọc キャド. Hay gặp: CADで描く, CADデータ, 3D CAD, 2D CAD; người làm bản vẽ gọi là CADオペレーター.","context_vi":"Dùng hằng ngày ở phòng thiết kế, khi trao đổi file với khách hàng, nhà cung cấp và xưởng gia công.","ex_en":"Please send the bracket as CAD data, not just a PDF drawing.","ex_ja":"ブラケットはPDF図面だけでなく、CADデータで送ってください。","ex_vi":"Vui lòng gửi giá đỡ dưới dạng dữ liệu CAD, không chỉ bản vẽ PDF.","syn_en":["computer-aided design","CADD (computer-aided design and drafting)"],"syn_ja":["コンピュータ支援設計","3D CAD (nghĩa hẹp hơn)"]},{"en":"3D model","pos":"noun phrase","ipa":"/ˌθriː ˈdiː ˈmɑːdəl/","ja":"3Dモデル","kana":"スリーディーモデル","romaji":"suriidiimoderu","vi":"mô hình 3D","level":1,"def_vi":"Biểu diễn hình học ba chiều của chi tiết hoặc cụm máy trong phần mềm CAD.","def_en":"A three-dimensional geometric representation of a part or assembly created in CAD software.","def_ja":"CADソフトで作成した部品や組立品の三次元形状データ。","usage_en":"Danh từ đếm được. Hay đi với: build / create / update a 3D model, 3D model of the housing; đọc 'three-D'.","usage_ja":"Hay nói 3Dモデルを作る/修正する, 3Dデータ. Trong xưởng đôi khi chỉ gọi モデル hoặc 3D.","context_vi":"Dùng trong thiết kế, kiểm tra lắp ráp, mô phỏng, lập trình CAM và trao đổi với nhà cung cấp.","ex_en":"I updated the 3D model after the customer changed the hole positions.","ex_ja":"顧客が穴位置を変更したので、3Dモデルを修正した。","ex_vi":"Tôi đã cập nhật mô hình 3D sau khi khách hàng thay đổi vị trí lỗ.","syn_en":["3D CAD model","solid model (nghĩa hẹp hơn)"],"syn_ja":["3Dデータ","三次元モデル"]},{"en":"sketch","pos":"noun","ipa":"/skɛtʃ/","ja":"スケッチ","kana":"スケッチ","romaji":"sukecchi","vi":"bản phác thảo (sketch)","level":1,"def_vi":"Biên dạng 2D vẽ trên một mặt phẳng trong CAD, làm cơ sở để tạo các tính năng 3D như đùn, xoay.","def_en":"A 2D profile drawn on a plane in CAD that serves as the basis for 3D features such as extrudes and revolves.","def_ja":"CADで平面上に描く2D輪郭。押し出しや回転などの3Dフィーチャの元となる。","usage_en":"Danh từ đếm được, cũng là động từ. Hay đi với: create a sketch on the top plane, edit the sketch, sketch plane, sketch entities.","usage_ja":"Hay gặp: スケッチを描く, スケッチ平面, スケッチを編集する. Trong thiết kế ý tưởng, 手書きスケッチ là phác tay trên giấy.","context_vi":"Dùng ở bước đầu tiên khi dựng mô hình trong SolidWorks, Inventor, Creo, NX, Fusion 360.","ex_en":"Start a new sketch on the front plane and draw the flange outline.","ex_ja":"正面に新しいスケッチを作成し、フランジの外形を描いてください。","ex_vi":"Hãy tạo một bản phác mới trên mặt phẳng trước và vẽ đường bao mặt bích.","syn_en":["profile","2D sketch"],"syn_ja":["2Dスケッチ","断面スケッチ (nghĩa gần)"]},{"en":"extrude","pos":"verb","ipa":"/ɪkˈstruːd/","ja":"押し出し","kana":"おしだし","romaji":"oshidashi","vi":"đùn khối (extrude)","level":1,"def_vi":"Lệnh CAD kéo một biên dạng phác thảo theo phương vuông góc một khoảng nhất định để tạo khối đặc hoặc cắt vật liệu.","def_en":"In CAD, to sweep a sketch profile straight along a direction by a set distance to add or cut material.","def_ja":"CADでスケッチ輪郭を一定方向に一定距離伸ばし、形状を追加または除去する操作。","usage_en":"Động từ, danh từ là 'extrusion' hoặc 'extrude' (tên tính năng). Hay đi với: extrude 20 mm, extrude cut, extruded boss; 'extrude through all'.","usage_ja":"Tên lệnh trong CAD Nhật: 押し出し, 押し出しボス/ベース, 押し出しカット. Động từ: 押し出す, 20mm押し出す.","context_vi":"Là thao tác dựng hình cơ bản nhất khi mô hình hóa tấm, vỏ, giá đỡ, mặt bích.","ex_en":"Extrude the sketch 15 mm to create the base plate.","ex_ja":"スケッチを15mm押し出してベースプレートを作成する。","ex_vi":"Đùn bản phác lên 15 mm để tạo tấm đế.","syn_en":["extrusion (danh từ)","pad (CATIA)"],"syn_ja":["押し出しボス","パッド (CATIA)"]},{"en":"revolve","pos":"verb","ipa":"/rɪˈvɑːlv/","ja":"回転","kana":"かいてん","romaji":"kaiten","vi":"xoay khối (revolve)","level":1,"def_vi":"Lệnh CAD xoay một biên dạng phác thảo quanh một trục để tạo khối tròn xoay như trục, puly, bạc.","def_en":"In CAD, to rotate a sketch profile about an axis to create an axisymmetric body such as a shaft or pulley.","def_ja":"CADでスケッチ輪郭を軸まわりに回し、軸やプーリなどの回転体を作る操作。","usage_en":"Động từ, cũng dùng như danh từ chỉ tính năng ('a revolve feature'). Hay đi với: revolve 360°, revolve about the centerline, revolved cut.","usage_ja":"Tên lệnh: 回転ボス/ベース, 回転カット. Động từ: 回転させる, 中心線を軸に回転する.","context_vi":"Dùng khi dựng các chi tiết tròn xoay như trục, bạc, puly, nắp, bánh đà.","ex_en":"Draw half of the shaft profile and revolve it about the centerline.","ex_ja":"軸の半断面を描き、中心線を軸に回転して形状を作る。","ex_vi":"Vẽ một nửa biên dạng trục rồi xoay nó quanh đường tâm.","syn_en":["revolve feature","shaft (CATIA)"],"syn_ja":["回転ボス","回転体 (liên quan)"]},{"en":"fillet","pos":"noun","ipa":"/ˈfɪlɪt/","ja":"フィレット","kana":"フィレット","romaji":"firetto","vi":"bo tròn cạnh (fillet)","level":1,"def_vi":"Tính năng CAD bo tròn cạnh hoặc góc trong của mô hình theo một bán kính cho trước.","def_en":"A CAD feature that rounds an edge or internal corner of a model with a specified radius.","def_ja":"モデルの稜線や入隅を指定半径で丸めるCADのフィーチャ。","usage_en":"Danh từ đếm được, cũng là động từ. Hay đi với: add a 2 mm fillet, fillet the edges; góc ngoài bo tròn còn gọi 'round'.","usage_ja":"Trong CAD gọi フィレット; trên bản vẽ và xưởng nói R, ví dụ R2を付ける, 角R. Động từ: フィレットをかける.","context_vi":"Dùng để giảm tập trung ứng suất, dễ gia công, dễ đúc/ép nhựa và tăng thẩm mỹ cho sản phẩm.","ex_en":"Add a 3 mm fillet to all internal corners of the casting.","ex_ja":"鋳物の入隅すべてに3mmのフィレットを付けてください。","ex_vi":"Hãy bo tròn 3 mm cho tất cả các góc trong của chi tiết đúc.","syn_en":["round","radius (khẩu ngữ)"],"syn_ja":["R (khẩu ngữ)","角丸め"]},{"en":"layer","pos":"noun","ipa":"/ˈleɪər/","ja":"画層","kana":"がそう","romaji":"gasou","vi":"lớp (layer)","level":1,"def_vi":"Lớp tổ chức đối tượng trong bản vẽ CAD 2D, mỗi lớp có màu, kiểu đường, độ dày nét riêng và có thể bật tắt.","def_en":"A named level in a 2D CAD drawing that groups objects with their own color, linetype and lineweight.","def_ja":"2D CAD図面で、色・線種・線の太さを持つ図形のグループを管理する層。","usage_en":"Danh từ đếm được. Hay đi với: put on / move to a layer, turn off / freeze / lock a layer, layer name.","usage_ja":"AutoCAD bản tiếng Nhật dùng 画層; nhiều CAD khác và trong xưởng gọi レイヤー. Động từ: 画層を切り替える, 画層を非表示にする.","context_vi":"Dùng khi vẽ 2D trong AutoCAD, quản lý nét tâm, nét kích thước, nét khuất theo quy định của công ty.","ex_en":"Put all center lines on the CENTER layer before plotting.","ex_ja":"印刷する前に、中心線はすべてCENTER画層に移してください。","ex_vi":"Hãy chuyển tất cả các đường tâm sang lớp CENTER trước khi in.","syn_en":["level (MicroStation)","drawing layer"],"syn_ja":["レイヤー","レイヤ"]},{"en":"rendering","pos":"noun","ipa":"/ˈrɛndərɪŋ/","ja":"レンダリング","kana":"レンダリング","romaji":"renderingu","vi":"kết xuất hình ảnh (rendering)","level":1,"def_vi":"Tạo ảnh trông như thật từ mô hình 3D bằng cách gán vật liệu, ánh sáng và bóng đổ.","def_en":"Producing a realistic image from a 3D model by applying materials, lighting and shadows.","def_ja":"3Dモデルに材質・光源・影を設定し、写実的な画像を作ること。","usage_en":"Danh từ (không đếm được chỉ quá trình, đếm được chỉ bức ảnh). Động từ 'render'. Hay đi với: photorealistic rendering, render an image.","usage_ja":"Hay gặp: レンダリングする, レンダリング画像, CG. Người Nhật thường gọi ảnh kết quả là パース (khi kiến trúc) hoặc CG.","context_vi":"Dùng trong thiết kế công nghiệp, catalog, báo giá và trình bày ý tưởng cho khách hàng.","ex_en":"Marketing needs a rendering of the new pump for the catalogue.","ex_ja":"カタログ用に、新型ポンプのレンダリング画像が必要だと営業から言われた。","ex_vi":"Bộ phận marketing cần một ảnh kết xuất của máy bơm mới cho catalog.","syn_en":["render","photorealistic image"],"syn_ja":["CG画像","レンダリング画像"]},{"en":"mirror","pos":"verb","ipa":"/ˈmɪrər/","ja":"ミラー","kana":"ミラー","romaji":"miraa","vi":"đối xứng gương (mirror)","level":1,"def_vi":"Lệnh CAD sao chép đối tượng hoặc tính năng đối xứng qua một mặt phẳng hoặc một đường.","def_en":"In CAD, to copy entities or features symmetrically about a plane or line.","def_ja":"CADで図形やフィーチャを平面または線に対して対称に複写する操作。","usage_en":"Động từ và danh từ ('a mirror feature'). Hay đi với: mirror about the right plane, mirror the holes, mirrored part (chi tiết đối xứng trái/phải).","usage_ja":"Tên lệnh: ミラー, ミラー部品 (chi tiết đối xứng). Động từ: ミラーする, ミラーコピーする; tiếng Nhật trang trọng: 鏡像.","context_vi":"Dùng để dựng nhanh chi tiết đối xứng và tạo chi tiết bên trái/bên phải trong ô tô, khung máy.","ex_en":"Model one side of the bracket and mirror it about the center plane.","ex_ja":"ブラケットの片側だけ作り、中心面でミラーしてください。","ex_vi":"Hãy dựng một nửa giá đỡ rồi lấy đối xứng qua mặt phẳng giữa.","syn_en":["symmetry (CATIA)","mirror copy"],"syn_ja":["鏡像","ミラーコピー"]},{"en":"export","pos":"verb","ipa":"/ɪkˈspɔːrt/","ja":"エクスポート","kana":"エクスポート","romaji":"ekusupooto","vi":"xuất file (export)","level":1,"def_vi":"Lưu dữ liệu CAD sang một định dạng khác như STEP, DXF, PDF, STL để dùng ở phần mềm khác.","def_en":"To save CAD data in another format, such as STEP, DXF, PDF or STL, for use in other software.","def_ja":"CADデータをSTEP・DXF・PDF・STLなど別の形式で保存すること。","usage_en":"Động từ và danh từ. Hay đi với: export to / as STEP, export a DXF for laser cutting; ngược nghĩa là 'import'.","usage_ja":"Hay nói エクスポートする, STEPで書き出す (書き出し là cách nói thuần Nhật). Ngược lại là インポート/読み込み.","context_vi":"Dùng khi gửi file cho nhà cung cấp, xưởng cắt laser, in 3D hoặc chuyển sang phần mềm CAE, CAM.","ex_en":"Export the sheet metal flat pattern as a DXF for the laser cutter.","ex_ja":"板金の展開図をDXFでエクスポートしてレーザー加工機に渡してください。","ex_vi":"Hãy xuất hình trải phẳng của chi tiết tấm sang DXF cho máy cắt laser.","syn_en":["save as","write out (nghĩa gần)"],"syn_ja":["書き出し","名前を付けて保存 (nghĩa gần)"]},{"en":"CAE","pos":"abbreviation","ipa":"/ˌsiː eɪ ˈiː/","ja":"CAE","kana":"シーエーイー","romaji":"shiieeii","vi":"kỹ thuật có trợ giúp của máy tính (CAE)","level":2,"def_vi":"Việc dùng phần mềm để mô phỏng, phân tích sức bền, nhiệt, dòng chảy, chuyển động của sản phẩm trước khi chế tạo.","def_en":"Computer-aided engineering: using software to simulate and analyse strength, heat, flow and motion before building a product.","def_ja":"製品を作る前に、強度・熱・流れ・動きをコンピュータで解析すること。","usage_en":"Viết tắt, đọc từng chữ cái. Hay đi với: CAE analysis, CAE engineer, CAE tools; trong công ty Mỹ thường nói 'simulation' thay cho CAE.","usage_ja":"Hay nói CAE解析, CAEで検証する, 解析担当. Trong công ty Nhật CAE gần như đồng nghĩa với 解析.","context_vi":"Dùng ở bộ phận R&D, ô tô, điện tử, khi muốn giảm số lần chế tạo mẫu thử.","ex_en":"The CAE team will check the bracket stiffness before we order prototypes.","ex_ja":"試作を発注する前に、CAEチームがブラケットの剛性を確認する。","ex_vi":"Nhóm CAE sẽ kiểm tra độ cứng của giá đỡ trước khi chúng tôi đặt làm mẫu thử.","syn_en":["computer-aided engineering","simulation (khẩu ngữ)"],"syn_ja":["解析 (khẩu ngữ)","シミュレーション"]},{"en":"solid model","pos":"noun phrase","ipa":"/ˈsɑːlɪd ˈmɑːdəl/","ja":"ソリッドモデル","kana":"ソリッドモデル","romaji":"soriddomoderu","vi":"mô hình khối đặc","level":2,"def_vi":"Mô hình 3D kín, có thể tích và khối lượng, phân biệt rõ phần trong và ngoài vật thể.","def_en":"A closed 3D model with volume and mass that clearly defines the inside and outside of the object.","def_ja":"体積と質量を持ち、内部と外部が明確に区別される閉じた3Dモデル。","usage_en":"Danh từ đếm được. Hay đi với: convert to a solid model, solid body, solid modeling (quá trình).","usage_ja":"Hay gặp: ソリッドモデル, ソリッドボディ, ソリッド化する (biến mặt thành khối).","context_vi":"Là dạng mô hình chuẩn cho chi tiết cơ khí, cần thiết để tính khối lượng, kiểm tra va chạm, phân tích FEA.","ex_en":"The imported surfaces were stitched into a solid model before meshing.","ex_ja":"読み込んだサーフェスを縫い合わせてソリッドモデルにしてから、メッシュを切った。","ex_vi":"Các mặt được nhập vào đã được khâu lại thành mô hình khối đặc trước khi chia lưới.","syn_en":["solid body","solid (khẩu ngữ)"],"syn_ja":["ソリッドボディ","ソリッド (khẩu ngữ)"]},{"en":"surface model","pos":"noun phrase","ipa":"/ˈsɝːfəs ˈmɑːdəl/","ja":"サーフェスモデル","kana":"サーフェスモデル","romaji":"saafesumoderu","vi":"mô hình mặt","level":2,"def_vi":"Mô hình 3D chỉ gồm các mặt không có độ dày, thường dùng cho hình dáng cong phức tạp.","def_en":"A 3D model made only of zero-thickness surfaces, typically used for complex curved shapes.","def_ja":"厚みのない面だけで構成された3Dモデル。複雑な曲面形状に用いる。","usage_en":"Danh từ đếm được; 'surface modeling' là kỹ thuật dựng mặt. Hay đi với: class-A surface, trim / knit / thicken surfaces.","usage_ja":"Hay gặp: サーフェスモデリング, サーフェスを張る, 面を貼る (khẩu ngữ). Bề mặt ngoại thất ô tô chất lượng cao gọi là 意匠面.","context_vi":"Dùng trong thiết kế vỏ ô tô, đồ gia dụng, khuôn mẫu và khi sửa dữ liệu quét 3D.","ex_en":"The designer built the handle as a surface model and then thickened it.","ex_ja":"デザイナーはハンドルをサーフェスモデルで作り、その後に厚み付けした。","ex_vi":"Nhà thiết kế dựng tay cầm dưới dạng mô hình mặt rồi mới tạo độ dày.","syn_en":["surface body","freeform surface (nghĩa gần)"],"syn_ja":["サーフェス","曲面モデル"]},{"en":"wireframe","pos":"noun","ipa":"/ˈwaɪərfreɪm/","ja":"ワイヤフレーム","kana":"ワイヤフレーム","romaji":"waiyafureemu","vi":"mô hình khung dây","level":2,"def_vi":"Cách biểu diễn mô hình 3D chỉ bằng các cạnh và đường, không có mặt hay khối.","def_en":"A representation of a 3D model using only edges and curves, without surfaces or volume.","def_ja":"面や体積を持たず、稜線と曲線だけで3D形状を表す方法。","usage_en":"Danh từ không đếm được hoặc dùng như tính từ: wireframe model, wireframe view, display in wireframe.","usage_ja":"Hay gặp: ワイヤフレーム表示, ワイヤフレームモデル; một số phần mềm viết ワイヤーフレーム.","context_vi":"Dùng như chế độ hiển thị để nhìn xuyên mô hình, hoặc làm khung đường dẫn trong dựng mặt.","ex_en":"Switch to wireframe view to see the hidden cooling channels.","ex_ja":"内部の冷却水路を見るには、ワイヤフレーム表示に切り替えてください。","ex_vi":"Hãy chuyển sang chế độ hiển thị khung dây để thấy các kênh làm mát bên trong.","syn_en":["wireframe model","edge view (nghĩa gần)"],"syn_ja":["ワイヤーフレーム","線画表示 (nghĩa gần)"]},{"en":"parametric modeling","pos":"noun phrase","ipa":"/ˌpærəˈmɛtrɪk ˈmɑːdəlɪŋ/","ja":"パラメトリックモデリング","kana":"パラメトリックモデリング","romaji":"parametorikkumoderingu","vi":"mô hình hóa tham số","level":2,"def_vi":"Phương pháp dựng mô hình dựa trên kích thước, ràng buộc và lịch sử tính năng, thay đổi tham số thì mô hình tự cập nhật.","def_en":"A modeling method driven by dimensions, constraints and feature history, so changing a parameter updates the model.","def_ja":"寸法・拘束・履歴でモデルを定義し、パラメータ変更で形状が自動更新される手法。","usage_en":"Danh từ không đếm được. Hay đi với: parametric CAD, parametric model, history-based parametric modeling.","usage_ja":"Hay gặp: パラメトリック設計, パラメトリックCAD; đối lập với ダイレクトモデリング. Ngoài xưởng nói 履歴ベース.","context_vi":"Là cách làm chuẩn trong SolidWorks, Inventor, Creo, cho phép tạo nhanh các biến thể kích thước của sản phẩm.","ex_en":"With parametric modeling, changing the bore diameter updates every related feature.","ex_ja":"パラメトリックモデリングでは、穴径を変えると関連するフィーチャがすべて更新される。","ex_vi":"Với mô hình hóa tham số, thay đổi đường kính lỗ sẽ cập nhật mọi tính năng liên quan.","syn_en":["history-based modeling","feature-based modeling (nghĩa gần)"],"syn_ja":["パラメトリック設計","履歴ベースモデリング"]},{"en":"feature tree","pos":"noun phrase","ipa":"/ˈfiːtʃər ˌtriː/","ja":"フィーチャーツリー","kana":"フィーチャーツリー","romaji":"fiichaatsurii","vi":"cây tính năng (cây lịch sử dựng hình)","level":2,"def_vi":"Danh sách dạng cây trong phần mềm CAD liệt kê theo thứ tự các bản phác và tính năng đã tạo nên mô hình.","def_en":"The tree-like list in CAD software showing, in order, the sketches and features used to build a model.","def_ja":"モデルを作ったスケッチやフィーチャを作成順に表示するCADのツリー。","usage_en":"Danh từ đếm được. Hay đi với: in the feature tree, roll back the feature tree, reorder features; SolidWorks gọi 'FeatureManager design tree'.","usage_ja":"Còn gọi 履歴ツリー, モデルツリー (Creo). Hay nói ツリーを戻す, ツリーの順番を入れ替える.","context_vi":"Dùng khi sửa mô hình, tìm lỗi tính năng và khi bàn giao file CAD cho người khác chỉnh sửa.","ex_en":"Keep the feature tree clean and name the important features.","ex_ja":"フィーチャーツリーは整理し、重要なフィーチャには名前を付けておくこと。","ex_vi":"Hãy giữ cây tính năng gọn gàng và đặt tên cho các tính năng quan trọng.","syn_en":["model tree","history tree","design tree (SolidWorks)"],"syn_ja":["履歴ツリー","モデルツリー (Creo)"]},{"en":"constraint","pos":"noun","ipa":"/kənˈstreɪnt/","ja":"拘束","kana":"こうそく","romaji":"kousoku","vi":"ràng buộc","level":2,"def_vi":"Điều kiện hình học (song song, tiếp tuyến, đồng tâm...) hoặc kích thước gán cho phần tử phác thảo để cố định hình dạng.","def_en":"A geometric condition (parallel, tangent, concentric, etc.) or dimension applied to sketch entities to fix their shape.","def_ja":"平行・正接・同心などの幾何条件や寸法を図形に与えて形状を決める条件。","usage_en":"Danh từ đếm được. Hay đi với: add / delete a constraint, geometric constraint, dimensional constraint, over-constrained sketch.","usage_ja":"Hay gặp: 幾何拘束, 寸法拘束, 拘束を付ける, 拘束を外す, 過剰拘束. Trong cụm lắp (Inventor) cũng gọi アセンブリ拘束.","context_vi":"Dùng khi vẽ phác thảo và lắp ghép mô hình để thiết kế thay đổi đúng ý đồ.","ex_en":"Add a tangent constraint between the arc and the line.","ex_ja":"円弧と直線の間に正接の拘束を追加してください。","ex_vi":"Hãy thêm ràng buộc tiếp tuyến giữa cung tròn và đoạn thẳng.","syn_en":["relation (SolidWorks)","geometric constraint"],"syn_ja":["幾何拘束","拘束条件"]},{"en":"fully defined","pos":"adjective","ipa":"/ˈfʊli dɪˈfaɪnd/","ja":"完全定義","kana":"かんぜんていぎ","romaji":"kanzenteigi","vi":"xác định hoàn toàn","level":2,"def_vi":"Trạng thái bản phác mà mọi phần tử đã được ràng buộc và ghi kích thước đủ, không thể tự dịch chuyển.","def_en":"Describing a sketch in which all entities are completely fixed by dimensions and constraints.","def_ja":"寸法と拘束によりすべての図形が完全に決まり、動かない状態。","usage_en":"Tính từ, thường dùng với be: 'the sketch is fully defined'. Ngược lại: under-defined, over-defined; động từ: fully define a sketch.","usage_ja":"Thuật ngữ trong SolidWorks tiếng Nhật; các trạng thái khác: 未定義, 過剰定義. Hay nói 完全定義にする, スケッチが完全定義になっていない.","context_vi":"Dùng trong quy định chất lượng mô hình CAD của công ty và khi hướng dẫn nhân viên mới dựng hình.","ex_en":"Make sure every sketch is fully defined before releasing the model.","ex_ja":"モデルを出図する前に、すべてのスケッチを完全定義にしておくこと。","ex_vi":"Hãy đảm bảo mọi bản phác đều được xác định hoàn toàn trước khi phát hành mô hình.","syn_en":["fully constrained","well-constrained (nghĩa gần)"],"syn_ja":["完全拘束","全拘束"]},{"en":"mate","pos":"noun","ipa":"/meɪt/","ja":"合致","kana":"がっち","romaji":"gacchi","vi":"ràng buộc lắp ghép (mate)","level":2,"def_vi":"Quan hệ giữa các chi tiết trong cụm lắp CAD (trùng mặt, đồng trục, khoảng cách...) để định vị chúng với nhau.","def_en":"A relationship between parts in a CAD assembly, such as coincident, concentric or distance, that positions them.","def_ja":"アセンブリで部品同士を一致・同心・距離などで位置決めする関係。","usage_en":"Danh từ đếm được, cũng là động từ ('mate the shaft to the bore'). Hay đi với: add a concentric mate, mate error; Inventor/NX gọi 'assembly constraint'.","usage_ja":"合致 là tên trong SolidWorks tiếng Nhật; Inventor, NX dùng アセンブリ拘束. Hay nói 合致を付ける, 合致エラー.","context_vi":"Dùng khi lắp ráp mô hình 3D, kiểm tra chuyển động và tạo bản vẽ lắp.","ex_en":"Add a concentric mate between the pin and the hole.","ex_ja":"ピンと穴の間に同心円の合致を追加する。","ex_vi":"Thêm ràng buộc lắp ghép đồng tâm giữa chốt và lỗ.","syn_en":["assembly constraint","joint (Fusion 360)"],"syn_ja":["アセンブリ拘束","拘束 (Inventor)"]},{"en":"interference check","pos":"noun phrase","ipa":"/ˌɪntərˈfɪrəns ˌtʃɛk/","ja":"干渉チェック","kana":"かんしょうチェック","romaji":"kanshouchekku","vi":"kiểm tra va chạm (giao thoa)","level":2,"def_vi":"Chức năng CAD tìm các vùng mà hai chi tiết trong cụm lắp chồng lấn lên nhau về thể tích.","def_en":"A CAD function that finds where two parts in an assembly overlap in volume.","def_ja":"アセンブリ内で部品同士が体積的に重なっている箇所を見つけるCAD機能。","usage_en":"Danh từ đếm được. Hay đi với: run an interference check, interference detection, clearance check (kiểm tra khe hở).","usage_ja":"Hay nói 干渉チェックをかける, 干渉している, 干渉箇所. Ngoài xưởng: 当たっている (chạm nhau).","context_vi":"Dùng trước khi phát hành bản vẽ lắp, thiết kế bố trí đường ống, dây điện, khung máy.","ex_en":"The interference check found that the bolt head hits the cover.","ex_ja":"干渉チェックで、ボルトの頭がカバーに当たっていることが分かった。","ex_vi":"Kiểm tra va chạm cho thấy đầu bu lông chạm vào nắp.","syn_en":["interference detection","clash detection"],"syn_ja":["干渉検査","干渉確認"]},{"en":"neutral file","pos":"noun phrase","ipa":"/ˈnuːtrəl ˌfaɪl/","ja":"中間ファイル","kana":"ちゅうかんファイル","romaji":"chuukanfairu","vi":"file định dạng trung gian","level":2,"def_vi":"File CAD ở định dạng chuẩn không phụ thuộc phần mềm như STEP, IGES, Parasolid, dùng để trao đổi dữ liệu.","def_en":"A CAD file in a vendor-independent format such as STEP, IGES or Parasolid, used to exchange data between systems.","def_ja":"STEP・IGES・Parasolidなど、特定のCADに依存しないデータ交換用ファイル。","usage_en":"Danh từ đếm được. Hay đi với: neutral file format, send a neutral file; dân thiết kế thường nói thẳng 'a STEP file'.","usage_ja":"Cách nói rất phổ biến ở công ty Nhật: 中間ファイルで送る, 中間ファイルに変換する. Thường chỉ STEP, IGES, Parasolid (x_t).","context_vi":"Dùng khi trao đổi mô hình với khách hàng, nhà cung cấp dùng phần mềm CAD khác.","ex_en":"Our supplier uses a different CAD system, so we send a STEP neutral file.","ex_ja":"仕入先は別のCADを使っているので、STEPの中間ファイルで送る。","ex_vi":"Nhà cung cấp dùng phần mềm CAD khác nên chúng tôi gửi file trung gian STEP.","syn_en":["STEP file","IGES file","exchange format"],"syn_ja":["STEPファイル","変換データ (khẩu ngữ)"]},{"en":"mass properties","pos":"noun phrase","ipa":"/ˈmæs ˌprɑːpərtiz/","ja":"質量特性","kana":"しつりょうとくせい","romaji":"shitsuryoutokusei","vi":"đặc tính khối lượng","level":2,"def_vi":"Các giá trị CAD tính từ mô hình: khối lượng, thể tích, diện tích bề mặt, trọng tâm và mômen quán tính.","def_en":"Values computed from a model: mass, volume, surface area, centre of gravity and moments of inertia.","def_ja":"モデルから求める質量・体積・表面積・重心・慣性モーメントなどの値。","usage_en":"Luôn dùng số nhiều. Hay đi với: check / calculate the mass properties, mass properties report; phải gán đúng vật liệu trước.","usage_ja":"Tên lệnh trong SolidWorks tiếng Nhật: 質量特性. Ngoài xưởng hỏi 重さは？, 重心位置は？.","context_vi":"Dùng để ước lượng khối lượng, chọn động cơ, tính cân bằng và lập dự toán vật tư.","ex_en":"Check the mass properties to find the centre of gravity of the frame.","ex_ja":"質量特性を確認して、フレームの重心位置を求めてください。","ex_vi":"Hãy xem đặc tính khối lượng để tìm trọng tâm của khung.","syn_en":["mass properties report","physical properties (Inventor)"],"syn_ja":["物理特性","重量計算 (nghĩa gần)"]},{"en":"linear pattern","pos":"noun phrase","ipa":"/ˈlɪniər ˈpætərn/","ja":"直線パターン","kana":"ちょくせんパターン","romaji":"chokusenpataan","vi":"sao chép mảng thẳng","level":2,"def_vi":"Tính năng CAD nhân bản một tính năng theo một hoặc hai phương thẳng với số lượng và khoảng cách đã cho.","def_en":"A CAD feature that copies a feature along one or two straight directions with a set count and spacing.","def_ja":"フィーチャを1方向または2方向に、指定した数と間隔で複写するCAD機能。","usage_en":"Danh từ đếm được. Hay đi với: create a linear pattern of holes, pattern spacing; loại khác: circular pattern (mảng tròn).","usage_ja":"Còn gọi 矩形パターン (Inventor); loại tròn là 円形パターン. Động từ: パターン化する, パターンで並べる.","context_vi":"Dùng để tạo dãy lỗ, gân, rãnh tản nhiệt, mặt bích nhiều bu lông nhanh và dễ sửa.","ex_en":"Use a linear pattern to create 12 ventilation slots at 10 mm spacing.","ex_ja":"直線パターンで、10mm間隔の通風スリットを12個作る。","ex_vi":"Dùng sao chép mảng thẳng để tạo 12 khe thông gió cách nhau 10 mm.","syn_en":["rectangular pattern","array (AutoCAD)"],"syn_ja":["矩形パターン","配列複写 (AutoCAD)"]},{"en":"motion analysis","pos":"noun phrase","ipa":"/ˈmoʊʃən əˈnæləsɪs/","ja":"機構解析","kana":"きこうかいせき","romaji":"kikoukaiseki","vi":"phân tích động học cơ cấu","level":2,"def_vi":"Mô phỏng chuyển động của cụm lắp CAD để tính vị trí, vận tốc, lực và mômen trên các khâu, khớp.","def_en":"Simulation of an assembly's movement to calculate positions, velocities, forces and torques in links and joints.","def_ja":"アセンブリの動きを模擬し、各部の位置・速度・力・トルクを求める解析。","usage_en":"Danh từ không đếm được. Hay đi với: run a motion analysis, motion study, multibody dynamics (MBD) software.","usage_ja":"Hay gặp: 機構解析ソフト, 動作シミュレーション, モーション解析; chuyên sâu gọi マルチボディダイナミクス.","context_vi":"Dùng khi thiết kế cơ cấu kẹp, tay robot, cơ cấu cam, cửa xe, để kiểm tra hành trình và chọn động cơ.","ex_en":"The motion analysis showed the cylinder needs at least 800 N to lift the arm.","ex_ja":"機構解析の結果、アームを持ち上げるにはシリンダに800N以上必要と分かった。","ex_vi":"Phân tích động học cơ cấu cho thấy xi lanh cần ít nhất 800 N để nâng tay đòn.","syn_en":["motion study","multibody simulation (nghĩa gần)"],"syn_ja":["モーション解析","動作シミュレーション"]},{"en":"topology optimization","pos":"noun phrase","ipa":"/təˈpɑːlədʒi ˌɑːptəməˈzeɪʃən/","ja":"トポロジー最適化","kana":"トポロジーさいてきか","romaji":"toporojiisaitekika","vi":"tối ưu hóa cấu trúc liên kết (topology)","level":3,"def_vi":"Phương pháp tính toán phân bố vật liệu tối ưu trong một vùng thiết kế để đạt độ cứng tối đa với khối lượng tối thiểu.","def_en":"A computational method that finds the best material layout in a design space for maximum stiffness at minimum mass.","def_ja":"設計領域内で、最小質量で最大剛性となる材料配置を計算で求める手法。","usage_en":"Danh từ không đếm được; Anh-Anh viết 'optimisation'. Hay đi với: run a topology optimization, design space, volume fraction target.","usage_ja":"Hay gặp: トポロジー最適化をかける, 設計空間, 体積制約. Thường đi kèm 積層造形 (in 3D kim loại).","context_vi":"Dùng trong hàng không, ô tô, giá đỡ in 3D kim loại khi cần giảm khối lượng mà vẫn đủ cứng.","ex_en":"Topology optimization reduced the bracket mass by 40 % without losing stiffness.","ex_ja":"トポロジー最適化により、剛性を落とさずにブラケットを40%軽量化できた。","ex_vi":"Tối ưu hóa topology đã giảm 40 % khối lượng giá đỡ mà không giảm độ cứng.","syn_en":["topology optimisation (Anh)","shape optimization (liên quan)"],"syn_ja":["位相最適化","形状最適化 (liên quan)"]},{"en":"modeling kernel","pos":"noun phrase","ipa":"/ˈmɑːdəlɪŋ ˈkɝːnəl/","ja":"モデリングカーネル","kana":"モデリングカーネル","romaji":"moderingukaaneru","vi":"lõi mô hình hình học (kernel)","level":3,"def_vi":"Thư viện phần mềm nền tảng tính toán hình học khối và mặt mà các phần mềm CAD xây dựng trên đó, như Parasolid, ACIS.","def_en":"The core geometry library, such as Parasolid or ACIS, on which CAD applications build their solid and surface operations.","def_ja":"ParasolidやACISなど、CADがソリッドや曲面演算に使う中核の形状ライブラリ。","usage_en":"Danh từ đếm được; còn gọi 'geometric modeling kernel'. Hay đi với: based on the Parasolid kernel, kernel compatibility.","usage_ja":"Hay nói CADカーネル, 形状カーネル; ví dụ: SolidWorksとNXは同じParasolidカーネル. Chủ yếu dùng trong giới IT-CAD.","context_vi":"Gặp khi chọn phần mềm CAD, xử lý lỗi chuyển đổi dữ liệu và chọn định dạng trao đổi như x_t, sat.","ex_en":"Both programs share the same modeling kernel, so Parasolid files open without errors.","ex_ja":"両ソフトは同じモデリングカーネルを使っているので、Parasolidファイルはエラーなく開ける。","ex_vi":"Hai phần mềm dùng chung lõi mô hình nên file Parasolid mở ra không bị lỗi.","syn_en":["geometric modeling kernel","CAD kernel"],"syn_ja":["CADカーネル","形状カーネル"]},{"en":"NURBS","pos":"abbreviation","ipa":"/nɝːbz/","ja":"NURBS","kana":"ナーブス","romaji":"naabusu","vi":"đường/mặt B-spline hữu tỉ không đều (NURBS)","level":3,"def_vi":"Mô hình toán học (non-uniform rational B-spline) dùng để biểu diễn chính xác đường cong và mặt cong tự do trong CAD.","def_en":"Non-uniform rational B-spline: a mathematical form used to represent freeform curves and surfaces exactly in CAD.","def_ja":"非一様有理Bスプライン。CADで自由曲線・自由曲面を正確に表す数式表現。","usage_en":"Đọc như một từ /nɝːbz/. Hay đi với: NURBS surface, NURBS curve, control points, degree; thường đối lập với mesh (lưới tam giác).","usage_ja":"Đọc ナーブス; hay gặp: NURBS曲面, 制御点, 次数. Phần mềm Rhino rất phổ biến với NURBS.","context_vi":"Gặp trong thiết kế bề mặt tự do, chuyển dữ liệu quét 3D (lưới) sang mô hình CAD và trong lý thuyết đồ họa.","ex_en":"The scanned mesh was converted into NURBS surfaces for the mold design.","ex_ja":"金型設計のため、スキャンしたメッシュをNURBS曲面に変換した。","ex_vi":"Lưới quét 3D đã được chuyển thành các mặt NURBS để thiết kế khuôn.","syn_en":["non-uniform rational B-spline","B-spline surface (nghĩa gần)"],"syn_ja":["非一様有理Bスプライン","自由曲面 (liên quan)"]},{"en":"top-down design","pos":"noun phrase","ipa":"/ˌtɑːp ˈdaʊn dɪˈzaɪn/","ja":"トップダウン設計","kana":"トップダウンせっけい","romaji":"toppudaunsekkei","vi":"thiết kế từ trên xuống","level":3,"def_vi":"Cách thiết kế bắt đầu từ bố trí tổng thể của cụm lắp, rồi tạo các chi tiết tham chiếu theo bố trí đó.","def_en":"A design approach that starts from the overall assembly layout and creates parts that reference it.","def_ja":"全体のレイアウトから始め、それを参照して各部品を作る設計手法。","usage_en":"Danh từ không đếm được; đối lập với 'bottom-up design'. Hay đi với: skeleton model, layout sketch, in-context parts.","usage_ja":"Hay gặp: トップダウン設計, スケルトンモデル, レイアウトスケッチ; đối lập: ボトムアップ設計.","context_vi":"Dùng cho máy chuyên dùng, dây chuyền, khung xe, nơi thay đổi kích thước tổng phải cập nhật nhiều chi tiết.","ex_en":"We used top-down design so that changing the frame width updates all the panels.","ex_ja":"フレーム幅を変えると全パネルが更新されるように、トップダウン設計にした。","ex_vi":"Chúng tôi dùng thiết kế từ trên xuống để khi đổi bề rộng khung thì mọi tấm vỏ tự cập nhật.","syn_en":["skeleton modeling","layout-driven design"],"syn_ja":["スケルトン設計","ボトムアップ設計 (đối nghĩa, liên quan)"]},{"en":"generative design","pos":"noun phrase","ipa":"/ˈdʒɛnərətɪv dɪˈzaɪn/","ja":"ジェネレーティブデザイン","kana":"ジェネレーティブデザイン","romaji":"jenereetibudezain","vi":"thiết kế tạo sinh","level":3,"def_vi":"Phương pháp phần mềm tự sinh ra nhiều phương án hình dạng từ tải trọng, ràng buộc, vật liệu và cách chế tạo do kỹ sư nhập.","def_en":"A method where software automatically generates many shape options from the loads, constraints, materials and processes entered.","def_ja":"荷重・拘束・材料・製法を入力し、ソフトが多数の形状案を自動生成する手法。","usage_en":"Danh từ không đếm được. Hay đi với: generative design study, generate outcomes; khác 'topology optimization' ở chỗ cho ra nhiều phương án.","usage_ja":"Hay viết ジェネレーティブデザイン; một số tài liệu dùng 生成的設計. Gặp nhiều trong Fusion 360, NX.","context_vi":"Dùng ở giai đoạn ý tưởng cho chi tiết nhẹ, đặc biệt khi chế tạo bằng in 3D hoặc đúc.","ex_en":"Generative design produced 25 options for the drone arm in one night.","ex_ja":"ジェネレーティブデザインで、ドローンのアーム案が一晩で25通り生成された。","ex_vi":"Thiết kế tạo sinh đã cho ra 25 phương án tay đỡ drone chỉ trong một đêm.","syn_en":["computational design (nghĩa rộng hơn)","topology optimization (liên quan)"],"syn_ja":["生成的設計","トポロジー最適化 (liên quan)"]},{"en":"reverse engineering","pos":"noun phrase","ipa":"/rɪˈvɝːs ˌɛndʒɪˈnɪrɪŋ/","ja":"リバースエンジニアリング","kana":"リバースエンジニアリング","romaji":"ribaasuenjiniaringu","vi":"thiết kế ngược","level":3,"def_vi":"Quá trình đo, quét 3D một chi tiết có sẵn rồi dựng lại mô hình CAD và bản vẽ của nó.","def_en":"Measuring or 3D-scanning an existing part and rebuilding its CAD model and drawings.","def_ja":"既存部品を測定・3Dスキャンし、CADモデルや図面を作り直すこと。","usage_en":"Danh từ không đếm được; động từ 'reverse-engineer'. Hay đi với: point cloud, 3D scanning, reverse engineering software.","usage_ja":"Hay gặp: リバースエンジニアリングする, 点群, 3Dスキャン; dân xưởng gọi tắt リバース.","context_vi":"Dùng khi làm lại phụ tùng không còn bản vẽ, sửa khuôn, kiểm tra chi tiết so với mô hình gốc.","ex_en":"We used reverse engineering to recreate the impeller because the original drawing was lost.","ex_ja":"元図面が紛失していたので、リバースエンジニアリングでインペラを作り直した。","ex_vi":"Chúng tôi dùng thiết kế ngược để làm lại cánh bơm vì bản vẽ gốc đã bị mất.","syn_en":["scan-to-CAD","back engineering (ít dùng)"],"syn_ja":["逆設計","リバース (khẩu ngữ)"]}]},{"id":18,"words":[{"en":"requirement","pos":"noun","ipa":"/rɪˈkwaɪərmənt/","ja":"要求事項","kana":"ようきゅうじこう","romaji":"youkyuujikou","vi":"yêu cầu (kỹ thuật)","level":1,"def_vi":"Điều mà sản phẩm bắt buộc phải đáp ứng, như tải trọng, kích thước, tuổi thọ, chi phí hay tiêu chuẩn.","def_en":"Something a product must satisfy, such as load, size, life, cost or a standard.","def_ja":"荷重・寸法・寿命・コスト・規格など、製品が満たさなければならない事柄。","usage_en":"Danh từ đếm được, thường số nhiều. Hay đi với: meet / satisfy / define requirements, customer requirements, functional requirement.","usage_ja":"Hay gặp: 要求事項を満たす, 顧客要求事項, 要求仕様書. Trong họp thường nói ngắn 要求 hoặc 要件.","context_vi":"Dùng ở đầu dự án khi thu thập và thống nhất yêu cầu với khách hàng, và khi kiểm tra thiết kế cuối cùng.","ex_en":"The pump must meet the requirement of 10,000 hours without maintenance.","ex_ja":"ポンプはメンテナンスなしで10,000時間という要求事項を満たさなければならない。","ex_vi":"Máy bơm phải đáp ứng yêu cầu chạy 10.000 giờ không cần bảo dưỡng.","syn_en":["spec (khẩu ngữ, nghĩa gần)","need (nghĩa rộng hơn)"],"syn_ja":["要求","要件"]},{"en":"customer needs","pos":"noun phrase","ipa":"/ˈkʌstəmər ˌniːdz/","ja":"顧客ニーズ","kana":"こきゃくニーズ","romaji":"kokyakuniizu","vi":"nhu cầu khách hàng","level":1,"def_vi":"Những mong muốn và vấn đề thực tế của người dùng mà sản phẩm mới cần giải quyết.","def_en":"The wants and real problems of users that a new product should address.","def_ja":"新製品が解決すべき、使用者の要望や実際の困りごと。","usage_en":"Thường dùng số nhiều. Hay đi với: identify / understand / capture customer needs, voice of the customer (VOC).","usage_ja":"Hay gặp: 顧客ニーズを把握する, ニーズ調査; trong họp nói ngắn ニーズ hoặc お客様の声.","context_vi":"Dùng trong khảo sát thị trường, lập kế hoạch sản phẩm và khi chuyển nhu cầu thành thông số kỹ thuật.","ex_en":"Interviews with operators helped us understand the customer needs for faster cleaning.","ex_ja":"作業者へのインタビューで、清掃を早くしたいという顧客ニーズが分かった。","ex_vi":"Phỏng vấn công nhân vận hành giúp chúng tôi hiểu nhu cầu khách hàng muốn vệ sinh nhanh hơn.","syn_en":["voice of the customer (VOC)","user needs"],"syn_ja":["ニーズ","お客様の声 (VOC)"]},{"en":"concept design","pos":"noun phrase","ipa":"/ˈkɑːnsɛpt dɪˈzaɪn/","ja":"構想設計","kana":"こうそうせっけい","romaji":"kousousekkei","vi":"thiết kế ý tưởng (thiết kế sơ bộ)","level":1,"def_vi":"Giai đoạn đầu của thiết kế, đưa ra và so sánh các phương án nguyên lý, bố trí tổng thể trước khi đi vào chi tiết.","def_en":"The early design stage where alternative working principles and layouts are proposed and compared before detailing.","def_ja":"詳細に入る前に、原理や全体配置の案を出して比較する設計の初期段階。","usage_en":"Danh từ (đếm được khi chỉ một phương án). Hay đi với: concept design phase, develop / select a concept; còn gọi 'conceptual design'.","usage_ja":"Rất phổ biến trong công ty Nhật: 構想設計→基本設計→詳細設計. Hay nói 構想を練る, 構想図.","context_vi":"Dùng khi thiết kế máy chuyên dùng, đồ gá, sản phẩm mới, thường kèm bản vẽ bố trí và tính toán sơ bộ.","ex_en":"We presented three layouts in the concept design review.","ex_ja":"構想設計のレビューで3つのレイアウト案を説明した。","ex_vi":"Chúng tôi đã trình bày ba phương án bố trí trong buổi xem xét thiết kế ý tưởng.","syn_en":["conceptual design","concept development"],"syn_ja":["概念設計","構想 (khẩu ngữ)"]},{"en":"brainstorming","pos":"noun","ipa":"/ˈbreɪnˌstɔːrmɪŋ/","ja":"ブレインストーミング","kana":"ブレインストーミング","romaji":"bureinsutoomingu","vi":"động não (brainstorming)","level":1,"def_vi":"Phương pháp làm việc nhóm, mọi người đưa ra thật nhiều ý tưởng tự do, chưa phê phán, rồi mới chọn lọc.","def_en":"A group method in which people freely generate many ideas without criticism before selecting the best ones.","def_ja":"批判せずに自由に多くのアイデアを出し合い、その後に絞り込む集団発想法。","usage_en":"Danh từ không đếm được; động từ 'brainstorm'. Hay đi với: brainstorming session, hold a brainstorming, brainstorm ideas.","usage_ja":"Ngoài công ty hay nói tắt ブレスト: ブレストする, ブレストをやる. Thường đi kèm KJ法 để phân nhóm ý tưởng.","context_vi":"Dùng ở giai đoạn ý tưởng, cải tiến (kaizen) và khi tìm nguyên nhân hoặc giải pháp cho vấn đề.","ex_en":"The brainstorming produced over forty ideas for reducing assembly time.","ex_ja":"ブレインストーミングで、組立時間短縮のアイデアが40以上出た。","ex_vi":"Buổi động não đã đưa ra hơn bốn mươi ý tưởng giảm thời gian lắp ráp.","syn_en":["ideation","brainstorm session"],"syn_ja":["ブレスト (khẩu ngữ)","アイデア出し"]},{"en":"prototype","pos":"noun","ipa":"/ˈproʊtətaɪp/","ja":"試作品","kana":"しさくひん","romaji":"shisakuhin","vi":"mẫu thử","level":1,"def_vi":"Sản phẩm được chế tạo thử trước khi sản xuất hàng loạt để kiểm tra chức năng, lắp ráp và tính năng.","def_en":"An early version of a product built before mass production to check function, fit and performance.","def_ja":"量産前に機能・組付け・性能を確認するために作る製品。","usage_en":"Danh từ đếm được; động từ 'prototype' (làm mẫu). Hay đi với: build / test a prototype, first prototype, prototype parts.","usage_ja":"Hay gặp: 試作する, 試作品を作る, 1次試作, 試作部品. Cách nói ngắn: 試作 hoặc プロト.","context_vi":"Dùng ở giai đoạn phát triển, đặt gia công mẫu, in 3D, thử nghiệm trước khi làm khuôn.","ex_en":"The first prototype showed that the latch was too stiff to open by hand.","ex_ja":"最初の試作品で、ラッチが固すぎて手で開けられないことが分かった。","ex_vi":"Mẫu thử đầu tiên cho thấy chốt khóa quá cứng, không thể mở bằng tay.","syn_en":["proto (khẩu ngữ)","trial sample"],"syn_ja":["試作","プロトタイプ"]},{"en":"mock-up","pos":"noun","ipa":"/ˈmɑːk ʌp/","ja":"モックアップ","kana":"モックアップ","romaji":"mokkuappu","vi":"mô hình mẫu (mock-up)","level":1,"def_vi":"Mô hình kích thước thật hoặc tỷ lệ, thường bằng xốp, gỗ, nhựa, dùng để xem hình dáng, kích thước, thao tác, không có chức năng.","def_en":"A full-size or scale model, often of foam, wood or plastic, used to check shape and handling but not function.","def_ja":"形状・大きさ・操作性を確認するための、機能を持たない実物大または縮尺模型。","usage_en":"Danh từ đếm được, còn viết 'mockup'. Hay đi với: build a mock-up, foam mock-up, full-scale mock-up.","usage_ja":"Hay nói モック, 外観モック, モックを作る. Khác với 試作品 vì không có chức năng.","context_vi":"Dùng trong thiết kế công nghiệp, kiểm tra công thái học, trưng bày cho khách hàng duyệt kiểu dáng.","ex_en":"A foam mock-up of the control panel was used to check operator reach.","ex_ja":"作業者の手の届く範囲を確認するため、操作盤の発泡モックアップを使った。","ex_vi":"Một mô hình mẫu bằng xốp của bảng điều khiển được dùng để kiểm tra tầm với của người vận hành.","syn_en":["mockup","dummy model (nghĩa gần)"],"syn_ja":["モック (khẩu ngữ)","外観モデル"]},{"en":"basic design","pos":"noun phrase","ipa":"/ˈbeɪsɪk dɪˈzaɪn/","ja":"基本設計","kana":"きほんせっけい","romaji":"kihonsekkei","vi":"thiết kế cơ sở","level":1,"def_vi":"Giai đoạn xác định cấu trúc, thông số chính, bố trí và lựa chọn bộ phận chủ yếu của sản phẩm.","def_en":"The stage that fixes the main structure, key parameters, layout and major components of a product.","def_ja":"製品の主要構造・主要諸元・配置・主要部品を決める段階。","usage_en":"Danh từ không đếm được. Trong công nghiệp dầu khí và nhà máy còn gọi 'FEED' hoặc 'front-end design'; hay đi với: basic design package, basic design phase.","usage_ja":"Hay gặp: 基本設計書, 基本設計審査. Thứ tự quen thuộc: 構想設計→基本設計→詳細設計.","context_vi":"Dùng trong dự án máy, nhà máy, tàu thủy; kết quả là bản vẽ bố trí chung và thông số chính để duyệt.","ex_en":"Basic design must be approved before we start the detailed drawings.","ex_ja":"詳細図面に入る前に、基本設計の承認を得なければならない。","ex_vi":"Thiết kế cơ sở phải được phê duyệt trước khi chúng tôi bắt đầu bản vẽ chi tiết.","syn_en":["preliminary design","FEED (front-end engineering design)"],"syn_ja":["基本計画 (nghĩa gần)","概略設計"]},{"en":"detailed design","pos":"noun phrase","ipa":"/ˈdiːteɪld dɪˈzaɪn/","ja":"詳細設計","kana":"しょうさいせっけい","romaji":"shousaisekkei","vi":"thiết kế chi tiết","level":1,"def_vi":"Giai đoạn hoàn thiện mọi kích thước, dung sai, vật liệu, bản vẽ chế tạo và danh mục vật tư để có thể sản xuất.","def_en":"The stage that completes all dimensions, tolerances, materials, manufacturing drawings and parts lists for production.","def_ja":"寸法・公差・材料・製作図・部品表をすべて決め、製作可能にする段階。","usage_en":"Danh từ không đếm được. Hay đi với: detailed design phase, complete the detailed design, detail drawings.","usage_ja":"Hay gặp: 詳細設計に入る, 詳細設計図, 詳細設計者. Kết quả chính là 部品図 và 組立図.","context_vi":"Dùng khi lập bản vẽ chế tạo, chọn chi tiết tiêu chuẩn và chuẩn bị hồ sơ để đặt hàng gia công.","ex_en":"Detailed design of the gearbox will take about six weeks.","ex_ja":"ギヤボックスの詳細設計には約6週間かかる見込みだ。","ex_vi":"Thiết kế chi tiết hộp số sẽ mất khoảng sáu tuần.","syn_en":["detail design","embodiment design (nghĩa gần)"],"syn_ja":["詳細 (khẩu ngữ)","実施設計"]},{"en":"ergonomics","pos":"noun","ipa":"/ˌɝːɡəˈnɑːmɪks/","ja":"人間工学","kana":"にんげんこうがく","romaji":"ningenkougaku","vi":"công thái học (ecgônômi)","level":1,"def_vi":"Khoa học thiết kế sản phẩm, máy và chỗ làm việc phù hợp với kích thước, sức lực và khả năng của con người.","def_en":"The science of designing products, machines and workplaces to fit human size, strength and abilities.","def_ja":"人の体格・力・能力に合うように製品・機械・作業場を設計するための学問。","usage_en":"Danh từ không đếm được, động từ đi số ít ('ergonomics is...'); tính từ 'ergonomic'. Hay đi với: ergonomic design, ergonomic handle, poor ergonomics.","usage_ja":"Hay gặp: 人間工学に基づく設計, 人間工学的, 作業姿勢; khẩu ngữ dùng エルゴノミクス.","context_vi":"Dùng khi thiết kế tay cầm, bảng điều khiển, chiều cao bàn lắp ráp, trạm làm việc trong nhà máy.","ex_en":"Good ergonomics reduced the operator's bending when loading parts into the fixture.","ex_ja":"人間工学を考慮した設計で、治具に部品を置く際の前かがみ姿勢が減った。","ex_vi":"Thiết kế công thái học tốt đã giảm việc người thợ phải cúi khi đặt chi tiết vào đồ gá.","syn_en":["human factors engineering","ergonomic design"],"syn_ja":["エルゴノミクス","ヒューマンファクター (nghĩa gần)"]},{"en":"design change","pos":"noun phrase","ipa":"/dɪˈzaɪn ˌtʃeɪndʒ/","ja":"設計変更","kana":"せっけいへんこう","romaji":"sekkeihenkou","vi":"thay đổi thiết kế","level":1,"def_vi":"Việc sửa đổi thiết kế đã phát hành như kích thước, vật liệu, hình dạng, phải được xem xét và phê duyệt.","def_en":"A modification to a released design, such as dimensions, material or shape, which must be reviewed and approved.","def_ja":"出図済みの寸法・材料・形状などを変更すること。審査と承認が必要。","usage_en":"Danh từ đếm được. Hay đi với: make / request / approve a design change, late design change; văn bản chính thức là ECN/ECO.","usage_ja":"Ngoài xưởng nói tắt 設変 (せっぺん): 設変が入る, 設変依頼. Văn bản: 設計変更通知書.","context_vi":"Dùng khi khách hàng đổi yêu cầu, khi phát hiện lỗi thiết kế, hoặc để giảm giá thành sản phẩm.","ex_en":"A late design change to the housing delayed the tooling by two weeks.","ex_ja":"ハウジングの遅い設計変更で、金型が2週間遅れた。","ex_vi":"Một thay đổi thiết kế muộn ở vỏ hộp đã làm chậm khuôn hai tuần.","syn_en":["engineering change","modification (nghĩa rộng hơn)"],"syn_ja":["設変 (khẩu ngữ)","仕様変更 (nghĩa gần)"]},{"en":"product planning","pos":"noun phrase","ipa":"/ˈprɑːdʌkt ˈplænɪŋ/","ja":"商品企画","kana":"しょうひんきかく","romaji":"shouhinkikaku","vi":"hoạch định sản phẩm","level":2,"def_vi":"Hoạt động xác định sản phẩm mới sẽ bán cho ai, có tính năng gì, giá bao nhiêu và ra mắt khi nào.","def_en":"Deciding who a new product is for, what features it has, its price and when it launches.","def_ja":"新製品の対象顧客・機能・価格・発売時期を決める活動。","usage_en":"Danh từ không đếm được. Hay đi với: product planning department, product planning stage; người phụ trách: product manager.","usage_ja":"Hay gặp: 商品企画部, 商品企画書, 企画段階. Với hàng công nghiệp cũng dùng 製品企画.","context_vi":"Dùng ở đầu chu kỳ phát triển, trước khi phòng thiết kế nhận yêu cầu và bắt đầu thiết kế ý tưởng.","ex_en":"Product planning set a target price of 300 dollars for the new drill.","ex_ja":"商品企画では、新しいドリルの目標価格を300ドルとした。","ex_vi":"Bộ phận hoạch định sản phẩm đặt mức giá mục tiêu 300 đô la cho máy khoan mới.","syn_en":["product definition","product management (nghĩa gần)"],"syn_ja":["製品企画","企画 (khẩu ngữ)"]},{"en":"design review","pos":"noun phrase","ipa":"/dɪˈzaɪn rɪˌvjuː/","ja":"デザインレビュー","kana":"デザインレビュー","romaji":"dezainrebyuu","vi":"xem xét thiết kế (design review)","level":2,"def_vi":"Cuộc họp chính thức, có nhiều bộ phận tham gia, để đánh giá thiết kế ở các mốc và quyết định có được đi tiếp không.","def_en":"A formal meeting where several departments evaluate a design at key milestones and decide whether it can proceed.","def_ja":"節目ごとに関係部署が設計を評価し、次に進めるかを判断する公式な会議。","usage_en":"Danh từ đếm được, viết tắt DR. Hay đi với: hold / pass a design review, preliminary / critical design review (PDR / CDR).","usage_ja":"Trong công ty Nhật nói DR (ディーアール): DRを実施する, DR1, DR2, DR指摘事項. Từ Hán: 設計審査.","context_vi":"Dùng ở các mốc dự án, có đại diện thiết kế, sản xuất, chất lượng, mua hàng tham gia.","ex_en":"Production engineering raised five issues at the design review.","ex_ja":"デザインレビューで、生産技術から5件の指摘が出た。","ex_vi":"Bộ phận kỹ thuật sản xuất đã nêu năm vấn đề trong buổi xem xét thiết kế.","syn_en":["DR","design audit (nghĩa gần)"],"syn_ja":["DR","設計審査"]},{"en":"feasibility study","pos":"noun phrase","ipa":"/ˌfiːzəˈbɪləti ˌstʌdi/","ja":"フィジビリティスタディ","kana":"フィジビリティスタディ","romaji":"fijibiritisutadi","vi":"nghiên cứu khả thi","level":2,"def_vi":"Phân tích sớm để xác định ý tưởng hoặc dự án có thực hiện được về kỹ thuật, chi phí và thời gian hay không.","def_en":"An early analysis of whether an idea or project is technically, financially and schedule-wise achievable.","def_ja":"アイデアや計画が技術・費用・日程の面で実現可能かを初期に検討すること。","usage_en":"Danh từ đếm được. Hay đi với: carry out / conduct a feasibility study, technical feasibility.","usage_ja":"Hay nói tắt FS; tiếng Nhật thuần: 実現可能性検討, 事前検討. Động từ: FSを行う.","context_vi":"Dùng trước khi quyết định đầu tư dự án, nhận đơn hàng khó hoặc áp dụng công nghệ mới.","ex_en":"A feasibility study showed that the part could be made by die casting.","ex_ja":"フィジビリティスタディの結果、その部品はダイカストで製作できると分かった。","ex_vi":"Nghiên cứu khả thi cho thấy chi tiết có thể chế tạo bằng đúc áp lực.","syn_en":["feasibility assessment","pre-study"],"syn_ja":["FS","実現可能性検討"]},{"en":"design intent","pos":"noun phrase","ipa":"/dɪˈzaɪn ɪnˌtɛnt/","ja":"設計意図","kana":"せっけいいと","romaji":"sekkeiito","vi":"ý đồ thiết kế","level":2,"def_vi":"Lý do và mục đích đằng sau mỗi quyết định thiết kế, như vì sao chọn kích thước, dung sai hay vật liệu đó.","def_en":"The purpose and reasoning behind design decisions, such as why a dimension, tolerance or material was chosen.","def_ja":"寸法・公差・材料などをなぜそう決めたかという設計上の目的と理由。","usage_en":"Danh từ không đếm được. Hay đi với: capture / communicate / preserve the design intent; 'this violates the design intent'.","usage_ja":"Hay nói 設計意図を伝える, 設計意図が分からない, 設計意図を図面に盛り込む.","context_vi":"Dùng khi giải thích thiết kế cho nhà cung cấp, sản xuất, hoặc khi dựng mô hình CAD có tham số hợp lý.","ex_en":"Explain the design intent of this tolerance before the supplier asks to relax it.","ex_ja":"サプライヤに緩和を求められる前に、この公差の設計意図を説明しておくこと。","ex_vi":"Hãy giải thích ý đồ thiết kế của dung sai này trước khi nhà cung cấp đề nghị nới lỏng.","syn_en":["design rationale","design purpose"],"syn_ja":["設計思想 (nghĩa rộng hơn)","設計の狙い"]},{"en":"trade-off","pos":"noun","ipa":"/ˈtreɪd ɔːf/","ja":"トレードオフ","kana":"トレードオフ","romaji":"toreedoofu","vi":"sự đánh đổi","level":2,"def_vi":"Tình huống phải hy sinh một tính chất để cải thiện tính chất khác, như độ cứng và khối lượng.","def_en":"A situation where improving one property means sacrificing another, such as stiffness versus weight.","def_ja":"剛性と重量のように、一方を良くすると他方が悪くなる関係。","usage_en":"Danh từ đếm được; động từ cụm 'trade off A against B'. Hay đi với: a trade-off between cost and performance, make a trade-off.","usage_ja":"Hay gặp: トレードオフの関係にある, トレードオフを考慮する; tiếng Nhật thuần: 二律背反.","context_vi":"Dùng khi so sánh phương án thiết kế, chọn vật liệu, cân bằng chi phí và tính năng.","ex_en":"There is a trade-off between wall thickness and cycle time in this molded part.","ex_ja":"この成形品では、肉厚とサイクルタイムがトレードオフの関係にある。","ex_vi":"Ở chi tiết ép này có sự đánh đổi giữa chiều dày thành và thời gian chu kỳ.","syn_en":["compromise","balance (nghĩa gần)"],"syn_ja":["二律背反","兼ね合い (khẩu ngữ)"]},{"en":"design freeze","pos":"noun phrase","ipa":"/dɪˈzaɪn ˌfriːz/","ja":"設計凍結","kana":"せっけいとうけつ","romaji":"sekkeitouketsu","vi":"chốt thiết kế (đóng băng thiết kế)","level":2,"def_vi":"Mốc sau đó thiết kế không được thay đổi nữa, trừ khi qua thủ tục thay đổi chính thức, để bắt đầu làm khuôn, đặt hàng.","def_en":"The milestone after which the design may not change except through formal change control, so tooling can start.","def_ja":"正式な変更手続き以外は設計を変えない節目。以降、金型手配などを開始する。","usage_en":"Danh từ đếm được. Hay đi với: reach / announce design freeze, after design freeze; động từ: freeze the design.","usage_ja":"Hay gặp: 設計凍結, 図面凍結, 仕様凍結; ngoài xưởng nói フリーズ: 図面をフリーズする.","context_vi":"Dùng trong lịch dự án ô tô, điện tử, nơi khuôn đắt tiền chỉ được làm sau khi chốt thiết kế.","ex_en":"Any change after design freeze needs approval from the chief engineer.","ex_ja":"設計凍結後の変更には、チーフエンジニアの承認が必要だ。","ex_vi":"Mọi thay đổi sau khi chốt thiết kế đều cần kỹ sư trưởng phê duyệt.","syn_en":["design lock","drawing freeze"],"syn_ja":["図面凍結","仕様凍結 (nghĩa gần)"]},{"en":"design for manufacturing","pos":"noun phrase","ipa":"/dɪˈzaɪn fər ˌmænjəˈfæktʃərɪŋ/","ja":"製造容易性設計","kana":"せいぞうよういせいせっけい","romaji":"seizouyouiseisekkei","vi":"thiết kế hướng đến khả năng chế tạo (DFM)","level":2,"def_vi":"Cách thiết kế chi tiết sao cho dễ chế tạo, ít công đoạn, ít phế phẩm và giá thành thấp.","def_en":"Designing parts so they are easy and cheap to make, with fewer operations and less scrap.","def_ja":"工程が少なく、不良が出にくく、安く作れるように部品を設計すること。","usage_en":"Thường viết tắt DFM; Anh-Anh dùng 'design for manufacture'. Hay đi với: DFM review, DFM guidelines; hay đi cặp với DFA (design for assembly).","usage_ja":"Công ty Nhật thường nói thẳng DFM hoặc 作りやすさを考えた設計; ngành đóng tàu dùng 生産設計.","context_vi":"Dùng khi xem xét bản vẽ với xưởng gia công, nhà cung cấp khuôn, đúc, ép nhựa trước khi chốt thiết kế.","ex_en":"Design for manufacturing removed two machining setups from the housing.","ex_ja":"製造容易性設計により、ハウジングの加工段取りを2つ削減できた。","ex_vi":"Thiết kế hướng đến khả năng chế tạo đã bỏ được hai lần gá gia công trên vỏ hộp.","syn_en":["DFM","design for manufacture (Anh)","DFMA (bao gồm lắp ráp)"],"syn_ja":["DFM","生産設計 (nghĩa gần)"]},{"en":"modular design","pos":"noun phrase","ipa":"/ˈmɑːdʒələr dɪˈzaɪn/","ja":"モジュール設計","kana":"モジュールせっけい","romaji":"mojuurusekkei","vi":"thiết kế mô-đun","level":2,"def_vi":"Cách chia sản phẩm thành các khối chức năng độc lập, có giao diện chuẩn, để dễ kết hợp, thay thế và tái sử dụng.","def_en":"Dividing a product into independent functional units with standard interfaces so they can be combined and reused.","def_ja":"製品を標準インタフェースを持つ独立した機能単位に分け、組合せや流用をしやすくする設計。","usage_en":"Danh từ không đếm được. Hay đi với: modular design approach, module, standard interface, modularity.","usage_ja":"Hay gặp: モジュール化, モジュール設計, ユニット化 (cách nói hay dùng trong xưởng Nhật).","context_vi":"Dùng cho máy đóng gói, băng tải, máy CNC, ô tô, nơi có nhiều biến thể sản phẩm dùng chung bộ phận.","ex_en":"Thanks to modular design, the conveyor can be extended in 1 m sections.","ex_ja":"モジュール設計のおかげで、コンベヤを1m単位で延長できる。","ex_vi":"Nhờ thiết kế mô-đun, băng tải có thể kéo dài theo từng đoạn 1 m.","syn_en":["modularization","modular architecture"],"syn_ja":["モジュール化","ユニット化 (khẩu ngữ)"]},{"en":"benchmarking","pos":"noun","ipa":"/ˈbɛntʃmɑːrkɪŋ/","ja":"ベンチマーキング","kana":"ベンチマーキング","romaji":"benchimaakingu","vi":"so sánh đối chuẩn (benchmarking)","level":2,"def_vi":"Việc so sánh sản phẩm, tính năng hoặc giá thành của mình với đối thủ hoặc sản phẩm tốt nhất để đặt mục tiêu.","def_en":"Comparing your product's performance or cost with competitors or best-in-class products to set targets.","def_ja":"自社製品の性能やコストを競合品や最高水準の製品と比較し、目標を決めること。","usage_en":"Danh từ không đếm được; động từ 'benchmark'. Hay đi với: competitive benchmarking, benchmark against, best-in-class.","usage_ja":"Hay nói ベンチマーク: 競合品をベンチマークする, ベンチマーク対象.","context_vi":"Dùng ở giai đoạn hoạch định sản phẩm và đặt mục tiêu chi phí, tính năng cho thiết kế mới.","ex_en":"Benchmarking against three rival compressors set our noise target at 62 dB.","ex_ja":"競合3社の圧縮機とのベンチマーキングにより、騒音目標を62dBとした。","ex_vi":"So sánh đối chuẩn với ba máy nén của đối thủ giúp đặt mục tiêu độ ồn 62 dB.","syn_en":["competitive analysis","benchmark study"],"syn_ja":["ベンチマーク","競合品比較"]},{"en":"teardown","pos":"noun","ipa":"/ˈtɛrdaʊn/","ja":"分解調査","kana":"ぶんかいちょうさ","romaji":"bunkaichousa","vi":"tháo rời phân tích (teardown)","level":2,"def_vi":"Việc tháo rời hoàn toàn sản phẩm của đối thủ hoặc của mình để phân tích cấu tạo, vật liệu, cách chế tạo và chi phí.","def_en":"Fully disassembling a competitor's or your own product to analyse its structure, materials, processes and cost.","def_ja":"競合品や自社品を完全に分解し、構造・材料・製法・コストを調べること。","usage_en":"Danh từ đếm được; động từ cụm 'tear down'. Hay đi với: competitor teardown, teardown analysis, teardown report.","usage_ja":"Còn gọi ティアダウン; ngành ô tô Nhật nói 他社車分解, 分解調査報告書.","context_vi":"Dùng trong ngành ô tô, điện tử để học hỏi đối thủ, ước tính giá thành và tìm ý tưởng giảm chi phí.","ex_en":"The teardown revealed that the rival motor uses a plastic end cover.","ex_ja":"分解調査で、競合品のモータが樹脂製のエンドカバーを使っていることが分かった。","ex_vi":"Việc tháo rời phân tích cho thấy động cơ của đối thủ dùng nắp đầu bằng nhựa.","syn_en":["teardown analysis","product dissection"],"syn_ja":["ティアダウン","分解分析"]},{"en":"pilot run","pos":"noun phrase","ipa":"/ˈpaɪlət ˌrʌn/","ja":"量産試作","kana":"りょうさんしさく","romaji":"ryousanshisaku","vi":"chạy thử sản xuất (pilot run)","level":2,"def_vi":"Đợt sản xuất số lượng nhỏ trên dây chuyền, khuôn, đồ gá thật để xác nhận quy trình trước khi sản xuất hàng loạt.","def_en":"A small production batch made on the real line, tooling and fixtures to confirm the process before mass production.","def_ja":"量産と同じライン・型・治具で少量生産し、量産前に工程を確認すること。","usage_en":"Danh từ đếm được. Hay đi với: carry out a pilot run, pilot-run parts, pilot production; ô tô hay gọi 'pre-production build'.","usage_ja":"Hay gặp: 量産試作, 量試 (khẩu ngữ), 号試 (Toyota). Khác với 試作 ở chỗ dùng khuôn và dây chuyền thật.","context_vi":"Dùng ở giai đoạn chuyển giao sang sản xuất, kết hợp với phê duyệt chi tiết sản xuất (PPAP) của khách hàng.","ex_en":"The pilot run of 200 units found a torque problem at station 4.","ex_ja":"200台の量産試作で、4番工程の締付トルク不具合が見つかった。","ex_vi":"Đợt chạy thử sản xuất 200 chiếc đã phát hiện lỗi mô-men siết ở trạm 4.","syn_en":["pilot production","pre-production build"],"syn_ja":["量試 (khẩu ngữ)","パイロットラン"]},{"en":"start of production","pos":"noun phrase","ipa":"/ˌstɑːrt əv prəˈdʌkʃən/","ja":"量産開始","kana":"りょうさんかいし","romaji":"ryousankaishi","vi":"thời điểm bắt đầu sản xuất hàng loạt (SOP)","level":2,"def_vi":"Mốc ngày chính thức bắt đầu sản xuất hàng loạt sản phẩm mới để giao cho khách hàng.","def_en":"The official date when mass production of a new product begins for delivery to customers.","def_ja":"新製品の顧客向け量産を正式に始める日程上の節目。","usage_en":"Viết tắt SOP (đọc từng chữ); dễ nhầm với SOP = standard operating procedure. Hay đi với: SOP date, before SOP, ramp-up after SOP.","usage_ja":"Hay gặp: 量産開始日, 量産立ち上げ, SOP; Toyota và các nhà cung cấp gọi 号口 (ごうぐち).","context_vi":"Dùng trong lịch dự án ô tô, điện tử, là mốc cuối mà mọi khuôn, đồ gá, phê duyệt phải hoàn thành.","ex_en":"Start of production is fixed for 1 March, so tooling must be approved by January.","ex_ja":"量産開始は3月1日に決まっているので、金型は1月までに承認を得る必要がある。","ex_vi":"Thời điểm bắt đầu sản xuất hàng loạt đã chốt là 1 tháng 3, nên khuôn phải được duyệt trước tháng 1.","syn_en":["SOP","production launch"],"syn_ja":["SOP","号口 (khẩu ngữ ngành ô tô)"]},{"en":"target cost","pos":"noun phrase","ipa":"/ˈtɑːrɡɪt ˌkɔːst/","ja":"目標原価","kana":"もくひょうげんか","romaji":"mokuhyougenka","vi":"giá thành mục tiêu","level":2,"def_vi":"Mức giá thành sản xuất tối đa được phép, tính từ giá bán dự kiến trừ lợi nhuận mong muốn, làm mục tiêu cho thiết kế.","def_en":"The maximum allowed manufacturing cost, derived from planned selling price minus desired profit, set as a design goal.","def_ja":"予定売価から目標利益を引いて決める、設計目標としての許容製造原価。","usage_en":"Danh từ đếm được. Hay đi với: meet / exceed the target cost, target costing (phương pháp), cost target.","usage_ja":"Hay gặp: 目標原価を達成する, 原価企画 (phương pháp target costing, xuất phát từ Nhật), 原価低減.","context_vi":"Dùng trong hoạch định sản phẩm, xem xét thiết kế và đàm phán giá với nhà cung cấp.","ex_en":"The current design is 8 % above the target cost, so we must simplify the frame.","ex_ja":"現行設計は目標原価を8%上回っているので、フレームを簡素化する必要がある。","ex_vi":"Thiết kế hiện tại vượt giá thành mục tiêu 8 % nên chúng tôi phải đơn giản hóa khung.","syn_en":["cost target","target costing (liên quan)"],"syn_ja":["原価企画 (liên quan)","目標コスト"]},{"en":"time to market","pos":"noun phrase","ipa":"/ˌtaɪm tə ˈmɑːrkɪt/","ja":"開発リードタイム","kana":"かいはつリードタイム","romaji":"kaihatsuriidotaimu","vi":"thời gian đưa sản phẩm ra thị trường","level":2,"def_vi":"Khoảng thời gian từ khi bắt đầu phát triển sản phẩm đến khi sản phẩm được bán ra thị trường.","def_en":"The time from the start of product development until the product is available for sale.","def_ja":"製品開発の開始から市場で販売されるまでの期間。","usage_en":"Danh từ không đếm được, thường viết 'time-to-market' khi làm tính từ. Hay đi với: shorten / reduce time to market.","usage_ja":"Công ty Nhật hay nói 開発リードタイムを短縮する, 開発期間; khi dịch sát dùng タイムトゥマーケット.","context_vi":"Dùng khi bàn về chiến lược phát triển, kỹ thuật đồng thời, mô phỏng thay thử nghiệm để rút ngắn dự án.","ex_en":"Using simulation instead of physical tests cut our time to market by four months.","ex_ja":"実機試験をシミュレーションに置き換えて、開発リードタイムを4か月短縮した。","ex_vi":"Dùng mô phỏng thay cho thử nghiệm thực đã rút ngắn thời gian ra thị trường bốn tháng.","syn_en":["development lead time","development cycle time"],"syn_ja":["開発期間","タイムトゥマーケット"]},{"en":"concurrent engineering","pos":"noun phrase","ipa":"/kənˈkɝːənt ˌɛndʒɪˈnɪrɪŋ/","ja":"コンカレントエンジニアリング","kana":"コンカレントエンジニアリング","romaji":"konkarentoenjiniaringu","vi":"kỹ thuật đồng thời","level":3,"def_vi":"Cách tổ chức phát triển sản phẩm cho thiết kế, công nghệ, sản xuất, mua hàng làm song song thay vì nối tiếp.","def_en":"Organizing product development so design, process, production and purchasing work in parallel rather than in sequence.","def_ja":"設計・生産技術・製造・購買などを順番ではなく並行して進める開発の進め方。","usage_en":"Danh từ không đếm được, viết tắt CE. Hay đi với: apply concurrent engineering, cross-functional team; còn gọi 'simultaneous engineering' (SE).","usage_ja":"Hay gặp: コンカレントエンジニアリング, サイマルテニアスエンジニアリング (SE), 同時並行開発.","context_vi":"Dùng trong ngành ô tô, hàng không, điện tử để rút ngắn thời gian phát triển và giảm thay đổi muộn.","ex_en":"With concurrent engineering, mold design started while the part was still being tested.","ex_ja":"コンカレントエンジニアリングにより、部品の評価中に金型設計を開始した。","ex_vi":"Nhờ kỹ thuật đồng thời, việc thiết kế khuôn đã bắt đầu ngay khi chi tiết còn đang thử nghiệm.","syn_en":["simultaneous engineering","CE"],"syn_ja":["サイマルテニアスエンジニアリング","同時並行開発"]},{"en":"quality function deployment","pos":"noun phrase","ipa":"/ˈkwɑːləti ˈfʌŋkʃən dɪˈplɔɪmənt/","ja":"品質機能展開","kana":"ひんしつきのうてんかい","romaji":"hinshitsukinoutenkai","vi":"triển khai chức năng chất lượng (QFD)","level":3,"def_vi":"Phương pháp dùng ma trận ('ngôi nhà chất lượng') chuyển nhu cầu khách hàng thành đặc tính kỹ thuật cụ thể.","def_en":"A matrix-based method (the 'house of quality') that translates customer needs into engineering characteristics.","def_ja":"品質表を用いて顧客の要求を技術特性に変換していく手法。","usage_en":"Viết tắt QFD. Hay đi với: house of quality, QFD matrix, build a QFD; phương pháp do Akao Yoji (Nhật) phát triển.","usage_ja":"Hay gặp: QFD, 品質表 (house of quality), 要求品質展開表. Là phương pháp gốc Nhật, rất phổ biến trong 品質工学.","context_vi":"Dùng ở giai đoạn hoạch định và thiết kế ý tưởng, nhất là trong ô tô, điện tử, sản phẩm tiêu dùng.","ex_en":"Quality function deployment linked 'easy to clean' to a minimum corner radius of 5 mm.","ex_ja":"品質機能展開により、「清掃しやすい」を最小コーナR5mmという特性に結び付けた。","ex_vi":"Triển khai chức năng chất lượng đã chuyển yêu cầu 'dễ vệ sinh' thành bán kính góc tối thiểu 5 mm.","syn_en":["QFD","house of quality (công cụ chính)"],"syn_ja":["QFD","品質表 (liên quan)"]},{"en":"stage-gate process","pos":"noun phrase","ipa":"/ˈsteɪdʒ ˌɡeɪt ˈprɑːsɛs/","ja":"ステージゲート法","kana":"ステージゲートほう","romaji":"suteejigeetohou","vi":"quy trình giai đoạn - cổng (stage-gate)","level":3,"def_vi":"Mô hình quản lý phát triển sản phẩm chia thành các giai đoạn, giữa mỗi giai đoạn có 'cổng' để quyết định tiếp tục hay dừng.","def_en":"A development model split into stages separated by decision 'gates' where the project is continued or stopped.","def_ja":"開発を段階に分け、各段階の間の関門で継続か中止かを判断するモデル。","usage_en":"Danh từ đếm được. Hay đi với: pass a gate, gate review, go / kill decision, phase-gate process.","usage_ja":"Hay gặp: ステージゲート法, ゲート審査, ゲートを通過する; cũng gọi フェーズゲート.","context_vi":"Dùng ở công ty lớn để quản lý danh mục dự án phát triển sản phẩm và phân bổ ngân sách.","ex_en":"Under our stage-gate process, the project cannot buy tooling until Gate 3 is passed.","ex_ja":"当社のステージゲート法では、ゲート3を通過するまで金型を購入できない。","ex_vi":"Theo quy trình stage-gate của chúng tôi, dự án không được mua khuôn trước khi qua cổng 3.","syn_en":["phase-gate process","gate review process"],"syn_ja":["フェーズゲート","ゲート審査 (liên quan)"]},{"en":"value engineering","pos":"noun phrase","ipa":"/ˈvæljuː ˌɛndʒɪˈnɪrɪŋ/","ja":"価値工学","kana":"かちこうがく","romaji":"kachikougaku","vi":"kỹ thuật giá trị (VE)","level":3,"def_vi":"Phương pháp có hệ thống phân tích chức năng của sản phẩm để đạt chức năng cần thiết với chi phí thấp nhất.","def_en":"A systematic method that analyses product functions to deliver the required function at the lowest cost.","def_ja":"製品の機能を分析し、必要な機能を最小のコストで実現する体系的な手法。","usage_en":"Viết tắt VE; với sản phẩm đang sản xuất gọi 'value analysis' (VA). Hay đi với: VE proposal, VE workshop, function analysis.","usage_ja":"Trong công ty Nhật gần như chỉ nói VE (ブイイー) hoặc VA/VE: VE提案, VE活動. 価値工学 là tên trong sách.","context_vi":"Dùng trong giảm giá thành, đề xuất của nhà cung cấp, dự án xây dựng và thiết kế lại sản phẩm.","ex_en":"Value engineering replaced the machined bracket with a pressed steel part.","ex_ja":"価値工学の手法で、切削ブラケットをプレス部品に置き換えた。","ex_vi":"Kỹ thuật giá trị đã thay giá đỡ gia công cắt gọt bằng chi tiết dập thép.","syn_en":["VE","value analysis (VA, liên quan)"],"syn_ja":["VE","VA (liên quan)"]},{"en":"robust design","pos":"noun phrase","ipa":"/roʊˈbʌst dɪˈzaɪn/","ja":"ロバスト設計","kana":"ロバストせっけい","romaji":"robasutosekkei","vi":"thiết kế bền vững (robust design)","level":3,"def_vi":"Cách thiết kế để tính năng sản phẩm ít bị ảnh hưởng bởi sai lệch chế tạo, môi trường và điều kiện sử dụng.","def_en":"Designing so that product performance is insensitive to manufacturing variation, environment and usage conditions.","def_ja":"製造ばらつき・環境・使用条件の影響を受けにくいように設計すること。","usage_en":"Danh từ không đếm được. Hay đi với: Taguchi method, noise factors, signal-to-noise ratio, parameter design.","usage_ja":"Gắn liền với 品質工学 và タグチメソッド; hay gặp: ロバスト性, SN比, パラメータ設計, 誤差因子.","context_vi":"Dùng trong thiết kế ô tô, điện tử, khi muốn giảm lỗi do biến động vật liệu, nhiệt độ, lắp ráp.","ex_en":"Robust design made the valve flow stable even with wide spring tolerances.","ex_ja":"ロバスト設計により、ばね公差が大きくてもバルブ流量が安定するようになった。","ex_vi":"Thiết kế bền vững giúp lưu lượng van ổn định ngay cả khi dung sai lò xo lớn.","syn_en":["Taguchi method","parameter design (nghĩa hẹp hơn)"],"syn_ja":["品質工学","タグチメソッド"]},{"en":"front-loading","pos":"noun","ipa":"/ˈfrʌnt ˌloʊdɪŋ/","ja":"フロントローディング","kana":"フロントローディング","romaji":"furontoroodingu","vi":"dồn nỗ lực vào giai đoạn đầu (front-loading)","level":3,"def_vi":"Chiến lược tập trung nguồn lực, mô phỏng, kiểm tra vào giai đoạn đầu thiết kế để phát hiện vấn đề sớm khi sửa còn rẻ.","def_en":"Concentrating resources, simulation and checks in early design to find problems while they are still cheap to fix.","def_ja":"設計の初期段階に資源と検討を集中し、問題を安価に直せるうちに見つけること。","usage_en":"Danh từ không đếm được; động từ 'front-load'. Hay đi với: front-loading of development, front-load the design work.","usage_ja":"Rất phổ biến ở công ty Nhật (Toyota): フロントローディング化, 開発の前倒し, 上流工程で作り込む.","context_vi":"Dùng khi cải tiến quy trình phát triển, áp dụng CAE, xem xét thiết kế sớm với sản xuất.","ex_en":"Front-loading with CAE reduced the number of prototype loops from three to one.","ex_ja":"CAEによるフロントローディングで、試作回数を3回から1回に減らした。","ex_vi":"Dồn nỗ lực vào giai đoạn đầu bằng CAE đã giảm số vòng làm mẫu thử từ ba xuống một.","syn_en":["upfront engineering","shift-left (nghĩa gần)"],"syn_ja":["開発の前倒し","上流での作り込み"]}]},{"id":19,"words":[{"en":"standard","pos":"noun","ipa":"/ˈstændərd/","ja":"規格","kana":"きかく","romaji":"kikaku","vi":"tiêu chuẩn","level":1,"def_vi":"Tài liệu do tổ chức có thẩm quyền ban hành, quy định thống nhất về kích thước, vật liệu, chất lượng hoặc phương pháp thử.","def_en":"A document issued by a recognized body that sets uniform rules for dimensions, materials, quality or test methods.","def_ja":"公認機関が定めた、寸法・材料・品質・試験方法などの統一的な取決め文書。","usage_en":"Danh từ đếm được. Hay đi với: comply with / conform to / meet a standard, according to the standard, issue / revise a standard. Đừng nhầm 'standard' (tiêu chuẩn) với 'standard work' (thao tác chuẩn).","usage_ja":"規格 là văn bản tiêu chuẩn chính thức (JIS規格, ISO規格); 標準 thiên về 'chuẩn hóa', 'mẫu chuẩn' (標準部品, 作業標準). Hay nói: 規格に準拠する, 規格を満たす.","context_vi":"Dùng khi ghi vật liệu, ren, dung sai trên bản vẽ, khi mua hàng và khi kiểm tra nghiệm thu sản phẩm.","ex_en":"All bolts must comply with the ISO 898-1 standard for property class 8.8.","ex_ja":"ボルトはすべて強度区分8.8についてISO 898-1の規格に適合すること。","ex_vi":"Tất cả bu lông phải tuân theo tiêu chuẩn ISO 898-1 cho cấp bền 8.8.","syn_en":["norm (châu Âu)","code (nghĩa gần, ví dụ ASME code)"],"syn_ja":["標準 (nghĩa gần)","スタンダード"]},{"en":"specification","pos":"noun","ipa":"/ˌspɛsəfɪˈkeɪʃən/","ja":"仕様","kana":"しよう","romaji":"shiyou","vi":"đặc tính kỹ thuật (thông số kỹ thuật)","level":1,"def_vi":"Tập hợp các yêu cầu cụ thể về tính năng, kích thước, vật liệu, điều kiện mà một sản phẩm hay vật tư phải đáp ứng.","def_en":"A precise set of requirements for performance, dimensions, materials and conditions that a product or material must meet.","def_ja":"製品や材料が満たすべき性能・寸法・材料・条件などの具体的な要求事項。","usage_en":"Danh từ đếm được, khẩu ngữ 'spec' / 'specs'. Hay đi với: meet the specification, out of spec, technical specification, 'to spec'.","usage_ja":"仕様 là nội dung yêu cầu; văn bản ghi nó là 仕様書. Hay nói: 仕様を満たす, 仕様変更, 仕様外 (ngoài thông số), スペック (khẩu ngữ).","context_vi":"Dùng khi đặt hàng thiết bị, viết hồ sơ mời thầu, so sánh sản phẩm và nghiệm thu máy móc.","ex_en":"The motor does not meet our specification for starting torque.","ex_ja":"そのモータは始動トルクについて当社の仕様を満たしていない。","ex_vi":"Động cơ đó không đáp ứng đặc tính kỹ thuật của chúng tôi về mô-men khởi động.","syn_en":["spec (khẩu ngữ)","technical specification"],"syn_ja":["スペック (khẩu ngữ)","仕様書 (văn bản, liên quan)"]},{"en":"ISO","pos":"abbreviation","ipa":"/ˈaɪsoʊ/","ja":"ISO","kana":"アイエスオー","romaji":"aiesuoo","vi":"Tổ chức Tiêu chuẩn hóa Quốc tế (ISO)","level":1,"def_vi":"Tổ chức quốc tế ban hành tiêu chuẩn cho hầu hết các lĩnh vực công nghiệp; cũng chỉ các tiêu chuẩn do tổ chức này ban hành.","def_en":"The International Organization for Standardization, which issues standards for most industries; also used for its standards.","def_ja":"国際標準化機構。多くの産業分野の国際規格を発行し、その規格自体も指す。","usage_en":"Thường đọc /ˈaɪsoʊ/ như một từ, cũng có người đánh vần I-S-O. Hay đi với: ISO standard, ISO 9001, 'ISO-certified', 'to ISO 2768-m'.","usage_ja":"Đọc アイエスオー hoặc イソ (khẩu ngữ). Hay gặp: ISO規格, ISO認証を取得する, ISO 9001.","context_vi":"Dùng trên bản vẽ (dung sai, ren, nhám), trong hợp đồng xuất khẩu và hệ thống quản lý chất lượng.","ex_en":"General tolerances on this drawing follow ISO 2768-mK.","ex_ja":"この図面の普通公差はISO 2768-mKによる。","ex_vi":"Dung sai chung trên bản vẽ này theo ISO 2768-mK.","syn_en":["International Organization for Standardization","ISO standard"],"syn_ja":["国際標準化機構","イソ (khẩu ngữ)"]},{"en":"JIS","pos":"abbreviation","ipa":"/ˌdʒeɪ aɪ ˈɛs/","ja":"JIS","kana":"ジス","romaji":"jisu","vi":"Tiêu chuẩn công nghiệp Nhật Bản (JIS)","level":1,"def_vi":"Hệ thống tiêu chuẩn quốc gia của Nhật Bản cho sản phẩm công nghiệp, ký hiệu theo nhóm chữ cái và số, ví dụ JIS B 1180.","def_en":"Japanese Industrial Standards, Japan's national standards for industrial products, numbered like JIS B 1180.","def_ja":"日本産業規格。工業製品に関する日本の国家規格で、JIS B 1180のように番号を付ける。","usage_en":"Người nói tiếng Anh đánh vần J-I-S. Hay đi với: JIS standard, JIS material (SS400, S45C), JIS mark, 'to JIS B 0405'.","usage_ja":"Đọc ジス; hay gặp: JIS規格, JISマーク, JIS品, JISに準拠. Từ 2019 tên chính thức là 日本産業規格 (trước là 日本工業規格).","context_vi":"Rất phổ biến ở các công ty Nhật tại Việt Nam: vật liệu thép, bu lông, bản vẽ, dung sai đều ghi theo JIS.","ex_en":"The customer specified JIS material S45C for the shaft.","ex_ja":"顧客はシャフトの材料にJISのS45Cを指定した。","ex_vi":"Khách hàng chỉ định vật liệu JIS S45C cho trục.","syn_en":["Japanese Industrial Standards","JIS standard"],"syn_ja":["日本産業規格","JIS規格"]},{"en":"TCVN","pos":"abbreviation","ipa":"/ˌtiː siː viː ˈɛn/","ja":"TCVN","kana":"ティーシーブイエヌ","romaji":"tiishiibuienu","vi":"Tiêu chuẩn Quốc gia Việt Nam (TCVN)","level":1,"def_vi":"Hệ thống tiêu chuẩn quốc gia của Việt Nam, nhiều tiêu chuẩn được chấp nhận tương đương từ ISO, ký hiệu như TCVN 1916.","def_en":"Vietnam's national standards, many adopted from ISO, numbered like TCVN 1916.","def_ja":"ベトナムの国家規格。多くはISOを採用したもので、TCVN 1916のように表記する。","usage_en":"Đọc từng chữ cái T-C-V-N. Khi viết cho người nước ngoài nên giải thích: 'TCVN (Vietnamese National Standard)', nêu tiêu chuẩn ISO tương đương nếu có.","usage_ja":"Người Nhật thường gọi ベトナム国家規格 hoặc ベトナム規格; khi viết tài liệu nên ghi kèm số ISO tương đương để dễ hiểu.","context_vi":"Dùng trong hồ sơ dự án, đấu thầu, thiết kế công trình và kiểm định thiết bị tại Việt Nam.","ex_en":"The pressure vessel must also be inspected according to TCVN 8366.","ex_ja":"この圧力容器はTCVN 8366に従った検査も必要である。","ex_vi":"Bình chịu áp lực này cũng phải được kiểm tra theo TCVN 8366.","syn_en":["Vietnamese National Standard","QCVN (quy chuẩn bắt buộc, liên quan)"],"syn_ja":["ベトナム国家規格","ベトナム規格"]},{"en":"standard part","pos":"noun phrase","ipa":"/ˈstændərd ˌpɑːrt/","ja":"標準部品","kana":"ひょうじゅんぶひん","romaji":"hyoujunbuhin","vi":"chi tiết tiêu chuẩn","level":1,"def_vi":"Chi tiết có hình dạng, kích thước theo tiêu chuẩn như bu lông, đai ốc, vòng bi, chốt, mua sẵn trên thị trường, không cần vẽ chế tạo.","def_en":"A part made to a published standard, such as a bolt, nut, bearing or pin, bought off the shelf rather than drawn and made.","def_ja":"ボルト・ナット・軸受・ピンなど、規格に基づき市販され、製作図を必要としない部品。","usage_en":"Danh từ đếm được. Hay đi với: use standard parts, standard part library (trong CAD), catalogue part; đối lập: custom part.","usage_ja":"Hay gặp: 標準部品を使う, 標準品, 規格品, 市販品 (hàng mua sẵn, nghĩa rộng hơn). Thư viện CAD: 標準部品ライブラリ.","context_vi":"Dùng khi thiết kế để giảm chi phí, khi lập BOM và khi chọn chi tiết từ catalog Misumi, SKF, NSK.","ex_en":"Use a standard part wherever possible instead of designing a special pin.","ex_ja":"専用ピンを設計せず、できるだけ標準部品を使うこと。","ex_vi":"Hãy dùng chi tiết tiêu chuẩn bất cứ khi nào có thể thay vì thiết kế chốt riêng.","syn_en":["catalogue part","off-the-shelf part"],"syn_ja":["規格品","市販品 (nghĩa rộng hơn)"]},{"en":"rated value","pos":"noun phrase","ipa":"/ˈreɪtɪd ˈvæljuː/","ja":"定格値","kana":"ていかくち","romaji":"teikakuchi","vi":"giá trị định mức","level":1,"def_vi":"Giá trị do nhà sản xuất công bố (công suất, điện áp, tốc độ, tải) mà thiết bị được thiết kế để làm việc lâu dài an toàn.","def_en":"The value declared by the manufacturer, such as power, voltage, speed or load, at which equipment is designed to run continuously.","def_ja":"出力・電圧・回転数・荷重など、機器が継続運転できるよう製造者が定めた値。","usage_en":"Danh từ đếm được. Tính từ 'rated' rất hay dùng: rated power, rated speed, rated load, rated pressure; 'exceed the rated value'.","usage_ja":"Hay gặp: 定格出力, 定格電流, 定格回転数, 定格荷重; 定格を超える, 定格運転. Thường in trên nhãn máy (銘板).","context_vi":"Dùng khi đọc nhãn máy, catalog động cơ, bơm, palăng và khi chọn thiết bị theo tải thực tế.","ex_en":"The pump was running at 120 % of its rated value, which overheated the motor.","ex_ja":"ポンプは定格値の120%で運転されており、モータが過熱した。","ex_vi":"Máy bơm chạy ở 120 % giá trị định mức nên động cơ bị quá nhiệt.","syn_en":["rating","nominal rating"],"syn_ja":["定格","公称値 (nghĩa gần)"]},{"en":"compliance","pos":"noun","ipa":"/kəmˈplaɪəns/","ja":"適合","kana":"てきごう","romaji":"tekigou","vi":"sự tuân thủ (phù hợp tiêu chuẩn)","level":1,"def_vi":"Trạng thái sản phẩm, quy trình đáp ứng đúng yêu cầu của tiêu chuẩn, quy định hoặc đặc tính kỹ thuật.","def_en":"The state of a product or process meeting the requirements of a standard, regulation or specification.","def_ja":"製品や工程が規格・法規・仕様の要求を満たしている状態。","usage_en":"Danh từ không đếm được; động từ 'comply with'. Hay đi với: in compliance with, ensure compliance, certificate of compliance. Lỗi hay gặp: 'comply to' (nên dùng 'comply with').","usage_ja":"Hay gặp: 規格に適合する, 適合品, 適合証明書, 不適合 (không phù hợp). Văn bản: ～に準拠する cũng rất hay dùng.","context_vi":"Dùng trong hợp đồng, chứng chỉ xuất xưởng, báo cáo kiểm tra và hồ sơ xuất khẩu.","ex_en":"The supplier must provide a certificate showing compliance with RoHS.","ex_ja":"サプライヤはRoHSへの適合を示す証明書を提出しなければならない。","ex_vi":"Nhà cung cấp phải cung cấp chứng nhận thể hiện sự tuân thủ RoHS.","syn_en":["conformance","conformity"],"syn_ja":["準拠","適合性"]},{"en":"international standard","pos":"noun phrase","ipa":"/ˌɪntərˈnæʃənəl ˈstændərd/","ja":"国際規格","kana":"こくさいきかく","romaji":"kokusaikikaku","vi":"tiêu chuẩn quốc tế","level":1,"def_vi":"Tiêu chuẩn do tổ chức quốc tế như ISO, IEC ban hành, dùng chung giữa nhiều nước để thuận lợi thương mại.","def_en":"A standard issued by an international body such as ISO or IEC and shared by many countries to ease trade.","def_ja":"ISOやIECなどの国際機関が制定し、多くの国で共通に使われる規格。","usage_en":"Danh từ đếm được. Hay đi với: adopt / harmonize with an international standard; đối lập: national standard.","usage_ja":"Hay gặp: 国際規格に整合させる, 国際規格との整合化; ISO, IEC là các 国際規格 tiêu biểu.","context_vi":"Dùng khi thiết kế sản phẩm xuất khẩu và khi so sánh tiêu chuẩn của các nước khác nhau.","ex_en":"Most JIS standards for screw threads are now identical to the international standard.","ex_ja":"ねじに関するJISの多くは、現在では国際規格と一致している。","ex_vi":"Hầu hết các tiêu chuẩn JIS về ren hiện nay đều giống hệt tiêu chuẩn quốc tế.","syn_en":["ISO/IEC standard","global standard (nghĩa gần)"],"syn_ja":["国際標準","ISO規格 (nghĩa hẹp hơn)"]},{"en":"national standard","pos":"noun phrase","ipa":"/ˈnæʃənəl ˈstændərd/","ja":"国家規格","kana":"こっかきかく","romaji":"kokkakikaku","vi":"tiêu chuẩn quốc gia","level":1,"def_vi":"Tiêu chuẩn do cơ quan tiêu chuẩn hóa của một nước ban hành, như JIS, DIN, GB, TCVN.","def_en":"A standard issued by a country's national standards body, such as JIS, DIN, GB or TCVN.","def_ja":"JIS・DIN・GB・TCVNなど、各国の標準化機関が制定する規格。","usage_en":"Danh từ đếm được. Hay đi với: national standards body, national standard of Vietnam; khác 'company standard' và 'industry standard'.","usage_ja":"Hay gặp: 国家規格, 各国の国家規格; ở Nhật JIS là 国家規格 chính. Lưu ý 国家標準 trong đo lường là 'chuẩn đo lường quốc gia' (nghĩa khác).","context_vi":"Dùng khi so sánh yêu cầu giữa các nước và khi chọn tiêu chuẩn áp dụng cho dự án.","ex_en":"Each country has its own national standard for steel pipe dimensions.","ex_ja":"鋼管の寸法については、国ごとに独自の国家規格がある。","ex_vi":"Mỗi nước có tiêu chuẩn quốc gia riêng về kích thước ống thép.","syn_en":["national norm","country standard (khẩu ngữ)"],"syn_ja":["国内規格","国家標準 (nghĩa gần)"]},{"en":"ASTM","pos":"abbreviation","ipa":"/ˌeɪ ɛs tiː ˈɛm/","ja":"ASTM","kana":"エーエスティーエム","romaji":"eesutiiemu","vi":"Hiệp hội Thử nghiệm và Vật liệu Hoa Kỳ (ASTM)","level":2,"def_vi":"Tổ chức tiêu chuẩn của Mỹ, nổi tiếng với tiêu chuẩn vật liệu và phương pháp thử, ví dụ ASTM A36, ASTM E8.","def_en":"ASTM International, a US-based body known for material and test-method standards such as ASTM A36 and E8.","def_ja":"材料規格や試験方法規格で知られる米国の規格団体。例:ASTM A36、E8。","usage_en":"Đọc từng chữ A-S-T-M. Hay đi với: ASTM standard, ASTM A36 steel, 'tested per ASTM E8'.","usage_ja":"Đọc エーエスティーエム; hay gặp: ASTM規格, ASTM A105相当. Thường dùng trong ngành dầu khí, đường ống, vật liệu.","context_vi":"Dùng khi đặt mua thép, ống, mặt bích, khi đọc chứng chỉ vật liệu và yêu cầu thử nghiệm của khách hàng Mỹ.","ex_en":"The flange material is ASTM A105 forged carbon steel.","ex_ja":"フランジの材料はASTM A105の炭素鋼鍛造品である。","ex_vi":"Vật liệu mặt bích là thép cacbon rèn ASTM A105.","syn_en":["ASTM International","American Society for Testing and Materials (tên cũ)"],"syn_ja":["米国材料試験協会","ASTM規格"]},{"en":"DIN","pos":"abbreviation","ipa":"/dɪn/","ja":"DIN","kana":"ディン","romaji":"din","vi":"Tiêu chuẩn Đức (DIN)","level":2,"def_vi":"Viện tiêu chuẩn Đức và hệ thống tiêu chuẩn của nó, rất phổ biến cho chi tiết lắp xiết, như DIN 912, DIN 125.","def_en":"The German Institute for Standardization and its standards, widely used for fasteners such as DIN 912 and DIN 125.","def_ja":"ドイツ規格協会とその規格。DIN 912、DIN 125など締結部品で広く使われる。","usage_en":"Đọc như một từ /dɪn/. Hay đi với: DIN standard, DIN rail, 'DIN 912 socket head cap screw'; nhiều tiêu chuẩn DIN cũ đã chuyển thành DIN EN ISO.","usage_ja":"Đọc ディン; hay gặp: DIN規格, DINレール, DIN 912相当. Thường gặp khi mua linh kiện châu Âu.","context_vi":"Dùng khi đặt mua bu lông, vòng đệm, thanh ray điện, linh kiện máy từ châu Âu.","ex_en":"Replace the screws with DIN 912 M8 × 25, strength class 12.9.","ex_ja":"ねじをDIN 912のM8×25、強度区分12.9に交換すること。","ex_vi":"Thay các vít bằng DIN 912 M8 × 25, cấp bền 12.9.","syn_en":["Deutsches Institut für Normung","German standard"],"syn_ja":["ドイツ規格","ドイツ規格協会"]},{"en":"ASME","pos":"abbreviation","ipa":"/ˈæzmiː/","ja":"ASME","kana":"アスメ","romaji":"asume","vi":"Hiệp hội Kỹ sư Cơ khí Hoa Kỳ (ASME)","level":2,"def_vi":"Hiệp hội kỹ sư cơ khí Mỹ, ban hành các bộ quy phạm như nồi hơi - bình áp lực (BPVC), đường ống B31, GD&T Y14.5.","def_en":"The American Society of Mechanical Engineers, publisher of codes such as the BPVC, B31 piping and Y14.5.","def_ja":"米国機械学会。ボイラ・圧力容器規格(BPVC)、配管B31、Y14.5などを発行。","usage_en":"Thường đọc /ˈæzmiː/ hoặc đánh vần A-S-M-E. Hay đi với: ASME code, ASME Section VIII, ASME stamp (U-stamp), ASME Y14.5.","usage_ja":"Người Nhật đọc アスメ hoặc アズミ; hay gặp: ASME規格, ASMEコード, ASMEスタンプ (chứng nhận chế tạo bình áp lực).","context_vi":"Dùng trong thiết kế, chế tạo nồi hơi, bình áp lực, đường ống công nghệ và trên bản vẽ theo chuẩn Mỹ.","ex_en":"The vessel is designed and stamped to ASME Section VIII, Division 1.","ex_ja":"この容器はASME Section VIII Division 1に従って設計され、スタンプが打たれている。","ex_vi":"Bình được thiết kế và đóng dấu theo ASME Section VIII, Division 1.","syn_en":["American Society of Mechanical Engineers","ASME code"],"syn_ja":["米国機械学会","ASMEコード"]},{"en":"industry standard","pos":"noun phrase","ipa":"/ˈɪndəstri ˈstændərd/","ja":"団体規格","kana":"だんたいきかく","romaji":"dantaikikaku","vi":"tiêu chuẩn ngành (tiêu chuẩn hiệp hội)","level":2,"def_vi":"Tiêu chuẩn do hiệp hội ngành như SAE, API, JASO ban hành cho một lĩnh vực cụ thể.","def_en":"A standard issued by a trade or professional association such as SAE, API or JASO for a specific sector.","def_ja":"SAE・API・JASOなど、業界団体が特定分野向けに制定する規格。","usage_en":"Danh từ đếm được. Hay đi với: follow the industry standard, industry-standard practice; cũng mang nghĩa 'chuẩn chung được cả ngành dùng'.","usage_ja":"Thuật ngữ chính thức: 団体規格; ngoài công ty hay nói 業界規格. Ví dụ JASO (ô tô), JEM (điện), JPI (dầu khí).","context_vi":"Dùng trong ngành ô tô, dầu khí, điện, nơi tiêu chuẩn quốc gia chưa đủ chi tiết.","ex_en":"The oil seal is tested to the JASO industry standard used by Japanese carmakers.","ex_ja":"このオイルシールは日本の自動車メーカーが使う団体規格JASOに従って試験している。","ex_vi":"Phớt dầu được thử theo tiêu chuẩn ngành JASO mà các hãng xe Nhật sử dụng.","syn_en":["association standard","sector standard"],"syn_ja":["業界規格","工業会規格"]},{"en":"company standard","pos":"noun phrase","ipa":"/ˈkʌmpəni ˈstændərd/","ja":"社内規格","kana":"しゃないきかく","romaji":"shanaikikaku","vi":"tiêu chuẩn cơ sở (tiêu chuẩn nội bộ)","level":2,"def_vi":"Tiêu chuẩn do chính công ty ban hành để thống nhất vật liệu, chi tiết, cách vẽ, thử nghiệm trong nội bộ.","def_en":"A standard issued by a company to unify materials, parts, drawing rules and tests internally.","def_ja":"材料・部品・製図・試験などを社内で統一するために企業が定める規格。","usage_en":"Danh từ đếm được. Hay đi với: our company standard, internal standard, comply with the customer's company standard.","usage_ja":"Hay gặp: 社内規格, 社内標準, 社規; các hãng lớn có tên riêng như TSH (Toyota). Hay nói 社内規格に従う.","context_vi":"Dùng khi làm việc với khách hàng Nhật, Hàn yêu cầu nhà cung cấp theo tiêu chuẩn nội bộ của họ.","ex_en":"The paint thickness must follow the customer's company standard, not JIS.","ex_ja":"塗装膜厚はJISではなく、顧客の社内規格に従うこと。","ex_vi":"Chiều dày sơn phải theo tiêu chuẩn nội bộ của khách hàng, không theo JIS.","syn_en":["internal standard","in-house standard"],"syn_ja":["社内標準","社規 (khẩu ngữ)"]},{"en":"material designation","pos":"noun phrase","ipa":"/məˈtɪriəl ˌdɛzɪɡˈneɪʃən/","ja":"材料記号","kana":"ざいりょうきごう","romaji":"zairyoukigou","vi":"ký hiệu vật liệu (mác vật liệu)","level":2,"def_vi":"Mã chữ và số theo tiêu chuẩn dùng để gọi tên vật liệu, như SS400, S45C, SUS304, A6061.","def_en":"The standard alphanumeric code used to name a material, such as SS400, S45C, SUS304 or A6061.","def_ja":"SS400・S45C・SUS304・A6061など、規格で定めた材料を表す英数字の記号。","usage_en":"Danh từ đếm được. Hay đi với: material designation on the drawing, steel grade; khẩu ngữ: 'material grade', 'material spec'.","usage_ja":"Trong bản vẽ ghi ở 部品欄 cột 材質. Ngoài xưởng hỏi 材質は？; hay nói 材料記号を記入する.","context_vi":"Dùng khi ghi vật liệu trên bản vẽ, đặt mua phôi và tra bảng quy đổi mác thép giữa các tiêu chuẩn.","ex_en":"Write the full material designation, for example SUS304, in the parts list.","ex_ja":"部品欄にはSUS304のように材料記号を正確に記入すること。","ex_vi":"Hãy ghi đầy đủ ký hiệu vật liệu, ví dụ SUS304, trong bảng kê chi tiết.","syn_en":["material grade","steel grade (nghĩa hẹp hơn)"],"syn_ja":["材質 (khẩu ngữ)","鋼種 (nghĩa hẹp hơn)"]},{"en":"grade","pos":"noun","ipa":"/ɡreɪd/","ja":"等級","kana":"とうきゅう","romaji":"toukyuu","vi":"cấp (cấp chính xác, cấp bền)","level":2,"def_vi":"Mức phân loại do tiêu chuẩn quy định về độ chính xác, độ bền hoặc chất lượng, như cấp chính xác vòng bi, cấp bền bu lông.","def_en":"A class defined by a standard for accuracy, strength or quality, such as bearing accuracy class or bolt property class.","def_ja":"規格で定めた精度・強度・品質の区分。例:軸受の精度等級、ボルトの強度区分。","usage_en":"Danh từ đếm được. Hay đi với: accuracy grade, tolerance grade (IT7), steel grade, 'a higher grade'; tiêu chuẩn bu lông dùng 'property class', vòng bi dùng 'tolerance class'.","usage_ja":"Hay gặp: 精度等級 (0級, 6級...), 等級を上げる; với bu lông dùng 強度区分, với thép dùng 種類/鋼種. Không nhầm với 級 trong tên chứng chỉ.","context_vi":"Dùng khi chọn vòng bi, ray dẫn hướng, vít me, bánh răng, bu lông theo catalog và tiêu chuẩn.","ex_en":"The spindle uses angular-contact bearings of accuracy grade P4.","ex_ja":"主軸には精度等級P4のアンギュラ玉軸受を使用している。","ex_vi":"Trục chính dùng ổ bi đỡ chặn cấp chính xác P4.","syn_en":["class","property class (cho bu lông)"],"syn_ja":["精度等級","強度区分 (cho bu lông, liên quan)"]},{"en":"field of application","pos":"noun phrase","ipa":"/ˈfiːld əv ˌæplɪˈkeɪʃən/","ja":"適用範囲","kana":"てきようはんい","romaji":"tekiyouhan'i","vi":"phạm vi áp dụng","level":2,"def_vi":"Mục đầu tiên của một tiêu chuẩn, nêu rõ tiêu chuẩn áp dụng cho sản phẩm, kích thước, điều kiện nào và không áp dụng cho gì.","def_en":"The opening clause of a standard stating which products, sizes and conditions it covers and excludes.","def_ja":"規格の最初の項目で、対象とする製品・寸法・条件と対象外を示す部分。","usage_en":"Danh từ không đếm được. Trong ISO tiêu đề mục 1 là 'Scope'; hay đi với: within / outside the field of application, 'This standard specifies...' là câu mở đầu điển hình.","usage_ja":"Là mục 1 của mọi JIS: 1 適用範囲. Hay nói 適用範囲外, ～は適用範囲に含まれない.","context_vi":"Dùng khi đọc tiêu chuẩn để xác định tiêu chuẩn đó có áp dụng cho sản phẩm của mình hay không.","ex_en":"Bolts larger than M39 are outside the field of application of this standard.","ex_ja":"M39を超えるボルトはこの規格の適用範囲外である。","ex_vi":"Bu lông lớn hơn M39 nằm ngoài phạm vi áp dụng của tiêu chuẩn này.","syn_en":["scope (tiêu đề mục 1 trong ISO)","coverage (nghĩa gần)"],"syn_ja":["対象範囲","適用 (khẩu ngữ)"]},{"en":"certification","pos":"noun","ipa":"/ˌsɝːtɪfɪˈkeɪʃən/","ja":"認証","kana":"にんしょう","romaji":"ninshou","vi":"chứng nhận","level":2,"def_vi":"Việc tổ chức bên thứ ba đánh giá và xác nhận bằng văn bản rằng sản phẩm, hệ thống hoặc con người phù hợp với tiêu chuẩn.","def_en":"Written assurance by a third party that a product, system or person conforms to a standard.","def_ja":"製品・システム・人が規格に適合していることを第三者が評価し、文書で保証すること。","usage_en":"Danh từ không đếm được; động từ 'certify', tính từ 'certified'. Hay đi với: obtain / renew certification, product certification, certification body.","usage_ja":"Hay gặp: 認証を取得する, 認証機関, 製品認証, ISO認証. Phân biệt với 認定 (công nhận năng lực tổ chức chứng nhận).","context_vi":"Dùng khi xin chứng nhận ISO, chứng nhận sản phẩm hợp quy, chứng chỉ thợ hàn.","ex_en":"The plant obtained ISO 14001 certification last year.","ex_ja":"その工場は昨年ISO 14001の認証を取得した。","ex_vi":"Nhà máy đã đạt chứng nhận ISO 14001 vào năm ngoái.","syn_en":["certificate (văn bản, liên quan)","registration (Mỹ, cho ISO)"],"syn_ja":["認証取得 (liên quan)","審査登録 (nghĩa gần)"]},{"en":"equivalent standard","pos":"noun phrase","ipa":"/ɪˈkwɪvələnt ˈstændərd/","ja":"相当規格","kana":"そうとうきかく","romaji":"soutoukikaku","vi":"tiêu chuẩn tương đương","level":2,"def_vi":"Tiêu chuẩn của nước hoặc tổ chức khác có yêu cầu gần giống, dùng để thay thế hoặc quy đổi vật liệu, chi tiết.","def_en":"A standard from another country or body with similar requirements, used to substitute or cross-reference materials and parts.","def_ja":"他国・他団体の規格で要求がほぼ同じもの。材料や部品の置換・対比に使う。","usage_en":"Danh từ đếm được. Hay đi với: or equivalent, cross-reference table, 'S45C is roughly equivalent to AISI 1045'. Cẩn thận: tương đương không có nghĩa là giống hệt.","usage_ja":"Hay gặp: ～相当, 相当材, 同等品. Ví dụ SS400相当, 'S45C相当品可' trên bản vẽ.","context_vi":"Dùng khi không mua được vật liệu đúng mác, phải chọn mác tương đương theo tiêu chuẩn khác và xin khách hàng chấp nhận.","ex_en":"We proposed C45 under EN 10083 as an equivalent standard material to S45C.","ex_ja":"S45Cの相当規格材として、EN 10083のC45を提案した。","ex_vi":"Chúng tôi đề xuất C45 theo EN 10083 làm vật liệu tiêu chuẩn tương đương với S45C.","syn_en":["or equivalent","cross-reference standard"],"syn_ja":["相当材","同等品 (nghĩa gần)"]},{"en":"specified value","pos":"noun phrase","ipa":"/ˈspɛsəfaɪd ˈvæljuː/","ja":"規格値","kana":"きかくち","romaji":"kikakuchi","vi":"giá trị quy định","level":2,"def_vi":"Giá trị hoặc khoảng giá trị được quy định trong tiêu chuẩn hay bản vẽ mà kết quả đo phải nằm trong đó.","def_en":"The value or range given in a standard or drawing that a measured result must fall within.","def_ja":"規格や図面で定められ、測定結果が収まるべき値または範囲。","usage_en":"Danh từ đếm được. Hay đi với: within the specified value, exceed the specified value, specified minimum tensile strength.","usage_ja":"Rất phổ biến trong xưởng Nhật: 規格値内, 規格値外, 規格値を外れる; trong phiếu kiểm tra có cột 規格値 và 実測値.","context_vi":"Dùng trong phiếu kiểm tra, báo cáo thử nghiệm, chứng chỉ vật liệu khi so sánh với giá trị đo thực tế.","ex_en":"The measured hardness of 52 HRC is within the specified value of 50–55 HRC.","ex_ja":"実測硬さ52HRCは規格値50〜55HRCの範囲内である。","ex_vi":"Độ cứng đo được 52 HRC nằm trong giá trị quy định 50–55 HRC.","syn_en":["specification value","required value"],"syn_ja":["規定値","基準値 (nghĩa gần)"]},{"en":"annex","pos":"noun","ipa":"/ˈænɛks/","ja":"附属書","kana":"ふぞくしょ","romaji":"fuzokusho","vi":"phụ lục (của tiêu chuẩn)","level":2,"def_vi":"Phần bổ sung ở cuối tiêu chuẩn, có thể là quy định bắt buộc (normative) hoặc chỉ tham khảo (informative).","def_en":"A supplementary section at the end of a standard, either normative (mandatory) or informative (for reference).","def_ja":"規格本体の後に付く追加部分。規定(必須)と参考の2種類がある。","usage_en":"Danh từ đếm được, viết hoa khi đi với chữ: Annex A, Annex B (normative / informative). Tiếng Mỹ cũng dùng 'appendix'.","usage_ja":"Viết 附属書 (không phải 付属書) trong JIS; ghi rõ 附属書A (規定) hoặc 附属書JA (参考). Hay nói 附属書を参照.","context_vi":"Dùng khi đọc tiêu chuẩn chi tiết, nhất là khi phương pháp thử hoặc bảng số liệu nằm trong phụ lục.","ex_en":"The test procedure is given in Annex B, which is normative.","ex_ja":"試験手順は附属書B(規定)に示されている。","ex_vi":"Quy trình thử được nêu trong phụ lục B, là phụ lục quy định.","syn_en":["appendix","supplement (nghĩa gần)"],"syn_ja":["付録 (nghĩa gần)","別表 (liên quan)"]},{"en":"CE marking","pos":"noun phrase","ipa":"/ˌsiː ˈiː ˈmɑːrkɪŋ/","ja":"CEマーキング","kana":"シーイーマーキング","romaji":"shiiiimaakingu","vi":"dấu CE","level":2,"def_vi":"Dấu bắt buộc cho nhiều sản phẩm bán ở Liên minh châu Âu, thể hiện nhà sản xuất tuyên bố sản phẩm đáp ứng các chỉ thị, quy định EU.","def_en":"A mandatory mark on many products sold in the EU, showing the manufacturer declares conformity with EU directives and regulations.","def_ja":"EUで販売する多くの製品に必要な表示。EU指令・規則への適合を製造者が宣言する。","usage_en":"Danh từ không đếm được; đọc 'C-E marking'. Hay đi với: affix CE marking, CE-marked machine, Machinery Directive, declaration of conformity.","usage_ja":"Hay gặp: CEマーキングを貼付する, CE適合宣言, 機械指令. Khẩu ngữ: CEマーク.","context_vi":"Dùng khi xuất khẩu máy móc, thiết bị điện, bình áp lực sang châu Âu.","ex_en":"The packing machine needs CE marking before it can be shipped to Germany.","ex_ja":"包装機はドイツに出荷する前にCEマーキングが必要だ。","ex_vi":"Máy đóng gói cần có dấu CE trước khi được xuất sang Đức.","syn_en":["CE mark","EU conformity marking"],"syn_ja":["CEマーク","CE表示"]},{"en":"standardization","pos":"noun","ipa":"/ˌstændərdəˈzeɪʃən/","ja":"標準化","kana":"ひょうじゅんか","romaji":"hyoujunka","vi":"tiêu chuẩn hóa","level":2,"def_vi":"Hoạt động xây dựng và áp dụng quy định chung để thống nhất sản phẩm, chi tiết, quy trình, giảm chủng loại và chi phí.","def_en":"Creating and applying common rules to unify products, parts and processes, reducing variety and cost.","def_ja":"共通の取決めを作り適用して、製品・部品・工程を統一し、種類やコストを減らす活動。","usage_en":"Danh từ không đếm được; Anh-Anh viết 'standardisation'; động từ 'standardize'. Hay đi với: parts standardization, promote standardization.","usage_ja":"Hay gặp: 標準化する, 部品の標準化, 標準化活動, 共通化 (gần nghĩa, hay dùng trong công ty).","context_vi":"Dùng trong thiết kế để giảm số loại bu lông, vòng bi, và trong quản lý sản xuất để thống nhất cách làm.","ex_en":"Standardization cut the number of screw types in the product from 46 to 12.","ex_ja":"標準化により、製品に使うねじの種類を46種から12種に減らした。","ex_vi":"Tiêu chuẩn hóa đã giảm số loại vít trong sản phẩm từ 46 xuống 12.","syn_en":["standardisation (Anh)","commonization (nghĩa gần)"],"syn_ja":["共通化 (nghĩa gần)","規格化"]},{"en":"conformity assessment","pos":"noun phrase","ipa":"/kənˈfɔːrməti əˈsɛsmənt/","ja":"適合性評価","kana":"てきごうせいひょうか","romaji":"tekigouseihyouka","vi":"đánh giá sự phù hợp","level":3,"def_vi":"Tập hợp hoạt động thử nghiệm, kiểm tra, chứng nhận nhằm chứng minh sản phẩm, quá trình hoặc hệ thống đáp ứng yêu cầu quy định.","def_en":"Testing, inspection and certification activities that demonstrate a product, process or system meets specified requirements.","def_ja":"試験・検査・認証などにより、製品・工程・システムが要求を満たすことを実証する活動。","usage_en":"Danh từ không đếm được. Hay đi với: conformity assessment body (CAB), conformity assessment procedure, module (theo EU).","usage_ja":"Thuật ngữ JIS Q 17000; hay gặp: 適合性評価機関, 適合性評価手続き. Dùng nhiều trong văn bản pháp quy.","context_vi":"Dùng trong hồ sơ hợp quy, xuất khẩu sang EU, và khi làm việc với tổ chức chứng nhận, phòng thử nghiệm.","ex_en":"For this pressure equipment, conformity assessment must involve a notified body.","ex_ja":"この圧力機器の適合性評価には、ノーティファイドボディの関与が必要だ。","ex_vi":"Với thiết bị áp lực này, việc đánh giá sự phù hợp phải có tổ chức được thông báo tham gia.","syn_en":["conformity evaluation","compliance assessment (nghĩa gần)"],"syn_ja":["適合評価","認証 (nghĩa hẹp hơn)"]},{"en":"accreditation","pos":"noun","ipa":"/əˌkrɛdɪˈteɪʃən/","ja":"認定","kana":"にんてい","romaji":"nintei","vi":"công nhận (năng lực)","level":3,"def_vi":"Việc cơ quan có thẩm quyền chính thức xác nhận một phòng thí nghiệm hoặc tổ chức chứng nhận có đủ năng lực, ví dụ theo ISO/IEC 17025.","def_en":"Formal recognition by an authoritative body that a laboratory or certification body is competent, e.g. to ISO/IEC 17025.","def_ja":"試験所や認証機関が能力を持つことを権威ある機関が公式に認めること。例:ISO/IEC 17025。","usage_en":"Danh từ không đếm được; tính từ 'accredited'. Hay đi với: accredited laboratory, accreditation body, ISO/IEC 17025 accreditation. Đừng nhầm với 'certification'.","usage_ja":"Hay gặp: 認定試験所, 認定機関 (IAJapan, JAB), 認定を受ける. 認定 là công nhận năng lực tổ chức, 認証 là chứng nhận sản phẩm/hệ thống.","context_vi":"Dùng khi chọn phòng thử nghiệm, hiệu chuẩn có chứng chỉ được quốc tế thừa nhận (ở Việt Nam: BoA cấp VILAS).","ex_en":"Only calibration certificates from a lab with ISO/IEC 17025 accreditation are accepted.","ex_ja":"ISO/IEC 17025の認定を受けた校正機関の証明書のみ受け付ける。","ex_vi":"Chỉ chấp nhận giấy chứng nhận hiệu chuẩn của phòng thí nghiệm được công nhận ISO/IEC 17025.","syn_en":["accredited status","certification (nghĩa gần, dễ nhầm)"],"syn_ja":["認定取得 (liên quan)","認証 (nghĩa gần, dễ nhầm)"]},{"en":"normative reference","pos":"noun phrase","ipa":"/ˈnɔːrmətɪv ˈrɛfərəns/","ja":"引用規格","kana":"いんようきかく","romaji":"in'youkikaku","vi":"tài liệu viện dẫn","level":3,"def_vi":"Tiêu chuẩn khác được dẫn chiếu trong một tiêu chuẩn và cần thiết để áp dụng tiêu chuẩn đó.","def_en":"Another standard cited in a standard that is indispensable for applying it.","def_ja":"ある規格の中で引用され、その規格を適用するために不可欠な他の規格。","usage_en":"Danh từ đếm được, thường số nhiều ở mục 2: 'Normative references'. Có năm (dated) thì dùng đúng bản đó; không năm (undated) thì dùng bản mới nhất.","usage_ja":"Là mục 2 của JIS: 2 引用規格. Hay gặp: 引用規格の最新版を適用する, 発効年を付記した引用規格.","context_vi":"Dùng khi lập danh mục tiêu chuẩn cho dự án, kiểm tra xem cần mua thêm những tiêu chuẩn nào.","ex_en":"ISO 6892-1 is listed as a normative reference, so we must follow its tensile test method.","ex_ja":"ISO 6892-1が引用規格に挙げられているので、その引張試験方法に従う必要がある。","ex_vi":"ISO 6892-1 nằm trong tài liệu viện dẫn nên chúng tôi phải theo phương pháp thử kéo của nó.","syn_en":["referenced standard","cited standard"],"syn_ja":["参照規格","関連規格 (nghĩa rộng hơn)"]},{"en":"amendment","pos":"noun","ipa":"/əˈmɛndmənt/","ja":"追補","kana":"ついほ","romaji":"tsuiho","vi":"sửa đổi bổ sung (của tiêu chuẩn)","level":3,"def_vi":"Văn bản sửa đổi, bổ sung một số điều khoản của tiêu chuẩn đã ban hành mà không ban hành lại toàn bộ.","def_en":"A document that changes or adds specific clauses of a published standard without reissuing the whole standard.","def_ja":"発行済みの規格の一部条項を、全体を改正せずに変更・追加する文書。","usage_en":"Danh từ đếm được, viết tắt Amd: 'ISO 4017:2022/Amd 1'. Hay đi với: issue an amendment, including Amendment 1. Phân biệt với 'revision' (soát xét toàn bộ).","usage_ja":"Trong JIS ghi 追補1 (2020); phân biệt với 改正 (sửa toàn bộ). Hay nói 追補を含めて適用する.","context_vi":"Dùng khi kiểm soát phiên bản tiêu chuẩn trong hợp đồng và khi cập nhật thư viện tiêu chuẩn của công ty.","ex_en":"Make sure you apply the 2019 edition together with its Amendment 1.","ex_ja":"2019年版はその追補1と合わせて適用すること。","ex_vi":"Hãy đảm bảo áp dụng phiên bản 2019 cùng với sửa đổi bổ sung số 1 của nó.","syn_en":["Amd (viết tắt)","corrigendum (đính chính, liên quan)"],"syn_ja":["改正 (soát xét toàn bộ, liên quan)","正誤票 (đính chính, liên quan)"]},{"en":"harmonized standard","pos":"noun phrase","ipa":"/ˈhɑːrmənaɪzd ˈstændərd/","ja":"整合規格","kana":"せいごうきかく","romaji":"seigoukikaku","vi":"tiêu chuẩn hài hòa","level":3,"def_vi":"Tiêu chuẩn châu Âu (EN) được công bố trên Công báo EU; áp dụng nó tạo 'giả định phù hợp' với yêu cầu của chỉ thị.","def_en":"A European (EN) standard cited in the EU Official Journal; applying it gives presumption of conformity with a directive.","def_ja":"EU官報に掲載された欧州規格。適用すると指令の要求に適合すると推定される。","usage_en":"Danh từ đếm được; Anh-Anh viết 'harmonised'. Hay đi với: presumption of conformity, listed in the OJEU, EN ISO 12100.","usage_ja":"Hay gặp: 整合規格を適用する, 適合推定, EN ISO 12100. Chủ yếu dùng trong hồ sơ CEマーキング.","context_vi":"Dùng khi làm hồ sơ dấu CE cho máy móc, chọn tiêu chuẩn an toàn để thiết kế.","ex_en":"We applied EN ISO 13849-1, a harmonized standard under the Machinery Directive.","ex_ja":"機械指令の整合規格であるEN ISO 13849-1を適用した。","ex_vi":"Chúng tôi áp dụng EN ISO 13849-1, một tiêu chuẩn hài hòa thuộc Chỉ thị Máy móc.","syn_en":["harmonised standard (Anh)","hEN"],"syn_ja":["EN整合規格","欧州整合規格"]},{"en":"preferred numbers","pos":"noun phrase","ipa":"/prɪˈfɝːd ˈnʌmbərz/","ja":"標準数","kana":"ひょうじゅんすう","romaji":"hyoujunsuu","vi":"dãy số ưu tiên","level":3,"def_vi":"Dãy số chuẩn theo cấp số nhân (dãy Renard R5, R10, R20...) dùng để chọn kích thước, công suất, tải trọng khi thiết kế.","def_en":"Standard geometric series (Renard R5, R10, R20, etc.) used to choose sizes, ratings and loads in design.","def_ja":"R5・R10・R20などの等比数列による標準の数値。寸法や容量の選定に使う。","usage_en":"Luôn dùng số nhiều. Hay đi với: preferred number series, R10 series, choose from preferred numbers (ISO 3, ISO 497).","usage_ja":"Theo JIS Z 8601; hay gặp: 標準数列, R10数列, 標準数から選ぶ.","context_vi":"Dùng khi xây dựng dải kích thước sản phẩm, chọn đường kính trục, công suất động cơ theo dãy chuẩn.","ex_en":"The pump sizes were chosen from preferred numbers in the R10 series.","ex_ja":"ポンプのサイズはR10数列の標準数から選定した。","ex_vi":"Các cỡ bơm được chọn từ dãy số ưu tiên R10.","syn_en":["Renard series","preferred number series"],"syn_ja":["標準数列","ルナール数列"]}]},{"id":20,"words":[{"en":"bill of materials","pos":"noun phrase","ipa":"/ˌbɪl əv məˈtɪriəlz/","ja":"部品表","kana":"ぶひんひょう","romaji":"buhinhyou","vi":"danh mục vật tư (BOM)","level":1,"def_vi":"Danh sách có cấu trúc gồm tất cả chi tiết, cụm, vật tư và số lượng cần để làm ra một sản phẩm.","def_en":"A structured list of all parts, subassemblies, materials and quantities needed to make a product.","def_ja":"製品を作るのに必要な部品・中間組立品・材料とその数量を構成順にまとめた表。","usage_en":"Danh từ đếm được, viết tắt BOM (đọc /bɑːm/ hoặc B-O-M); số nhiều 'bills of materials'. Hay đi với: create / update / release the BOM, BOM line, BOM level.","usage_ja":"Công ty Nhật hay nói BOM (ボム) hoặc 部品表; hay gặp: 部品表を作成する, 部品表に登録する, 構成表 (nghĩa gần).","context_vi":"Dùng ở phòng thiết kế, mua hàng, kế hoạch sản xuất và kho để đặt vật tư, tính giá thành, lắp ráp.","ex_en":"The new bracket has been added to the bill of materials for the pump unit.","ex_ja":"新しいブラケットをポンプユニットの部品表に追加した。","ex_vi":"Giá đỡ mới đã được thêm vào danh mục vật tư của cụm bơm.","syn_en":["BOM","parts list (nghĩa gần)"],"syn_ja":["BOM","構成表"]},{"en":"part number","pos":"noun phrase","ipa":"/ˈpɑːrt ˌnʌmbər/","ja":"品番","kana":"ひんばん","romaji":"hinban","vi":"mã chi tiết (mã hàng)","level":1,"def_vi":"Mã định danh duy nhất gán cho mỗi chi tiết hoặc vật tư để quản lý trong bản vẽ, BOM, kho và đơn hàng.","def_en":"A unique identifier assigned to each part or item to manage it in drawings, BOMs, stock and orders.","def_ja":"図面・部品表・在庫・注文で管理するため、部品ごとに付ける固有の番号。","usage_en":"Danh từ đếm được, viết tắt P/N hoặc PN. Hay đi với: assign a part number, look up the part number, 'part number 12345-A'.","usage_ja":"Hay gặp: 品番を採番する, 品番を付ける, 品番違い (lỗi nhầm mã). Trang trọng: 部品番号.","context_vi":"Dùng hằng ngày khi đặt hàng, nhập kho, ghi nhãn, tra cứu bản vẽ và phụ tùng thay thế.","ex_en":"Please quote the part number when ordering replacement seals.","ex_ja":"交換用シールを注文する際は品番を明記してください。","ex_vi":"Vui lòng ghi mã chi tiết khi đặt mua phớt thay thế.","syn_en":["P/N","item number (nghĩa gần)"],"syn_ja":["部品番号","品目コード (nghĩa gần)"]},{"en":"part name","pos":"noun phrase","ipa":"/ˈpɑːrt ˌneɪm/","ja":"品名","kana":"ひんめい","romaji":"hinmei","vi":"tên chi tiết","level":1,"def_vi":"Tên gọi ngắn gọn, thống nhất của chi tiết ghi trên bản vẽ, BOM và nhãn, như 'TRỤC ĐẦU VÀO'.","def_en":"The short, standardized name of a part shown on drawings, BOMs and labels, e.g. 'INPUT SHAFT'.","def_ja":"図面・部品表・ラベルに記載する、部品の簡潔で統一された名称。","usage_en":"Danh từ đếm được. Hay đi với: part name and part number, the part name field; quy ước thường là danh từ chính trước: 'SHAFT, INPUT'.","usage_ja":"Hay gặp: 品名, 品番・品名, 部品名称 (trang trọng). Trên bản vẽ ghi ở khung tên và 部品欄.","context_vi":"Dùng khi lập bản vẽ, BOM, hóa đơn, nhãn hàng để người đọc nhận biết nhanh chi tiết.","ex_en":"The part name on the label does not match the drawing.","ex_ja":"ラベルの品名が図面と一致していない。","ex_vi":"Tên chi tiết trên nhãn không khớp với bản vẽ.","syn_en":["description","item name"],"syn_ja":["部品名","名称"]},{"en":"revision history","pos":"noun phrase","ipa":"/rɪˈvɪʒən ˈhɪstəri/","ja":"改訂履歴","kana":"かいていりれき","romaji":"kaiteirireki","vi":"lịch sử sửa đổi","level":1,"def_vi":"Bảng ghi các lần sửa đổi của bản vẽ hoặc tài liệu: ký hiệu phiên bản, nội dung thay đổi, ngày và người duyệt.","def_en":"The record of changes to a drawing or document: revision letter, description, date and approver.","def_ja":"図面や文書の改訂記号・変更内容・日付・承認者を記録した欄や表。","usage_en":"Danh từ đếm được. Hay đi với: check the revision history, revision block / revision table (trên bản vẽ), 'Rev. C' là phiên bản.","usage_ja":"Hay gặp: 改訂履歴欄, 改訂記号, 変更履歴; khẩu ngữ: リビジョン, レビ. Hay nói 改訂履歴を確認する.","context_vi":"Dùng khi kiểm soát bản vẽ, đảm bảo xưởng gia công đúng phiên bản mới nhất và biết đã đổi gì.","ex_en":"The revision history shows that the hole diameter changed in revision C.","ex_ja":"改訂履歴を見ると、穴径は改訂Cで変更されている。","ex_vi":"Lịch sử sửa đổi cho thấy đường kính lỗ đã thay đổi ở phiên bản C.","syn_en":["revision block","change history"],"syn_ja":["変更履歴","改訂欄"]},{"en":"parts list","pos":"noun phrase","ipa":"/ˈpɑːrts ˌlɪst/","ja":"部品欄","kana":"ぶひんらん","romaji":"buhinran","vi":"bảng kê chi tiết (trên bản vẽ)","level":1,"def_vi":"Bảng in trên bản vẽ lắp liệt kê số vị trí, tên, mã, vật liệu và số lượng của từng chi tiết.","def_en":"The table on an assembly drawing listing item number, name, part number, material and quantity of each part.","def_ja":"組立図上に、照合番号・品名・品番・材質・数量を部品ごとに記載する欄。","usage_en":"Danh từ đếm được. Hay đi với: in the parts list, add to the parts list; khác BOM ở chỗ in trên bản vẽ, thường chỉ một cấp.","usage_ja":"Thuật ngữ JIS: 部品欄, thường đặt phía trên khung tên. Hay nói 部品欄に記入する.","context_vi":"Dùng khi đọc bản vẽ lắp tại xưởng để biết cần những chi tiết nào và số lượng bao nhiêu.","ex_en":"Item 7 in the parts list should be M6 × 20, not M6 × 16.","ex_ja":"部品欄の7番はM6×16ではなくM6×20が正しい。","ex_vi":"Vị trí số 7 trong bảng kê chi tiết phải là M6 × 20, không phải M6 × 16.","syn_en":["item list","parts table"],"syn_ja":["明細表","部品表 (nghĩa rộng hơn)"]},{"en":"datasheet","pos":"noun","ipa":"/ˈdeɪtəˌʃiːt/","ja":"データシート","kana":"データシート","romaji":"deetashiito","vi":"bảng thông số kỹ thuật (datasheet)","level":1,"def_vi":"Tài liệu ngắn của nhà sản xuất tóm tắt thông số, kích thước, vật liệu, giới hạn làm việc của một sản phẩm.","def_en":"A short manufacturer's document summarizing a product's specifications, dimensions, materials and operating limits.","def_ja":"製品の仕様・寸法・材質・使用範囲などをまとめた、メーカーの簡潔な資料。","usage_en":"Danh từ đếm được, cũng viết 'data sheet'. Hay đi với: product datasheet, according to the datasheet, download the datasheet.","usage_ja":"Hay gặp: データシートを確認する, 仕様書 (khi dài hơn), カタログ値. Ngành dự án: 機器データシート.","context_vi":"Dùng khi chọn động cơ, cảm biến, xi lanh, vật liệu và khi lập hồ sơ thiết bị cho dự án.","ex_en":"According to the datasheet, the sensor works up to 85 °C.","ex_ja":"データシートによると、このセンサは85°Cまで使用できる。","ex_vi":"Theo bảng thông số kỹ thuật, cảm biến này hoạt động đến 85 °C.","syn_en":["data sheet","spec sheet"],"syn_ja":["仕様書 (nghĩa gần)","カタログ (nghĩa gần)"]},{"en":"instruction manual","pos":"noun phrase","ipa":"/ɪnˈstrʌkʃən ˈmænjuəl/","ja":"取扱説明書","kana":"とりあつかいせつめいしょ","romaji":"toriatsukaisetsumeisho","vi":"sách hướng dẫn sử dụng","level":1,"def_vi":"Tài liệu kèm theo máy hướng dẫn lắp đặt, vận hành, an toàn và bảo dưỡng cho người dùng.","def_en":"A document supplied with a machine explaining installation, operation, safety and maintenance to the user.","def_ja":"機械に添付し、据付・運転・安全・保守の方法を使用者に説明する文書。","usage_en":"Danh từ đếm được. Hay đi với: refer to / follow the instruction manual, operating manual, user manual; 'see manual section 5'.","usage_ja":"Ngoài xưởng gọi tắt 取説 (とりせつ); hay gặp: 取扱説明書を読む, 取扱説明書に従う.","context_vi":"Dùng khi bàn giao máy, đào tạo vận hành và là tài liệu bắt buộc trong hồ sơ CE.","ex_en":"Read the instruction manual before changing the hydraulic oil.","ex_ja":"作動油を交換する前に取扱説明書を読んでください。","ex_vi":"Hãy đọc sách hướng dẫn sử dụng trước khi thay dầu thủy lực.","syn_en":["operating manual","user manual"],"syn_ja":["取説 (khẩu ngữ)","マニュアル"]},{"en":"purchased part","pos":"noun phrase","ipa":"/ˈpɝːtʃəst ˌpɑːrt/","ja":"購入品","kana":"こうにゅうひん","romaji":"kounyuuhin","vi":"chi tiết mua ngoài","level":1,"def_vi":"Chi tiết hoặc thiết bị mua sẵn từ nhà cung cấp, không do công ty tự chế tạo, như động cơ, vòng bi, xi lanh.","def_en":"A part or device bought from a supplier rather than made in-house, such as a motor, bearing or cylinder.","def_ja":"モータ・軸受・シリンダなど、自社で作らず仕入先から買う部品や機器。","usage_en":"Danh từ đếm được. Hay đi với: purchased parts list, bought-out part (Anh); đối lập: manufactured part / in-house part.","usage_ja":"Hay gặp: 購入品リスト, 購入品と加工品, 市販品. Trong BOM thường có cột phân loại 購入/内製.","context_vi":"Dùng khi lập BOM, phân công mua hàng và lập kế hoạch thời gian giao hàng của thiết bị.","ex_en":"Purchased parts such as the gear motor have a lead time of eight weeks.","ex_ja":"ギヤモータなどの購入品は納期が8週間かかる。","ex_vi":"Các chi tiết mua ngoài như động cơ giảm tốc có thời gian giao hàng tám tuần.","syn_en":["bought-out part (Anh)","buy part"],"syn_ja":["市販品","外部購入品"]},{"en":"drawing release","pos":"noun phrase","ipa":"/ˈdrɔːɪŋ rɪˌliːs/","ja":"出図","kana":"しゅつず","romaji":"shutsuzu","vi":"phát hành bản vẽ","level":1,"def_vi":"Việc chính thức đưa bản vẽ đã được duyệt ra cho sản xuất, mua hàng hoặc nhà cung cấp sử dụng.","def_en":"Officially issuing an approved drawing for use by production, purchasing or suppliers.","def_ja":"承認済みの図面を製造・購買・仕入先が使えるよう正式に発行すること。","usage_en":"Danh từ không đếm được; động từ 'release a drawing'. Hay đi với: drawing release date, released for production, 'not released'.","usage_ja":"Từ rất hay dùng ở công ty Nhật: 出図する, 出図日, 出図遅れ, 出図前. Đối với thay đổi: 改訂出図.","context_vi":"Dùng trong lịch dự án, là mốc để mua hàng đặt vật tư và xưởng bắt đầu gia công.","ex_en":"Drawing release for the frame parts is scheduled for Friday.","ex_ja":"フレーム部品の出図は金曜日の予定だ。","ex_vi":"Việc phát hành bản vẽ các chi tiết khung được lên lịch vào thứ Sáu.","syn_en":["drawing issue","release (khẩu ngữ)"],"syn_ja":["図面発行","リリース"]},{"en":"approval","pos":"noun","ipa":"/əˈpruːvəl/","ja":"承認","kana":"しょうにん","romaji":"shounin","vi":"phê duyệt","level":1,"def_vi":"Việc người có thẩm quyền xác nhận chính thức rằng tài liệu hoặc bản vẽ đã đúng và được phép sử dụng.","def_en":"Formal confirmation by an authorized person that a document or drawing is correct and may be used.","def_ja":"権限のある者が、文書や図面が正しく使用してよいと正式に認めること。","usage_en":"Danh từ không đếm được; động từ 'approve'. Hay đi với: for approval, get / give approval, approved by; khung chữ ký: drawn / checked / approved.","usage_ja":"Khung chữ ký Nhật: 作成・検図・承認 (hoặc 設計・検図・承認). Hay nói 承認を得る, 承認印, 承認待ち.","context_vi":"Dùng trong quy trình duyệt bản vẽ, tài liệu, thay đổi thiết kế và đơn đặt hàng.","ex_en":"The drawing cannot be released until it has the manager's approval.","ex_ja":"課長の承認がなければ、その図面は出図できない。","ex_vi":"Bản vẽ không thể phát hành cho đến khi có phê duyệt của trưởng phòng.","syn_en":["sign-off","authorization"],"syn_ja":["承認印 (liên quan)","決裁 (nghĩa gần)"]},{"en":"quantity per assembly","pos":"noun phrase","ipa":"/ˈkwɑːntəti pər əˈsɛmbli/","ja":"員数","kana":"いんずう","romaji":"inzuu","vi":"số lượng trên một cụm","level":2,"def_vi":"Số lượng của một chi tiết cần dùng cho một đơn vị cụm lắp hoặc sản phẩm cấp trên trong BOM.","def_en":"The number of a given part required for one unit of its parent assembly in the BOM.","def_ja":"部品表で、親の組立品1台に使う子部品の個数。","usage_en":"Danh từ đếm được, viết tắt 'Qty per' hoặc 'QPA'. Hay đi với: quantity per assembly column, check the quantity per assembly.","usage_ja":"Từ chuyên dùng trong BOM và xưởng Nhật: 員数, 員数違い (sai số lượng), 員数を確認する. Kiểm tra đủ số lượng gọi là 員数チェック.","context_vi":"Dùng khi lập BOM, tính nhu cầu vật tư và chuẩn bị bộ chi tiết cho lắp ráp.","ex_en":"The quantity per assembly for the M8 bolt should be 6, not 4.","ex_ja":"M8ボルトの員数は4ではなく6が正しい。","ex_vi":"Số lượng trên một cụm của bu lông M8 phải là 6, không phải 4.","syn_en":["Qty per","usage quantity"],"syn_ja":["使用数","個数 (nghĩa rộng hơn)"]},{"en":"engineering change notice","pos":"noun phrase","ipa":"/ˌɛndʒɪˈnɪrɪŋ ˈtʃeɪndʒ ˌnoʊtɪs/","ja":"設計変更通知書","kana":"せっけいへんこうつうちしょ","romaji":"sekkeihenkoutsuuchisho","vi":"thông báo thay đổi kỹ thuật (ECN)","level":2,"def_vi":"Văn bản chính thức thông báo nội dung, lý do, thời điểm áp dụng một thay đổi thiết kế tới các bộ phận liên quan.","def_en":"A formal document informing all affected departments of a design change, its reason and effective date.","def_ja":"設計変更の内容・理由・適用時期を関係部署に正式に知らせる文書。","usage_en":"Danh từ đếm được, viết tắt ECN; tương tự ECO (engineering change order). Hay đi với: issue an ECN, ECN number, effective date, disposition of stock.","usage_ja":"Hay gặp: 設変通知, 設計変更通知書を発行する, 適用時期, 在庫処置 (xử lý hàng tồn).","context_vi":"Dùng khi thay đổi bản vẽ đã phát hành, cần báo cho mua hàng, sản xuất, kho, chất lượng cùng biết.","ex_en":"The engineering change notice states that old stock may be used until 30 June.","ex_ja":"設計変更通知書には、旧品在庫は6月30日まで使用可と記載されている。","ex_vi":"Thông báo thay đổi kỹ thuật ghi rằng hàng tồn cũ được dùng đến ngày 30 tháng 6.","syn_en":["ECN","engineering change order (ECO)"],"syn_ja":["設変通知 (khẩu ngữ)","ECN"]},{"en":"redline","pos":"noun","ipa":"/ˈrɛdlaɪn/","ja":"朱書き","kana":"しゅがき","romaji":"shugaki","vi":"bản đánh dấu sửa bằng mực đỏ (redline)","level":2,"def_vi":"Ghi chú sửa đổi vẽ bằng màu đỏ trực tiếp lên bản vẽ hoặc tài liệu để chỉ ra chỗ cần thay đổi.","def_en":"Corrections marked in red directly on a drawing or document to show what must be changed.","def_ja":"図面や文書に赤で直接書き込んだ修正指示。","usage_en":"Danh từ đếm được, cũng là động từ ('redline the drawing'). Hay đi với: redline markup, redlined drawing, as-built redlines.","usage_ja":"Hay gặp: 朱書きする, 朱書き図面, 赤ペン (khẩu ngữ), 赤入れ. Khi kiểm tra bản vẽ, người kiểm tra 朱書き rồi trả lại.","context_vi":"Dùng khi kiểm tra bản vẽ, khi xưởng ghi lại sửa đổi thực tế để cập nhật bản vẽ hoàn công.","ex_en":"The checker returned the drawing with three redlines on the hole positions.","ex_ja":"検図者は穴位置に3か所の朱書きを入れて図面を返した。","ex_vi":"Người kiểm tra trả lại bản vẽ với ba chỗ đánh dấu sửa đỏ ở vị trí lỗ.","syn_en":["markup","red-pen correction"],"syn_ja":["赤入れ","赤書き"]},{"en":"certificate of conformity","pos":"noun phrase","ipa":"/sərˈtɪfɪkət əv kənˈfɔːrməti/","ja":"適合証明書","kana":"てきごうしょうめいしょ","romaji":"tekigoushoumeisho","vi":"giấy chứng nhận phù hợp (CoC)","level":2,"def_vi":"Văn bản nhà cung cấp ký xác nhận lô hàng được chế tạo đúng bản vẽ, đặc tính kỹ thuật và tiêu chuẩn đã thỏa thuận.","def_en":"A signed supplier statement that a delivered lot was made in accordance with the agreed drawing, specification and standards.","def_ja":"納入ロットが合意した図面・仕様・規格どおりに製作されたことを仕入先が署名して証明する書類。","usage_en":"Danh từ đếm được, viết tắt CoC; còn gọi 'certificate of conformance' (Mỹ). Hay đi với: supply a CoC with each shipment, CoC and test report.","usage_ja":"Hay gặp: 適合証明書を添付する, 品質証明書 (nghĩa gần), CoC. Khác với ミルシート (chứng chỉ vật liệu của nhà máy thép).","context_vi":"Dùng khi giao hàng chi tiết gia công, linh kiện mua ngoài cho ngành hàng không, ô tô, thiết bị y tế.","ex_en":"Each shipment of fasteners must come with a certificate of conformity.","ex_ja":"締結部品は出荷ごとに適合証明書を添付しなければならない。","ex_vi":"Mỗi lô bu lông, đai ốc giao đến phải kèm giấy chứng nhận phù hợp.","syn_en":["CoC","certificate of conformance (Mỹ)"],"syn_ja":["品質証明書 (nghĩa gần)","CoC"]},{"en":"mill certificate","pos":"noun phrase","ipa":"/ˈmɪl sərˌtɪfɪkət/","ja":"ミルシート","kana":"ミルシート","romaji":"mirushiito","vi":"chứng chỉ vật liệu (mill certificate)","level":2,"def_vi":"Giấy chứng nhận do nhà máy luyện, cán thép cấp, ghi thành phần hóa học, cơ tính và số mẻ nấu của lô vật liệu.","def_en":"A certificate from the steel mill stating the chemical composition, mechanical properties and heat number of a material lot.","def_ja":"鉄鋼メーカーが発行し、材料ロットの化学成分・機械的性質・溶鋼番号を示す証明書。","usage_en":"Danh từ đếm được; còn gọi 'mill test certificate (MTC)', 'material certificate'. Hay đi với: EN 10204 3.1 certificate, heat number, request the mill certificate.","usage_ja":"Từ katakana ミルシート rất phổ biến; tên chính thức 鋼材検査証明書. Hay nói ミルシートを添付する, ミルシートと照合する.","context_vi":"Dùng khi nhận thép tấm, ống, thanh cho bình áp lực, kết cấu, chi tiết an toàn cần truy xuất nguồn gốc.","ex_en":"Check the heat number on the plate against the mill certificate.","ex_ja":"鋼板の溶鋼番号をミルシートと照合してください。","ex_vi":"Hãy đối chiếu số mẻ nấu trên tấm thép với chứng chỉ vật liệu.","syn_en":["mill test certificate (MTC)","material certificate"],"syn_ja":["鋼材検査証明書","材料証明書"]},{"en":"approval drawing","pos":"noun phrase","ipa":"/əˈpruːvəl ˌdrɔːɪŋ/","ja":"承認図","kana":"しょうにんず","romaji":"shouninzu","vi":"bản vẽ trình duyệt","level":2,"def_vi":"Bản vẽ do nhà cung cấp lập và gửi khách hàng xem xét, ký duyệt trước khi chế tạo.","def_en":"A drawing prepared by the supplier and submitted to the customer for review and sign-off before manufacture.","def_ja":"製作前に仕入先が作成し、顧客に提出して確認・承認を受ける図面。","usage_en":"Danh từ đếm được. Hay đi với: submit approval drawings, approved for construction (AFC), 'drawing for approval'.","usage_ja":"Hay gặp: 承認図を提出する, 承認図返却, 承認図方式 (nhà cung cấp tự thiết kế); đối lập 貸与図 (bản vẽ khách hàng cấp).","context_vi":"Dùng khi đặt chế tạo máy, thiết bị theo đơn, và trong quan hệ nhà cung cấp linh kiện ô tô Nhật.","ex_en":"Fabrication will start after the customer returns the signed approval drawing.","ex_ja":"顧客から承認図が返却されてから製作を開始する。","ex_vi":"Việc chế tạo sẽ bắt đầu sau khi khách hàng gửi lại bản vẽ trình duyệt đã ký.","syn_en":["drawing for approval","submittal drawing"],"syn_ja":["承認用図面","貸与図 (đối nghĩa, liên quan)"]},{"en":"as-built drawing","pos":"noun phrase","ipa":"/ˌæz ˈbɪlt ˈdrɔːɪŋ/","ja":"完成図","kana":"かんせいず","romaji":"kanseizu","vi":"bản vẽ hoàn công","level":2,"def_vi":"Bản vẽ được cập nhật sau khi chế tạo, lắp đặt xong, thể hiện đúng trạng thái thực tế của thiết bị hoặc công trình.","def_en":"A drawing updated after fabrication or installation to show the equipment or plant exactly as actually built.","def_ja":"製作・据付完了後に、実際の出来上がりの状態に合わせて修正した図面。","usage_en":"Danh từ đếm được, thường số nhiều 'as-built drawings' hoặc 'as-builts'. Hay đi với: submit as-built drawings, as-built documentation.","usage_ja":"Hay gặp: 完成図書 (bộ hồ sơ hoàn công), 竣工図 (ngành xây dựng), 完成図を提出する.","context_vi":"Dùng khi bàn giao dự án nhà máy, đường ống, máy móc để phục vụ vận hành và bảo trì sau này.","ex_en":"The pipe routing changed on site, so the as-built drawing must be updated.","ex_ja":"配管ルートが現場で変わったので、完成図を修正しなければならない。","ex_vi":"Tuyến ống đã thay đổi tại công trường nên bản vẽ hoàn công phải được cập nhật.","syn_en":["as-builts","record drawing"],"syn_ja":["竣工図","完成図書 (nghĩa rộng hơn)"]},{"en":"work instruction","pos":"noun phrase","ipa":"/ˈwɝːk ɪnˌstrʌkʃən/","ja":"作業手順書","kana":"さぎょうてじゅんしょ","romaji":"sagyoutejunsho","vi":"hướng dẫn công việc","level":2,"def_vi":"Tài liệu mô tả từng bước thực hiện một công việc tại trạm, kèm hình ảnh, dụng cụ, thông số và điểm cần chú ý.","def_en":"A document describing step by step how to do a task at a workstation, with pictures, tools, settings and key points.","def_ja":"作業の手順を、図・工具・条件・注意点とともに一つずつ示した文書。","usage_en":"Danh từ đếm được, viết tắt WI. Hay đi với: follow the work instruction, write / revise a work instruction; khác 'work order' (lệnh sản xuất).","usage_ja":"Hay gặp: 作業手順書, 作業標準書, 作業要領書; khẩu ngữ: 手順書. Động từ: 手順書に従う, 手順書を作成する.","context_vi":"Dùng ở dây chuyền lắp ráp, trạm kiểm tra, đào tạo công nhân mới và trong hồ sơ ISO.","ex_en":"Update the work instruction to show the new torque value of 25 N·m.","ex_ja":"新しい締付トルク25N·mを作業手順書に反映してください。","ex_vi":"Hãy cập nhật hướng dẫn công việc theo giá trị mô-men siết mới là 25 N·m.","syn_en":["WI","standard operating procedure (SOP, nghĩa gần)"],"syn_ja":["作業標準書","作業要領書"]},{"en":"document control","pos":"noun phrase","ipa":"/ˈdɑːkjəmənt kənˌtroʊl/","ja":"文書管理","kana":"ぶんしょかんり","romaji":"bunshokanri","vi":"kiểm soát tài liệu","level":2,"def_vi":"Hệ thống quy định cách đánh số, duyệt, phát hành, phân phối, sửa đổi và lưu trữ tài liệu kỹ thuật.","def_en":"The system for numbering, approving, issuing, distributing, revising and archiving technical documents.","def_ja":"技術文書の採番・承認・発行・配布・改訂・保管を管理する仕組み。","usage_en":"Danh từ không đếm được. Hay đi với: document control procedure, document controller, send it to document control.","usage_ja":"Hay gặp: 文書管理規程, 文書管理システム, 図面管理 (cho bản vẽ). Bộ phận quản lý bản vẽ thường gọi 図面管理課.","context_vi":"Dùng trong hệ thống ISO 9001, dự án lớn và ở phòng kỹ thuật để tránh dùng nhầm tài liệu cũ.","ex_en":"Send the signed drawings to document control for scanning and distribution.","ex_ja":"署名済みの図面は、スキャンと配布のため文書管理担当に送ってください。","ex_vi":"Hãy gửi các bản vẽ đã ký cho bộ phận kiểm soát tài liệu để scan và phân phối.","syn_en":["document management","records control (nghĩa gần)"],"syn_ja":["図面管理 (nghĩa hẹp hơn)","ドキュメント管理"]},{"en":"drawing register","pos":"noun phrase","ipa":"/ˈdrɔːɪŋ ˌrɛdʒɪstər/","ja":"図面台帳","kana":"ずめんだいちょう","romaji":"zumendaichou","vi":"sổ đăng ký bản vẽ (danh mục bản vẽ)","level":2,"def_vi":"Danh sách quản lý tất cả bản vẽ của dự án hoặc sản phẩm, ghi số, tên, phiên bản, ngày phát hành và trạng thái.","def_en":"A list of all drawings for a project or product, recording number, title, revision, issue date and status.","def_ja":"案件や製品の全図面について、図番・名称・版・発行日・状態を記録した一覧。","usage_en":"Danh từ đếm được. Hay đi với: update the drawing register, drawing list, document register (MDR - master document register).","usage_ja":"Hay gặp: 図面台帳に登録する, 図面リスト, 図面一覧表. Ngày nay thường quản lý trên hệ thống PDM.","context_vi":"Dùng ở phòng kỹ thuật và dự án để biết bản vẽ nào là phiên bản mới nhất và đã gửi cho ai.","ex_en":"According to the drawing register, the frame drawing is at revision D.","ex_ja":"図面台帳によると、フレーム図面は改訂Dが最新である。","ex_vi":"Theo sổ đăng ký bản vẽ, bản vẽ khung đang ở phiên bản D.","syn_en":["drawing list","master document register (MDR)"],"syn_ja":["図面リスト","図面一覧表"]},{"en":"in-house part","pos":"noun phrase","ipa":"/ˌɪn ˈhaʊs ˌpɑːrt/","ja":"内製品","kana":"ないせいひん","romaji":"naiseihin","vi":"chi tiết tự chế tạo (sản xuất nội bộ)","level":2,"def_vi":"Chi tiết được gia công, chế tạo ngay trong nhà máy của công ty thay vì mua từ bên ngoài.","def_en":"A part manufactured in the company's own factory rather than bought from outside.","def_ja":"外部から買わず、自社工場で加工・製作する部品。","usage_en":"Danh từ đếm được. Hay đi với: in-house parts and purchased parts, make in-house; còn gọi 'manufactured part', 'make part'.","usage_ja":"Hay gặp: 内製品, 内製化 (chuyển sang tự làm), 内製・外注; đối lập: 購入品, 外注品.","context_vi":"Dùng khi phân loại BOM, lập kế hoạch sản xuất xưởng và tính giá thành.","ex_en":"In-house parts are marked with 'M' in the make/buy column of the BOM.","ex_ja":"部品表の内外区分欄では、内製品に「M」を付けている。","ex_vi":"Trong cột tự làm/mua ngoài của BOM, chi tiết tự chế tạo được đánh dấu 'M'.","syn_en":["manufactured part","make part"],"syn_ja":["自社製作品","加工品 (nghĩa gần)"]},{"en":"item number","pos":"noun phrase","ipa":"/ˈaɪtəm ˌnʌmbər/","ja":"照合番号","kana":"しょうごうばんごう","romaji":"shougoubangou","vi":"số vị trí (số chỉ dẫn chi tiết)","level":2,"def_vi":"Số ghi trong vòng tròn (bóng) trên bản vẽ lắp, chỉ vào chi tiết và khớp với dòng tương ứng trong bảng kê.","def_en":"The number in a balloon on an assembly drawing that points to a part and matches its line in the parts list.","def_ja":"組立図で部品を指す丸囲みの番号。部品欄の行と対応する。","usage_en":"Danh từ đếm được; ký hiệu tròn gọi là 'balloon'. Hay đi với: item number 5, add item balloons, find number (Mỹ).","usage_ja":"Thuật ngữ JIS: 照合番号; ngoài xưởng gọi 品番 (nghĩa khác, dễ nhầm), 部品番号, 風船 hoặc バルーン.","context_vi":"Dùng khi đọc bản vẽ lắp để tìm chi tiết trong bảng kê và khi lắp ráp theo bản vẽ.","ex_en":"Item number 12 points to the spacer between the two bearings.","ex_ja":"照合番号12は2つの軸受の間にあるスペーサを指している。","ex_vi":"Số vị trí 12 chỉ vào bạc chặn giữa hai ổ lăn.","syn_en":["balloon number","find number (Mỹ)"],"syn_ja":["バルーン番号","部品番号 (nghĩa gần)"]},{"en":"unit of measure","pos":"noun phrase","ipa":"/ˈjuːnɪt əv ˈmɛʒər/","ja":"単位","kana":"たんい","romaji":"tan'i","vi":"đơn vị tính","level":2,"def_vi":"Cột trong BOM hoặc hệ thống ERP cho biết số lượng tính theo cái, mét, kg, lít, bộ...","def_en":"The field in a BOM or ERP system stating how a quantity is counted: each, metre, kg, litre, set, etc.","def_ja":"部品表やERPで数量の数え方(個・m・kg・L・セットなど)を示す項目。","usage_en":"Danh từ đếm được, viết tắt UOM / UoM. Hay đi với: UOM: EA (each), M, KG, SET; lỗi hay gặp: nhập dây, ống theo 'EA' thay vì 'M'.","usage_ja":"Trong BOM Nhật có cột 単位: 個, 本, 枚, m, kg, 式 (một bộ/lô). Lưu ý trợ từ đếm 本, 枚 khác nhau theo hình dạng.","context_vi":"Dùng khi lập BOM, mã hóa vật tư trên ERP, đặt hàng và nhập kho.","ex_en":"The cable is listed with the wrong unit of measure: it should be metres, not pieces.","ex_ja":"ケーブルの単位が間違っている。個ではなくmにすべきだ。","ex_vi":"Cáp bị ghi sai đơn vị tính: phải là mét, không phải cái.","syn_en":["UOM","unit"],"syn_ja":["数量単位","単位区分"]},{"en":"spare parts list","pos":"noun phrase","ipa":"/ˈspɛr ˌpɑːrts ˈlɪst/","ja":"予備品リスト","kana":"よびひんリスト","romaji":"yobihinrisuto","vi":"danh mục phụ tùng dự phòng","level":2,"def_vi":"Danh sách chi tiết hao mòn và dự phòng mà nhà sản xuất khuyên người dùng mua sẵn, kèm mã và số lượng.","def_en":"A list of wear and spare parts, with numbers and quantities, that the manufacturer recommends the user keep in stock.","def_ja":"メーカーが使用者に常備を勧める消耗品・予備品の品番と数量の一覧。","usage_en":"Danh từ đếm được. Hay đi với: recommended spare parts list (RSPL), commissioning spares, two-year spares.","usage_ja":"Hay gặp: 予備品リスト, 推奨予備品, 消耗品リスト, スペアパーツリスト.","context_vi":"Dùng khi bàn giao máy, lập ngân sách bảo trì và trong hồ sơ hoàn công của dự án.","ex_en":"The spare parts list recommends two sets of seals for the first year.","ex_ja":"予備品リストでは、初年度用にシール2セットを推奨している。","ex_vi":"Danh mục phụ tùng dự phòng khuyến nghị hai bộ phớt cho năm đầu tiên.","syn_en":["recommended spare parts list (RSPL)","spares list"],"syn_ja":["スペアパーツリスト","推奨予備品表"]},{"en":"engineering BOM","pos":"noun phrase","ipa":"/ˌɛndʒɪˈnɪrɪŋ ˌbiː oʊ ˈɛm/","ja":"設計部品表","kana":"せっけいぶひんひょう","romaji":"sekkeibuhinhyou","vi":"BOM thiết kế (E-BOM)","level":3,"def_vi":"BOM do phòng thiết kế lập, phản ánh cấu trúc sản phẩm theo chức năng và bản vẽ, chưa tính công đoạn sản xuất.","def_en":"The BOM created by engineering, reflecting product structure by function and drawings, without production steps.","def_ja":"設計部門が作る部品表。機能や図面に基づく製品構成で、製造工程は含まない。","usage_en":"Danh từ đếm được, viết tắt EBOM / E-BOM. Hay đi với: convert the EBOM to an MBOM, EBOM in PLM.","usage_ja":"Hay gặp: E-BOM, 設計BOM, E-BOMからM-BOMへ変換する. Thường quản lý trong PLM/PDM.","context_vi":"Dùng ở công ty có hệ thống PLM/ERP, khi bàn giao dữ liệu thiết kế cho sản xuất.","ex_en":"The engineering BOM shows the motor as one item, but production splits it into kits.","ex_ja":"設計部品表ではモータは1品目だが、製造側ではキットに分けている。","ex_vi":"BOM thiết kế thể hiện động cơ là một mục, nhưng sản xuất lại tách thành nhiều bộ.","syn_en":["EBOM","design BOM"],"syn_ja":["E-BOM","設計BOM"]},{"en":"manufacturing BOM","pos":"noun phrase","ipa":"/ˌmænjəˈfæktʃərɪŋ ˌbiː oʊ ˈɛm/","ja":"製造部品表","kana":"せいぞうぶひんひょう","romaji":"seizoubuhinhyou","vi":"BOM sản xuất (M-BOM)","level":3,"def_vi":"BOM được sắp xếp theo trình tự lắp ráp và công đoạn sản xuất, có thêm vật tư phụ như dầu mỡ, keo, bao bì.","def_en":"A BOM arranged by assembly sequence and production steps, adding consumables such as grease, adhesive and packaging.","def_ja":"組立順序や工程に沿って並べ、グリス・接着剤・梱包材などの副資材も加えた部品表。","usage_en":"Danh từ đếm được, viết tắt MBOM / M-BOM. Hay đi với: MBOM in ERP, routing, phantom items.","usage_ja":"Hay gặp: M-BOM, 製造BOM, 工程別部品表. Do bộ phận 生産技術 hoặc 生産管理 quản lý.","context_vi":"Dùng trong ERP để tính nhu cầu vật tư, cấp phát vật tư theo trạm và tính giá thành sản xuất.","ex_en":"Thread-locking adhesive appears only in the manufacturing BOM, not on the drawing.","ex_ja":"ねじロック剤は図面には載らず、製造部品表にだけ記載されている。","ex_vi":"Keo khóa ren chỉ có trong BOM sản xuất, không có trên bản vẽ.","syn_en":["MBOM","production BOM"],"syn_ja":["M-BOM","製造BOM"]},{"en":"multi-level BOM","pos":"noun phrase","ipa":"/ˌmʌlti ˈlɛvəl ˌbiː oʊ ˈɛm/","ja":"多階層部品表","kana":"たかいそうぶひんひょう","romaji":"takaisoubuhinhyou","vi":"BOM nhiều cấp","level":3,"def_vi":"BOM thể hiện cấu trúc dạng cây: sản phẩm gồm các cụm, mỗi cụm gồm cụm con và chi tiết, đánh số cấp 0, 1, 2...","def_en":"A tree-structured BOM in which the product contains assemblies, which contain subassemblies and parts, numbered by level.","def_ja":"製品→組立品→部品のように階層構造で表し、レベル番号を付けた部品表。","usage_en":"Danh từ đếm được; còn gọi 'indented BOM'. Đối lập: single-level BOM. Hay đi với: BOM level, parent / child item.","usage_ja":"Hay gặp: 多段階部品表, ストラクチャ型部品表, 親品目・子品目; đối lập: サマリー型部品表.","context_vi":"Dùng để quản lý sản phẩm phức tạp như máy, ô tô, thiết bị điện, trên ERP và PLM.","ex_en":"In the multi-level BOM, the gearbox is a level-1 assembly under the conveyor.","ex_ja":"多階層部品表では、ギヤボックスはコンベヤの下のレベル1組立品になっている。","ex_vi":"Trong BOM nhiều cấp, hộp số là cụm cấp 1 thuộc băng tải.","syn_en":["indented BOM","structured BOM"],"syn_ja":["多段階部品表","ストラクチャ型部品表"]},{"en":"where-used list","pos":"noun phrase","ipa":"/ˈwɛr ˌjuːzd ˈlɪst/","ja":"逆展開","kana":"ぎゃくてんかい","romaji":"gyakutenkai","vi":"danh sách nơi sử dụng (tra ngược)","level":3,"def_vi":"Kết quả tra ngược BOM cho biết một chi tiết đang được dùng trong những cụm và sản phẩm nào.","def_en":"A reverse BOM query showing every assembly and product in which a given part is used.","def_ja":"ある部品がどの組立品・製品に使われているかを部品表から逆にたどった一覧。","usage_en":"Danh từ đếm được. Hay đi với: run a where-used list, where-used report / query; rất cần khi đánh giá ảnh hưởng của thay đổi.","usage_ja":"Hay gặp: 逆展開する, 使用先一覧, 使用先照会; đối lập: 正展開.","context_vi":"Dùng khi thay đổi thiết kế, chi tiết ngừng sản xuất hoặc có lỗi chất lượng cần biết sản phẩm nào bị ảnh hưởng.","ex_en":"The where-used list shows that this O-ring is in 14 different valves.","ex_ja":"逆展開の結果、このOリングは14種類のバルブに使われていた。","ex_vi":"Danh sách nơi sử dụng cho thấy vòng O này có mặt trong 14 loại van khác nhau.","syn_en":["where-used report","reverse BOM explosion"],"syn_ja":["使用先一覧","使用先照会"]},{"en":"BOM explosion","pos":"noun phrase","ipa":"/ˌbiː oʊ ˈɛm ɪkˈsploʊʒən/","ja":"正展開","kana":"せいてんかい","romaji":"seitenkai","vi":"triển khai BOM (khai triển xuôi)","level":3,"def_vi":"Việc khai triển BOM từ sản phẩm xuống mọi cấp để liệt kê toàn bộ chi tiết và tổng số lượng cần.","def_en":"Breaking down a BOM from the product through every level to list all parts and total quantities required.","def_ja":"製品から下位の全階層へ部品表を展開し、必要な全部品と総数量を求めること。","usage_en":"Danh từ đếm được; động từ 'explode the BOM'. Hay đi với: BOM explosion in MRP, gross requirements; đối lập: where-used / implosion.","usage_ja":"Hay gặp: 正展開, 部品展開, 所要量展開 (trong MRP); đối lập: 逆展開.","context_vi":"Dùng trong ERP/MRP để tính nhu cầu vật tư khi có đơn hàng và khi lập bộ chi tiết cho lắp ráp.","ex_en":"A BOM explosion for 50 machines gives a total of 1,200 M6 screws.","ex_ja":"50台分の正展開をすると、M6ねじは合計1,200本必要になる。","ex_vi":"Triển khai BOM cho 50 máy cho ra tổng cộng 1.200 vít M6.","syn_en":["parts explosion","requirements explosion"],"syn_ja":["部品展開","所要量展開"]},{"en":"obsolete part","pos":"noun phrase","ipa":"/ˌɑːbsəˈliːt ˈpɑːrt/","ja":"廃番品","kana":"はいばんひん","romaji":"haibanhin","vi":"chi tiết ngừng sản xuất (hết mã)","level":3,"def_vi":"Chi tiết có mã đã bị hủy, không còn được sản xuất hoặc cung cấp, cần tìm chi tiết thay thế.","def_en":"A part whose number has been withdrawn and is no longer made or supplied, so a replacement must be found.","def_ja":"品番が廃止され、製造・供給されなくなった部品。代替品の選定が必要。","usage_en":"Danh từ đếm được. Hay đi với: become obsolete, obsolescence management, last-time buy, replacement part; tình trạng EOL (end of life).","usage_ja":"Hay gặp: 廃番になる, 廃番品の代替, 生産終了品 (EOL); khẩu ngữ: 廃番.","context_vi":"Dùng khi bảo trì máy cũ, cập nhật BOM và quản lý vòng đời linh kiện điện tử, cơ khí mua ngoài.","ex_en":"The cylinder is now an obsolete part, so we must qualify a replacement model.","ex_ja":"そのシリンダは廃番品になったので、代替機種を評価しなければならない。","ex_vi":"Xi lanh đó đã là chi tiết ngừng sản xuất nên chúng tôi phải đánh giá một mẫu thay thế.","syn_en":["discontinued part","end-of-life (EOL) part"],"syn_ja":["生産終了品","廃番 (khẩu ngữ)"]}]}]};
